def collect_files_in_dir_and_subdir_with_keywords_in_bsn(dir, list_kwd_no_or_1 = [], list_kwd_yes_or_2 = [], list_kwd_yes_or_3 = []):
      print('\n[collect_files_in_dir_and_subdir_with_keywords_in_bsn]')
      #[1] Check if directory exists
      if not os.path.isdir(dir):
            raise FileNotFoundError(f"The directory '{dir}' was not found.")
      #[2] Initialize a list to hold the full paths of the files that match the keywords
      list_path = []
      #[3] Walk through the directory and its subdirectories to get a list of files
      for dirpath, _dirnames, basenames in os.walk(dir):
            for iter_bsn in basenames:
                  # Apply the filters progressively, skipping the file as soon as one condition fails
                  if list_kwd_no_or_1 and any(keyword in iter_bsn for keyword in list_kwd_no_or_1):
                        continue  # Skip this file as it contains a keyword from list_kwd_no_or_1
                  if list_kwd_yes_or_2 and not any(keyword in iter_bsn for keyword in list_kwd_yes_or_2):
                        continue  # Skip this file as it doesn't contain any keyword from list_kwd_yes_or_2
                  if list_kwd_yes_or_3 and not any(keyword in iter_bsn for keyword in list_kwd_yes_or_3):
                        continue  # Skip this file as it doesn't contain any keyword from list_kwd_yes_or_3
                  # If the function reaches this point, the file matches all criteria
                  list_path.append(os.path.join(dirpath, iter_bsn))
      return list_path


def count_files_in_dir_and_subdir_with_keywords_in_bsn(dir, list_kwd_yes_or_1):
      print('\n[collect_files_in_dir_and_subdir_with_keywords_in_bsn]')
      print('\n--(Index from 0 to len(list_kwd_yes_or_1)-1 are the numbers that falls into these catagories.)')
      #[1] Check if directory exists
      if not os.path.isdir(dir):
            raise FileNotFoundError(f"The directory '{dir}' was not found.")
      #[2] Initialize a list to hold the full paths of the files that match the keywords
      int_total_kwd = len(list_kwd_yes_or_1)
      list_kwd_count = [0] * (int_total_kwd + 2)
      #[3] Walk through the directory and its subdirectories to get a list of files
      for cnt, output  in enumerate(os.walk(dir)):
            dirpath, _dirnames, basenames = output
            #[4] Iterate through basenames in dir and subdir.
            for iter_bsn in basenames:
                  no_match = 0
                  #[5] Iterate through kwywords. 
                  for cnt_kwd, iter_kwd in enumerate(list_kwd_yes_or_1):
                        #print(f'[{cnt}] {iter_bsn}, {iter_kwd}')
                        if iter_kwd in iter_bsn:
                              list_kwd_count[cnt_kwd] += 1
                              #print(f'--list_kwd_count[{cnt_kwd}] += 1')
                        else:
                              no_match += 1
                  if no_match == int_total_kwd:
                        list_kwd_count[int_total_kwd] += 1
                  list_kwd_count[int_total_kwd + 1] += 1
      return list_kwd_count




def check_if_two_folders(dir_master, dir_slave, slave_replace_with, list_kwd_yes_or_1, list_kwd_no_or_2):
    # [1] List of files in two folders.
    list_paths_m, list_bsn_m = filter_file_in_dir_with_keywords(dir_master, list_kwd_yes_or_1, list_kwd_no_or_2, False)
    list_paths_s, list_bsn_s = filter_file_in_dir_with_keywords(dir_slave, list_kwd_yes_or_1, list_kwd_no_or_2, False)

    # [6] Split element with "_reduced".
    if slave_replace_with:
        str_replace, str_with = slave_replace_with
        list_bsn_s = [filename.replace(str_replace, str_with) for filename in list_bsn_s]

    # [8] Check if similar.
    if sorted(list_bsn_m) == sorted(list_bsn_s):
        print('All background sample images have a reduced version.')
    else:
        print('Does not match. Clear the reduced folder and process again.')

    # [9] Remove all the files (no folders) in the dir_slave.
    for iter_r in os.listdir(dir_slave):
        path_iter_r = os.path.join(dir_slave, iter_r)
        if os.path.isfile(path_iter_r):
            os.remove(path_iter_r)

    # [12] Copy every file from dir_master to dir_slave.
    for file_path in list_paths_m:
        shutil.copy(file_path, dir_slave)


