def move_all_files_to_the_surface(dir_main, print_status=False):
    """
    Moves all files in the subdirectories into the main directory and removes empty folders.

    Parameters:
    dir_main (str): The main directory path.
    print_status (bool): Whether to print status messages. Default is False.
    """
    print('\n[move_all_files_to_the_surface]')
    
    #[1] Ensure the main directory exists
    if not os.path.isdir(dir_main):
        print(f'Provided path is not a directory: {dir_main}')
        return
    
    #[2] Traverse through all subdirectories
    for root, dirs, files in os.walk(dir_main, topdown=False):
        if root == dir_main:
            continue  # Skip the main directory itself

        #[3] Move files to the main directory
        for sub_item in files:
            sub_item_full_path = os.path.join(root, sub_item)
            new_item_path = os.path.join(dir_main, sub_item)

            try:
                os.rename(sub_item_full_path, new_item_path)
                if print_status:
                    print(f'-- Moved: {sub_item} to {os.path.basename(dir_main)}')
            except FileExistsError:
                if print_status:
                    print(f'-- File already exists: {new_item_path}. Skipping.')
            except FileNotFoundError:
                if print_status:
                    print(f'-- File not found: {sub_item_full_path}. Skipping.')
            except Exception as e:
                if print_status:
                    print(f'-- Error moving file {sub_item_full_path}: {e}')

        #[4] Remove empty directories
        try:
            os.rmdir(root)
            if print_status:
                print(f'-- Removed empty folder: {root}')
        except OSError:
            if print_status:
                print(f'-- Folder not empty or cannot be removed: {root}')



