    ax2.set_ylim(-limit, limit)
    ax2.set_aspect('equal', adjustable='box')
    for vec, color in zip(list_vectors, colors_array):
        ax2.quiver(0, 0, vec[1], vec[0], color=color, angles='xy', scale_units='xy', scale=1)
    ax2.set_xlabel('Green')
    ax2.set_ylabel('Blue')
