import numpy as np
import matplotlib.pyplot as plt
from mpl_toolkits import mplot3d

X_min = -1; X_max = 1; X_num = 11
Y_min = -1; Y_max = 1; Y_num = 11
Z_min = -1; Z_max = 1; Z_num = 11

X = np.round(np.linspace(X_min, X_max, X_num),2)
Y = np.round(np.linspace(Y_min, Y_max, Y_num),2)
Z = np.round(np.linspace(Z_min, Z_max, Z_num),2)

#X, Y, Z = np.mgrid[X_min:X_max:(X_num * 1j), Y_min:Y_max:(Y_num * 1j), Z_min:Z_max:(Z_num * 1j)]
#print (X,X.shape,'\n',Y,Y.shape,'\n',Z,Z.shape)


AN = 1; a0 = 0.0529 # Unit: nm
def PBD(a, b, c):
    r = np.sqrt(np.power(a, 2) + np.power(b, 2) + np.power(c, 2))
    rho = AN * r / a0
    wf1s = 1 / np.sqrt(np.pi) * np.power(AN / a0, 3 / 2) * np.exp(-rho)
    pd1s = np.power(wf1s, 2)
    return pd1s

fig = plt.figure('Wavefunction of 1s orbit', figsize=(12,6))
plt.subplots_adjust(left=0.05, right=0.95, bottom=0.1, top=0.9, wspace=None, hspace=None)
ax1 = fig.add_subplot(121, projection='3d')
ax1.view_init(azim=-60, elev=20)


#ax.scatter(X, Y, Z)

#https://stackoverflow.com/questions/55375515/change-marker-color-in-3d-scatter-plot-based-on-condition


for x in X:
    for y in Y:
        for z in Z:
            if PBD(x, y, z) > 0.01:
                ax1.scatter(x, y, z, c='g', marker='o')



# Set up the plot figure.
plt.xticks(np.arange(-1, 1 + 1, 0.5));plt.yticks(np.arange(-1, 1 + 1, 0.5))
ax1.set_zticks(np.linspace(-2, 2, 9))
# The above is the only way to set z-ticks.
# https://stackoverflow.com/questions/37711538/matplotlib-3d-axes-ticks-labels-and-latex
# Make X-, Y-, Z-axis in equal aspect ratio.
# https://stackoverflow.com/questions/13685386/matplotlib-equal-unit-length-with-equal-aspect-ratio-z-axis-is-not-equal-to

#print (X,X.shape,'\n',Y,Y.shape,'\n',Z,Z.shape)

# This part calculate the plotting range and show it.
max_range = np.array([X.max()-X.min(), Y.max()-Y.min(), Z.max()-Z.min()]).max() / 2
print('X ( max, min ) = (',X.max(),',', X.min(), ')')
print('Y ( max, min ) = (',Y.max(),',', Y.min(), ')')
print('Z ( max, min ) = (',Z.max(),',', Z.min(), ')\n max_range =', max_range)
mid_x = (X.max() + X.min()) * 0.5
mid_y = (Y.max() + Y.min()) * 0.5
mid_z = (Z.max() + Z.min()) * 0.5
ax1.set_xlim(mid_x - max_range, mid_x + max_range)
ax1.set_ylim(mid_y - max_range, mid_y + max_range)
ax1.set_zlim(mid_z - max_range, mid_z + max_range)
# Show axis labels.
ax1.set_xlabel('X axis (nm)')
ax1.set_ylabel('Y axis (nm)')
ax1.set_zlabel('Z axis (nm)')


ax2 = fig.add_subplot(122)
ax2.set_xlabel('X axis (nm)')
ax2.set_ylabel('Y axis (nm)')

for x in X:
    if PBD(x, 0, 0) > 0.01:
        ax2.scatter(x, PBD(x, 0, 0), c='g', marker='o')
        print(x,', ', np.round(PBD(x, 0, 0),2))
    else:
        ax2.scatter(x, PBD(x, 0, 0), c='r', marker='x')
        print(x,', ', np.round(PBD(x, 0, 0),2))

plt.show()

