ax4 = fig.add_subplot(3, 2, 4)
ax4.set_xlabel('r axis (nm)')
ax4.set_ylabel('\u03C82'.translate(SUP))
ax4.plot(R_superfine, np.power(WF_value(R_superfine, 0, 0),2), color='#16a3f0')
plt.xticks(np.arange(0, 0.22, 0.02))


# 2D plot, 4 * pi * r^2 * Phi^2.
ax4 = fig.add_subplot(3, 2, 6)
ax4.set_xlabel('r axis (nm)')
ax4.set_ylabel('4\u03C0r2\u03C82'.translate(SUP))
ax4.plot(R_superfine, 4 * np.pi * np.power(R_superfine, 2) * np.power(WF_value(R_superfine, 0, 0), 2), color='#16a3f0')
plt.xticks(np.arange(0, 0.22, 0.02))

plt.show()

