an_Z = 2; a0 = 0.0529  # Unit: nm
def PBA_surface(r, theta, phi):
    rho = an_Z * r / a0
    wf2s = np.round(1 / (4*np.sqrt(2*np.pi)) * np.power(an_Z / a0, 3 / 2) *(2-rho)* np.exp(-rho/2), 4)
    return wf2s

def cart_to_sph(x,y,z):
    r = np.round(np.sqrt(x**2+y**2+z**2), 3)
    theta = np.round(np.arccos(z/r), 3)
    if x != 0:
        phi = np.round(np.arctan(y/x), 3)
    elif x == 0:
        phi = 0
    return (r, theta, phi)

def sph_to_cart(r, theat, phi):
    x = np.round(r * np.sin(theat) * np.cos(phi), 3)
    y = np.round(r * np.sin(theat) * np.sin(phi), 3)
    z = np.round(r * np.cos(theat), 3)
    return (x, y, z)


