R = lambda r, n, l: (2 * r / n / a0) ** l * numpy.exp(-r / n / a0) * scipy.special.genlaguerre(n - l - 1, 2*l + 1)(
    2 * r / n / a0)
WF = lambda r, theta, phi, n, l, m: R(r, n, l) * scipy.special.sph_harm(m, l, phi, theta)
