def identify_usb_devices():
    ports = serial.tools.list_ports.comports()
    devices = []
    for port in ports:
        devices.append({
            'port': port.device,
            'name': port.name,
            'description': port.description,
            'hwid': port.hwid,
            'vid': port.vid,
            'pid': port.pid,
            'serial_number': port.serial_number,
            'location': port.location,
            'manufacturer': port.manufacturer,
            'product': port.product,
            'interface': port.interface
        })
    return devices


def select_the_arduino_port():
    print('\n[where_is_arduino]')
    #[1] List all devices.
    devices = identify_usb_devices()
    
    #[2] Filter for Arduino devices
    arduino_devices = [
        device for device in devices 
        if '9025' in str(device['vid']).lower() or '67' in str(device['pid']).lower()]
       
    #[4] Handle if there are multiple USB devices.
    if len(arduino_devices) > 1:
        text = 'Multiple Arduino devices detected. There should be only one Arduino device.'
        raise ValueError(text)
    elif len(arduino_devices) == 0:
        print('--No Arduino device detected.')
        return None  # No Arduino devices found
    
    #[5] Report
    port_name = arduino_devices[0]['port']
    print(f'--The Arduino device is at {port_name}.')
    return port_name



def connect_to_arduino_beautifully(port_Arduino, ser_arduino, baudrate=9600, timeout=1, time_stable=1):
    if ser_arduino is None:
        print(f'\n[connect_to_arduino_beautifully]')
        #[2] Open serial port to Arduino
        try:
            ser_arduino = serial.Serial(port_Arduino, baudrate=baudrate, timeout=timeout)
        except Exception as e:
            print(f'Error opening serial port: {e}')
            if 'Access is denied.' in str(e):
                print(f'Detected "Access is denied" in the error message. Did you forgot to close Arduino IDE? System exit.')
                sys.exit()
        
        #[3] Wait connection to stabilize.
        time.sleep(time_stable) 
        print(f'-- Arduino serial communication estabilshed. Waiting for {time_stable} seconds to stabilize.')
        time.sleep(time_stable)
    return ser_arduino  


