def calculate_sharpness_metric_and_save_frame(frame, dir, bsn=False, note=None):
    #[1] Calculate sharpness_metric
    sharpness = M1UTL.calculate_MSE_color_difference(frame)
    print(f'\tsharpness {note}: {sharpness:.2f}')
    
    #[2] Save frame at dir
    if bsn:
        path_save = os.path.join(dir, f'{bsn}.png')
        cv2.imwrite(path_save, frame)
    return sharpness

def case_C_stage_up_2pt5um(ser, XYZ_coord_mm):
    X_coord_mm, Y_coord_mm, Z_coord_mm = XYZ_coord_mm
    try: #[] Move Z up(+) for 2.5 um.
        message = 'C' + '\n'
        ser.write(message.encode())
        Z_coord_mm = Z_coord_mm + 0.0025
        print('Moved Z down(+) for 2.5 um. Z_coord_mm =', "%0.4f" %Z_coord_mm)
    except KeyboardInterrupt:
        print("Serial communication stopped.")

def case_F_stage_down_2pt5um(ser, XYZ_coord_mm):
    X_coord_mm, Y_coord_mm, Z_coord_mm = XYZ_coord_mm
    try: #[] Move Z down(-) for 2.5 um.
        message = 'F' + '\n'
        ser.write(message.encode())
        Z_coord_mm = Z_coord_mm - 0.0025
        print('Moved Z down(-) for 2.5 um. Z_coord_mm =', "%0.4f" %Z_coord_mm)
    except KeyboardInterrupt:
        print("Serial communication stopped.")



def auto_focus(max_trail, capture, ser, dir, bsn, XYZ_coord_mm):
    """
    max_trail: maximum trail of step in z-axis to take.
    capture: the connection of optical image camera from USB. 
    ser: the connection to Arduino
    dir: directory to save captured images.
    bsn: basename of captured images.
    XYZ_coord_mm: X, Y, and Z coordinates.
    """
    #[1] Open an empty list to save sharpness_metric
    list_sharpness = []
    cnt = 0
    
    #[1] Capture first image and calculate blur metric.
    ret, frame = capture.read()
    sharp_metric_1 = calculate_sharpness_metric_and_save_frame(frame, dir, f'{bsn}-{cnt:02d}', '(1st try)')
    list_sharpness.append(sharp_metric_1)
    cnt += 1
    
    #[2] Move up by 2.5 um.
    case_C_stage_up_2pt5um(ser, XYZ_coord_mm) # "C" is the switch-case commend for Arduino to move the linear stage up by 2.5 um.
    time.sleep(2)  
    
    #[3] Capture second image and calculate blur metric.
    ret, frame = capture.read()
    sharp_metric_2 = calculate_sharpness_metric_and_save_frame(frame, dir, f'{bsn}-{cnt:02d}', '(2nd try)')
    list_sharpness.append(sharp_metric_2)
    cnt += 1
    
    #[4] Check the trend
    if sharp_metric_1 < sharp_metric_2: # Move up gets more sharp.
        for i, trail in enumerate (range(1, max_trail)):
            #[] Move down by 2.5 um.
            case_C_stage_up_2pt5um(ser, XYZ_coord_mm)
            #[] Capture  image and calculate blur metric.
            ret, frame = capture.read()
            cnt = i + 2
            sharp_metric_1 = calculate_sharpness_metric_and_save_frame(frame, dir, f'{bsn}-{cnt:02d}')
            
            print('sharp_metric_1: ', sharp_metric_1)
            
    elif sharp_metric_1 < sharp_metric_2:
        for i, trail in enumerate (range(1, max_trail)):
            #[] Move up by 2.5 um.
            ser = serial.Serial('COM3', 9600, timeout=1)
            case_F_stage_down_2pt5um(ser, XYZ_coord_mm)
            #[] Capture  image and calculate blur metric.
            ret, frame = capture.read()
            cnt = i + 2
            blur_metric_1 = calculate_sharpness_metric_and_save_frame(frame, dir, f'{bsn}-{cnt:02d}')
            
            print('blur_metric_1: ', blur_metric_1)
    else:
        print('Perfect focus!')
    return XYZ_coord_mm, list_sharpness
            

def check_for_collision(ser):
    """
    Communicates with the Arduino via serial to get the current position and limit switch states,
    and parses the response to extract these values.
    """
    def parse_response(response):
        try:
            #[1] Find and extract the part of the response that contains the position
            pos_start = response.find("Current_Position_(XYZ): ") + len("Current_Position_(XYZ): ")
            pos_end = response.find(" Limit_switch_state_(XYZP):_")
            positions = response[pos_start:pos_end].split(',')

            #[2] Find and extract the part of the response that contains the limit switch states
            limit_start = response.find("Limit_switch_state_(XYZP):_") + len("Limit_switch_state_(XYZP):_")
            limit_states = response[limit_start:]

            #[3] Convert positions to floats
            x, y, z = map(float, positions)

            #[4] Convert limit states to booleans
            p_limit_states = [bool(int(state)) for state in limit_states]
            XYZP = [x, y, z, p_limit_states]
            return XYZP
        except (ValueError, IndexError) as e:
            print(f'-- Error parsing response: {e}')
            return None

    #[1] Communication with arduino.
    try:
        message = '3' + '\n'
        ser.write(message.encode())
        time.sleep(1)  # Wait for the device to respond
        if ser.in_waiting > 0:
            response = ser.readline().decode('utf-8').strip()
            print(f'-- Serial response: {response}')
        else:
            print('-- No response from the device.')
            return None
    except Exception as e:
        print(f'-- Error in serial communication: {e}')
        return None

    #[2] Decode response
    XYZP = parse_response(response)
    print(f'-- Proximity detection: {XYZP}')
    
    return XYZP


def capture_limit_switch_state(serial_output):
    #[1] Define pattern and extract match
    pattern = r"Limit_switch_state_\(XYZP\):_(\d{4})"
    match = re.search(pattern, serial_output)

    #[2] Analyze match
    if match:
        text = match.group(1)
        list_XYZP = [*text]
        return list_XYZP
    else:
        return None


def send_message_to_arduino_and_wait_for_reply(ser_arduino, message, timeout=5):
    #[1] Prepare the message
    try:
        #[2] Clear any existing data in the input buffer
        ser_arduino.flushInput()
        
        #[3] Send message.
        message = f'{message}\n'
        ser_arduino.write(message.encode())

        #[5] Start the timer and Wait for the response
        start_time = time.time()
        while time.time() - start_time < timeout:
            if ser_arduino.in_waiting > 0:
                response = ser_arduino.readline().decode('utf-8').strip()
                print(f'-- [response] {response}')
                #[6] Capture the limit switch state
                list_XYZP = capture_limit_switch_state(response)
                
                #[8] Calculate and print the passed time and the response.
                passed_time = time.time() - start_time
                print(f'-- Serial response ({passed_time:.2f} seconds): {response}')
                return list_XYZP
            time.sleep(0.2)  # Small sleep to prevent busy-waiting

        #[9] Handle timeout case
        print(f'-- No response from the device within the timeout period of {timeout} seconds.')
        return None

    #[12] Handle exceptions
    except Exception as e:
        print(f'-- Error in serial communication with Arduino: \n{e}')
        return None











