def update_XYZ_coordinate(XYZ_coord_um, m_case, m_repeat, df_cases):
    """
    df_cases has three columns: Case, X_um, Y_um, Z_um.
    XYZ_coord_um is a list of three float numbers: X_coord_um, Y_coord_um, Z_coord_um
    If m_case matches "Case", then XYZ_coord_um += [X_um, Y_um, Z_um] * m_repeat
    If not, raise ValueError (f'Case {df_cases} not found. Please check.)
    """
    #print(f'\n[update_XYZ_coordinate]')
    #[1] Copy coordinate.
    XYZ_coord_um = np.array(XYZ_coord_um)  # Convert to numpy array
    XYZ_coord_um_new = XYZ_coord_um.copy()  # Ensure we are not modifying the original array
    
    #[2] Movement data.
    m_case, m_repeat = str(m_case), str(m_repeat)
    df_cases['Case'] = df_cases['Case'].astype(str)
    df_movement_row = df_cases[df_cases['Case'] == m_case]
    #print(f'-- [df_movement_row]\n{tabulate(df_movement_row.head(), headers="keys", tablefmt="orgtbl")}\n')

    #[3] Read movement data.
    if not df_movement_row.empty:
        delta_X, delta_Y, delta_Z = df_movement_row[['X_um', 'Y_um', 'Z_um']].values[0]
        
        #[4] Convert XYZ_coord_um to a list        
        XYZ_coord_um_new[0] += delta_X
        XYZ_coord_um_new[1] += delta_Y
        XYZ_coord_um_new[2] += delta_Z
        
    #[5] If it's a homing operation. The moving away from the limit volume can be changed in Airuino code.
    elif m_case == '0': # (X, R, Y, Z, or A for all axis.)
        if m_repeat == 'X':
            XYZ_coord_um_new[0] = 0
        elif m_repeat == 'R':
            XYZ_coord_um_new[0] = 250000
        elif m_repeat == 'Y':
            XYZ_coord_um_new[1] = 0
        elif m_repeat == 'Z':
            XYZ_coord_um_new[2] = 30000     # After Z is homed, it move away from limit for 3 cm (30000 um).
    else:
        raise ValueError(f'Case {m_case} not found. Please check.')

    #[6] Calculate difference.
    XYZ_diff = XYZ_coord_um_new - XYZ_coord_um
    
    return XYZ_coord_um_new, XYZ_diff



def decide_wait_time_for_serial_response(m_case, m_repeat):
    #[10] Examine type of movement and decide sec_wait.
    if m_case in ['4', '5', '6', '7', '8', '9']:
        sec_wait = 2 * int(m_repeat)
    elif m_case in ['0']:
        sec_wait = 10
    elif int(m_repeat) >= 5:
        sec_wait = 2
    else:
        sec_wait = 0.5
    return sec_wait



def stage_list_of_movements(list_move_set, port_Arduino, ser_arduino, XYZ_coord_um, df_cases, listening_timeout=1):
    print(f'\n[stage_list_of_movements] \tInitial XYZ_coord_um = \t{XYZ_coord_um}')
    
    #[2] Open serial port to Arduino
    ser_arduino = M2DEV.connect_to_arduino_beautifully(port_Arduino, ser_arduino, baudrate=9600, timeout=1, time_stable=1)
    XYZ_coord_um_new = None
    
    #[5] Iterate through list of movements.
    for i, iter_move in enumerate(list_move_set):
        #[7] Update current XYZ coordinate with the new coordinate from the previous iteration
        if XYZ_coord_um_new is not None:
            XYZ_coord_um = XYZ_coord_um_new
        
        #[8] Extract movement info.
        print(f'\n[{i:02d}] Performing {iter_move}.', end='')
        if len(iter_move) == 2:
            
            #[9] Convert to required data formate.
            m_case, m_repeat = list(iter_move)
            m_case, m_repeat = str(m_case), str(m_repeat)
        else:
            raise ValueError(f'iter_move must contain exactly two characters. It is now "{iter_move}".')
        
        #[12] Send command to Arduino and wait for response
        try:
            ser_arduino.write(f'{iter_move}\n'.encode())
            
            #[13] Initialize an empty list to store the responses
            responses = []
            
            #[14] Keep reading responses until a specific condition is met or listening_timeout occurs
            start_time = time.time()
            while time.time() - start_time < listening_timeout:
                if ser_arduino.in_waiting > 0:
                    response = ser_arduino.readline().decode('utf-8').strip()
                    responses.append(response)
                    
                    #[15] Check if the desired condition is met (e.g., a specific response)
                    if response == 'Complete.':
                        break
                
                #[18] Optional: Add a small delay to avoid consuming too much CPU
                time.sleep(0.1)
            
            #[20] Process the received responses
            if 'Complete.' in responses:
                #[18] Update XYZ coordinates
                next_move = list_move_set[i + 1] if i + 1 < len(list_move_set) else 'End of list'
                print(f'\tComplete. (Next: {next_move})')
                XYZ_coord_um_new, XYZ_diff = update_XYZ_coordinate(XYZ_coord_um, m_case, m_repeat, df_cases)
                #print(f'-- XYZ_diff = \t\t{XYZ_diff}. \n-- XYZ_coord_um_new = \t{XYZ_coord_um_new}')
            else:
                print(f'-- Received responses: {responses}')
        except Exception as e:
            print(f'-- Error in serial communication: {e}')

    return XYZ_coord_um_new, XYZ_diff, ser_arduino










