def stream_movement_capture(dir, port_Arduino, ser_arduino, cam_idx, bsn, XYZ_coord_um):
    #[1] Initialize
    X_coord_um, Y_coord_um, Z_coord_um = XYZ_coord_um
    unit = 1000

    #[2] Open serial port to Arduino
    ser_arduino = M2DEV.connect_to_arduino_beautifully(port_Arduino, ser_arduino, baudrate=9600, timeout=1, time_stable=1)
    
    #[3] Open video streaming.
    print('Opening VideoCapture. Wait for about 10 seconds.')
    capture = cv2.VideoCapture(cam_idx) # Open the first camera device

    if not capture.isOpened():
        print("Error: Couldn't open the camera.")
        return
    
    #[5] Image capturing is working.
    text_working =      f'\n[Image capture is working]\n'\
                        f'  type "Enter" \tfor calculate_sharpness_metric_and_save_frame.\n'\
                        f'  type "_" \tfor auto_focus.\n'\
                        f'  type "3" \tfor status report.\n'\
                        f'  type "-" \tto quite the loop.\n\n'
    print(text_working)
    
    #[6] Wait for orders.
    while True:
        ret, frame = capture.read() # Capture frame-by-frame
        if not ret:
            print("Error: Couldn't capture a frame.")
            break

        cv2.imshow('Camera Stream', frame) # Display the resulting frame
        key = cv2.waitKey(1) & 0xFF
        
        #[9] Capture the frame if 'Enter' is pressed
        if key == 13: 
            #[9-1] Change the format of timestampe here.
            timestamp = datetime.now().strftime("%y%m%d-%H%M%S")
            M2DEV.calculate_sharpness_metric_and_save_frame(frame, dir, f'{bsn}_{timestamp}', '(single test)')
        
        #[10] Auto focus if "_" is pressed.
