#[5] Azimuth angle correction - Start

def clear_camera_buffer(capture, num_frames_to_clear=5):
    for _ in range(num_frames_to_clear):
        ret, frame = capture.read()
        if not ret:
            print("Failed to grab frame")


def move_stage_capture_image_and_move_back(capture, ser, frame, direction, dir_save):
    print('\n[check_displacement]')
    
    #[5] Capture first image.
    timestamp = datetime.now().strftime("%Y-%m%d-%H%M%S")
    path_capture_image = os.path.join(dir_save, f'_{direction}-0.png')
    cv2.imwrite(path_capture_image, frame)
    print(f'--First image captured, saved at {path_capture_image}')
    time.sleep(1)
    
    #[7] Move +X or +Y by 100 um.
    if direction == 'X':
        ser.write('M\n'.encode())
        time.sleep(2)
        clear_camera_buffer(capture)
        print('--Sent "M" to Arduino through serial, moving linear stage toward +X for 100 um.')
    elif direction == 'Y':
        ser.write('N\n'.encode())
        time.sleep(2)
        clear_camera_buffer(capture)
        print('--Sent "N" to Arduino through serial, moving linear stage toward +Y for 100 um.')
    ret, frame = capture.read()
    time.sleep(2)
    
    #[8] Capture second image.
    clear_camera_buffer(capture)
    path_capture_image = os.path.join(dir_save, f'_{direction}-1.png')
    cv2.imwrite(path_capture_image, frame)
    print(f'--Second image captured, saved at {path_capture_image}')
    
    #[10] Move back.
    if direction == 'X':
        ser.write('P\n'.encode())
        time.sleep(2)
        clear_camera_buffer(capture)
        print('--Sent "P" to Arduino through serial, moving linear stage toward -X for 100 um.')
    elif direction == 'Y':
        ser.write('Q\n'.encode())
        time.sleep(2)
        clear_camera_buffer(capture)
        print('--Sent "Q" to Arduino through serial, moving linear stage toward -Y for 100 um.')
    time.sleep(2)
    #print('--Take a breath for 2 seconds.', end='\n\n')
        

def find_good_matches_SIFT(img1, img2, LR=0.7):
    print('\n[calculate_displacement_sift] (+x, +y) means img is moved right by x and down by y comparing with img1.')
    sift = cv2.SIFT_create()       # Initialize SIFT detector
    #[1] Detect SIFT features and compute descriptors.
    key_point_info = []
    keypoints1, descriptors1 = sift.detectAndCompute(img1, None)
    num_kpt_1 = len(keypoints1)
    key_point_info.append(num_kpt_1)
    keypoints2, descriptors2 = sift.detectAndCompute(img2, None)
    num_kpt_2 = len(keypoints2)
    key_point_info.append(num_kpt_2)
    print(f'--Number of keypoints in (img1, img2): {num_kpt_1}, {num_kpt_2}')
    
    #[2] Initialize and use FLANN matcher
    FLANN_INDEX_KDTREE = 1
    index_params = dict(algorithm = FLANN_INDEX_KDTREE, trees = 5)
    search_params = dict(checks = 50)
    flann = cv2.FlannBasedMatcher(index_params, search_params)
    matches = flann.knnMatch(descriptors1, descriptors2, k=2)
    
    #[3] Filter matches using the Lowe's ratio test
    list_good_matches, list_distance = [], []
    for best_match, second_match in matches:
        if best_match.distance < LR * second_match.distance:
            list_good_matches.append(best_match)
            
    return list_good_matches, keypoints1, keypoints2
            
    
    
def convert_match_to_lists(list_good_matches, keypoints1, keypoints2):
    # [4] Calculate displacement distances
    list_coor2_x, list_coor2_y = [], []
    list_coor1_x, list_coor1_y = [], []
    list_d_x, list_d_y, list_d_l = [], [], []
    for cnt, iter_match in enumerate(list_good_matches):
        # Ensure match.trainIdx is within the range of keypoints1 and keypoints2
        if 0 <= iter_match.trainIdx < len(keypoints1) and 0 <= iter_match.queryIdx < len(keypoints2):
            coor2_x, coor2_y = keypoints2[iter_match.trainIdx].pt
            coor1_x, coor1_y = keypoints1[iter_match.queryIdx].pt
            d_x, d_y = (coor2_x - coor1_x) , (coor2_y - coor1_y)
            d_l = np.sqrt(d_x ** 2 + d_y ** 2)
            list_coor1_x.append(coor1_x)
            list_coor1_y.append(coor1_y)
            list_coor2_x.append(coor2_x)
            list_coor2_y.append(coor2_y)
            list_d_x.append(d_x)
            list_d_y.append(d_y)
            list_d_l.append(d_l)
            
    return (
        list_coor1_x, list_coor1_y
        , list_coor2_x, list_coor2_y
        , list_d_x, list_d_y, list_d_l)

def refining_match_quality(list_coor1_x, list_coor1_y
                    , list_coor2_x, list_coor2_y
                    , list_d_x, list_d_y, list_d_l
                    , f1_dl_upper_limit_ratio, f2_dl_std_limit):
    """
    [d_std_limit] is important. 2 is too lose, 1 is not tight enough. 0.5 is better. 
    """
    #[1] Remove outliers
    if f1_dl_upper_limit_ratio is not None and f1_dl_upper_limit_ratio > 0 :

        #[5] Before first filtering, initiate empty lists and gather information. 
        list_f1_coor2_x, list_f1_coor2_y = [], []
        list_f1_coor1_x, list_f1_coor1_y = [], []
        list_f1_d_x, list_f1_d_y, list_f1_d_l = [], [], []
        
        #[6] First filtering
        f0_mean_d_l = np.mean(list_d_l)
        f1_d_l_lower_lmt, f1_d_l_upper_lmt\
            = 5, f0_mean_d_l * f1_dl_upper_limit_ratio
        print(f'\n--[First filtering]\n--Removing displacement outliers exceeding {f1_dl_upper_limit_ratio} times of the mean value.')
        print(f'--Retaining displacements within the range of {f1_d_l_lower_lmt:.2f} to {f1_d_l_upper_lmt:.2f} pixels.')
        for i, iter_d_l in enumerate(list_d_l):
            if f1_d_l_lower_lmt <= iter_d_l and iter_d_l <= f1_d_l_upper_lmt:
                #[6] Collect lists
                list_f1_coor1_x.append(list_coor1_x[i])
                list_f1_coor1_y.append(list_coor1_y[i])
                list_f1_coor2_x.append(list_coor2_x[i])
                list_f1_coor2_y.append(list_coor2_y[i])
                list_f1_d_x.append(list_d_x[i])
                list_f1_d_y.append(list_d_y[i])
                list_f1_d_l.append(list_d_l[i])
        
        #[Second Filtering]
        #[10] Before second filtering, initiate empty lists and gather information.
        f1_mean_d_l = np.mean(list_f1_d_l)
        f1_std_d_l = np.std(list_f1_d_l)
        list_f2_coor2_x, list_f2_coor2_y = [], []
        list_f2_coor1_x, list_f2_coor1_y = [], []
        list_f2_d_x, list_f2_d_y, list_f2_d_l = [], [], []

        #[12] second filtering
        d_upper_lmt, d_lower_lmt \
            = f1_mean_d_l + f2_dl_std_limit * f1_std_d_l\
                , f1_mean_d_l - f2_dl_std_limit * f1_std_d_l
        print(f'\n--[Second filtering]\n--Removing displacement outside the range of {f2_dl_std_limit} standard deviations.')
        for i, iter_d_l in enumerate(list_f1_d_l):
            if d_lower_lmt <= iter_d_l and iter_d_l <= d_upper_lmt:
                #[15] Collect lists
                list_f2_coor1_x.append(list_f1_coor1_x[i])
                list_f2_coor1_y.append(list_f1_coor1_y[i])
                list_f2_coor2_x.append(list_f1_coor2_x[i])
                list_f2_coor2_y.append(list_f1_coor2_y[i])
                list_f2_d_x.append(list_f1_d_x[i])
                list_f2_d_y.append(list_f1_d_y[i])
                list_f2_d_l.append(list_f1_d_l[i])
            
        #[20] Update the original lists with the filtered ones
        before_filtering, after_filtering = len(list_d_l), len(list_f2_d_l)
        
        print(f'--Outliers (before, after, removed) = ({before_filtering}, {after_filtering}, {before_filtering - after_filtering})')

    return (list_f2_coor1_x, list_f2_coor1_y
            , list_f2_coor2_x, list_f2_coor2_y
            , list_f2_d_x, list_f2_d_y, list_f2_d_l)
    
    
def mark_good_matches_on_img(list_d_l, list_coor2_x, list_coor2_y, path_image, bsn = '3-marked'):
    print('\n[mark_good_matches_on_img]')
    print(f'[list_d_l] {list_d_l[:5]}')
    print(f'[list_coor2_x] {list_coor2_x[:5]}')
    print(f'[list_coor2_y] {list_coor2_y[:5]}')
    
    #[1] Load the image from the given path
    img2 = cv2.imread(path_image)
    if img2 is None:
        raise FileNotFoundError(f"No image found at {path_image}")
    
    #[10] Set font size.
    esfs, esft = 1.2, 4     # mm = Max and min; es = else
    s_cir = 15

    #[2] Calculate max, min, and range.
    max_displs = np.round(np.max(list_d_l), 4)
    min_displs = np.round(np.min(list_d_l), 4)
    rangeMm = np.round(max_displs - min_displs, 4)   # Range = Max - min
    print(f'(max_displs, min_displs, rangeMm) = ({max_displs}, {min_displs}, {rangeMm})')
    if rangeMm == 0:
        rangeMm = 1  # Prevent division by zero if all displacements are the same

    #[3] Iterate over all good matches and their corresponding displacements
    list_location = []
    for i, (iter_x, iter_y) in enumerate(zip(list_coor2_x, list_coor2_y)):
        if i not in [np.argmin(list_d_l), np.argmax(list_d_l)]:
            #[5] Create a tuple of (x, y) coordinates from separate lists
            location = (int(iter_x), int(iter_y))
            
            #[6] Draw a circle at the keypoint location
            scale = (list_d_l[i] - min_displs) / rangeMm
            scale_10 = s_cir
            scale_288 = int(288 * scale)                # Deliberatly exceed 255 to have better visual effect.
            cv2.circle(img2, location, scale_10, (255, 271 - scale_288, scale_288 - 16), -1) # From (255, 271, -16) to (255, -16, 271).
            
            #[8] Decide on the displacement text format based on min_displs
            text_shift = 20
            text = f'({iter_x:.0f},{iter_y:.0f})'
            text_location = (location[0] + text_shift, location[1] + text_shift)
            list_location.append(location)
            
            #[10] Make extrema later, so that they are on top of other points.
            if i != np.argmin(list_d_l) or i != np.argmax(list_d_l):
                cv2.putText(img2, text, text_location, cv2.FONT_HERSHEY_SIMPLEX, esfs, (40, 40, 40), esft) 

    
    
    #[12] Save the result with a modified file name to indicate marking
    img_ext = os.path.splitext(path_image)[1]
    path_marked_image = path_image.replace(img_ext, f'_{bsn}{img_ext}')
    cv2.imwrite(path_marked_image, img2)

    return (list_d_l, list_coor2_x, list_coor2_y, path_marked_image)

   
    
    
        
def calculate_displacement(dir_img_folder, direction):
    print('\n[calculate_displacement]')
    #[1] Filter file
    list_kwd_no_or_1 = ['crop', 'enh']
    list_image_name = M1UTL.filter_file_in_dir_with_keywords(dir_img_folder, 
                                                            list_kwd_no_or_1=list_kwd_no_or_1)[1]
    
    #[2] Sort file with time and get the two most recently created files
    list_image_name.sort(key=lambda file: os.path.getctime(os.path.join(dir_img_folder, file)), reverse=True)
    latest_two_images = list_image_name[:2]
    print('latest_two_images: ', latest_two_images)
    path_img_t1 = os.path.join(dir_img_folder, latest_two_images[1])
    path_img_t2 = os.path.join(dir_img_folder, latest_two_images[0])

    #[3] Create dataframe
    df_ImgTable = pd.DataFrame()
    df_ImgTable['Image Name'] = latest_two_images
    df_ImgTable['Image Number'] = ('t2', 't1')

    #[4] Size correction and image enhancement.
    path_img_t1, path_img_t2 = M1UTL.crop_to_same_size(path_img_t1, path_img_t2)
    clipLimit, tileGridSize = 2, 8
    path_img_t1_enh = M1UTL.enhance_image(path_img_t1, clipLimit, tileGridSize)
    path_img_t2_enh = M1UTL.enhance_image(path_img_t2, clipLimit, tileGridSize)
    img_t1, img_t2 = cv2.imread(path_img_t1_enh, 1), cv2.imread(path_img_t2_enh, 1)

    #[5] Detect displacment.
    #displacements, keypoints2 = find_good_matches_SIFT(img_t1, img_t2)
    list_good_matches, keypoints1, keypoints2 = find_good_matches_SIFT(img_t1, img_t2, LR=0.8)
    (list_coor1_x, list_coor1_y
    , list_coor2_x, list_coor2_y
    , list_d_x, list_d_y, list_d_l) = convert_match_to_lists(list_good_matches, keypoints1, keypoints2)
    
    #[7] Refine filtering
    (list_coor1_x, list_coor1_y
    , list_coor2_x, list_coor2_y
    , list_d_x, list_d_y, list_d_l) = refining_match_quality(list_coor1_x, list_coor1_y
                                                                    , list_coor2_x, list_coor2_y
                                                                    , list_d_x, list_d_y, list_d_l
                                                                    , 1.5, 0.5)
                            
    #[8] Mark displacement on image.
    mark_good_matches_on_img(list_d_l, list_coor2_x, list_coor2_y, path_img_t2, bsn = '3-marked')
    

    #[10] Calculate camera correction angle.
    dx, dy = np.mean(list_d_x), -np.mean(list_d_y)  # In computer image, +x is right and +y is down.
    print(f'Displacements (Cartesian Coordinate): \t{[dx, dy]}')

    if dx == 0 and dy == 0:         
        print('[Error] I think the stage did not move.')
        return
    elif dx == 0:
        arctan_dy_dx = 90
    else:
        arctan_dy_dx = round(np.rad2deg(np.arctan(dy/dx)))
        """
        Be careful for the math in this part.
        1. All clockwise has been counter-clockwise because microscope is inveted image.
        """
        if direction == 'X':
            if dx >= 0 and dy >= 0 :    # Quadrant I
                text_result = f'X[Quadrant I] Please turn the camera counter-clockwise by { arctan_dy_dx} degrees.'              #[Case B] (dx,dy) = (1.7, 1), arctan(1/1.7) = 30
                shift_to = 'Q-I'
            elif dx < 0 and dy >= 0 :   # Quadrant II
                text_result = f'X[Quadrant II] Please turn the camera counter-clockwise by {180 + arctan_dy_dx} degrees.'        #[Case C] (dx,dy) = (-1, 1.7), arctan(1.7/-1) = -60
                shift_to = 'Q-II'
            elif dx < 0 and dy < 0 :    # Quadrant III
                text_result = f'X[Quadrant III] Please turn the camera clockwise by {90 + arctan_dy_dx} degrees.'                #[Case D] (dx,dy) = (-1.7, -1), arctan(-1/-1.7) = 30
                shift_to = 'Q-III'
            elif dx >= 0 and dy < 0 :    # Quadrant IV
                text_result = f'X[Quadrant IV] Please turn the camera clockwise by {-arctan_dy_dx} degrees.'                     #[Case A] (dx,dy) = (1.7, -1), arctan(-1/1.7) = -30
                shift_to = 'Q-IV'
                
        elif direction == 'Y':
            if dx >= 0 and dy >= 0 :    # Quadrant I
                text_result = f'Y[Quadrant I] Please turn the camera clockwise by {90 - arctan_dy_dx} degrees.'                  #[Case A] (dx,dy) = (1, 1.7), arctan(1.7/1) = 60
                shift_to = 'Q-I'
            elif dx < 0 and dy >= 0 :   # Quadrant II
                text_result = f'Y[Quadrant II] Please turn the camera counter-clockwise by {90 + arctan_dy_dx} degrees.'         #[Case B] (dx,dy) = (-1, 1.7), arctan(1.7/-1) = -60
                shift_to = 'Q-II'
            elif dx < 0 and dy < 0 :    # Quadrant III
                text_result = f'Y[Quadrant III] Please turn the camera counter-clockwise by {90 + arctan_dy_dx} degrees.'        #[Case C] (dx,dy) = (-1.7, -1), arctan(-1/-1.7) = 30
                shift_to = 'Q-III'
            elif dx >= 0 and dy < 0 :    # Quadrant IV
                text_result = f'Y[Quadrant IV] Please turn the camera clockwise by {90 - arctan_dy_dx} degrees.'                 #[Case D] (dx,dy) = (1.7, -1), arctan(-1/1.7) = -30        {90 - arctan_dy_dx}
                shift_to = 'Q-IV'
                
    print(f'\n\n{text_result}\n\n--(direction, shift_to, arctan_dy_dx): {direction}, {shift_to}, {arctan_dy_dx}.')
    
    #[14] Rename file with shift info
    #path_img_t2_new = path_img_t2.replace('-1_', f'-1_{shift_to}_{arctan_dy_dx}deg_')
    bsn_ext = os.path.basename(path_img_t2)
    bsn, ext = os.path.splitext(bsn_ext)
    path_img_t2_new = os.path.join(dir_img_folder, f'{bsn}_{shift_to}_{arctan_dy_dx}deg_{ext}')
    os.rename(path_img_t2, path_img_t2_new)
   
    #[15] Dump enhanced image files.
    list_kwd_yes_or_1 = ['enh']
    list_kwd_no_or_1  = []
    M1UTL.batch_file_relocate(dir_img_folder, list_kwd_yes_or_1, list_kwd_no_or_1, '01_dump', False)
    print('--Take a break for 1 seconds.', end='\n\n')
    time.sleep(1)
    return text_result



def start_camera_streaming_for_azimuth_angle_corr(cam_idx, dir_save):
    print('\n[start_camera_streaming]')
    
    #[1] Open serial port for Arduino first.
    ser = serial.Serial('COM3', 9600, timeout=2)
    print('--Serial to Arduino opened. Wait for 2 seconds.')
    time.sleep(2)  
    print('--Opening VideoCapture. Wait for about 2 seconds.')
    
    #[2] Open camera
    capture = cv2.VideoCapture(cam_idx) # Open the first camera device
    time.sleep(2)  
    if not capture.isOpened():
        print("Error: Couldn't open the camera.")
        return
    while True:
        ret, frame = capture.read()
        if not ret:
            print("Error: Couldn't capture a frame.")
            break
        
        #[4] X direction
        move_stage_capture_image_and_move_back(capture, ser, frame, 'X', dir_save)
        text_result_X = calculate_displacement(dir_save, 'X')
        
        #[5] Y direction
        move_stage_capture_image_and_move_back(capture, ser, frame, 'Y', dir_save)
        text_result_Y = calculate_displacement(dir_save, 'Y')
        break

    #[6] Release the capture and close windows at the end.
    capture.release()
    cv2.destroyAllWindows()
    ser.close()
    print('--Camera and serial port closed.')
    
    return text_result_X, text_result_Y


