"""
[USBC-2_(consecutive image capture).py]
Purpose: Capture one image per second and calculate sharpness value.
Author: Meng-Chi Ed Chen
Date: 2023-06-06
Reference:
    1. Open camera then open serial results in access denied.
    2.

Status: Complete.
"""
import os, sys, cv2, time, serial
import numpy as np
from datetime import datetime




def autofocus_routine_trend_test(capture, ser, dir_captured, Z_coord_um, list_sharpness, list_Z_coord_um, Z_direction = 'up'):
    print('\n[autofocus_routine_trend_test]')
    #[1] Set direction test attemp.
    total_attempts = 3
    
    #[2] Start direction test. (Move z-axis in one direction to see if the sharpness increases.)
    for attempt in range(total_attempts):
        sharpness = capture_and_save(capture, ser, Z_coord_um, dir_captured, len(list_sharpness))
        if sharpness is not None:
            print(f'--[Attempt {attempt}] sharpness: {round(sharpness, 3)}')
            list_sharpness.append(sharpness)
            list_Z_coord_um.append(Z_coord_um)
            
            #[5] Move Z-axis
            if Z_direction == 'up':
                ser.write('I\n'.encode()) # Case "I" move Z up(+) for 10 um (0.01 mm).
                Z_coord_um += 10
            elif Z_direction == 'down':
                    ser.write('L\n'.encode()) # Case "L" move Z down(-) for 10 um (0.01 mm).
                    Z_coord_um += 10  
            
            print(f'--  Moving linear stage to Z={Z_coord_um} um.')
        else:
            print("Error: Autofocus routine failed to capture an image.")
            break

    #[3] Exam direction test result.
    print('\nTrend test result:')
    last_three_sharpness = list_sharpness[-3:]
    
    #[4] If AND(s0<s1, s1<s2, s2<s3), that means the image is getting sharper, and we are in the right direction (toward focus).
    if all(iter_s < list_sharpness[cnt+1] for cnt, iter_s in enumerate(last_three_sharpness[:-1])):
        print(f'--Right direction! Moving toward focus. Keep moving +Z.')
        trend = 'higher_Z'
    
    #[5] If AND(s0>s1, s1>s2, s2>s3), that means the image is getting blurer, and we are in the wrong direction (away from focus).
    elif all(iter_s > list_sharpness[cnt+1] for cnt, iter_s in enumerate(last_three_sharpness[:-1])):
        print(f'--Wrong direction! Moving away from focus. Trun around and move toward -Z.')
        trend = 'lower_Z'
        
        #[10] Moving stage back to original position
        ser.write(f'L{total_attempts}\n'.encode())  # Case "L" move Z down(-) for 10 um (0.01 mm).
        Z_coord_um -= 10*(total_attempts)  # Assuming 10 um increment for example
        print(f'--Moving linear stage back to Z={Z_coord_um} um')
    
    #[16] If blur metric inconsistant
    else:
        print(f'--Blur metric trend is inconsistent. {list_sharpness}')
        
        #[20] Move Z back
        
        
        
        trend = None
        
    return trend, Z_coord_um, list_sharpness, list_Z_coord_um




def autofocus_routine_real(capture, ser, dir_captured, total_attempts, trend, Z_coord_um, list_sharpness, list_Z_coord_um):
    print('\n[autofocus_routine_real]')
    existing_len = len(list_sharpness)
    last_sharpness = list_sharpness[-1]
    Z_coord_um
    for attempt in range(total_attempts):
        current_sharpness = capture_and_save(capture, ser, Z_coord_um, dir_captured, len(list_sharpness))
        if current_sharpness is not None:
            print(f'\n[Attempt {attempt}] sharpness: {round(current_sharpness, 3)}')
            list_sharpness.append(current_sharpness)
            list_Z_coord_um.append(Z_coord_um)
            # Move Z-axis
            if trend == 'lower_Z':
                ser.write('L\n'.encode())
                Z_coord_um -= 10
            elif trend == 'higher_Z':
                ser.write('I\n'.encode())
                Z_coord_um += 10
            else:
                raise TypeError('Check trend: {trend}.')
            print(f'--Moving linear stage to Z={Z_coord_um} um')
        else:
            print("Error: Autofocus routine failed to capture an image.")
            break
        
        print(f'--current_sharpness: {current_sharpness}')
        print(f'--last_sharpness:    {last_sharpness}')
        if current_sharpness > last_sharpness:
            print('--Found point with maximum sharpness.')
        last_sharpness = current_sharpness # Update the last sharpness.

    
    #[8] Move to point with maximum sharpness.
    index = list_sharpness.index(max(list_sharpness))
    focus_sharpness = list_sharpness[index]
    focus_Z_coord_um = list_Z_coord_um[index]
    
    #[11] If final Z is lower than focused Z.
    if Z_coord_um > focus_Z_coord_um:
        repeat = int((Z_coord_um - focus_Z_coord_um)/10)
        print('--Z_coord_um > focus_Z_coord_um', repeat)
        
        #[10] Case "L" move Z down(-) for 10 um (0.01 mm).
        for i in range(repeat):
            ser.write(f'L\n'.encode())
            Z_coord_um -= 10
            print(f'--[{i}] Moving linear stage to Z={Z_coord_um} um.')
            time.sleep(1)
            
    #[11] If final Z is higher than focused Z.
    elif Z_coord_um < focus_Z_coord_um:
        repeat = int((focus_Z_coord_um - Z_coord_um)/10)
        print('--Z_coord_um < focus_Z_coord_um', repeat)
        
        #[11] Case "I" move Z up(+) for 10 um (0.01 mm).
        for i in range(repeat):
            ser.write(f'I\n'.encode())
            Z_coord_um -= 10
            print(f'--[{i}] Moving linear stage to Z={Z_coord_um} um.')
            time.sleep(1)
    
        
    #[15] Take the last image
    current_sharpness = capture_and_save(capture, ser, Z_coord_um, dir_captured, len(list_sharpness))
    list_sharpness.append(current_sharpness)
    list_Z_coord_um.append(Z_coord_um)
    return list_sharpness, list_Z_coord_um




def start_camera_streaming_for_auto_focus(camera_number, dir_captured, total_attempts):
    print('\n[start_camera_streaming_for_auto_focus]')
    
    #[1] Check if directory exist.
    try:
        os.mkdir(dir_captured)
        print(f'--Directory was not exists. Just made one. {dir_captured}')
    except FileExistsError:
        print('--Directory already exists. Skipping directory creation.')
    
    #[2] Set up serial communication.
    ser = serial.Serial('COM3', 9600, timeout=2)
    time.sleep(2)
    capture = cv2.VideoCapture(camera_number)
    if not capture.isOpened():
        print("Error: Couldn't open the camera.")
        return
    
    #[3] First focus temp to see the trend.
    list_sharpness = []
    list_Z_coord_um = []
    Z_coord_um = 0
    trend, Z_coord_um, list_sharpness, list_Z_coord_um = autofocus_routine_trend_test(capture, 
                                                                                                ser, 
                                                                                                dir_captured,
                                                                                                Z_coord_um, 
                                                                                                list_sharpness, 
                                                                                                list_Z_coord_um)
    #[4] If the trend is not obvious, jump away and measure again.
    if trend == None:
        ser.write('R\n'.encode()) # Case "R" move Z down(-) for 100 um (0.1 mm).
        Z_coord_um -= 100
        print(f'--Moving linear stage to Z={Z_coord_um} um, because we might be too close to focus point.')
        trend, Z_coord_um, list_sharpness, list_Z_coord_um = autofocus_routine_trend_test(capture,
                                                                                                    ser,
                                                                                                    dir_captured,
                                                                                                    Z_coord_um, 
                                                                                                    list_sharpness,
                                                                                                    list_Z_coord_um)
        
    #[5] Start auto focus

    list_sharpness, list_Z_coord_um = autofocus_routine_real(capture, 
                                                                   ser, 
                                                                   dir_captured, 
                                                                   total_attempts, 
                                                                   trend, 
                                                                   Z_coord_um, 
                                                                   list_sharpness, 
                                                                   list_Z_coord_um)
    
    
    #[6] Save focusing record.
    timestamp = datetime.now().strftime("%Y-%m%d-%H%M%S")
    path_plot_save = os.path.join(dir_captured, f'{timestamp}_auto_focus_plot.png')
    capture.release()
    ser.close()
    plot_auto_focus_result(list_sharpness, list_Z_coord_um, path_plot_save)
    print('\n[list_sharpness]:', list_sharpness)
    print('\n[list_Z_coord_um]:', list_Z_coord_um)
# End of [M9_bkup.py]




