def reduce_size(img_path, dir_img_folder, ratio):
      global path_reduced_img
      image = Image.open(img_path)
      # Calculate crop dimensions
      crop_width = int(image.width * 0.1)
      crop_height = int(image.height * 0.1)
      cropped_image = image.crop((crop_width, crop_height, image.width - crop_width, image.height - crop_height))
      # Calculate compress dimensions
      tenth_width = cropped_image.width // ratio
      tenth_height = cropped_image.height // ratio
      reduced_img = cropped_image.resize((tenth_width, tenth_height), Image.NEAREST)
      #Save
      path_reduced_img = img_path.replace('.png','_1-reduced.png')
      reduced_img.save(path_reduced_img) # Must save this.


def quick_correction(img_path, dir_img_folder):
      global path_binary_img
      image = cv2.imread(img_path)
      #[boxBlur]
      blurred_image = cv2.blur(image,(5,5))
      path_blurred_image = img_path.replace('_1-reduced.png','_2-blurred.png')
      #cv2.imwrite(path_blurred_image, blurred_image)
      #[Grayscale]
      gray_image = cv2.cvtColor(blurred_image, cv2.COLOR_BGR2GRAY)  # Convert to grayscale
      path_grayscaled_img = img_path.replace('_1-reduced.png','_3-grayscaled.png')
      cv2.imwrite(path_grayscaled_img, gray_image)
      #[Binary]
      binary_image = cv2.adaptiveThreshold(gray_image, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C, cv2.THRESH_BINARY, 19, 2)
      path_binary_img = img_path.replace('_1-reduced.png','_4-binary.png')
      cv2.imwrite(path_binary_img, binary_image)
      #[medianBlur]
      blurred_image = cv2.medianBlur(binary_image, ksize=9)
      path_blurred_image = img_path.replace('_1-reduced.png','_5-blurred.png')
      cv2.imwrite(path_blurred_image, blurred_image)


def edge_detection(img_path, dir_img_folder):
      global path_sobelxy_img
      image = cv2.imread(img_path)
      sobelxy_img = cv2.Sobel(src = image, ddepth=cv2.CV_64F, dx=1, dy=1, ksize=5) # Combined X and Y Sobel Edge Detection
      #Save
      path_sobelxy_img = img_path.replace('_4-corrected.png','_6-sobelxy.png')
      cv2.imwrite(path_sobelxy_img, sobelxy_img)


for iter_file in full_directory_list:
      #[] Start the timer
      start_time = time.time()


      reduce_size(iter_file, dir_img_folder, 10)
      quick_correction(path_reduced_img, dir_img_folder)
      #edge_detection(path_corrected_img, dir_img_folder)


      #[] Stop the timer
      end_time = time.time()
      print("Execution Time:", round(end_time - start_time, 5), "seconds")


