import numpy as np
import cv2
import sys
import random


path_image = r'D:\01_Floor\a_Ed\16_Coding\03_Python\04_OngoingTools\2023-0706_Image Line Detection with Hough\ILH-1_Test image\0034_10X_3-grayScaled.png'


def find_Harris_Corner(img_path):
    global path_corner_img

    img_gray = cv2.imread(img_path, cv2.IMREAD_GRAYSCALE)
    img = np.zeros_like(img_gray)

    print('gray.shape:', img_gray.shape)
    print('img.shape:', img.shape)


    # find Harris corners
    dst = cv2.cornerHarris(img_gray, blockSize = 2, ksize = 3, k = 1)
    dst = cv2.dilate(dst, None) #result is dilated for marking the corners, not important
    ret, dst = cv2.threshold(dst, 0.01 * dst.max(), 255, 0)
    dst = np.int64(dst)

    # find centroids
    ret, labels, stats, centroids = cv2.connectedComponentsWithStats(dst)

    # define the criteria to stop and refine the corners
    criteria = (cv2.TERM_CRITERIA_EPS + cv2.TERM_CRITERIA_MAX_ITER, 100, 0.001)
    corners = cv2.cornerSubPix(img_gray, np.float32(centroids), (5, 5), (-1, -1), criteria)

    # Now draw them
    res = np.hstack((centroids, corners))
    res = np.int64(res)

    print('res:', res)

    for point in res:
        x, y, subpixel_x, subpixel_y = point
        print('point:', point)
        print(x, y, subpixel_x, subpixel_y)

        cv2.circle(img, (x, y), 10, (240, 176, 0), -1)
        cv2.circle(img, (subpixel_x, subpixel_y), 5, (240, 176, 0), -1)
        
    #cv2.circle(img, (int(random.randint(5,90)), int(random.randint(5,90))), 5, (255, 255, 0), -1)

    path_corner_img = path_image.replace('.png', '_corner.png')
    cv2.imwrite(path_corner_img, img)
    print('path_corner_img:', path_corner_img)
    
    
find_Harris_Corner(path_image)
# End of [ILH-6_(Harris Corner Detection) copy.py]




