def get_working_cameras():
    print('\n[get_working_cameras]')
    # [1] Define the maximum number of cameras to check, and initiate list
    max_cameras = 10
    list_cam = []
    
    # [3] Loop through the potential camera indices
    for num_cam in range(max_cameras):
        # [4] Try to open the camera
        name_cam = cv2.VideoCapture(num_cam)
        
        # [5] Check if the camera is opened successfully
        if name_cam.isOpened():
            # [6] Get camera properties
            width = name_cam.get(cv2.CAP_PROP_FRAME_WIDTH)
            height = name_cam.get(cv2.CAP_PROP_FRAME_HEIGHT)
            fps = name_cam.get(cv2.CAP_PROP_FPS)
            
            list_cam.append({
                "name_cam": name_cam,
                "Camera Index": num_cam,
                "Status": "Working",
                "Resolution": f"{int(width)}x{int(height)}",
                "FPS": fps
            })
        else:
            break
    
    # [7] Create a DataFrame from the list of cameras
    df_working_cam = pd.DataFrame(list_cam)
    
    # [8] Return the DataFrame
    return df_working_cam


