def phase_correlation(img1_cropped, img2_cropped):
    print('\n[phase_correlation]')
    # Convert the images to grayscale
    img_t1_gray = cv2.cvtColor(img1_cropped, cv2.COLOR_BGR2GRAY)
    img_t2_gray = cv2.cvtColor(img2_cropped, cv2.COLOR_BGR2GRAY)
    # Apply the Fourier Transform to both images
    f1 = np.fft.fft2(img_t1_gray)
    f2 = np.fft.fft2(img_t2_gray)
    # Compute the cross-power spectrum
    denom = np.abs(f1) * np.abs(f2)
    denom[denom == 0] = 1  # avoid division by zero
    cross_power = f1 * np.conj(f2) / denom
    # Compute the inverse Fourier Transform
    shift = np.fft.ifft2(cross_power)
    shift_abs = np.abs(shift)
    # Get the displacement
    y, x = np.unravel_index(np.argmax(shift_abs), shift_abs.shape)
    # If the displacement is in the second half of the image, 
    # consider it as negative (this handles wrapping)
    if y > img_t1_gray.shape[0] // 2:
        y -= img_t1_gray.shape[0]
    if x > img_t1_gray.shape[1] // 2:
        x -= img_t1_gray.shape[1]
    return x, y

