def phase_correlation_rgb(img1_cropped, img2_cropped):
    print('\n[phase_correlation_rgb]')
    # Initialize displacement results for each channel
    displacements = []

    # Iterate over each color channel
    for i in range(3):
        # Extract the current channel from both images
        img_t1_channel = img1_cropped[:,:,i]
        img_t2_channel = img2_cropped[:,:,i]

        # Apply the Fourier Transform to both channel images
        f1 = np.fft.fft2(img_t1_channel)
        f2 = np.fft.fft2(img_t2_channel)

        # Compute the cross-power spectrum
        denom = np.abs(f1) * np.abs(f2)
        denom[denom == 0] = 1  # avoid division by zero
        cross_power = f1 * np.conj(f2) / denom

        # Compute the inverse Fourier Transform
        shift = np.fft.ifft2(cross_power)
        shift_abs = np.abs(shift)

        # Get the displacement
        y, x = np.unravel_index(np.argmax(shift_abs), shift_abs.shape)

        # Handle wrapping
        if y > img_t1_channel.shape[0] // 2:
            y -= img_t1_channel.shape[0]
        if x > img_t1_channel.shape[1] // 2:
            x -= img_t1_channel.shape[1]

        # Store displacement for the current channel
        displacements.append((x, y))

    return displacements

