def datetime_tag():
    # Get current date and time.
    now = datetime.datetime.now()
    current_date = now.strftime("%Y-%m-%d")
    current_time = now.strftime("%H-%M-%S")
    current_datetime = current_date + '_' + current_time
    return current_datetime

def start_camera_streaming(camera_number):
    #[1] Open serial port for Arduino first.
    ser = serial.Serial('COM3', 9600, timeout=2)
    time.sleep(2) 
    print('Serial opened. Wait for 2 seconds.')
    time.sleep(2)  
    print('Opening VideoCapture. Wait for about 10 seconds.')
    capture = cv2.VideoCapture(camera_number) # Open the first camera device
    if not capture.isOpened():
        print("Error: Couldn't open the camera.")
        return None, None
    return capture, ser


def check_displacement(capture, ser, direction):
    print('\n[check_displacement]')
    #[2] Capture camera image
    ret, frame = capture.read() # Capture frame-by-frame
    if not ret:
        print("Error: Couldn't capture a frame.")
        return # break
    cv2.imshow('Camera Stream', frame) # Display the resulting frame
    key = cv2.waitKey(1) & 0xFF
    time.sleep(1)  
    #[3] Capture camera image
    print('[Start camera angle correction]')
    #[3-1] Capture first image.
    path_capture_image = os.path.join(dir_captured, datetime_tag() + '.png')
    cv2.imwrite(path_capture_image, frame)
    print(f'First image captured, saved at {path_capture_image}')
    time.sleep(1)
    #[3-2] Move +X or +Y by 10 um.
    if direction == 'X':
        ser.write('M\n'.encode())
        time.sleep(1)
        print('Sent "M" to Arduino through serial, moving linear stage toward +X for 100 um.')
    elif direction == 'Y':
        ser.write('N\n'.encode())
        time.sleep(1)
        print('Sent "N" to Arduino through serial, moving linear stage toward +Y for 100 um.')
    time.sleep(10)
    #[3-3] Capture second image.
    path_capture_image = os.path.join(dir_captured, datetime_tag() + '.png')
    cv2.imwrite(path_capture_image, frame)
    print(f'Second image captured, saved at {path_capture_image}')
    time.sleep(5)
    print('Take a breath for 5 seconds.', end='\n\n')
        
        
def calculate_displacement(dir_img_folder, direction):
    print('\n[calculate_displacement]')
    list_keywords_select = ['crop', 'enh']
    F02_File.batch_file_relocate(dir_img_folder, list_keywords_select=list_keywords_select)
    list_keywords_discard = ['crop', 'enh']
    list_image_name = F02_File.filter_file_with_keywords(dir_img_folder, 
                                                         list_keywords_discard=list_keywords_discard)[1]
    #[2] Sort file with time and get the two most recently created files
    list_image_name.sort(key=lambda file: os.path.getctime(os.path.join(dir_img_folder, file)), reverse=True)
    latest_two_images = list_image_name[:2]
    print('latest_two_images: ', latest_two_images)
    path_img_t1 = os.path.join(dir_img_folder, latest_two_images[1])
    path_img_t2 = os.path.join(dir_img_folder, latest_two_images[0])

    #[3] Create dataframe
    df_ImgTable = pd.DataFrame()
    table_formate = 'orgtbl'
    df_ImgTable['Image Name'] = latest_two_images
    df_ImgTable['Image Number'] = ('t2', 't1')

    #[4] Size correction and image enhancement.
    path_img_t1, path_img_t2 = F09_OMcam.crop_to_same_size(path_img_t1, path_img_t2)
    clipLimit, tileGridSize = 2, 8
    path_img_t1, path_img_t2 =  F09_OMcam.enhance_image(path_img_t1, clipLimit, tileGridSize, 1),\
                                F09_OMcam.enhance_image(path_img_t2, clipLimit, tileGridSize, 1)
    img_t1, img_t2 = cv2.imread(path_img_t1, 1), cv2.imread(path_img_t2, 1)

    #[5] Detect displacment.
    displacements, key_point_info = F09_OMcam.calculate_displacement_sift(img_t1, img_t2)
    print('Displacements (Raster Coordinate):       ', np.ndarray.tolist(displacements))

    #[6] Calculate camera correction angle.
    dx, dy = displacements[0], -displacements[1]  # In computer image, +x is right and +y is down.
    print('Displacements (Cartesian Coordinate):    ', [dx, dy])
    
    if dx == 0 and dy == 0:
        print('[Error] I think the stage did not move.')
        return
    elif dx == 0:
       theta_miss = 90
    elif direction == 'X':
        theta_miss = round(np.rad2deg(np.arctan(dy/dx)))
    elif direction == 'Y':
        theta_miss = round(np.rad2deg(np.arctan(dy/dx))) + 90  #Check if this is correct!!!!
    
    print('theta_miss:', theta_miss)
    if dx >= 0 and dy >= 0 :    # Quadrant I
        print(f'[Quadrant I] Please trun the camera clockwise by {theta_miss} degrees.')
    elif dx < 0 and dy >= 0 :   # Quadrant II
        print(f'[Quadrant II] Please trun the camera clockwise by {180-theta_miss} degrees.')
    elif dx < 0 and dy < 0 :    # Quadrant III
        print(f'[Quadrant III] Please trun the camera counter-clockwise by {180-theta_miss} degrees.')  
    elif dx >= 0 and dy < 0 :    # Quadrant IV
        print(f'[Quadrant IV] Please trun the camera counter-clockwise by {-theta_miss} degrees.')
    time.sleep(5)
    print('Take a breath for 5 seconds.', end='\n\n')



def main(camera_number, dir_captured):
    camera_number = camera_number  # or whatever your camera number is
    capture, ser = start_camera_streaming(camera_number)
    if capture is None or ser is None:
        return  # Exit if there was an error initializing
    try:
        while True:
            print('Camera start streaming.')
            check_displacement(capture, ser, 'X')
            calculate_displacement(dir_captured, 'X')
            check_displacement(capture, ser, 'Y')
            calculate_displacement(dir_captured, 'Y')   
    except KeyboardInterrupt:
        print("Stopping...")
    finally:
        capture.release()
        cv2.destroyAllWindows()
        ser.close()




