# [Import modules]
from bs4 import BeautifulSoup
from urllib.request import Request, urlopen
import xlsxwriter
from datetime import datetime

# [Web Scrapping]
# Target url.
main_url = 'https://www.eecs.mit.edu/role/faculty/'
# Let servers identify us.
hdr = {'User-Agent': 'Mozilla/5.0'}

# Making the request wuth BeaitifulSoup module
req_1 = Request(main_url, headers=hdr)
page_1 = urlopen(req_1)
soup_1 = BeautifulSoup(page_1, features="html.parser")
# This prints the whole html text file: print(soup_1)

# Display the title.
print("Title of the website is: ", end = '')
for titles in soup_1.find_all('title'):
    individual_title  = titles.get_text()
    print(individual_title, end='\n\n')

# [Categorize research interest]
all_research_areas = set([])
for research_interests in soup_1.find_all('div', {"class": "people-research"}):
    for interests in research_interests.find_all('a', href=True):
        individual_interest = interests.get_text()
        all_research_areas.add(individual_interest)

all_research_areas = sorted(all_research_areas)
print('All research areas: ', all_research_areas, end='\n')
print('Count of research area = ', len(all_research_areas))
"""
# This prints all research areas.
for x in range(1, len(all_research_areas) + 1):
    print('%02d.' %x, list(all_research_areas)[x-1])
    """
print('')




# [Create Excel]
now = datetime.now()
current_date = now.strftime("%Y-%m-%d")
current_time = now.strftime("%H%M%S")

print("Date (yyyy-MM-dd) =", current_date)
print("Time (hhmmss) =", current_time)


# Create workbook and worksheet with desired name.
workbook = xlsxwriter.Workbook(current_date + '.xlsx')
worksheet = workbook.add_worksheet(individual_title)


# Display faculty list and count.
prof_count = 0
max_interest_cnt = 0
worksheet.write('A1', '[Name]')
worksheet.write('B1', '[Email]')
for x in range(1, len(all_research_areas) + 1):
    worksheet.write(0, x + 1, list(all_research_areas)[x-1])
    # print('%02d.' %x, list(all_research_areas)[x-1])


for professor_blocks in soup_1.find_all('div', {"class": "people-entry small-12 medium-6 large-4 larger-3 cell"}):
    prof_count = prof_count + 1
    row_num = prof_count
    individual_professor_block = professor_blocks.get_text()
    # print("[Professor ", str(prof_count).zfill(2), "]")

    for professor_names in professor_blocks.find_all('h5'):
        individual_professor_name = professor_names.get_text()
        # print(" " * first_indent, individual_professor_name, end='')
        worksheet.write(row_num, 0, individual_professor_name)

    for emails in professor_names.find_all('a', href=True):
        individual_email = emails.get('href')      # print(link['href'])
        # print(" " * (second_indent - len(individual_professor_name) + 5), individual_email)
        worksheet.write(row_num, 1, individual_email)

    for research_interests in professor_blocks.find_all('div', {"class": "people-research"}):
        interest_cnt = 0
        for interests in research_interests.find_all('a', href=True):
            interest_cnt = interest_cnt + 1
            individual_interest = interests.get_text()
            area_index = all_research_areas.index(individual_interest)
            # print(" " * first_indent, individual_interest)
            worksheet.write(row_num, 2 + interest_cnt - 1, str(area_index) + individual_interest)
        worksheet.write(row_num, 2 + len(all_research_areas), '[' + str(interest_cnt) + ' interests.]')
        if interest_cnt > max_interest_cnt: max_interest_cnt = interest_cnt

    # if prof_count >= 5:break # Break the loop for testing. [Remove Before Flight]

worksheet.set_column(0, 0, 20)
worksheet.set_column(1, 1, 5)
worksheet.set_column(2, max_interest_cnt + 1, 5)
workbook.close()
print("Faculty count: ", prof_count)





