def add_date_to_file_name(path_file, date_str, date_format='%Y-%m%d', print_status=False):
    """
    Add a date string to the file name before the file extension.
    
    Parameters:
    - path_file: The full path of the file.
    - date_str: The date string to add.
    - date_format: The format of the date string (default is '%Y-%m-%d').
    - print_status: Whether to print the status of the operation.
    
    Returns:
    - new_path_file: The new file path with the date added to the name.
    """
    try:
        #[1] Extract the base name and extension from the file path
        bsn_file = os.path.basename(path_file)
        bsn_ext = os.path.splitext(bsn_file)
        
        #[2] Create the new file name
        new_bsn_file = f"{date_str}_{bsn_ext[0]}{bsn_ext[1]}"
        
        #[3] Construct the new file path
        new_path_file = os.path.join(os.path.dirname(path_file), new_bsn_file)
        
        #[4] Rename the file
        os.rename(path_file, new_path_file)
        
        if print_status:
            print(f"File renamed from '{bsn_file}' to '{new_bsn_file}'")
        
        return new_path_file
    
    except Exception as e:
        print(f"Error adding date to file name: {e}")
        return None 


def batch_add_date_to_file_name(dir_folder, date_format='%Y-%m%d', print_status=False):
    print(f'\n[batch_add_date_to_file_name]')
    allowed_image_ext = ['.AVIF', '.HEIC', '.WEBP', '.TIF', '.TIFF', '.BMP', '.JPEG', '.JPG']
    
    print(f'-- dir_folder: {dir_folder}')
    
    #[1] Prepare file lists and create processed directory, ignoring .JPG
    list_path_original = [
        os.path.join(dir_folder, file)
        for file in os.listdir(dir_folder)
        if any(file.upper().endswith(ext) for ext in allowed_image_ext) 
    ]
        
    #[3] Prepare file lists and create processed directory
    cnt_original = len(list_path_original)
    print(f'-- list_path_original: {list_path_original}')

    #[5] Process each image file
    for i, path_original in enumerate(list_path_original):
        
        #[6] Skip if there is already a date-like format (yyyy-mmdd_) in the beginning of the file name.
        if re.match(r'^\d{4}-\d{4}_', os.path.basename(path_original)) or \
            re.match(r'^\d{4}-\d{2}_', os.path.basename(path_original)):
            print(f'-- Already have date. Skip: {path_original}')
            continue
        
        #[7] Check and add date to the file name.
        try:
            
            ext, media_datetime, method \
                = MD3I.retrieve_datetime_of_single_media_files(path_original, '%Y-%m%d')
            
            #[6] Add date to file name
            new_path_file = add_date_to_file_name(path_original, media_datetime, date_format, print_status)
            
            if print_status:
                print(f"[{i+1:03d}/{cnt_original:03d}] \tOriginal: {path_original} \tNew: {new_path_file}")
        
        except Exception as e:
            print(f"Error processing file '{path_original}': {e}")

