import os, sys, time, glob
from datetime import datetime
from tabulate import tabulate
from tkinter.filedialog import askdirectory


import MD1_Utilities as MD1U
import MD2_Files as MD2F
import MD3_Image as MD3I



#[1] Ask folder location
print('\nWelcome to Media Date Sorting.\nLet us turn your mements into memories.')
dir_sort = askdirectory(title='Select Folder')
#dir_sort = r'D:\01_Floor\a_Ed\09_EECS\10_Python\03_MatureTools\2022-0603_Media Date Sorting\MFS-5_MP4'

#[2] Start text name.
dir_bsn = os.path.basename(dir_sort)
timestamp = datetime.now().strftime("%Y-%m%d-%H%M%S")
text_3 = f'{timestamp}\n\nDirectory: {dir_sort}\n\n\n'
text_report = text_3
print(text_3)

#[3] Dump AAE fils.
list_paths, list_bsn = MD2F.batch_file_relocate(dir_sort, ['.AAE'], [], '01_AAE', print_bsn=False)
text_3 = f'[AEE] There are {len(list_bsn)} AEE files.\n\n\n'
text_report += text_3

#[4] Convert HEIC to JPG   
list_paths, list_error = MD3I.convert_HEIC_to_JPG_and_keep_EXIF_info(dir_sort, delete_or_remove=False, print_status=True)
text_error = print('\n[list_error]:\n' + '\n'.join(list_error))
text_4 = f'[HEIC] There are {len(list_paths)} HEIC files. \nHEIC conversion error ({len(list_error)}):\n{text_error}\n\n\n'
text_report += text_4

#[5] Filter files
list_kwd_yes_or_1 = ['.png', '.PNG', '.jpg', '.JPG', '.gif', '.GIF', 'mov', 'MOV', 'mp4', 'MP4']
list_kwd_no_or_1 = ['.txt', '.HEIC', '.bat']
list_path_media, list_bns_media = MD2F.filter_file_in_dir_with_keywords(dir_sort, list_kwd_yes_or_1, list_kwd_no_or_1, False)
text_5 = f'[Media] There are {len(list_bns_media)} media files. (PNG, JPG, GIF, or MOV)\n\n\n'
text_report += text_5

#[8] Start organizing each files.
list_media_datetime, list_media_ext, list_method = MD3I.retrieve_datetime_from_list_of_media_files(list_path_media
                                                                                                   , print_status=True
                                                                                                   , datetime_format = '%Y-%m-%d, %H:%M:%S')
list_result = MD3I.move_media_files_into_date_folders(list_path_media, list_media_datetime, print_status=True)

#[10] Searh large files.
mb_limit = 10
df_report = MD2F.file_type_statistic_in_dir_and_subdir(dir_sort, mb_limit, save_txt=False)
table = tabulate(df_report, headers='keys', tablefmt='orgtbl')
#print(f'[tabulet test]\n {table}')
text_10 = f'[Large] There are {len(df_report)} files over {mb_limit} Mb. \nPlease review them to save space.\n\n{table}\n\n\n'
text_report += text_10

#[12] Save report
path_report = os.path.join(dir_sort, f'{timestamp}_[{dir_bsn}].txt')
MD1U.create_txt_and_save_text(path_report, text_report, open_file=True)

#[20] Complete
print('\nComplete "MDS-10_Media Date Sorting". Close in 5 seconds.')
time.sleep(5)







