def add_one_more_row(df_latest):
    next_date = df_latest.index[-1] + pd.Timedelta(days=1)
    average_values = df_latest.mean()
    new_row = pd.DataFrame([average_values], index=[next_date])
    df_latest = pd.concat([df_latest, new_row])
    return df_latest
    
    
