def visualize_specified_parameters_1D(model, keyword, dir_image):
    print('\n[iter_specified_named_parameters]')
    for name, param in model.named_parameters():
        if keyword in name:
            #[1] Set up
            size = param.size(0)  # Assuming param is a 1D tensor for bias
            print(f'Parameter name: {name}; parameter size: {size}')

            #[2] Set up the figure and axes
            H_pixel = 600
            dpi = 300
            WH_ratio = 0.3
            W_inch, H_inch = round(WH_ratio * H_pixel/dpi, 3), round(H_pixel/dpi, 3)
            print(f'--figsize=({W_inch}, {H_inch})')
            fig, ax = plt.subplots(figsize=(W_inch, H_inch), dpi=dpi)

            #[2] Plot the 1D matrix (bias) in a vertical orientation
            vmin, vmax = -2, 2
            cax = ax.imshow(param.detach().numpy().reshape(-1, 1), cmap='seismic_r', aspect=0.2, vmin=vmin, vmax=vmax)
            ax.set_title(f'{name}', fontsize=5)  # Main title
            
            #[3] Adjust axes visibility and labels
            ax.set_xlabel('')  # Remove x-axis label as we want to keep only y-axis
            ax.set_yticks(np.arange(0, size, 10))  # Set y-ticks to represent every 10th parameter in the tensor
            ax.tick_params(axis='y', length=0, labelsize=4)  # Adjust y-tick label size
            
            #[4] Remove unnecessary spines and ticks
            ax.spines['top'].set_visible(False)
            ax.spines['right'].set_visible(False)
            ax.spines['bottom'].set_visible(False) 
            ax.spines['left'].set_visible(False)
            ax.xaxis.set_ticks([])  # Remove x-axis ticks

            #[6] Save the plot
            #plt.tight_layout()
            path_image = os.path.join(dir_image, keyword + '.png')
            plt.savefig(path_image)
            plt.close(fig)

    return path_image



def combine_horizontally(path_img_1, path_img_2, path_output, left_pad=0, right_pad=0):
    img1 = Image.open(path_img_1)
    img2 = Image.open(path_img_2)
    
    # Ensure both images have the same height
    height1 = img1.height
    height2 = img2.height
    if height1 != height2:
        # Resize the taller image to match the shorter image's height
        new_height = min(height1, height2)
        if height1 > height2:
            # Calculate resized width maintaining the aspect ratio
            new_width = int(img1.width * (new_height / height1))
            img1 = img1.resize((new_width, new_height), Image.ANTIALIAS)
        else:
            # Calculate resized width maintaining the aspect ratio
            new_width = int(img2.width * (new_height / height2))
            img2 = img2.resize((new_width, new_height), Image.ANTIALIAS)
    
    # Calculate total width using the resized images
    total_width = img1.width + img2.width + left_pad + right_pad
    height = new_height  # Both images now have the same height
    
    # Create a new image with the calculated dimensions
    new_img = Image.new('RGB', (total_width, height), (255, 255, 255))
    new_img.paste(img1, (left_pad, 0))  # Paste img1 at the left
    new_img.paste(img2, (left_pad + img1.width, 0))  # Paste img2 next to img1
    
    # Save the new image
    new_img.save(path_output)
    return path_output



def combine_vertically(path_img_1, path_img_2, path_output, top_pad = 0, bottom_pad = 0):
    img1 = Image.open(path_img_1)
    img2 = Image.open(path_img_2)
    #[1] Ensure both images have the same height
    width1 = img1.width
    width2 = img2.width
    if width1 != width2:
        raise ValueError("Images do not have the same width")
    #[2] Calculate total width and the same height
    total_height = img1.height + img2.height + top_pad + bottom_pad
    width = img1.width
    # Create a new image with the calculated dimensions
    new_img = Image.new('RGB', (width, total_height), (255, 255, 255))
    new_img.paste(img1, (0, top_pad))  # Paste img1 at the left
    new_img.paste(img2, (0, top_pad + img1.height))  # Paste img2 next to img1
    #[3] Save the new image
    new_img.save(path_output)
    return path_output



