#[] Directory, file names, and sheet names.
dir_data_excel = r'D:\01_Floor\a_Ed\16_Coding\03_Python\04_OngoingTools\2022-0614_Stock Price Prediction\SPP-1_Stock Price Data'
dir_model = r'D:\01_Floor\a_Ed\16_Coding\03_Python\04_OngoingTools\2022-0614_Stock Price Prediction\SPP-2_Models and Training Record'
path_data_excel = F02_File.tkinter_select_file(dialog_title = 'Choose Training Data')
basename_data_excel =  os.path.basename(path_data_excel)
sheet_name_1 = '1_TD' # TD = Trade data.
