#[] Record training result after training.
post_training_record = '\n[post_training_record]' \
                        + '\ntraining_time: ' + str(training_time) + ' sec.' \
                        + '\ntest_loss: ' + str(test_loss) \
                        + '\n\n' + str(str_model_summary)
str_train_settings = pre_training_record + post_training_record
history_plot_name = model_name + '_history-plot.png'
path_history_plot_save = os.path.join(dir_model, history_plot_name)
