# Set date search range
date_range_start = datetime(2020, 1, 1)
date_range_iteration_max = 12

for date_range_iteration in range(1, date_range_iteration_max + 1):
    # Date range iteration
    date_to_search = date_range_start + relativedelta(month=1*date_range_iteration)
    # Encode date range
    max_search_date = (date_to_search - timedelta(days=0)).strftime("%#m/%#d/%Y")
    min_search_date = (date_to_search - timedelta(days=30)).strftime("%#m/%#d/%Y")

    print('max_search_date = ', max_search_date, ', min_search_date = ', min_search_date, '.')
    date_range_appendex = ':1,cd_min:' + min_search_date + ',cd_max:' + max_search_date
    date_range_appendex_UTF_8 = '&tbs=cdr' + urllib.parse.quote(date_range_appendex, safe='')
    print(date_range_appendex_UTF_8)
    # https://www.google.com/search?q=%E5%8F%B0%E7%A9%8D%E9%9B%BB&source=lnt

    if date_range_iteration == 3:
        break

    # Generate Target URL
    main_url = 'https://www.google.com/search?q=' + company_UTF_8 + date_range_appendex_UTF_8 + '&tbm=nws'
