"""
SPP-1_Stock-price-from-yahoo-plot.py
Purpose: Fetch stock price and plot
Author: Ed Chen
Date: 2021-1202
"""

import pandas
import pandas_datareader as pdr
from datetime import datetime
from plotly.subplots import make_subplots
from plotly.offline import plot
import plotly.graph_objects as go
from tabulate import tabulate
from ta.volatility import BollingerBands


# Check datetime
now = datetime.now()
current_date = now.strftime("%Y-%m-%d")
current_time = now.strftime("%H%M%S")
print("Date =", current_date)
print("Time =", current_time)

# Stock price data range
start_date = datetime(2021, 1, 1)
end_date = now # datetime(2022, 1, 1)
# Get stock price from Yahoo.
taiwan_stock_symbol = '2330.TW'
TW2330 = pdr.get_data_yahoo(symbols=taiwan_stock_symbol, start=start_date, end=end_date)
print('Data Type: ' + str(type(TW2330)))


# Open secondary axis.
fig1 = make_subplots(specs=[[{"secondary_y": True}]])
# Plot OHLC on main axis.
fig1.add_trace(go.Candlestick(x=TW2330.index,
                              open=TW2330['Open'],
                              high=TW2330['High'],
                              low=TW2330['Low'],
                              close=TW2330['Close']
                              ))
close_max_value = TW2330['Close'].max()
close_min_value = TW2330['Close'].min()
fig1.update_yaxes(range=[close_min_value*0.9, close_max_value*1.05], secondary_y=False)

# Moving average.
fig1.add_trace(go.Scatter(x=TW2330.index,
                          y=TW2330['Close'].rolling(window=20).mean(),
                          marker_color='blue',
                          name='20 Day MA'))

# Color of volume bar.
TW2330['Volume-diff'] = TW2330['Volume'] - TW2330['Volume'].shift(1)
TW2330.loc[TW2330['Volume-diff'] >= 0, 'Volume-color'] = 'green'
TW2330.loc[TW2330['Volume-diff'] < 0, 'Volume-color'] = 'red'
# Volume chart.
volume_max_value = TW2330['Volume'].max()
fig1.add_trace(go.Bar(x=TW2330.index,
                      y=TW2330['Volume'],
                      name='Volume',
                      marker={'color': TW2330['Volume-color']}), secondary_y=True)
fig1.update_yaxes(range=[0, volume_max_value*10], secondary_y=True)
fig1.update_yaxes(visible=False, secondary_y=True)
fig1.update_layout(xaxis_rangeslider_visible=True)  # You can also hide the range slider.


# Initialize Bollinger Bands Indicator
indicator_bb = BollingerBands(close=TW2330["Close"], window=20, window_dev=2)

# Add Bollinger Bands and Indicators.
TW2330['bb_bbm'] = indicator_bb.bollinger_mavg()
TW2330['bb_bbh'] = indicator_bb.bollinger_hband()
TW2330['bb_bbl'] = indicator_bb.bollinger_lband()
TW2330['bb_bbhi'] = indicator_bb.bollinger_hband_indicator()*TW2330["Close"]
TW2330['bb_bbli'] = indicator_bb.bollinger_lband_indicator()*TW2330["Close"]
fig1.add_trace(go.Scatter(x=TW2330.index,
                          y=TW2330['bb_bbh'],
                          marker_color='skyblue',
                          name='Bollinger Band High'))
fig1.add_trace(go.Scatter(x=TW2330.index,
                          y=TW2330['bb_bbl'],
                          marker_color='skyblue',
                          name='Bollinger Band Low'))

# Chart title.
chart_title = taiwan_stock_symbol + ' (from ' + str(start_date.strftime("%Y-%m-%d")) \
              + ' to ' + str(end_date.strftime("%Y-%m-%d")) + ')'
fig1.update_layout(title={'text': chart_title, 'x': 0.5})
# Tabulate table and print chart.
print(tabulate(TW2330, headers='keys', tablefmt='psql'))
plot(fig1, auto_open=True)






