"""
SPP-10_Fetch-primary-invester-data.py
Purpose: Fetch stock price and save to excel
Author: Ed Chen
Date: 2021-1202
"""

# 20180522
# 多日交易紀錄寫入資料庫
# 抓取三大法人買賣金額 by 大數學堂
# http://www.largitdata.com

import pandas as pd
import time
import datetime
from datetime import date, timedelta
import sqlite3

# 今天日期
todayis = date.today()

# source
url = "http://www.twse.com.tw/fund/BFI82U?response=html&dayDate={0}"


def getTradeValue(dt):
    dfs = pd.read_html(url.format(dt))
    dfs[0].columns = dfs[0].columns.droplevel()
    new_dfs = dfs[0]
    new_dfs['Date'] = todayis.strftime('%Y-%m-%d')
    new_dfs['Date'] = pd.to_datetime(new_dfs['Date'])
    # 寫入資料庫
    with sqlite3.connect('big3trade_plus.sqlite') as db:
        new_dfs.to_sql('new_dfs', con=db, if_exists='append')
    # 印出
    # print(new_dfs)


# 在range(1,10) 10就是要抓取的天數，可自行修改
for i in range(1, 10):
    todayis = todayis + timedelta(days=-1)
    week = datetime.datetime.strptime(str(todayis), "%Y-%m-%d").isoweekday()
    if week < 6:
        try:
            dayary = str(todayis).replace('-', '')
            time.sleep(4)
            getTradeValue(dayary)
        except:
            pass
    else:
        pass
# End of [SPP-10_Fetch-primary-invester-data-2.py]




