#[1] Text - Start


def create_txt_and_save_text(path_txt, text, open_file=True):
    print('\n[create_txt_and_save_text]')
    #[1] Ensure the directory where the file will be saved exists.
    os.makedirs(os.path.dirname(path_txt), exist_ok=True)    
       
    #[2] Open the file in write mode ('w'), which will create the file if it doesn't exist.
    with open(path_txt, 'w') as file:
        file.write(text)
        
    #[3] After saving, optionally open the txt file.
    if open_file:
        #[4] Check the platform and open the file accordingly
        if os.name == 'nt':             # For Windows
            os.startfile(path_txt)
        elif os.name == 'posix':        # For MacOS
            subprocess.run(['open', path_txt])
        else:                           # For Linux (xdg-open should work for most environments)
            subprocess.run(['xdg-open', path_txt])


#[1] Text - End






#[2] File - Start






def make_dir_if_not_exist(dir_to_make=None):
    #[1] If dir_to_make is not provided, make a dir at current directory with timestamp as folder name.
    if dir_to_make is None:
        dir_current = os.path.dirname(os.path.abspath(__file__))
        timestamp = datetime.now().strftime("%Y-%m%d-%H%M%S")
        dir_to_make = os.path.join(dir_current, f'{timestamp}_dir_name')
        
    #[2] Make dir.
    try:
        os.mkdir(dir_to_make)
        print("--Directory wasn't exists. Just made one.")
    except FileExistsError:
        print("--Directory already exists. Skipping directory creation.")



def tkinter_select_directory(dialog_title='Select a directory'):
    #[1] Initiate and hide the main window.
    root = tkinter.Tk()
    root.withdraw()
    try:
        path_dir = tkinter.filedialog.askdirectory(title=dialog_title)
        if path_dir:
            #[2] Extract the base name of the selected directory.
            bsn_dir = os.path.basename(path_dir)
            #[3] Clean the path and append the trailing separator.
            path_dir = os.path.normpath(path_dir) + os.sep
            print('--path_dir:', path_dir)
            return path_dir, bsn_dir
        else:
            #[4] Exit the program if no directory is selected.
            print('--No directory selected. Exiting.')
            sys.exit()
    except Exception as e:
        print(f'--An error occurred: {e}')
        return None, None
    finally:
        #[5] Clean up and destroy the Tkinter window.
        root.destroy()


def get_dir_size(path='.'):
    total = 0
    for entry in os.scandir(path):
        if entry.is_file():
            # [1] Add the size of the file to the total
            total += entry.stat().st_size
        elif entry.is_dir():
            # [2] Recursively add the size of the directory
            total += get_dir_size(entry.path)
    return total


def find_folder_size_and_file_count(dir_target):
    #[1] Get list of folder basenames in the target directory
    list_bsn_folder = [f for f in os.listdir(dir_target) if not os.path.isfile(os.path.join(dir_target, f))]
    
    #[2] Initialize lists to store folder sizes and file counts
    list_folder_size_mb = []
    list_file_count = []
    
    #[3] Calculate folder sizes and file counts
    for bsn_folder in list_bsn_folder:
        path_folder = os.path.join(dir_target, bsn_folder)
        list_folder_size_mb.append(round(get_dir_size(path_folder) / 1048576))
        list_file_count.append(sum(len(files) for _, _, files in os.walk(path_folder)))
    
    #[4] Create a DataFrame with folder statistics
    df_dir_target = pd.DataFrame({
        'Folder Name': list_bsn_folder,
        'Size (Mb)': list_folder_size_mb,
        'Number of Files': list_file_count
    })
    
    #[5] Find folder with max size and max file count
    if not df_dir_target.empty:
        bsn_folder_max_size = df_dir_target.loc[df_dir_target['Size (Mb)'].idxmax(), 'Folder Name']
        val_folder_max_size = df_dir_target['Size (Mb)'].max()
        bsn_folder_max_file = df_dir_target.loc[df_dir_target['Number of Files'].idxmax(), 'Folder Name']
        val_folder_max_file = df_dir_target['Number of Files'].max()
    else:
        print('No folders found in the given directory.')
        bsn_folder_max_size = val_folder_max_size = bsn_folder_max_file = val_folder_max_file = None
    
    #[6] Return folder statistics and max size/file count information
    return df_dir_target, bsn_folder_max_size, val_folder_max_size, bsn_folder_max_file, val_folder_max_file

#[2] File - End





#[3] iPhone Connection -Start



def get_iphone_internal_storage():
    print('\n[get_iphone_storage_info]')
    #[1] Initiate and settings.
    total_size = 0
    total_files = 0
    max_attempt = 5

    #[3] Connection.
    shell = win32com.client.Dispatch("Shell.Application")
    my_computer = shell.Namespace(17)  # "This PC" Namespace

    #[1] Find iPhone device
    iphone = None
    for attempt in range(max_attempt):  # Retry up to 5 times
        for item in my_computer.Items():
            if 'Apple iPhone' in item.Name:
                print('-- "Apple iPhone" detected.')
                iphone = item.GetFolder
                break
        if iphone:
            break
        print('iPhone not detected. Retrying...')
        time.sleep(2)  # Wait for 2 seconds before retrying

    if not iphone:
        print('iPhone not detected. Ensure it is unlocked and trusted.')
        return

    #[2] Find Internal Storage
    internal_storage = None
    for item in iphone.Items():
        if "Internal Storage" in item.Name:
            internal_storage = item.GetFolder
            break

    if not internal_storage:
        print("Internal Storage not found.")
        return
    
    return internal_storage


def get_list_of_folder_name_in_iPhone(internal_storage):
    #[1] Initiate lists.
    list_folder_names = []

    #[2] Iterate through folders.
    for item in internal_storage.Items():
        if item.IsFolder:
            folder = item.GetFolder
            folder_name = item.Name
            list_folder_names.append(folder_name)
    return list_folder_names



def print_iPhone_folder_list(list_folder_names, rank=True):
    print()
    if rank:
        list_folder_names = sorted(list_folder_names)
    for i_folder_name in list_folder_names:
        if '__' in i_folder_name:
            print(f'\n{i_folder_name},\t', end='')
        else:
            print(f'{i_folder_name},\t', end='')
    print()



def find_folder_stat_of_a_year_in_iPhone(internal_storage, assigned_year=None):
    """
    Three columns: Folder name, file count, folder size.
    """
    print('\n[find_folder_stat_of_a_year_in_iPhone]')
    #[1] Initiate lists.
    folder_names = []
    file_counts = []
    
    #[2] Show current year if assigned_year is none.
    if assigned_year is None:
        assigned_year = datetime.now().year
    
    assigned_year_str = str(assigned_year)

    for item in internal_storage.Items():
        if item.IsFolder:
            folder = item.GetFolder
            folder_name = item.Name
            if assigned_year_str in folder_name:
                print(f'-- {folder_name}')
                file_count = folder.Items().Count  
                print(f'-- {file_count}')
                folder_names.append(folder_name)
                file_counts.append(file_count)

    df_iPhone = pd.DataFrame({
        'Folder Name': folder_names,
        'Number of Files': file_counts,
    })

    return df_iPhone





