print(len(words_list_2), ', removed punctuations and numbers, keep only English.')

# [03-4] Remove empty elements.
words_list_2[:] = [x for x in words_list_2 if x]
print(len(words_list_2), ', removed empty elements.')

# [03-5] Turn into singular form
words_list_3 =[]
for i in words_list_2:
    words_list_3.append(inflection.singularize(i))

# [03-6] Convert to lower case, sort, and remove duplicates.
words_list_3 = [i.lower() for i in words_list_3]
words_list_4 = sorted(words_list_3)  # Sort
words_list_4 = list(OrderedDict.fromkeys(words_list_4))  # Remove duplicates.
words_list_4 = [x for x in words_list_4 if not len(x) <= 3]
print(len(words_list_4), ', removed duplicates.\n\n')

# [04] Create empty lists.
start_with_ABCD = []
