"""
[WL-03_Check New Word From a Website.py]
Purpose: Check new words for learning.
Author: Meng-Chi Ed Chen
Date: 2022-07-11
Reference:
    1.https://pythonbasics.org/selenium-get-html/
    2.

Status: Ongoing.
"""

import pandas
from tabulate import tabulate
import sys
import os
import requests
from bs4 import BeautifulSoup
from collections import OrderedDict
import inflection
import numpy as np
from datetime import datetime


website_address = 'https://www.washingtonpost.com/climate-environment/2022/07/20/heatwave-us-record-oklahoma-texas/'


# [Function] remove punctuation and numbers.
def remove_punc_num(text_string):
    punc = '''!()-[]{};:'"\, |<>./?@#$%^&*_~0123456789®'''
    for ele in text_string:
        if ele in punc:
            text_string = text_string.replace(ele, "")
        if not ele.isascii():
            text_string = ''
    return text_string


# [Function] compare import word list with Excel word list.
def check_words(import_w_list, existing_w_list):
    export_w_list = []
    for individual_word in import_w_list:
        if individual_word not in existing_w_list:
            if individual_word.endswith('s'):
                individual_word = individual_word[:len(individual_word) - 1]
                if individual_word not in existing_w_list:
                    export_w_list.append(individual_word)
            else:
                export_w_list.append(individual_word)
    export_w_list = sorted(export_w_list)
    return export_w_list

# [First Part]

# [01] Ask for website address.
url_article = input('[Website Address] Paste the website address here. \n'
                    + "(Please make it right, because I didn't write code to prevent error input.) \n")
url_article = url_article.replace("'", '')
print('Website Address:', url_article)
# url_article = 'https://en.wikipedia.org/wiki/Jablonski_diagram'
    #'https://www.latimes.com/california/story/2022-07-10/firefighters-continue-battle-against-fire-threatening-giant-sequoias-in-yosemite-national-park'


# [02-1] Start scrapping.
try:
    resp = requests.get(url_article)
    soup = BeautifulSoup(resp.content, 'html.parser')
    ResultSet_WebText = soup.find_all(text=True)
    string_WebText = ''
    for ind_string in ResultSet_WebText:
        string_WebText += ind_string.text + ' '
        # Add a space, to prevent the last word of nth line sticks with the first word of n+1th line.
    for ind_title in soup.find_all('title'):
        string_WebTitle = ind_title.get_text()
except OSError:
    print('[OSError] System related error. Please check internet connection.')


# [02] Get web_title and web_html
print('Web Title:', string_WebTitle)
# print('[Start]', string_WebText,'[End]')
print(len(string_WebText), ', lenth of the string fresh from website.')

# [03] Handling web text.
# [03-1] Split paragraph by whitespace.
words_list_0 = string_WebText.split()
# print('string_WebText: \n', string_WebText)
print(len(words_list_0), ', complete list count.')

# [03-2] Eliminate elements longer than 20 letters and shorter than 3 letters.
words_list_1 = [x for x in words_list_0 if (not len(x) >= 20) and (not len(x) <= 3)]
print(len(words_list_1), ', kept only elements with 4-20 characters.')

# [03-3] Remove punctuation and number.
words_list_2 = [remove_punc_num(i) for i in words_list_1]
print(len(words_list_2), ', removed punctuations and numbers, keep only English.')

# [03-4] Remove empty elements.
words_list_2[:] = [x for x in words_list_2 if x]
print(len(words_list_2), ', removed empty elements.')

# [03-5] Turn into singular form
words_list_3 =[]
for i in words_list_2:
    words_list_3.append(inflection.singularize(i))

# [03-6] Convert to lower case, sort, and remove duplicates.
words_list_3 = [i.lower() for i in words_list_3]
words_list_4 = sorted(words_list_3)  # Sort
words_list_4 = list(OrderedDict.fromkeys(words_list_4))  # Remove duplicates.
words_list_4 = [x for x in words_list_4 if not len(x) <= 3]
print(len(words_list_4), ', removed duplicates.\n\n')

# [04] Create empty lists.
start_with_ABCD = []
start_with_EFGH = []
start_with_IJKLMN = []
start_with_OPQRS = []
start_with_TUVWXYZ = []
start_with_else = []


# [05] Start sorting into different word sets according to letter frequency.
for individual_word in words_list_4:
    if individual_word.startswith(('a', 'b', 'c', 'd')):
        start_with_ABCD.append(individual_word)
    elif individual_word.startswith(('e', 'f', 'g', 'h')):
        start_with_EFGH.append(individual_word)
    elif individual_word.startswith(('i', 'j', 'k', 'l', 'm', 'n')):
        start_with_IJKLMN.append(individual_word)
    elif individual_word.startswith(('o', 'p', 'q', 'r', 's')):
        start_with_OPQRS.append(individual_word)
    elif individual_word.startswith(('t', 'u', 'v', 'w', 'x', 'y', 'z')):
        start_with_TUVWXYZ.append(individual_word)
    else:
        start_with_else.append(individual_word)


# [06] Print separated words.
print('[start_with_ABCD],', len(start_with_ABCD), 'words:\n    ', start_with_ABCD)
print('[start_with_EFGH],', len(start_with_EFGH), 'words:\n    ', start_with_EFGH)
print('[start_with_IJKLMN],', len(start_with_IJKLMN), 'words:\n    ', start_with_IJKLMN)
print('[start_with_OPQRS],', len(start_with_OPQRS), 'words:\n    ', start_with_OPQRS)
print('[start_with_TUVWXYZ],', len(start_with_TUVWXYZ), 'words:\n    ', start_with_TUVWXYZ)
print('[start_with_else],', len(start_with_else), 'words:\n    ', start_with_else)



# [Second Part]


# [01] Read words from Excel files.
excel_path_basic = sys.path[0] + '\\01_Basic Words.xlsx'
df_basic_words = pandas.read_excel(excel_path_basic, engine='openpyxl', sheet_name='1-Basic Words')
df_corrections = pandas.read_excel(excel_path_basic, engine='openpyxl', sheet_name='2-Corrections')


# [02] Convert dataframe to lists.
excel_basic_ABCD = df_basic_words['ABCD'].tolist()
excel_basic_EFGH = df_basic_words['EFGH'].tolist()
excel_basic_IJKLMN = df_basic_words['IJKLMN'].tolist()
excel_basic_OPQRS = df_basic_words['OPQRS'].tolist()
excel_basic_TUVWXYZ = df_basic_words['TUVWXYZ'].tolist()
excel_basic_else = df_basic_words['else'].tolist()

excel_s_wrong = df_corrections['s_wrong'].tolist()
excel_s_correct = df_corrections['s_correct'].tolist()


# [03] collected words.
import_ABCD = start_with_ABCD
import_EFGH = start_with_EFGH
import_IJKLMN = start_with_IJKLMN
import_OPQRS = start_with_OPQRS
import_TUVWXYZ = start_with_TUVWXYZ
import_else = start_with_else


# [04] Check number of collected words (import).
print('\n[Number of collected words (import)]\n'
      '    ABCD: ', len(import_ABCD), ',\n',
      '   EFGH: ', len(import_EFGH), ',\n',
      ' IJKLMN: ', len(import_IJKLMN), ',\n',
      '  OPQRS: ', len(import_OPQRS), ',\n',
      'TUVWXYZ: ', len(import_TUVWXYZ), ',\n',
      '   else: ', len(import_else), '.\n',)


# [05] Check if the imported words exists in the existing basic word list.
export_ABCD = check_words(import_ABCD, excel_basic_ABCD)
export_EFGH = check_words(import_EFGH, excel_basic_EFGH)
export_IJKLMN = check_words(import_IJKLMN, excel_basic_IJKLMN)
export_OPQRS = check_words(import_OPQRS, excel_basic_OPQRS)
export_TUVWXYZ = check_words(import_TUVWXYZ, excel_basic_TUVWXYZ)
export_else = check_words(import_else, excel_basic_else)


# [06] Remove errors due to singularization.
export_ABCD = check_words(export_ABCD, excel_s_wrong)
export_EFGH = check_words(export_EFGH, excel_s_wrong)
export_IJKLMN = check_words(export_IJKLMN, excel_s_wrong)
export_OPQRS = check_words(export_OPQRS, excel_s_wrong)
export_TUVWXYZ = check_words(export_TUVWXYZ, excel_s_wrong)
export_else = check_words(export_else, excel_s_wrong)

# [07] Add web title, url, and running date.
export_else.append(string_WebTitle)
export_else.append(url_article)
current_datetime = datetime.now()
datatime_in_excel = current_datetime.strftime('%Y-%m-%d,  %H:%M:%S')
export_else.append(datatime_in_excel)


# [07] Check number of new words (export).
print('\n[Number of new words (export)]\n'
      '    ABCD: ', len(export_ABCD), ',\n',
      '   EFGH: ', len(export_EFGH), ',\n',
      ' IJKLMN: ', len(export_IJKLMN), ',\n',
      '  OPQRS: ', len(export_OPQRS), ',\n',
      'TUVWXYZ: ', len(export_TUVWXYZ), ',\n',
      '   else: ', len(export_else), '.\n',)

df_export_words = pandas.Series([],dtype=pandas.StringDtype())

df_export_words = pandas.DataFrame({'ABCD': pandas.Series(export_ABCD, dtype=str),
                                 'EFGH': pandas.Series(export_EFGH, dtype=str),
                                 'IJKLM': pandas.Series(export_IJKLMN, dtype=str),
                                 'OPQRS': pandas.Series(export_OPQRS, dtype=str),
                                 'UVWXYZ': pandas.Series(export_TUVWXYZ, dtype=str),
                                 'else': pandas.Series(export_else, dtype=str)})

df_export_words = df_export_words.replace(np.nan, '', regex=True)  # Replace nan into '--'.


# [08] Check if the Excel file already exist. This part is not necessary, but just for practice.
excel_path_new = sys.path[0] + '\\03_New Words_' + string_WebTitle + '.xlsx'
if os.path.isfile(excel_path_new):
    xl = pandas.ExcelFile(excel_path_new)
    sheet_name_list = xl.sheet_names
    if sheet_name_list == ['3-New Words']:
        print("File already exist. Update old file.\n(", excel_path_new, ")\n")
    else:
        print("More than one sheet detected. Clear all sheets and paste new sheet.",
              "\nSheet Names: ", sheet_name_list,
              "\n(", excel_path_new, ")")
else:
    print("File doesn't exist. Create new file.\n(", excel_path_new, ")")

# [09] Save the dataframe to Excel.
try:
    writer = pandas.ExcelWriter(excel_path_new, engine='xlsxwriter')
except(PermissionError):
    print('[PermissionError] Please close the file and try again.\n', excel_path_new)
    exit()

df_export_words.to_excel(writer, sheet_name='3-New Words')
worksheet = writer.sheets['3-New Words']
worksheet.set_column('B:F', 20)
writer.save()


print(excel_path_new)
print(tabulate(df_export_words, headers='keys', tablefmt='table_formate'))
exit()






