"""
[MC-01_single matrix operations]
Purpose: Single matrix operation.
Author: Meng-Chi Ed Chen
Date: 2023-01-11
Reference:
    1.https://pythonbasics.org/selenium-get-html/
    2.

Status: Done (2023-02-14).
"""

import numpy as np
from numpy.linalg import inv
from scipy.stats import unitary_group

# [01] Generate a matrix_A with random integers.
print('\n[01] Generate a matrix_A with random integers.')
# "randint" generates random integers in the “half-open” interval [low, high).
matrix_A = np.random.randint(0, 10, size=(3, 5))
# Check the type of matrix A
type_matrix_A = type(matrix_A)
print('[Random integers] matrix_A: \n', matrix_A)
print('type_matrix_A: ', type_matrix_A)
# Convert to matrix
matrix_A = np.matrix(matrix_A)
type_matrix_A = type(matrix_A)
print('--(after convert to matrix)--\ntype_matrix_A: ', type_matrix_A, '\n')


# [02] Generate another matrix_A as square matrix.
print('\n[02] Generate another matrix_A as square invertible matrix')
matrix_A = np.random.randint(0, 10, size=(3, 3))
print('[Random integers] matrix_A: \n', matrix_A, '\n')
# Extract a diagonal array.
array_A_D = np.diag(matrix_A)
print('[Diagonal elements of matrix_A] array_A_D: \n', array_A_D, '\n')
# Make it into a diagonal matrix
matrix_A_D = np.diag(array_A_D)
print('[Diagonal matrix of matrix_A] matrix_A_D: \n', matrix_A_D, '\n')


# Returns the transpose of the matrix.
matrix_A_T = matrix_A.transpose()
print('[Transpose of matrix_A] matrix_A_T: \n', matrix_A_T, '\n')
# Returns the inverse of the matrix.
matrix_A_I = inv(matrix_A)
print('[Inverse of matrix_A] matrix_A_I: \n', matrix_A_I, '\n')
# Multiply matrix_A with matrix_A_I.
matrix_A_mtp_A_I = np.ndarray.round(np.dot(matrix_A, matrix_A_I))  # Did a round to clean it up.
print('[Multiply matrix_A with matrix_A_I] matrix_A_mtp_A_I: \n', matrix_A_mtp_A_I, '\n')


# [03] Generate another matrix_A with random integer complex.
print('\n[03] Generate another matrix_A with random integer complex')
matrix_A = np.random.randint(-10, 10, size=(3, 3)) + 1.j * np.random.randint(-10, 10, size=(3, 3))
print('[Random integers] matrix_A: \n', matrix_A, '\n')
matrix_A_C = matrix_A.conjugate()
print('[Conjugate] matrix_A_C: \n', matrix_A_C, '\n')


# [04] Generate another matrix_A as a random unitary matrix.
print('\n[04] Generate another matrix_A as a random unitary matrix')
# matrix_A = np.random.randint(-10, 10, size=(3, 3)) + 1.j * np.random.randint(-10, 10, size=(3, 3))
# Return a random unitary matrix.
matrix_A = unitary_group.rvs(3)
print('[Unitary matrix] matrix_A: \n', matrix_A, '\n')
# Returns the (complex) conjugate transpose of self.
matrix_A_CT = np.matrix(matrix_A).getH()
print('[Conjugate transpose of matrix_A] matrix_A_CT: \n', matrix_A_CT, '\n')
# Returns the inverse of the matrix.
matrix_A_I = inv(matrix_A)
print('[Inverse of matrix_A] matrix_A_I: \n', matrix_A_I, '\n')
print('[Inverse and conjugate transpose of an unitary matrix are identical] matrix_A_I - matrix_A_CT: \n'
      , np.ndarray.round(matrix_A_I-matrix_A_CT), '\n')

# Multiply unitary with its conjugate transpose results in an identity matrix.
matrix_A_mtp_A_CT = np.ndarray.round(np.dot(matrix_A, matrix_A_CT))
print('[Multiply matrix_A with matrix_A_CT] matrix_A_mtp_A_CT: \n', matrix_A_mtp_A_CT, '\n')


# [05] Generate other random matrices.
print('\n[05] Generate other random matrices')
# "rand" generates random uniform distribution over [0, 1)
matrix_B = np.random.rand(3, 3)
print('[Random real numbers] matrix_B: \n', matrix_B, '\n')

# "normal" Draw random samples from a normal (Gaussian) distribution.
matrix_C = np.ndarray.round(np.random.normal(0, 1, (7, 7)), decimals=3)
# Round elements in a matrix to 3 decimal places.
print('[Random real numbers with normal distribution] matrix_C: \n', matrix_C, '\n')

# Calculate element average
avg_matrix_C = round(np.sum(matrix_C)/(len(matrix_C)*len(matrix_C[0])), 4)
print('[The average of all elements in the matrix_C] avg_matrix_C: \n', avg_matrix_C, '\n')
# The identity array is a square array with ones on the main diagonal.
matrix_I = np.identity(3)
print('[Identity] matrix_I: \n', matrix_I, '\n')
# End of [MC-01_generate matrices.py]




