"""
[PIS-06_Correct Vignetting and Enhance.py]
Purpose: Correct vignetting and enhance image.
Author: Meng-Chi Ed Chen
Date: 2023-06-06
Reference:
    1.
    2.

Status: Complete.
"""

import os
import numpy as np
import cv2
import sys
from tkinter.filedialog import askdirectory


#[] Ask directory
dir_image_folder = askdirectory(title='Select Folder')
#dir_image_folder=r'D:\01_Floor\a_Ed\16_Coding\03_Python\03_MatureTools\2023-0525_Image Stitching_stitching\PIS-4_demo_adj+corr, stitch'
image_list = os.listdir(dir_image_folder)
image_list = [file for file in image_list if 'blank' in file]
# Keep if contain "blank" in file name.

#[] Print image names and file list.
print ('[image_list]', *image_list, sep='\n')
print ('[image_listcount]', len(image_list), '\n')
if len(image_list) == 0:
      print('No blank image found. Please provide a blank image into the folder and try again.', '\n')
      sys.exit()


full_directory_list = [os.path.join(dir_image_folder, file) for file in image_list]

#[] Set ratio of averging extention.
ratio_extend = 0.02
print('Ratio of averging extention, Re =', ratio_extend,
      '\n(If Re = 0.05, it means averaging from 0.45 to 0.55 along width and leangth.)')

#[] Count of types of blanks and reset parameters.
cnt_50X = 0
cnt_10X = 0
image_modifier_50X_1D = '(empty)'
image_modifier_10X_1D = '(empty)'
image_modifier_XX_1D = '(empty)'

print('If there is more than one blank for 10X, the code will rewrite the file.')

#[] Count 10X of blank and 50X of blank.
for iter_file in range(len(full_directory_list)):
      image_basename = os.path.basename(str(full_directory_list[iter_file]))
      if '10X' in image_basename:
            cnt_10X +=1
      elif '50X' in image_basename:
            cnt_50X +=1
print('cnt_10X = ', cnt_10X, '. cnt_50X = ', cnt_50X, '.', sep ='')


#[] Average the center pixel of png array.
for iter_file in range(len(full_directory_list)):
      #[]Print iteration
      print('\n[', iter_file+1, ']')

      #[] Check if we do blank for 50X or 10X twice.
      image_basename = os.path.basename(str(full_directory_list[iter_file]))
      if (cnt_50X == 1 and cnt_10X == 1):
            print('Both blk-50X and blk-10X already exist.')
            break
      elif (cnt_50X == 1 and '50X' in image_basename):
            print('blk-50X already exist.')
            continue
      elif (cnt_10X == 1 and '10X' in image_basename):
            print('blk-10X already exist.')
            continue
      elif (cnt_50X == 0 and cnt_10X == 0):
            print('Please check if you provided both 10X and 50X of blank. If you only have one blank, just duplicate and name it blank_10X and blank_50X.')
            sys.exit()

      
      # Print full directory
      # print('[', iter_file+1, '] ', full_directory_list[iter_file], sep='')

      
      #[] Calculate image dimension.
      image = cv2.imread(full_directory_list[iter_file])
      print('Dimension (width, height, channel) =', image.shape)
      h, w, c = image.shape
      h_center = round(h/2)
      h_upper = round(h_center + h*ratio_extend)
      h_lower = round(h_center - h*ratio_extend)

      w_center = round(w/2)
      w_upper = round(w_center + w*ratio_extend)
      w_lower = round(w_center - w*ratio_extend)

      #print('Height (lower, center, upper) =', h_lower, h_center, h_upper)
      #print('Width (lower, center, upper) =', w_lower, w_center, w_upper)
      #[] Average a center area of the image as sample.
      array1D_center_averaged = (image[h_lower:h_upper,w_lower:w_upper].mean(axis=0).mean(axis=0)).astype(int)
      avg_color_ard_ctr = np.around(array1D_center_averaged)
      print('Averaged color around center (B, G, R) =', avg_color_ard_ctr)

      #[] Use sampled color to tile a ndarray.
      array3D_center_averaged = np.tile(array1D_center_averaged, (h, w, 1))
      #print('Dimension (width, height, channel) =', array3D_center_averaged.shape)
      #print(array3D_center_averaged)

      #[] Generate image modifier for color correction.
      image_modifier = image - array3D_center_averaged
      """filename_image_modifier = 'modifier' + str(iter_file+1) + '_.png'
      path_image_modifier = os.path.join(dir_image_folder, filename_image_modifier)
      cv2.imwrite(path_image_modifier, image_modifier)"""

      #[] Check for type of blank
      image_basename = os.path.basename(str(full_directory_list[iter_file]))
      if '50X' in image_basename:
            cnt_50X = cnt_50X + 1 
            type_of_blank = '50X'
            image_modifier_50X_3D = image_modifier
            image_modifier_50X_1D = avg_color_ard_ctr
            print('image_modifier_50X:', avg_color_ard_ctr)
      elif '10X' in image_basename:
            cnt_10X = cnt_10X + 1 
            type_of_blank = '10X'
            image_modifier_10X_3D = image_modifier
            image_modifier_10X_1D = avg_color_ard_ctr
            print('image_modifier_10X:', avg_color_ard_ctr)
      else:
            type_of_blank = '??X'
            image_modifier_XX_3D = image_modifier
            image_modifier_XX_1D = avg_color_ard_ctr
            print('image_modifier_XX:', avg_color_ard_ctr)

      print('type_of_blank:', type_of_blank)

      #[] Generate corrected blank image and save
      corrected_blank = image - image_modifier
      filename_corrected_blank = 'corrected-blk-' + type_of_blank + '_' + str(iter_file+1) + '.png'
      path_corrected_blank = os.path.join(dir_image_folder, filename_corrected_blank)
      cv2.imwrite(path_corrected_blank, corrected_blank)


print('\n\n(End of for loop of generating image modifiers)\n')
print('image_modifier_50X_1D:', image_modifier_50X_1D)
print('image_modifier_10X_1D:', image_modifier_10X_1D)
print('image_modifier_XX_1D:', image_modifier_XX_1D)
print('\n(Start correcting experimental images.)\n\n')


#[] Correct images taken.
image_list = os.listdir(dir_image_folder)
image_list = [file for file in image_list if not ('blank' in file or 'blk' in file or 'corr' in file or 'panorama' in file or '.txt' in file or 'TestEnh' in file)]
