image = np.zeros([100, 100, 3])
cv2.line(image, (0, 0), (50, 50), (0, 255, 0), 2) # Test green line. From (0, 0) to (50, 50).

draw_a_line(50, 30, (255, 50, 0), 2, image)
draw_a_line(50, 60, (255, 80, 0), 2, image)
draw_a_line(50, 90, (255, 110, 0), 2, image)
draw_a_line(50, 1200, (255, 140, 0), 2, image)

cv2.imwrite(dir_img_folder, image)

