#[1] Interaction - Start
def ask_for_input(question_message, readback=True, strip_spaces=True, allow_blank_input=False):
    print('\n[ask_for_input] ', end='')
    # Loop until the user provides a valid input
    while True:
        str_find = input(question_message)
        if strip_spaces:
            str_find = str_find.strip()
        if str_find or allow_blank_input: 
            if readback:
                print(f'-- User said: {str_find}')
            return str_find
        else:
            print('-- Please enter a non-empty value!')

            
            
            
#[1] Interaction - End



#[2] File - Start
def preview_files_and_folders_in_dir(dir_folder, preview_cnt=20):
    """
    Keep this preview function simple. Do not add other function like file_only or list_bsn.
    """
    print(f'\n[preview_files_and_folders_in_dir] {dir_folder}')
    try:
        #[1] Check if the directory exists
        if not os.path.isdir(dir_folder):
            raise FileNotFoundError(f"The directory '{dir_folder}' does not exist.")
        
        #[2] List all files and folders in the directory
        list_folder_and_files = os.listdir(dir_folder)
        
        #[3] Limit the number of entries to the first `first_cnt_files`
        limited_list = list_folder_and_files[:preview_cnt]
        
        #[4] Print each entry on a new line
        cnt = len(limited_list)
        for i, entry in enumerate(limited_list):
            print(f'-- [{i+1:03d}/{cnt:03d}] \t{entry}')
        
        return limited_list
    
    except Exception as e:
        print(f"Error: {e}")


def filter_file_in_dir_with_keywords(dir_folder, list_kwd_yes_or_1=[], list_kwd_no_or_2=[], print_bsn = False):
    print(f'\n[filter_file_in_dir_with_keywords] dir_folder = {dir_folder}')
    #[1] Check if directory exists
    if not os.path.isdir(dir_folder):
        raise FileNotFoundError(f'The directory {dir_folder} was not found.')
    
    #[2] Get list of files in the directory, no folders.
    list_bsns = [file for file in os.listdir(dir_folder) if os.path.isfile(os.path.join(dir_folder, file))]
    cnt_before = len(list_bsns)
    
    #[3] Filter names by keywords to select (if list_kwd_yes_or_1 is not empty list).
    if list_kwd_yes_or_1 != []:
        list_bsns = [file for file in list_bsns if any(keyword in file for keyword in list_kwd_yes_or_1)]
    
    #[4] Filter names by keywords to discard (if list_kwd_no_or_2 is not empty list).
    if list_kwd_no_or_2 != []:
        list_bsns = [file for file in list_bsns if not any(keyword in file for keyword in list_kwd_no_or_2)]
        
    #[5] Generate file paths and orint
    list_paths = [os.path.join(dir_folder, file) for file in list_bsns]
    cnt_after = len(list_bsns)
    if print_bsn:
        print(f'\n--  Count (before, after) = {cnt_before}, {cnt_after}. list_bsns: \n{list_bsns}', end='\n\n')
    return list_paths, list_bsns

#[2] File - End





#[3] Replace - Start       

def replace_folders_in_dir_with_complete_string(dir_path, str_old, str_new):
    print(f'\n[replace_folders_with_complete_string] replacing "{str_old}" with "{str_new}".')
    
    #[1] Check if the given directory exists
    if not os.path.exists(dir_path):
        print('--Given dir_path doesn\'t exist. Exit program.')
        sys.exit(1)

    #[2] Iterate over all items in the directory
    for item in os.listdir(dir_path):
        
        #[5] Construct full path
        path_item = os.path.join(dir_path, item)
        
        #[6] Check if it's a directory and contains str_old in its name
        if os.path.isdir(path_item) and str_old in item:
            
            #[7] Construct new folder name
            new_name = item.replace(str_old, str_new)
            new_path = os.path.join(dir_path, new_name)
            
            #[8] Rename the folder
            os.rename(path_item, new_path)
            print(f'Renamed folder {item} to {new_name}')

        
def replace_folders_and_files_in_dir_with_complete_string(dir_path, str_old, str_new, for_real=True):
    print(f'\n[replace_folders_with_complete_string] replacing "{str_old}" with "{str_new}". Skipping batch file (.BAT).')
    
    #[1] Check if the given directory exists
    if not os.path.exists(dir_path):
        print('--Given dir_path doesn\'t exist. Exit program.')
        sys.exit(1)

    #[2] Iterate over all items in the directory
    for item in os.listdir(dir_path):
        #[4] Skipping bat file.
        if os.path.basename(item).upper().endswith('.BAT'):
            continue
        
        #[5] Construct full path
        path_item = os.path.join(dir_path, item)
        
        #[7] Construct new folder name
        new_name = item.replace(str_old, str_new)
        new_path = os.path.join(dir_path, new_name)
        
        #[8] Rename the file
        if for_real:
            os.rename(path_item, new_path)
        print(f'-- Renamed folder \t{item} to \t{new_name}')
            
            
            
def replace_folders_in_dir_with_complete_string(dir_path, str_old, str_new):
    print(f'\n[replace_folders_with_complete_string] replacing "{str_old}" with "{str_new}".')
    
    #[1] Check if the given directory exists
    if not os.path.exists(dir_path):
        print('--Given dir_path doesn\'t exist. Exit program.')
        sys.exit(1)

    #[2] Iterate over all items in the directory
    for item in os.listdir(dir_path):
        
        #[5] Construct full path
        path_item = os.path.join(dir_path, item)
        
        #[6] Check if it's a directory and contains str_old in its name
        if os.path.isdir(path_item) and str_old in item:
            
            #[7] Construct new folder name
            new_name = item.replace(str_old, str_new)
            new_path = os.path.join(dir_path, new_name)
            
            #[8] Rename the file
            os.rename(path_item, new_path)
            print(f'-- Renamed folder {item} to {new_name}')  
            
            
            

def replace_bsnext_with_complete_string(list_file_paths, str_old, str_new):
    print(f'\n[replace_with_complete_string] replacing "{str_old}" with "{str_new}".')
    
    #[1] Check if the given directory exists
    for i, iter_path_file in enumerate(list_file_paths):
        dir_path, bsn_ext = os.path.split(iter_path_file)
        new_bsn_ext = bsn_ext.replace(str_old, str_new)
        new_iter_path_file = os.path.join(dir_path, new_bsn_ext)
        
        #[2] Check if the file names are different and if the original file exists
        if bsn_ext != new_bsn_ext and os.path.exists(iter_path_file):
            os.rename(iter_path_file, new_iter_path_file)
            print(f'[{i:03d}] Renamed as: {new_bsn_ext}')


def ask_to_check(str_to_check, message_1, message_2):
    print('\n[ask_to_check_dir]')
    string_ques = input(message_1)
    if ('yes' in string_ques) or ('ye' in string_ques) or ('y' in string_ques) or ('ok' in string_ques) \
        or ('sure' in string_ques) or ('go' in string_ques):
        print('User said yes.', string_ques)
        return str_to_check
    elif ('no' in string_ques) or ('n' in string_ques):
        print('User said no.', string_ques)
        str_to_check_new = ask_for_input(message_2)
        return str_to_check_new
    else:
        print('[Invalid Input] System exit.\n', string_ques)
        sys.exit(1)






def replace_file_with_start_end(list_file_paths, str_old_start, str_old_end, str_new):
    print('\n[replace_with_start_end]')
    for i, iter_path_file in enumerate(list_file_paths):
        # Escape the special characters in the start and end strings
        str_old_start_escaped = re.escape(str_old_start)  # re.escape can convert '[' into '\['
        str_old_end_escaped = re.escape(str_old_end)
        # Build the regex pattern
        pattern = f'({str_old_start_escaped}.+?{str_old_end_escaped})'
        match = re.search(pattern, iter_path_file)
        if match:
            # Replace the entire matched pattern
            new_iter_path_file = re.sub(pattern, str_new, iter_path_file)
            os.rename(iter_path_file, new_iter_path_file)
            print(f'[{i}] {os.path.basename(new_iter_path_file)}')



import os

def replace_file_name_in_dir_and_subdir_with_prefix_and_suffix(dir_path, list_kwd_exclude, prefix='', suffix='', for_real=True):
    """
    Replace files in dir_path and its subdirectories with a new file name in the format:
    new_file_name = f'{prefix}_{bsn}_{suffix}{ext}'.
    list_kwd_exclude is a list of keywords to exclude files containing those keywords in their names.
    """
    # [1] Adjust file name if empty.
    prefix_add = f'{prefix}_' if prefix else '' 
    suffix_add = f'_{suffix}' if suffix else '' 

    # [2] Walk through the directory and subdirectories
    for root, dirs, files in os.walk(dir_path):
        for file_name in files:
            
            # [3] Check if the file name contains any excluded keyword
            if any(kwd in file_name for kwd in list_kwd_exclude):
                continue  # Skip this file
            
            # [4] Full path to the file
            iter_path = os.path.join(root, file_name)
            
            # [5] Extract file name without extension and the extension
            bsn_ext = os.path.basename(iter_path)
            bsn, ext = os.path.splitext(bsn_ext)
            
            # [6] Generate the new file name with prefix and suffix
            new_file_name = f'{prefix_add}{bsn}{suffix_add}{ext}'
            
            # [7] Full path to the new file name
            new_file_path = os.path.join(root, new_file_name)
            
            # [8] Rename the file
            if for_real:
                os.rename(iter_path, new_file_path)
            print(f'-- Renamed file \t{iter_path} to \t{new_file_path}')



#[3] Replace - End       





