def retrieve_datetime_of_single_media_files_with_timezone(path_media, 
                                            datetime_format = '%Y-%m-%d, %H:%M:%S',
                                            timezone_str='America/New_York'):  # Add a default timezone
    #[2] Get file extension
    bsn_ext = os.path.basename(path_media)
    bsn, ext = os.path.splitext(bsn_ext)
    ext = ext.upper()
    
    # Set the UTC and local timezones
    utc = pytz.UTC
    local_tz = pytz.timezone(timezone_str)  # Local timezone
    
    #[3] Check file type for image
    if ext in ['.JPG', '.JPEG', '.PNG', '.GIF', '.TIF']:
        try:
            # Use 'with' to ensure the file is closed after use
            with Image.open(path_media) as img:
                media_datetime = datetime.strptime(img._getexif()[36867], 
                                                    '%Y:%m:%d %H:%M:%S')
            method = '[1] get_date_taken(image)'
            media_datetime = utc.localize(media_datetime).astimezone(local_tz)  # Convert to local time
            media_datetime = media_datetime.strftime(datetime_format)
        except (KeyError, UnidentifiedImageError, TypeError, AttributeError):
            media_datetime = datetime.fromtimestamp(os.path.getmtime(path_media))
            method = '[2] os.path.getmtime(image)'
            media_datetime = utc.localize(media_datetime).astimezone(local_tz)  # Convert to local time
            media_datetime = media_datetime.strftime(datetime_format)
    
    #[4] Check file type for video
    elif ext in ['.MP4', '.MOV']:
        try:
            # Use hachoir to extract metadata from video file
            parser = createParser(path_media)
            metadata = extractMetadata(parser)
            if metadata and metadata.has("creation_date"):
                media_datetime = metadata.get("creation_date")
                method = '[3] hachoir creation_date(video)'
                media_datetime = utc.localize(media_datetime).astimezone(local_tz)  # Convert to local time
                media_datetime = media_datetime.strftime(datetime_format)
            else:
                media_datetime = datetime.fromtimestamp(os.path.getmtime(path_media))
                method = '[4] os.path.getmtime(video)'
                media_datetime = utc.localize(media_datetime).astimezone(local_tz)  # Convert to local time
                media_datetime = media_datetime.strftime(datetime_format)
        except Exception as e:
            print(f'Error extracting metadata: {e}')
            media_datetime = datetime.fromtimestamp(os.path.getmtime(path_media))
            method = '[5] os.path.getmtime(video)error'
            media_datetime = utc.localize(media_datetime).astimezone(local_tz)  # Convert to local time
            media_datetime = media_datetime.strftime(datetime_format)
        finally:
            if parser:
                parser.stream._input.close()  # Force closing of the file stream
            del parser  # Explicitly delete the parser object to release file handle
    
    #[5] Handle unknown file types
    else:
        media_datetime, method = None, None
        print(f'Unknown file type {bsn_ext}, usually AEE or HEIC.')
    
    return ext, media_datetime, method








def get_video_length_of_a_movie(path_media, unit_in_second=True):
    #[3] Check file type for image
    ext = os.path.splitext(os.path.basename(path_media))[1].upper()
    if ext in ['.MP4', '.MOV', '.AVI']:
        #[3] Open the video file using cv2
        video = cv2.VideoCapture(path_media)
    
        #[4] Get the frame count and frame rate (fps)
        frames = video.get(cv2.CAP_PROP_FRAME_COUNT)
        fps = video.get(cv2.CAP_PROP_FPS)
        
        #[5] Calculate video length in seconds
        length_in_seconds = int(frames / fps)
        
        #[6] Return in seconds if unit_in_second is True, otherwise return in minutes
        if unit_in_second:
            length = length_in_seconds
        else:
            length = int(length_in_seconds / 60)
        video.release()  # Release the video capture object
        
    
    #[5] Handle unknown file types
    else:
        length = None
    return length  
        
    


def retrieve_datetime_from_list_of_media_files(list_path_media, 
                                               print_status=False, 
                                               datetime_format = '%Y-%m-%d, %H:%M:%S'):
    #[1] Initiate lists.
    cnt_total = len(list_path_media)
    list_media_datetime = []
    list_media_ext = []
    list_method = []
    
    for i, iter_path in enumerate(list_path_media):
        #[3] Get datetime from media file
        ext, media_datetime, method = retrieve_datetime_of_single_media_files_2(iter_path, datetime_format)


        #[6] Collect into lists.
        list_media_datetime.append(media_datetime)
        list_media_ext.append(ext)
        list_method.append(method)
        
        #[6] Optionally print status.
        if print_status:
            print(f'-- [{i:04d}/{cnt_total:04d}] \t{media_datetime}, \t{os.path.basename(iter_path)}, \t{method}.')
    
    return list_media_datetime, list_media_ext, list_method







