def df_two_col_of_list_subtract(list2D_col_big, list2D_col_small, decimals=2):
    list2D_result = []  # Initialize an empty 2D list for the result
    # Iterate over pairs of sublists from list2D_col_big and list2D_col_small
    for list1D_big, list1D_small in zip(list2D_col_big, list2D_col_small):
        list1D_temp = []  # Temporary 1D list to store the result of subtraction for each pair of sublists
        # Iterate over pairs of elements from the current pair of 1D sublists
        for m, c in zip(list1D_big, list1D_small):
            diff = round(m - c, decimals)  # Perform the subtraction and round it
            list1D_temp.append(diff)  # Append the result to the temporary 1D list
        list2D_result.append(list1D_temp)  # Append the temporary 1D list to the final 2D result list
    return list2D_result




def plot_four_3D(list_vectors, list_color, title, path_save_plot):
    # Normalization and calculation
    norm = colors.Normalize(min(list_color), max(list_color))
    cmap = cm.winter
    colors_array = cmap(norm(list_color))
    max_abs_element = max([max(map(abs, vec)) for vec in list_vectors])

    # Create a 2x2 subplot grid
    fig, axs = plt.subplots(2, 2, subplot_kw={'projection': '3d'}, figsize=(12, 8))

    # Axis limit factors
    limit_factors = [1, 0.8, 0.5, 0.1]

    for i, ax in enumerate(axs.flat):
        # Set axis limits
        limit = max_abs_element * limit_factors[i]
        ax.set_xlim(-limit, limit)
        ax.set_ylim(-limit, limit)
        ax.set_zlim(-limit, limit)

        # Plot vectors
        for vec, color in zip(list_vectors, colors_array):
            ax.quiver(0, 0, 0, vec[0], vec[1], vec[2], color=color, arrow_length_ratio=0.2, linewidth=3)

        # Set labels
        ax.set_xlabel('Blue')
        ax.set_ylabel('Green')
        ax.set_zlabel('Red')

        # Set individual titles
        ax.set_title(f'Axes Limit: {limit_factors[i]} * max_abs_element', color='gray', fontsize=10, pad=-15)

    # Adjust the main title
    fig.suptitle(title, fontsize=16, y=0.95)

    # Create a mappable object for the colorbar
    sm = plt.cm.ScalarMappable(cmap=cmap, norm=norm)
    sm.set_array([])

    # Add colorbar in the lower right corner
    cbar_ax = fig.add_axes([0.92, 0.15, 0.01, 0.7])  # x, y, width, height
    cbar = fig.colorbar(sm, cax=cbar_ax, orientation='vertical')
    cbar.set_label('Color Scale')

    # Adjust layout
    plt.tight_layout()
    plt.subplots_adjust(top=0.88, bottom=0.1, hspace=0.2)  # Adjust top spacing to accommodate main title

    # Show plot
    plt.show()
    
    # Save plot
    fig.savefig(path_save_plot, dpi=300)  # Save the figure
    print(f"Plot saved as '{path_save_plot}'")
    return



