#[1] File - Start

def filter_file_in_dir_with_keywords(dir_folder, list_kwd_yes_or_1=[], list_kwd_no_or_2=[], print_bsn = False):
    print('\n[filter_file_in_dir_with_keywords]')
    #[1] Check if directory exists
    if not os.path.isdir(dir_folder):
        raise FileNotFoundError(f"The directory '{dir_folder}' was not found.")
    
    #[2] Get list of files in the directory, no folders.
    list_bsn = [file for file in os.listdir(dir_folder) if os.path.isfile(os.path.join(dir_folder, file))]
    cnt_before = len(list_bsn)
    
    #[3] Filter names by keywords to select
    if list_kwd_yes_or_1:
        list_bsn = [file for file in list_bsn if any(keyword in file for keyword in list_kwd_yes_or_1)]
    
    #[4] Filter names by keywords to discard
    if list_kwd_no_or_2:
        list_bsn = [file for file in list_bsn if not any(keyword in file for keyword in list_kwd_no_or_2)]
        
    #[5] Generate file paths and orint
    list_paths = [os.path.join(dir_folder, file) for file in list_bsn]
    cnt_after = len(list_bsn)
    if print_bsn:
        print(f'\n--  Count (before, after) = {cnt_before}, {cnt_after}. list_bsn: \n{list_bsn}', end='\n\n')
    return list_paths, list_bsn

#[1] File - End




#[2] Image - Start


def create_avg_color_for_patches(list_path_img):
    print('\n[create_avg_color_for_patches]')
    arr_mean_color = np.empty((0, 3))  # Initialize an empty NumPy array to store averaged colors

    #[1] Iterate through list of paths.
    for i, iter_path_image in enumerate(list_path_img):
        
        #[2] Read image and calculate average color.
        arrimg_patch = cv2.imread(iter_path_image)
        array1D_avg_color = np.mean(arrimg_patch, axis=(0, 1))  # Calculate average color across all pixels
        avg_color = np.around(array1D_avg_color, decimals=2)
        
        #[3] Store average color and print information.
        arr_mean_color = np.append(arr_mean_color, [avg_color], axis=0)  # Append average color to the array
        
        basename_image = os.path.basename(iter_path_image)
        str_avg_color = f'[{avg_color[0]},{avg_color[1]},{avg_color[2]}]'
        print(f'\n-- [{i}] Averaged color (BGR) of {basename_image} is {str_avg_color}')
        
        #[4] Rename image with its color value.
        new_path_image = iter_path_image.replace('.png', f'_ac{str_avg_color}.png')
        os.rename(iter_path_image, new_path_image)
        
    return arr_mean_color
    
#[2] Image - End




#[5] Excel - Start

def save_df_as_excel_add(df, dir_excel, bsn_excel, sheet_name_or_index):
    print('\n[save_df_as_excel_add]')
    #[1] Convert sheet index to string name if an integer is provided
    if isinstance(sheet_name_or_index, int):
        sheet_name = f'Sheet{sheet_name_or_index}'
    else:
        sheet_name = str(sheet_name_or_index)  # Ensure sheet_name is always a string
        
    #[2] Ensure the directory exists
    if not os.path.exists(dir_excel):
        os.makedirs(dir_excel)
    path_xlsx = os.path.join(dir_excel, bsn_excel)
    
    #[3] Check if the file exists
    if os.path.isfile(path_xlsx):
        book = openpyxl.load_workbook(path_xlsx)
        
        #[4] If the file and sheet both exist, remove existing sheet
        if sheet_name in book.sheetnames:
            del book[sheet_name]
        with pd.ExcelWriter(path_xlsx, engine='openpyxl', mode='a', if_sheet_exists='new') as writer: #Close the file
            df.to_excel(writer, sheet_name=sheet_name, index=True)
            
    #[5] If file doesn't exist, create a new one
    else:  
        with pd.ExcelWriter(path_xlsx, engine='openpyxl', mode='w') as writer:
            df.to_excel(writer, sheet_name=sheet_name, index=True)
    print(f'--Dataframe saved to {path_xlsx} in sheet {sheet_name}', end='\n\n')
    return path_xlsx



#[5] Excel - End





