def latex_in_txt_file_to_PDF(path_txt):
    """
    Purpose: From a latex code saved in a .txt file, generate a .pdf file,
             ensuring that the bibliography is correctly processed.
    """
    print('\n[latex_in_txt_file_to_PDF]')
    t0 = time.time()
    # [1] Check if the input path exists
    if not os.path.exists(path_txt):
        raise ValueError('File not exist. Please check the file name and path.')
    # [2] Determine if the file is a .txt or .tex file
    if path_txt.endswith('.txt'):
        print('--The input file is .txt, converting to .tex.')
        path_tex = path_txt.rsplit('.', 1)[0] + '.tex'
        shutil.copy(path_txt, path_tex)
    elif path_txt.endswith('.tex'):
        print('--The input file is already .tex.')
        path_tex = path_txt
    else:
        raise ValueError("Unsupported file type. Only .txt and .tex files are supported.")
    dir_pdf = os.path.dirname(path_tex)
    base_name = os.path.splitext(os.path.basename(path_tex))[0]
    os.chdir(dir_pdf)  # Change the current working directory
    #[3] Compile LaTeX document with correct order for bibliography
    print('--[Start compilation]--\n\n')
    try:
        compile_cmd = ['pdflatex', '-shell-escape', '-interaction=nonstopmode', base_name]
        bibtex_cmd = ['bibtex', base_name]
        
        # First LaTeX run to generate AUX file
        subprocess.run(compile_cmd, check=True)
        # Run BibTeX to process bibliography and generate BBL
        subprocess.run(bibtex_cmd, check=True)
        # Run LaTeX again to incorporate bibliography and update citations
        subprocess.run(compile_cmd, check=True)
        # Final LaTeX run to ensure all references are correctly updated
        subprocess.run(compile_cmd, check=True)
    except subprocess.CalledProcessError as e:
        print(f"\n\n--[Error during LaTeX compilation]\n--{e}")
        return None
    
    path_pdf = os.path.join(dir_pdf, base_name + '.pdf')
    t1 = time.time()
    print('\n\n--[End compilation]--')
    print(f'\n\n--PDF saved at: {path_pdf}\nTime duration(s): {round(t1-t0,2)}s')
    return path_pdf



def remove_generated_auxiliary_files(path_tex, remove_log=True, remove_pdf=False):
    """
    Removes auxiliary files generated during LaTeX compilation.
    :param path_tex: Path to the LaTeX file (including .tex extension).
    :param remove_log: Boolean indicating whether to remove .log files.
    :param remove_pdf: Boolean indicating whether to remove the compiled .pdf file.
    """
    print('[remove_generated_auxiliary_files]')
    path_wo_ext = '.'.join(path_tex.split('.')[:-1])
    aux_extensions = ['.aux', '.log', '.out', '.toc', '.lof', '.lot', '.blg', '-blx.bib', '.run.xml']
    if remove_log:
        aux_extensions.append('.log')
    if remove_pdf:
        aux_extensions.append('.pdf')
    for ext in aux_extensions:
        try:
            os.remove(path_wo_ext + ext)
            print(f'-- File removed: {ext}')
        except FileNotFoundError:
            pass
    
    
    





