import os, sys, cv2, re
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from datetime import datetime


def generate_square_wave(period, amplitude, start, end, sample_density):
    num_samples = sample_density * int(end - start)
    t = np.linspace(start, end, num_samples, endpoint=False)
    square_wave = np.sign(np.sin(2 * np.pi * t / period)) * amplitude
    df = pd.DataFrame({'X': t, 'Y': square_wave})
    return df

def fourier_transform(df_signal):
    signal = df_signal['Y'].values
    ft = np.fft.fft(signal)
    freq = np.fft.fftfreq(len(signal))
    df_ft = pd.DataFrame({'X': freq, 'Y': ft})
    return df_ft

def plot_results(df_signal, df_ft, text, dir, basename):
    fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(15, 6))
    
