    ax1.set_xlabel('Time')
    ax1.set_ylabel('Amplitude')
    ax1.set_title('Square Wave')

    ax2.plot(df_ft['X'], np.abs(df_ft['Y']))
    ax2.set_xlabel('Frequency')
    ax2.set_xlim([0, 0.1])
    ax2.set_ylabel('Magnitude')
    ax2.set_title('Fourier Transform')

    add_text_to_matplotlib_figure(fig, text, start_x=0.1, start_y=0.9, line_spacing=0.05,
                                    font_scale=12, font_color=(13/255, 130/255, 240/255), thickness=2)

    plt.tight_layout()
    path_fig = os.path.join(dir, basename)
    plt.savefig(path_fig)


