# File path: D:\01_Floor\a_Ed\09_EECS\10_Python\03_MatureTools\2024-0320_Fourier Transform\FT-03_six-pulse rectifier FFT-modulated.ipynb

import os, sys, cv2, re
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from datetime import datetime


def generate_siz_pulse_reflected_wave(period, amplitude, start, end, sample_density):
    num_samples = sample_density * int(end - start)
    t = np.linspace(start, end, num_samples, endpoint=False)
    freq = 1/period
    omega_t = np.pi * freq * t  # Calculate ωt for the entire array
    
    # Apply the condition to each element using numpy.where
    condition = ((np.pi/6 < omega_t % (2*np.pi)) & (omega_t % (2*np.pi) < 5*np.pi/6)) | \
                ((7*np.pi/6 < omega_t % (2*np.pi)) & (omega_t % (2*np.pi) < 11*np.pi/6))
    
    reflected_wave = np.where(condition, amplitude * np.sin(omega_t), 0)
    
    df = pd.DataFrame({'X': t, 'Y': reflected_wave})
    return df

def fourier_transform(df_signal, sampling_rate):
    signal = df_signal['Y'].values
    ft = np.fft.fft(signal)
    n = len(signal)
    # Assuming sampling_rate is passed correctly to reflect the actual sampling rate of the signal
    freq = np.fft.fftfreq(n, d=1./sampling_rate)
    df_ft = pd.DataFrame({'X': freq, 'Y': ft})
    return df_ft



