def pick_data_with_col2_larger_than_value(df, column_name, v_min, v_max):
    max_a, avg_a, min_a = int(df[column_name].max()), int(df[column_name].mean()), int(df[column_name].min())
    print(f'(max_a, avg_a, min_a) = {max_a:.2f}, {avg_a:.2f}, {min_a:.2f}')
