def resize_photo(dir_input, dir_output, req_w, req_h, start_number):
    print('\n[resize_photo]')
    #[1] Read file list
    list_file_paths = [os.path.join(dir_input, file) for file in os.listdir(dir_input) if file.lower().endswith(('png', 'jpg', 'jpeg', 'bmp', 'gif'))]  # Only image files
    req_w2h = req_w / req_h
    for cnt, iter_path in enumerate(list_file_paths):
        #[2] Read file size.
        with Image.open(iter_path) as img:
            img_w, img_h = img.size
            img_w2h = img_w / img_h
            print(f'--Processing image {cnt}: {os.path.basename(iter_path)}. Original size (w, h) = {img_w}, {img_h}.')
            if img_w2h >= req_w2h:  # Top and bottom filled, left and right cropped.
                #[3] Define result image size.
                end_h = img_h
                end_w = int(end_h * req_w2h)  # Ensure dimensions are integer
                #[4] Crop image. crop box (left, upper, right, lower)
                left = (img_w - end_w) / 2
                right = left + end_w
                crop_box = (int(left), 0, int(right), img_h)
                cropped_img = img.crop(crop_box)
            else:  # Top and bottom cropped, left and right filled.
                #[3] Define result image size.
                end_w = img_w
                end_h = int(end_w / req_w2h)  # Ensure dimensions are integer
                #[4] Crop image. crop box (left, upper, right, lower)
                top = (img_h - end_h) / 2
                bottom = top + end_h
                crop_box = (0, int(top), img_w, int(bottom))
                cropped_img = img.crop(crop_box)

            #[5] Resize the image
            resized_img = cropped_img.resize((req_w, req_h), Image.LANCZOS)
            bsn = f'{(int(start_number) + cnt)}'.zfill(4) + '.jpg'
            path_save = os.path.join(dir_output, bsn)
            resized_img.save(path_save)
            print(f'--Saved resized image as: {path_save}')
           
                
req_w, req_h = 300, 300
start_number = 4500
resize_photo(dir_input, dir_output, req_w, req_h, start_number)


