def gaussian_kernel(size, sigma=1):
    """ Generate a Gaussian kernel. """
    kernel = np.fromfunction(
        lambda x, y: (1/(2*np.pi*sigma**2)) * np.exp(-((x-(size-1)/2)**2 + (y-(size-1)/2)**2) / (2*sigma**2)), 
        (size, size)
    )
    return kernel / np.sum(kernel)








