def list_of_images_into_GIF(list_path_img, fps=10, output_filename='output.gif', bounce=True, compress_ratio=1):
    # [1] Create a list to hold the image data
    image_data = []
    
    # [2] Load each image and apply compression if needed
    for image_path in list_path_img:
        img = Image.open(image_path)
        if compress_ratio != 1:
            # Calculate new dimensions
            new_width = int(img.width * compress_ratio)
            new_height = int(img.height * compress_ratio)
            img = img.resize((new_width, new_height), Image.LANCZOS)
        img_array = np.array(img)  # Convert Pillow image to a NumPy array
        image_data.append(img_array)
    
    # [3] If bounce is true, reverse the image list (excluding the first and last image) and append it to the original list
    if bounce:
        reversed_data = image_data[-2:0:-1]  # Reverse the list but exclude the first and last items to avoid repetition at the ends
        image_data.extend(reversed_data)

    # [4] Create GIF
    output_path = os.path.join(os.path.dirname(list_path_img[0]), output_filename)
    imageio.mimsave(output_path, image_data, format='GIF', fps=fps, loop=0)
    
    return output_path



def add_file_name_as_text_to_image(list_path_img, x, y, font_size, font_color, font_thickness, list_text=[]):
    contain_ext = False
    
    #[1] Create list of text to add onto the image
    if not list_text:
        for iter_path in list_path_img:
            iter_basename = os.path.basename(iter_path)
            if not contain_ext:
                iter_basename = os.path.splitext(iter_basename)[0]
            list_text.append(iter_basename)
    
    #[2] Check length of both lists
    len_path = len(list_path_img)
    len_text = len(list_text)
    if len_path != len_text:
        raise ValueError(f'The number of image paths ({len_path}) and the number of text items ({len_text}) are not equal. Please check.')
    
    #[3] Iterate through images
    list_path_save = []
    for cnt, iter_path in enumerate(list_path_img):
        #[6] Read the image
        image = cv2.imread(iter_path)
        if image is None:
            raise ValueError(f'Image at path {iter_path} could not be read. Please check the file path.')
        
        #[7] Add text to the image
        text = list_text[cnt]
        font = cv2.FONT_HERSHEY_SIMPLEX
        cv2.putText(image, text, (x, y), font, font_size, font_color, font_thickness, cv2.LINE_AA)
        
        #[8] Save the image
        ext = os.path.splitext(iter_path)[1]
        path_save = iter_path.replace(f'{ext}', f'_mk{ext}')
        cv2.imwrite(path_save, image)
        list_path_save.append(path_save)
    return list_path_save



