import sys, re
import numpy as np
from PIL import Image, ImageDraw



def generate_truncated_triangle(truncate_ratio, triangle_size, rotation_angle, position, image_size=(255, 255), ssaa_factor=2):
    """
    Generate an image with a black background and a white truncated equilateral triangle.
    truncate_ratio: 0 for a triangle, and 1 for a hexagon.
    triangle_size: size of the triangle relative to the image. 1 means as big as the image, and 0 means no triangle.
    rotation_angle: the angle in degrees to rotate the shape.
    position: [x, y] where x and y are the ratios of the image width and height, respectively.
    image_size: the desired final image size.
    ssaa_factor: super-sampling anti-aliasing factor (e.g., 2 means 2x the size).
    """
    #[1] Check inputs
    if not (0 <= truncate_ratio <= 1):
        raise ValueError(f'truncate_ratio should be between 0 and 1. It is now {truncate_ratio}.')
    if not (0 <= triangle_size <= 1):
        raise ValueError(f'triangle_size should be between 0 and 1. It is now {triangle_size}.')
    if not (0 <= rotation_angle <= 360):
        raise ValueError(f'rotation_angle should be between 0 and 360 degrees. It is now {rotation_angle}.')
    if not (0 <= position[0] <= 1) or not (0 <= position[1] <= 1):
        raise ValueError(f'position should be between 0 and 1. It is now {position}.')
    
    #[2] Create a blank image with higher resolution for SSAA
    high_res_size = (image_size[0] * ssaa_factor, image_size[1] * ssaa_factor)
    img = Image.new('L', high_res_size, 0)
    draw = ImageDraw.Draw(img)
    
    #[3] Define center of triangle and length
    sx, sy = high_res_size
    tri_cx, tri_cy = sx * position[0], sy * position[1]
    tri_l = min(sx, sy) * triangle_size
    
    #[4] Common constants for equilateral triangle of length 1
    a = 0.5773502692 # 1/(sqrt(3)), the distance of its center to any of its vertices.
    b = 0.2886751346 # 1/(2*sqrt(3)), y distance to the lower vertices.
    
    #[5] From equilateral triangle of length 1, define vertices for hexagon truncated from that.    
    k = truncate_ratio
    
    #[6] Define every vertex
    vA = ((0 - k * 1/6), (a - k * b))
    vB = ((0 + k * 1/6), (a - k * b))
    vC = ((0.5 - k * 1/6), (-b * (1 - k)))
    vD = ((0.5 - k * 1/3), (-b))
    vE = ((-0.5 + k * 1/3), (-b))
    vF = ((-0.5 + k * 1/6), (-b * (1 - k)))
    
    #[7] Collect ABCDEF into an array of vertex coordinates.
    vertices = [vA, vB, vC, vD, vE, vF]
    
    #[8] Apply scaling for triangle size and adjust to the image position
    scaled_vertices = [(tri_cx + tri_l * x, tri_cy + tri_l * y) for x, y in vertices]
    
    #[9] Apply rotation
    rotated_vertices = []
    for x, y in scaled_vertices:
        x -= tri_cx
        y -= tri_cy
        new_x = x * np.cos(np.radians(rotation_angle)) - y * np.sin(np.radians(rotation_angle))
        new_y = x * np.sin(np.radians(rotation_angle)) + y * np.cos(np.radians(rotation_angle))
        rotated_vertices.append((new_x + tri_cx, new_y + tri_cy))
    
    #[10] Draw the polygon
    draw.polygon(rotated_vertices, fill=255)
    
    #[11] Vertically flip the image
    img = img.transpose(Image.FLIP_TOP_BOTTOM)
    
    #[12] Downsample the image to the desired size
    img = img.resize(image_size, Image.Resampling.LANCZOS)
    
    return img




def recover_generation_info_from_filename(bsn_sample):
    """
    Example bsn_sample:
    0020_TR0.03_TS0.29_RA28_P[0.50,0.45].png
    0020_TR0.44_TS0.22_RA12_P[0.56,0.61].png
    0020_TR0.72_TS0.28_RA27_P[0.50,0.50].png
    """
    #[1] Extract filename from path
    #bsn_sample = os.path.basename(path_sample)

    #[2] Define regular expression pattern to match filename structure
    pattern = r'(\d{4})_TR(\d+\.\d+)_TS(\d+\.\d+)_RA(\d+)_P\[(\d+\.\d+),(\d+\.\d+)\]\.png'

    #[3] Use regular expression to match the pattern
    match = re.match(pattern, bsn_sample)

    if match:
        # Extract matched groups
        TR, TS, AR, Px, Py = map(float, match.groups()[1:])  # Excluding the first group (the whole match)
        return TR, TS, AR, Px, Py
    else:
        raise ValueError(f'Filename format does not match the expected pattern. {bsn_sample}')
        return None
    


def check_if_object_touch_edge(img, edge=3):
    """
    For a given PIL image, check if all pixels at the edge=3 pixels are black.
    If yes, return True, if not, return False.
    """
    # Convert image to grayscale if it's not already
    img = img.convert('L')

    # Get image dimensions
    width, height = img.size

    # Get pixel data
    pixels = img.load()

    # Check the top and bottom edges
    for x in range(width):
        for y in range(edge):
            if pixels[x, y] != 0:  # Top edge
                return False
            if pixels[x, height - 1 - y] != 0:  # Bottom edge
                return False

    # Check the left and right edges
    for y in range(height):
        for x in range(edge):
            if pixels[x, y] != 0:  # Left edge
                return False
            if pixels[width - 1 - x, y] != 0:  # Right edge
                return False

    return True
