#[1] Training precheck - start
def check_CUDA_or_ROCm():
    if torch.cuda.is_available():
        print(f'CUDA is available. Device count: {torch.cuda.device_count()}')
        print(f'CUDA Device Name: {torch.cuda.get_device_name(0)}')
    elif torch.backends.mps.is_available() and torch.backends.mps.is_built():
        print('ROCm is available.')
    else:
        print('Neither CUDA nor ROCm is available.')
        sys.exit()


#[1] Training precheck - end





#[3] Dataset and Dataloader - start

class TruncatedTriangleDataset(Dataset):
    def __init__(self, image_dir, transform=None):
        self.image_dir = image_dir
        self.transform = transform
        self.image_files = [f for f in os.listdir(image_dir) if f.endswith('.png')]
        self.truncate_ratios = [M1SG.recover_generation_info_from_filename(f)[0] for f in self.image_files]

    def __len__(self):
        return len(self.image_files)

    def __getitem__(self, idx):
        img_name = os.path.join(self.image_dir, self.image_files[idx])
        image = Image.open(img_name).convert('L')  # Convert to grayscale
        if self.transform:
            image = self.transform(image)
        truncate_ratio = self.truncate_ratios[idx]
        return image, torch.tensor(truncate_ratio, dtype=torch.float32)

# Define transformations for the images
transform = transforms.Compose([
    transforms.Resize((128, 128)),
    transforms.ToTensor(),
])

#[3] Dataset and Dataloader - end



#[5] Model construction - start
class TruncatedTriangleCNN(nn.Module):
    def __init__(self):
        super(TruncatedTriangleCNN, self).__init__()
        self.conv1 = nn.Conv2d(1, 32, kernel_size=3, padding=1)
        self.conv2 = nn.Conv2d(32, 64, kernel_size=3, padding=1)
        self.conv3 = nn.Conv2d(64, 128, kernel_size=3, padding=1)
        self.pool = nn.MaxPool2d(kernel_size=2, stride=2)
        self.fc1 = nn.Linear(128 * 16 * 16, 512)
        self.fc2 = nn.Linear(512, 1)

    def forward(self, x):
        x = self.pool(F.relu(self.conv1(x)))
        x = self.pool(F.relu(self.conv2(x)))
        x = self.pool(F.relu(self.conv3(x)))
        x = x.view(-1, 128 * 16 * 16)  # Flatten the tensor
        x = F.relu(self.fc1(x))
        x = self.fc2(x)
        return x
    
#[5] Model construction - end

# End of [Module_2_Model_and_Training.py]




