def plot_training_result(list_loss, text, path_save):
    #[1] Plot settings
    plt.figure(figsize=(8, 4))

    #[2] Plot
    plt.plot(list_loss, marker='o')
    plt.xlabel('Epoch')
    plt.ylabel('Loss')
    set_xlim = plt.xlim(0, num_epochs)
    set_ylim = plt.ylim(0, 0.1)
    plt.title('Training Loss Over Epochs')
    plt.grid()

    #[3] Add text box with provided information
    plt.text(0.7, 0.60, text, transform=plt.gca().transAxes, fontsize=12,
             verticalalignment='bottom', horizontalalignment='left',
             bbox={'facecolor': 'white', 'alpha': 0.5, 'pad': 10})
    #[4] Save the plot
    plt.savefig(path_save)
    print(f'Plot saved at: {path_save}')
    plt.show()



