#[1] Load the model
path_model = '/content/drive/My Drive/05_Projects/2024-0605_Truncated Triangle Identifier/11_Output/model_2024-0606-1618.pt'

#[2] Recreate the model architecture
model = TruncatedTriangleCNN()

#[3] Load the state dictionary
model.load_state_dict(torch.load(path_model))
model.eval()


#[4] Ensure model is on the same device as the input
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
model.to(device)

#[5] Lists to store the results
list_bsn = []
list_TR_true = []
list_TR_pred = []
list_error = []


#[6] Iterate over the images in the directory
for filename in os.listdir(dir_3):
    if filename.endswith('.png'):
        #[10] Extract true truncate ratio (TR) from the filename
        TR, _, _, _, _ = recover_generation_info_from_filename(filename)

        #[11] Load and preprocess the image
        img_path = os.path.join(dir_3, filename)
        image = Image.open(img_path)
        image = transform(image).unsqueeze(0).to(device)

        #[12] Predict the truncate ratio (TR) using the model
        with torch.no_grad():
            output = model(image)
            TR_pred = output.item()

        #[13] Calculate the error
        error = abs(TR - TR_pred)

        #[15] Store the results in the lists
        print(f'filename: {filename}')
        list_bsn.append(filename)
        list_TR_true.append(TR)
        list_TR_pred.append(TR_pred)
        list_error.append(error)


#[10] Create dataframes to store the results
df_results = pd.DataFrame({
    'Filename': list_bsn,
    'TR True': list_TR_true,
    'TR Pred': list_TR_pred,
    'Error': list_error
})
print(tabulate(df_results, headers='keys', tablefmt='orgtbl'), end='\n\n')


#[12] Calculate mean error
