def save_df_as_excel_overwrite(df, path_xlsx, sheet_name):
    print('\n[save_df_as_excel_overwrite]')
    #[1] Make dir if not exist.
    dir_excel = os.path.dirname(path_xlsx)
    if not os.path.exists(dir_excel):
        os.makedirs(dir_excel)

    #[2] Use openpyxl to preserve existing sheets
    if os.path.exists(path_xlsx):
        with pd.ExcelWriter(path_xlsx, engine='openpyxl', mode='a', if_sheet_exists='replace') as writer:
            df.to_excel(writer, sheet_name=sheet_name, index=True)
    else:
        with pd.ExcelWriter(path_xlsx, engine='openpyxl') as writer:
            df.to_excel(writer, sheet_name=sheet_name, index=True)
            
    print(f'--Dataframe saved to {path_xlsx} in sheet {sheet_name}', end='\n\n')


def read_excel_into_df(path_xlsx, sheet_name=None):
    print('\n[read_excel_into_df]')
    if sheet_name is None:
        sheet_name = 0  # Assuming 0 is the index of the first sheet
    df = pd.read_excel(path_xlsx, sheet_name=sheet_name)
    print('--[dataframe headers]', df.head())
    return df



def average_temp_df_by_minutes(path_xlsx, sheet_name):
    """
    This function reads temperature data from an Excel file, groups the data by minute, 
    and calculates the average temperature for each minute.

    Parameters:
    path_xlsx (str): The path to the Excel file.
    sheet_name (str): The sheet name in the Excel file.
    
    Returns:
    df_avg: (index), Time, TC1, TC2, ...
    """
    # [1] Read data
    df_data = read_excel_into_df(path_xlsx, sheet_name)

    # [2] Validate that the first column is "Time"
    if df_data.columns[0] != 'Time':
        raise ValueError("The first column in the Excel sheet must be named 'Time'.")    

    # [3] Convert 'Time' to datetime format and group by the minute
    df_data['Time'] = pd.to_datetime(df_data['Time'], format='%H:%M:%S')
    df_data['Minute'] = df_data['Time'].dt.floor('T')

    # [4] Calculate the average temperature for each minute
    df_avg = df_data.groupby('Minute').mean()

    # [5] Reset the index to make 'Minute' a regular column and ensure the index is a sequence of integers
    df_avg = df_avg.reset_index()

    # [6] Convert 'Minute' to time format
    df_avg['Minute'] = df_avg['Minute'].dt.time

    # [7] Display the results
    print(f'\n[average_temp_df_by_minutes] {df_avg.shape}')
    print(tabulate(df_avg, headers="keys", tablefmt="orgtbl"))
    
    return df_avg


def plot_temp_trend(df_avg, path_save, name_index_col='Index', name_time_col='Minute', list_name_plot_col=['TC1', 'TC2']):
    """
    Plots the temperature trend from the given DataFrame.

    Parameters:
    df_avg (pd.DataFrame): The DataFrame containing the data to plot.
    list_col_names (list): List of column names to plot. Default is ['Index', 'Minute', 'TC1', 'TC2'].
    """
    # [1] Set start time as the first data of the list_col_names[1] column (Minute).
    start_time = df_avg[name_time_col].iloc[0]
    
    # [2] Check if name_index_col is in columns or is the index
    if name_index_col not in df_avg.columns:
        if name_index_col == df_avg.index.name or name_index_col == 'Index':
            x_values = df_avg.index
        else:
            raise KeyError(f"'{name_index_col}' not found in DataFrame columns or index.")
    else:
        x_values = df_avg[name_index_col]

    # [3] Plot each specified column
    plt.figure(figsize=(10, 6))
    for col in list_name_plot_col:
        print(f'--Plotting {col}')
        plt.plot(x_values, df_avg[col], label=col)

    # [4] Set plot labels and title
    plt.xlabel('Time (min)')
    plt.ylabel('Temperature (°C)')
    plt.title(f'Temperature Trend Starting from {start_time}')
    plt.legend()

    # [5] Display the plot and save the image
    plt.grid(True)

    #[6] Ensure the directory exists before saving
    os.makedirs(os.path.dirname(path_save), exist_ok=True)

    plt.savefig(path_save)
    plt.close()  # Close the plot to avoid display in interactive environments

    print(f'Plot saved at: {path_save}')
    
