def detect_blank_edge_of_image(path_img, color_diff_limit=32, smallest_edge=3, cut_more = 2, little_bar=30):
    print(f'\n[detect_blank_edge_of_image] {os.path.basename(path_img)}')
    #[1] Open image
    arrimg_3D = cv2.imread(path_img)
    arrimg_2D = cv2.cvtColor(arrimg_3D, cv2.COLOR_BGR2GRAY)
    
    #[2] Sum the array.
    vert_sum = np.mean(arrimg_2D, axis=0)
    horz_sum = np.mean(arrimg_2D, axis=1)

    #[3] Image size.
    vert_size, horz_size = arrimg_2D.shape
    horz_start, horz_end = 0, horz_size
    vert_start, vert_end = 0, vert_size
    
    #[4] Correct input values.
    if cut_more > 5 or cut_more > min(vert_size, horz_size):
        cut_more = min(5, min(vert_size, horz_size))
    
    #[4] Check background color.
    edge_color = 0
    if all(sum == vert_sum[0] for sum in vert_sum[:smallest_edge]):
        edge_color = vert_sum[0]
    elif all(sum == horz_sum[0] for sum in horz_sum[:smallest_edge]):
        edge_color = horz_sum[0]  
    else:
        print(f'Could not detect edge color. Set edge_color = {edge_color} for now.')
    
    #[5] Check vertically from the left (start)
    print('\n Check horizontally from the left (end). (column number, sum of ith row, sum of i+1th row)')
    for i_horz in range(horz_size):
        print(f'\t{i_horz}, \t{vert_sum[i_horz]:.0f},  {vert_sum[i_horz + 1]:.0f}')
        #[6] Only calculate the vertical column STD if the next column have different sum.
        if (vert_sum[i_horz] - edge_color) > color_diff_limit:
            if i_horz == 0:
                horz_start = i_horz
            else:
                horz_start = i_horz + cut_more
            print(f'-- horz_start = {horz_start}')
            break

    #[10] Check horizontally from the right (end)
    print('\n Check horizontally from the right (end). (column number, sum of ith row, sum of i+1th row)')
    for i_horz in range(horz_size - 1, -1, -1):
        print(f'\t{i_horz}, \t{vert_sum[i_horz]:.0f},  {vert_sum[i_horz - 1]:.0f}. \t vert_sum[i_vert - little_bar] - edge_color = {vert_sum[i_horz - little_bar] - edge_color:.0f}')
        #[6] Only calculate the vertical column STD if the next column have different sum.
        if (vert_sum[i_horz] - edge_color) > color_diff_limit and (vert_sum[i_horz - little_bar] - edge_color) > color_diff_limit:
            if i_horz == horz_size:
                horz_end = horz_size
            else:
                horz_end = i_horz - cut_more
            print(f'-- horz_end = {horz_end}')
            break


    #[15] Check vertically from the top (start)
    print('\n Check vertically from the top (start). (row number, sum of ith row, sum of i+1th row)')
    for i_vert in range(vert_size):
        print(f'\t{i_vert}, \t{horz_sum[i_vert]:.0f},  {horz_sum[i_vert + 1]:.0f}')
        #[6] Only calculate the vertical column STD if the next column have different sum.
        if (horz_sum[i_vert] - edge_color) > color_diff_limit:
            if i_vert == 0:
                vert_start = i_vert
            else:
                vert_start = i_vert + cut_more
            print(f'-- vert_start = {vert_start}')
            break

    #[20] Check vertically from the bottom (end)
    print('\n Check vertically from the bottom (end). (row number, sum of ith row, sum of i+1th row)')
    for i_vert in range(vert_size - 1, -1, -1):
        print(f'\t{i_vert}, \t{horz_sum[i_vert]:.0f},  {horz_sum[i_vert - 1]:.0f}. \t horz_sum[i_vert - little_bar] - edge_color = {horz_sum[i_vert - little_bar] - edge_color:.0f}')
        #[6] Only calculate the vertical column STD if the next column have different sum.
        if (horz_sum[i_vert] - edge_color) > color_diff_limit and (horz_sum[i_vert - little_bar] - edge_color) > color_diff_limit:
            if i_vert == vert_size:
                vert_end = vert_size
            else:
                vert_end = i_vert - cut_more
            print(f'-- vert_end = {vert_end}')
            break          
    
    #[25] Correct if the edge is too small.
    if horz_start < smallest_edge:
        horz_start = 0
    if horz_end > horz_size - smallest_edge:
        horz_end = horz_size
    if vert_start < smallest_edge:
        vert_start = 0
    if vert_end > vert_size - smallest_edge:
        vert_end = vert_size
        
    #[26] Final print
    print(f'\n-- Origianl Size (vert, horz): [{vert_size}, {horz_size}]\n'\
        f'-- Vertical: [{vert_start}, {vert_end}]\n'\
        f'-- Horizontal: [{horz_start}, {horz_end}]\n')
    
    #[27] Crop image.
    if len(arrimg_3D) == 3:
        arrimg_crop = arrimg_3D[vert_start:vert_end, horz_start:horz_end, :]
    else:
        arrimg_crop = arrimg_3D[vert_start:vert_end, horz_start:horz_end]
    return arrimg_crop







def read_list_image_into_RGB_and_HVS_df_and_save(list_img_path, sampling_rate, path_xlsx):
    """
    1. list_img_path is a list of image paths. Read them into BGR and convert to RGB.
    2. Collect RGB and HVS values into separate DataFrames and save to Excel.
    
    Parameters:
        list_img_path (List[str]): List of image file paths.
        path_xlsx (str): Path to save Excel file.
        sheetname_base (str): Base sheetname for RGB and HVS.
    """
    print(f'\n[read_list_image_into_RGB_and_HVS_df_and_save]')
    # [1] Check if sampling_rate is valid.
    if not (0 < sampling_rate <= 0.01):
        raise ValueError(f'sampling_rate {sampling_rate} should be larger than 0 but less or equal to 0.1.')
    
    # [2] Settings
    cnt_image = len(list_img_path)
    sheetname_RGB = f'01_RGB'
    sheetname_HVS = f'02_HVS'
    list_RGB_rows = []
    list_HVS_rows = []

    # [3] Loop over images
    for i, i_path_image in enumerate(list_img_path):
        i_bsn_image = os.path.basename(i_path_image)
        print(f'-- Processing [{i:02d}/{cnt_image:02d}] {i_bsn_image}')
        # [4] Read image
        arr_BGR = cv2.imread(i_path_image)
        if arr_BGR is None:
            print(f"Warning: Could not read image: {i_path_image}")
            continue
        
        #[5] Resize the image using sampling_rate**0.5
        resize_ratio = sampling_rate**0.5
        new_width = int(arr_BGR.shape[1] * resize_ratio)
        new_height = int(arr_BGR.shape[0] * resize_ratio)
        arr_BGR = cv2.resize(arr_BGR, (new_width, new_height), interpolation=cv2.INTER_AREA)
        
        #[7] Convert to RGB and HSV
        arr_RGB = cv2.cvtColor(arr_BGR, cv2.COLOR_BGR2RGB)
        arr_HSV = cv2.cvtColor(arr_BGR, cv2.COLOR_BGR2HSV)

        
        # [8] Flatten arrays and apply sampling_rate
        arr_RGB_flat = arr_RGB.reshape(-1, 3)
        arr_HVS_flat = arr_HSV.reshape(-1, 3)
        del arr_BGR, arr_RGB, arr_HSV
        gc.collect()

        #[11] We are not recording position or image name to reduce file size.
        for i in range(arr_RGB_flat.shape[0]):
            r, g, b = arr_RGB_flat[i]
            h_, s_, v_ = arr_HVS_flat[i]
            list_RGB_rows.append([r, g, b])
            list_HVS_rows.append([h_, v_, s_]) 
        
    # [13] Create DataFrames
    print(f'-- The following step might take 10 seconds.')
    df_RGB = pd.DataFrame(list_RGB_rows, columns=['R', 'G', 'B'])
    df_HVS = pd.DataFrame(list_HVS_rows, columns=['H', 'V', 'S'])
    print(f'-- df_RGB = {df_RGB.shape}')
    print(f'-- df_HVS = {df_HVS.shape}')
    del list_RGB_rows, list_HVS_rows
    gc.collect()
    
    # [14] Save to Excel
    print(f'-- The following step might take 10 seconds.')
    try:
        # Ensure the directory for the file exists
        dir_save = os.path.dirname(path_xlsx)
        if not os.path.exists(dir_save):
            os.makedirs(dir_save)
            print(f'-- Directory {dir_save} created.')

        # Save the DataFrames to Excel
        with pd.ExcelWriter(path_xlsx, engine='openpyxl', mode='w') as writer:
            df_RGB.to_excel(writer, sheet_name=sheetname_RGB, index=False)
            df_HVS.to_excel(writer, sheet_name=sheetname_HVS, index=False)
        print(f'-- Dataframe saved to {path_xlsx} in sheet {sheetname_RGB} and {sheetname_HVS}.\n')
    except Exception as e:
        print(f'-- Error occurred while saving to Excel: {e}')




def reduce_df_size(df_input, sampling_rate):
    print(f'\n[reduce_df_size] {sampling_rate}')
    # [1] Check if sampling_rate is valid.
    if not (0 < sampling_rate <= 1):
        raise ValueError(f'sampling_rate {sampling_rate} should be larger than 0 but less or equal to 1.')
    
    # [2] Sample the DataFrame.
    df_reduced = df_input.sample(frac=sampling_rate, random_state=42)
    df_reduced.reset_index(drop=True, inplace=True)
    
    print(f'-- Original size: {len(df_input)}, Reduced size: {len(df_reduced)}')
    return df_reduced





