def filter_file_in_dir_with_keywords(dir_folder, list_kwd_yes_or_1=[], list_kwd_no_or_2=[], print_bsn = False):
    print(f'\n[filter_file_in_dir_with_keywords] dir_folder = {dir_folder}')
    #[1] Check if directory exists
    if not os.path.isdir(dir_folder):
        raise FileNotFoundError(f'The directory {dir_folder} was not found.')
    
    #[2] Get list of files in the directory, no folders.
    list_bsns = [file for file in os.listdir(dir_folder) if os.path.isfile(os.path.join(dir_folder, file))]
    cnt_before = len(list_bsns)
    
    #[3] Filter names by keywords to select (if list_kwd_yes_or_1 is not empty list).
    if list_kwd_yes_or_1 != []:
        list_bsns = [file for file in list_bsns if any(keyword in file for keyword in list_kwd_yes_or_1)]
    
    #[4] Filter names by keywords to discard (if list_kwd_no_or_2 is not empty list).
    if list_kwd_no_or_2 != []:
        list_bsns = [file for file in list_bsns if not any(keyword in file for keyword in list_kwd_no_or_2)]
        
    #[5] Generate file paths and orint
    list_paths = [os.path.join(dir_folder, file) for file in list_bsns]
    cnt_after = len(list_bsns)
    if print_bsn:
        print(f'\n--  Count (before, after) = {cnt_before}, {cnt_after}. list_bsns: \n{list_bsns}', end='\n\n')
    return list_paths, list_bsns


def rename_training_file(path_file):
    """
    Rename file with this format of file name: 
    B619_center_00_(9-sbar-1)_wi.jpg
    B621_cent_73_(9-sbar-1)_wi.jpg
    B622_edge_07_(9-sbar-1)_wi.jpg
    
    Into:
    _wi_(B619_center_00).jpg
    _wi_(B621_cent_73).jpg
    _wi_(B622_edge_07).jpg
    """
    #[1] Extract the directory, file name, and extension
    dir_name, base_name = os.path.split(path_file)
    bsn, ext = os.path.splitext(base_name)

    #[2] Check if the file name is already in the target format
    if bsn.startswith("_") and bsn.endswith(")"):
        print(f"-- File already renamed: {path_file}")
        return path_file  # Return the original path without renaming

    #[3] Split the file name to extract the parts
    parts = bsn.split('_')
    
    #[4] Identify the sections to retain and reformat
    prefix = parts[-1]  # '_wi'
    identifier = '_'.join(parts[:-2])  # 'B619_center_00'
    
    #[5] Create the new file name
    new_bsn = f"_{prefix}_({identifier}){ext}"
    
    #[6] Construct new path and rename the file.
    path_new = os.path.join(dir_name, new_bsn)
    os.rename(path_file, path_new)
    print(f'-- File renamed as: {path_new}')
    
    return path_new

def replace_bsnext_with_complete_string(list_file_paths, str_old, str_new):
    print(f'\n[replace_with_complete_string] replacing "{str_old}" with "{str_new}".')
    
    #[1] Check if the given directory exists
    for i, iter_path_file in enumerate(list_file_paths):
        dir_path, bsn_ext = os.path.split(iter_path_file)
        new_bsn_ext = bsn_ext.replace(str_old, str_new)
        new_iter_path_file = os.path.join(dir_path, new_bsn_ext)
        
        #[2] Check if the file names are different and if the original file exists
        if bsn_ext != new_bsn_ext and os.path.exists(iter_path_file):
            os.rename(iter_path_file, new_iter_path_file)
            print(f'[{i:03d}] Renamed as: {new_bsn_ext}')



