def try_convert_float(value):
    try:
        return float(value)
    except ValueError:
        return value

def extract_raman_mapping_data_in_ASCII_txt_from_WITec(path_txt, path_xlsx
                                                       , sheetname_01_Info='01_Info'
                                                       , sheetname_02_Data='02_Raw Data'):
    print(f'\n[remove_unnecessary_part_in_the_front_of_txt] {os.path.basename(path_txt)}')
    
    #[1] Open the text file with 'latin-1' encoding to handle non-UTF-8 characters.
    with open(path_txt, 'r', encoding='latin-1') as file:
        lines = file.readlines()

    #[2] Initialize start_index to None.
    start_index = None
    
    #[3] Find the line that ends with '\tCCD cts\n' and get the index of the line after it.
    for i, line in enumerate(lines):
        if line.endswith('\tCCD cts\n'):
            start_index = i + 1  # Set start_index to the next line
            break
        
    #[4] Extract part I list info.
    bsn_txt = os.path.basename(path_txt)
    partI_list_info = [bsn_txt] + lines[:start_index]
    print(f'[partI_list_info]{partI_list_info[:3]}')

    #[10] Proceed if start_index is found
    if start_index is not None:
        
        #[11] Slice the list of lines from the start_index to the end
        partII_lines = lines[start_index:]
        
    #[13] In case there is no info in the first part.
    else:
        partI_list_info = [bsn_txt]
        partII_lines = lines
        
    #[15] Convert the remaining lines to a 2D array
    list_data = [line.split('\t') for line in partII_lines if line.strip()]
    
    #[17] Convert list of lists to a NumPy array
    partII_array_data = np.array(list_data)
     
    #[20] Convert elements to float if possible
    partII_array_data = np.array([[try_convert_float(cell) for cell in row] for row in partII_array_data])

    #[22] Debug output for array shape
    print(f'\len(partI_list_info) = {len(partI_list_info)}')
    print(f'\npartII_array_data.shape = {partII_array_data.shape}')
    
    #[23] Transpose array to make it more readable.
    partII_array_data = partII_array_data.T
    print(f'\npartII_array_data.shape = {partII_array_data.shape}')
    
    #[23] Create a new Excel workbook
    workbook = openpyxl.Workbook()

    #[24] Write partI_list_info to the first sheet
    sheet_info = workbook.active
    sheet_info.title = sheetname_01_Info
    for row_index, line in enumerate(partI_list_info, start=1):
        sheet_info.cell(row=row_index, column=1, value=line.strip())
    
    #[27] Create a new sheet for partII_array_data
    sheet_data = workbook.create_sheet(title=sheetname_02_Data)
    for row_index, row_data in enumerate(partII_array_data, start=1):
        for col_index, cell_value in enumerate(row_data, start=1):
            sheet_data.cell(row=row_index, column=col_index, value=cell_value)
    
    #[28] Save the workbook to the specified path
    workbook.save(path_xlsx)
    
    return partI_list_info, partII_array_data


def smooth_raman_data_with_Savitzky_Golay_filter(path_xlsx
                                                 , window_length=11, polyorder=3
                                                 , sheetname_input='02_Raw Data'
                                                 , sheetname_output='03_Filtered Data'):
    """
    The first column is the x-axis, 
    the second column is the y-intensity of the first data, 
    the third column is the y-intensity of the second data, 
    and so on.
    Do Savitzky-Golay filtering on each column except the first column.
    Save the smoothed data as sheetname_output.
    
    """
    print(f'\n[smooth_raman_data_with_Savitzky_Golay_filter] {os.path.basename(path_xlsx)}')
    #[1] Open the Excel sheet.
    workbook = openpyxl.load_workbook(path_xlsx)
    sheet_input = workbook[sheetname_input]
    
    # [2] Read data from the input sheet
    data = []
    for row in sheet_input.iter_rows(values_only=True):
        data.append(row)
    
    # Convert data to a numpy array for easier manipulation
    array_data = np.array(data)
    
    # [3] Extract the x-axis (wavenumber) from the first column
    x_wavenumber = array_data[:, 0]
    y_intensities = array_data[:, 1:]
    
    # [4] Apply Savitzky-Golay filter to each column except the first
    smoothed_y_intensities = np.apply_along_axis(
        lambda y: savgol_filter(y, window_length, polyorder), axis=0, arr=y_intensities)
    
    # [5] Combine the x-axis and smoothed y-intensities back into one array
    smoothed_data = np.column_stack((x_wavenumber, smoothed_y_intensities))
    
    # [6] Check if the output sheet exists, if so, remove it
    if sheetname_output in workbook.sheetnames:
        del workbook[sheetname_output]
    
    # [7] Create a new sheet for the filtered data
    sheet_output = workbook.create_sheet(title=sheetname_output)
    
    # [8] Write the smoothed data to the output sheet
    for row in smoothed_data:
        sheet_output.append(row.tolist())
    
    # [9] Save the workbook with the updated data
    workbook.save(path_xlsx)
    
    # [10] Debug output for confirmation
    print(f'Data successfully saved to sheet "{sheetname_output}" in "{path_xlsx}".')
    


