def find_the_peak_among_top_n_points(array_data, path_xlsx, sheetname='04_Top n', show_top=5, list_possible_peaks=[385, 405]):
    print(f'\n[find_the_peak_among_top_n_points] \t Size of data: {array_data.shape}, show top {show_top} of points.')
    
    #[2] Check if there is only two peaks.
    if len(list_possible_peaks) != 2:
        raise ValueError(f'list_possible_peaks should have a length of 2, it\'s now {list_possible_peaks}.')
    
    #[3] Extract the x-axis (wavenumber) from the first column
    x_wavenumber = array_data[:, 0]
    y_intensities = array_data[:, 1:]
    
    #[4] Calculate the max in each column in y_intensities, and find the index of top (show_top=5)).
    max_int_in_each_point = np.max(y_intensities, axis=0)
    indices_of_top_n_point = np.argsort(max_int_in_each_point)[-show_top:][::-1]
    y_int_of_top_n_point = y_intensities[:, indices_of_top_n_point]
    array_data_top_n = np.column_stack((x_wavenumber, y_int_of_top_n_point))
    print(f'[array_data_top_n.shape] {array_data_top_n.shape}')
    save_2d_array_to_existing_excel(path_xlsx, array_data_top_n, sheetname)
    
    #[5] Calculate the sum in each column in y_intensities, and find the index of the peak.
    sum_int_by_x_wn = np.sum(y_int_of_top_n_point, axis=1)
    indices_of_top_x_wn = np.argsort(sum_int_by_x_wn)[::-1][:50]
    
    #[5] Generate a new array of x_wavenumber from array of index indices_of_top_x_wn
    #top_x_wavenumbers = x_wavenumber[indices_of_top_x_wn]
    
    #[6] Start sorting.
    list_peak_E2g, list_peak_A1g = [], []
    k_wn = 8
    for i in indices_of_top_x_wn:
        
        #[7] Check the range of x_wn.
        i_x_wn = x_wavenumber[i]
        #print(f'[{i}] i_x_wn: {i_x_wn}\t', end='')
        if  abs(i_x_wn-list_possible_peaks[0]) < k_wn:
            if len(list_peak_E2g) <= 5:
                list_peak_E2g.append(i_x_wn)
        elif  abs(i_x_wn-list_possible_peaks[1]) < k_wn:
            if len(list_peak_A1g) <= 5:
                list_peak_A1g.append(i_x_wn)
                
    #[8] Average the peaks.
    peak_E2g = np.round(np.mean(list_peak_E2g), 3)
    peak_A1g = np.round(np.mean(list_peak_A1g), 3)
    diff_E2g_A1g = np.round(np.mean(list_peak_A1g) - np.mean(list_peak_E2g), 3)
    print(f'\t [peak_E2g]{peak_E2g:.3f}, \t list_peak_E2g: {list_peak_E2g}')      
    print(f'\t [peak_A1g]{peak_A1g:.3f}, \t list_peak_A1g: {list_peak_A1g}')
    print(f'\t\t A1g - E2g = {diff_E2g_A1g:.3f} (1/cm).')

    return peak_E2g, peak_A1g, diff_E2g_A1g
    

    
    
