def visualize_outlier_as_2D_colormap_stupid(array_data, data_title, path_save):
    print('\n[visualize_outlier_as_2D_colormap]')
    #[3] Extract the x-axis (wavenumber) from the first column
    x_wavenumber = array_data[0, :]
    y_intensities = array_data[1:, :]
    
    fs_title, fs_axis, ft_tick, fs_cbar = 32, 28, 24, 24  # Increased color bar font size
    
    #[5] Plot y_intensities as 2D color map with viridis colormap.
    plt.figure(figsize=(25, 20))
    extent = [x_wavenumber[0], x_wavenumber[-1], 0, y_intensities.shape[0]]
    data_aspect = (extent[1] - extent[0]) / (extent[3] - extent[2])
    im = plt.imshow(y_intensities, aspect=data_aspect, cmap='viridis', extent=extent)
    
    #[6] Adjust the color bar size and font
    cbar = plt.colorbar(im, label='Intensity', fraction=0.04, pad=0.01)  # Thinner color bar
    cbar.ax.yaxis.set_tick_params(color='lightgray', labelsize=fs_cbar)  # Increase text size
    plt.setp(plt.getp(cbar.ax.axes, 'yticklabels'), color='lightgray')
    cbar.set_label('Intensity', fontsize=fs_cbar)  
    plt.xlabel('Wavenumber', color='lightgray', fontsize=fs_axis)
    plt.ylabel('Sample Index', color='lightgray', fontsize=fs_axis)
    
    #[8] Set the y-axis to count from the upper left
    sample_cnt = y_intensities.shape[0]
    tick_count = 10  # Aim for ~10 major ticks
    available_ticks = np.array([10, 20, 25, 50, 100, 250])
    desired_tick_size = sample_cnt / tick_count
    tick_size = available_ticks[np.argmin(np.abs(available_ticks - desired_tick_size))]
    yticks = np.arange(0, sample_cnt, tick_size)
    
    #[9] Ensure the last index is included
    if yticks[-1] != sample_cnt - 1:
        yticks = np.append(yticks, sample_cnt - 1)
    yticks_reverse = yticks[::-1]  # Reverse the order for labeling
    plt.yticks(yticks, yticks_reverse)
    plt.title(data_title, color='lightgray', fontsize=fs_title)
    
    plt.gca().set_facecolor('black')
    plt.gcf().patch.set_facecolor('black')
    plt.gca().tick_params(axis='x', colors='lightgray', labelsize=ft_tick)
    plt.gca().tick_params(axis='y', colors='lightgray', labelsize=ft_tick)
    plt.tight_layout()
    plt.savefig(path_save, bbox_inches='tight', facecolor='black')
    plt.close()

