def fit_one_peak(peak_start, peak_end, x_wavenumber, i_y_intensity, 
                 bl_guess, use_peak_range_only =True):
    """
    Fit a single Lorentzian peak to the data.
    Use the following as initial guess:
    x01 (peak position) = np.mean([peak_start, peak_end])
    a1 (peak height) = max(i_y_intensity)
    gamma1 (half FWHM) =  0.25 * (peak_end - peak_start)
    """
    
    # [3] Initial guess for the parameters: [location1, FWHM1, intensity1, baseline]
    FWHM1_guess = 0.25 * (peak_end - peak_start)
    initial_guess = [np.mean([peak_start, peak_end]), 
                     FWHM1_guess, 
                     max(i_y_intensity) - bl_guess, 
                     bl_guess]
    
    # [5] Define parameter bounds ([location1, FWHM1, intensity1, baseline])
    lower_bounds = [peak_start,
                    FWHM1_guess*0.1,
                    0,
                    bl_guess * 0.99] 
    upper_bounds = [peak_end,
                    FWHM1_guess*2,
                    max(i_y_intensity)*1.2 - bl_guess,
                    bl_guess * 1.01]
    
    # [7] Trim the fitting range if needed
    if use_peak_range_only:
        len_x = len(x_wavenumber)
        x_idx_start = min(range(len_x), key=lambda i: abs(peak_start - x_wavenumber[i]))
        x_idx_end = min(range(len_x), key=lambda i: abs(peak_end - x_wavenumber[i])) + 1 
        x_wavenumber = x_wavenumber[x_idx_start:x_idx_end]
        i_y_intensity = i_y_intensity[x_idx_start:x_idx_end]
    
    try:
        # [8] Curve fitting with the single Lorentzian function
        popt, _ = curve_fit(single_lorentzian, x_wavenumber, i_y_intensity, 
                            p0=initial_guess, bounds=(lower_bounds, upper_bounds))
        fit_pos1, fit_gamma1, fit_int1, fit_bl = map(float, popt)
        fit_FWHM1 = 2 * fit_gamma1
        
        # [9] Calculate the fitted curve
        fitted_curve = single_lorentzian(x_wavenumber, fit_pos1, fit_gamma1, fit_int1, fit_bl)
        
        # [12] Compute R² value
        ss_res = np.sum((i_y_intensity - fitted_curve) ** 2)  # Sum of squared residuals
        ss_tot = np.sum((i_y_intensity - np.mean(i_y_intensity)) ** 2)  # Total sum of squares
        fit_r2 = 1 - (ss_res / ss_tot) if ss_tot != 0 else None  # Avoid division by zero
        
        return np.array([fit_pos1, fit_int1, fit_FWHM1, fit_bl, fit_r2])
    except RuntimeError:
        return np.array([None, None, None, None, None])
    
    





