def fit_one_peak_lorentzian(peak_start, peak_end, x_spectral_unit, i_y_intensity, 
                 bl_int, bl_range, use_peak_range_only =True):
    """
    Fit a single Lorentzian peak to the data.
    Use the following as initial guess:
    range = peak_end - peak_start
    range should be 2 x basewidth, and 4 x FWHM
    FWHM = 2 * gamma1 for Lorentzian
    Therefore, FWHM = 0.25 * range, so range_to_width_r is set to 0.25.    
    """
    
    #[3] Initial guess for the parameters: [position, height, gamma, baseline]
    range_to_width_r = 0.02
    window_to_range_r = 0.30
    peak_pos_lower, peak_pos_upper = M3PFF.compute_peak_bounds_from_peak_range(peak_start, peak_end, window_to_range_r)
    
    #[4] Trim the fitting range if needed
    if use_peak_range_only:
        len_x = len(x_spectral_unit)
        x_idx_start = min(range(len_x), key=lambda i: abs(peak_start - x_spectral_unit[i]))
        x_idx_end = min(range(len_x), key=lambda i: abs(peak_end - x_spectral_unit[i])) + 1 
        x_spectral_unit = x_spectral_unit[x_idx_start:x_idx_end]
        i_y_intensity = i_y_intensity[x_idx_start:x_idx_end]
    
    
    #[5] Compute initial guess for the parameters.
    print_guess = False
    peak_position_guess, peak_height_guess, peak_FWHM_guess, text_no_signal \
        = peak_initial_guess(x_spectral_unit, i_y_intensity, 
                            peak_start, peak_end, 
                            peak_pos_lower, peak_pos_upper,
                            bl_int, bl_range, range_to_width_r,
                            print_guess)
    gamma_guess = peak_FWHM_guess / 2   # Definition of Lorentzian FWHM.
    
    #[5] Compose intitial guess.
    initial_guess = [peak_position_guess, 
                     peak_height_guess, 
                     gamma_guess, 
                     bl_int]
    #print('Initial guess (Lorentzian):', initial_guess)
    
    #[6] Define parameter bounds: [position, height, gamma, baseline]
    lower_bounds = [peak_pos_lower,
                    peak_height_guess * 0.8,
                    gamma_guess * 0.01,
                    bl_int * 0.8] 
    upper_bounds = [peak_pos_upper,
                    peak_height_guess * 1.2,
                    int(gamma_guess * 50),
                    bl_int * 1.2]
    
    #[7] Start fitting.
    try:
        # [8] Curve fitting with the single Lorentzian function
        popt, _ = curve_fit(single_lorentzian, x_spectral_unit, i_y_intensity, 
                            p0=initial_guess, bounds=(lower_bounds, upper_bounds))
                            # method='trf', max_nfev=10000, ftol=1e-6
        fit_pos1, fit_int1, fit_gamma1, fit_bl = map(float, popt)
        
        # [9] Calculate the fitted curve
        fitted_curve = single_lorentzian(x_spectral_unit, fit_pos1, fit_int1, fit_gamma1, fit_bl)
        
        # [12] Compute R² value
        ss_res = np.sum((i_y_intensity - fitted_curve) ** 2)  # Sum of squared residuals
        ss_tot = np.sum((i_y_intensity - np.mean(i_y_intensity)) ** 2)  # Total sum of squares
        fit_r2 = 1 - (ss_res / ss_tot) if ss_tot != 0 else None  # Avoid division by zero
        
        fitting_result_L =  np.array([fit_pos1, fit_int1, fit_gamma1, fit_bl, fit_r2])
    except RuntimeError:
        fitting_result_L =  np.array([None, None, None, None, None])
        
    #[8] Optionally print the fitting result.
    if print_guess:
        lower_bounds = [round(val, 2) if isinstance(val, (float, int)) else val for val in lower_bounds]
        print(f'Lower bounds: \t\t{lower_bounds}')
        upper_bounds = [round(val, 2) if isinstance(val, (float, int)) else val for val in upper_bounds]
        print(f'Upper bounds: \t\t{upper_bounds}')
        formatted_result = [round(val, 2) if isinstance(val, (float, int)) else val for val in fitting_result_L]
        print(f'Fitting result: \t{formatted_result}\n')
    
    #[15] Organize log as df_log.
    titles = ['Initial Guess', 'Lower Bounds', 'Upper Bounds', 'Fitting Result']
    data = {
        'Title': titles,
        'Position': [initial_guess[0], lower_bounds[0], upper_bounds[0], fitting_result_L[0]],
        'Height': [initial_guess[1], lower_bounds[1], upper_bounds[1], fitting_result_L[1]],
        'Gamma': [initial_guess[2], lower_bounds[2], upper_bounds[2], fitting_result_L[2]],
        'Baseline': [initial_guess[3], lower_bounds[3], upper_bounds[3], fitting_result_L[3]],
        'R²': [np.nan, np.nan, np.nan, fitting_result_L[4]]
    }
    df_log = pd.DataFrame(data)
    df_log = df_log.applymap(lambda x: f"{x:.5f}" if isinstance(x, (float, int)) else x)
    text_fit = f'\n[Lorentzian] {text_no_signal}\n{tabulate(df_log, headers="keys", tablefmt="orgtbl")}\n'
    
    return fitting_result_L, text_fit, text_no_signal
    







