def fit_two_peak_lorentzian(peak_start, peak_end, x_spectral_unit, i_y_intensity, 
                            peak1_pos, peak1_int, peak2_gamma,
                 bl_int, bl_range, use_peak_range_only =True):
    """
    Fit a single Lorentzian peak to the data.
    Use the following as initial guess:
    range = peak_end - peak_start
    range should be 2 x basewidth, and 4 x FWHM
    FWHM = 2 * gamma1 for Lorentzian
    Therefore, FWHM = 0.25 * range, so range_to_width_r is set to 0.25.    
    """
    
    #[3] Initial guess for the parameters: [position, height, gamma, baseline]
    range_to_width_r = 0.02
    window_to_range_r = 0.30
    peak_pos_lower, peak_pos_upper = M3PFF.compute_peak_bounds_from_peak_range(peak_start, peak_end, window_to_range_r)
    
    #[4] Trim the fitting range if needed
    if use_peak_range_only:
        len_x = len(x_spectral_unit)
        x_idx_start = min(range(len_x), key=lambda i: abs(peak_start - x_spectral_unit[i]))
        x_idx_end = min(range(len_x), key=lambda i: abs(peak_end - x_spectral_unit[i])) + 1 
        x_spectral_unit = x_spectral_unit[x_idx_start:x_idx_end]
        i_y_intensity = i_y_intensity[x_idx_start:x_idx_end]
    
    #[5] Compute initial guess for the parameters.
    print_guess = False
    peak_position_guess, peak_height_guess, peak_FWHM_guess, text_no_signal \
        = peak_initial_guess(x_spectral_unit, i_y_intensity, 
                            peak_start, peak_end, 
                            peak_pos_lower, peak_pos_upper,
                            bl_int, bl_range, range_to_width_r,
                            print_guess)
    gamma_guess = peak_FWHM_guess / 2   # Definition of Lorentzian FWHM.

    #[5] Compose intitial guess for first peak.
    peak1_initial_guess = [peak1_pos, 
                        peak1_int, 
                        peak2_gamma, 
                        bl_int]
    #print('Initial guess (Lorentzian):', initial_guess)
    
    #[6] Define parameter bounds: [position, height, gamma, baseline]
    peak1_lower_bounds = [peak1_pos - 2,
                        peak1_int - 10,
                        peak2_gamma * 0.8,
                        bl_int * 0.9] 
    peak1_upper_bounds = [peak1_pos + 2,
                        peak1_int - 10,
                        peak2_gamma * 0.8,
                        bl_int * 0.9] 
    

    
    #double_lorentzian(x, x01, a1, gamma1, x02, a2, gamma2, bl)
    
  
    return fitting_result_L, text_fit, text_no_signal
    

