def fit_trimmed_spectrum_with_three_methods(trimmed_array_data, is_Raman,
                                            peak_range, use_peak_range_only, 
                                            sw4_plot_ovlp_spectra, plot_title, path_save,
                                            df_time=None, df_fit=None, df_R2=None, text_log=None):
    """
    Fits the trimmed spectrum using three methods (Gaussian, Lorentzian, Voigt) and updates DataFrames.

    Parameters:
        trimmed_array_data (ndarray): The trimmed spectrum data.
        peak_start (float): Start of the peak range.
        peak_end (float): End of the peak range.
        use_peak_range_only (bool): Whether to use only the peak range for fitting.
        sheetname_input (str): Name of the sheet being processed.
        dir_avg_data (str): Directory to save plots.
        sw4_plot_ovlp_spectra (bool): Whether to plot overlapping spectra.
        df_time (DataFrame): DataFrame to store time data for each method.
        df_R2 (DataFrame): DataFrame to store R² values for each method.
        text_log (str): Log text to append fitting details.

    Returns:
        tuple: Updated (df_time, df_R2, text_log).
    """
    print('\n[fit_trimmed_spectrum_with_three_methods]')
    #[12] If dataframe is empty, create it with appropriate columns.
    if df_time is None:
        df_time = pd.DataFrame(columns=['Peak Range', 'Method', 'Time (sec)'])
    if df_fit is None:
        df_fit = pd.DataFrame(columns=['Peak Range', 'Method', 'Parameters'])
    if df_R2 is None:
        df_R2 = pd.DataFrame(columns=['Peak Range', 'Gaussian', 'Lorentzian', 'Voigt'])
    if text_log is None:
        text_log = f'(text_log was not provided.)\n\n-----\n[Peak Range] {peak_start} ~ {peak_end}\n'\
                    f'trimmed_array_data.shape: {trimmed_array_data.shape}\n'

    #[13] Unpack peak range.
    peak_start, peak_end = M3PFF.unpack_peak_range(peak_range)
    
    # [14] Optionally plot the trimmed spectrum.
    if sw4_plot_ovlp_spectra:
        M4VIS.plot_overlapping_spectra(trimmed_array_data, None, is_Raman, plot_title, path_save)

    # [15] Fit spectrum (Gaussian, Lorentzian, Voigt).
    t1 = time.time()
    print(f't1 = {t1}')
    array_fitting_result_G, text_fit, _ = fit_mapping_data_with_single_peak(
        trimmed_array_data, peak_start, peak_end, 'Gaussian', use_peak_range_only)
    text_log += text_fit
    t2 = time.time()
    print(f't2 = {t2}')

    array_fitting_result_L, text_fit, _ = fit_mapping_data_with_single_peak(
        trimmed_array_data, peak_start, peak_end, 'Lorentzian', use_peak_range_only)
    text_log += text_fit
    t3 = time.time()
    array_fitting_result_V, text_fit, _ = fit_mapping_data_with_single_peak(
        trimmed_array_data, peak_start, peak_end, 'Voigt', use_peak_range_only)
    text_log += text_fit
    t4 = time.time()

    print(f'array_fitting_result_G: {array_fitting_result_G}')
    print(f'array_fitting_result_L: {array_fitting_result_L}')
    print(f'array_fitting_result_V: {array_fitting_result_V}')
    sys.exit()
    
    # [18] Convert fitting result to dataframe.
    M4VIS.plot_overlapping_spectra_to_test_diff_fitting_method(
        trimmed_array_data, plot_title, path_save,
        array_fitting_result_G, array_fitting_result_L, array_fitting_result_V)

    # [20] Append time data to df_time.
    df_time = pd.concat([
        df_time,
        pd.DataFrame([
            {'Peak Range': f'{peak_start} ~ {peak_end}', 'Method': 'Gaussian', 'Time (sec)': round(t2 - t1, 5)},
            {'Peak Range': f'{peak_start} ~ {peak_end}', 'Method': 'Lorentzian', 'Time (sec)': round(t3 - t2, 5)},
            {'Peak Range': f'{peak_start} ~ {peak_end}', 'Method': 'Voigt', 'Time (sec)': round(t4 - t3, 5)}
        ])
    ], ignore_index=True)

    # [20] Append fitting data to df_fit.
    df_fit = pd.concat([
        df_fit,
        pd.DataFrame([
            {'Peak Range': f'{peak_start} ~ {peak_end}', 
             'Method': 'Gaussian', 
             'Parameters': array_fitting_result_G[0]},
            {'Peak Range': f'{peak_start} ~ {peak_end}', 
             'Method': 'Lorentzian', 
             'Parameters': array_fitting_result_L[0]},
            {'Peak Range': f'{peak_start} ~ {peak_end}', 
             'Method': 'Voigt', 
             'Parameters': array_fitting_result_V[0]}
        ])
    ], ignore_index=True)
    
    #[20] Append R² values to df_R2.
    df_R2 = pd.concat([
        df_R2,
        pd.DataFrame([
            {'Peak Range': f'{peak_start} ~ {peak_end}', 
             'Gaussian': array_fitting_result_G[0][4], 
             'Lorentzian': array_fitting_result_L[0][4], 
             'Voigt': array_fitting_result_V[0][5]}
        ])
    ])

    return df_time, df_fit, df_R2, text_log









def fit_mapping_data_with_two_overlapping_peaks(array_data, peak_start, peak_end, 
                                                fit_method, peak2_pos_bias, peak2_int_ratio, peak2_width_ratio,
                                                use_peak_range_only=True):
    """
    2025-05-01_I think this ia outdated and need to be fix.
    There are two peaks, the first peak is larger, and the second peak is smaller.
    The position of the second smaller peak is peak2_pos_bias higher than the first larger peak.
    The intensity of the second peak is peak2_int_ratio times the first peak.
    The width of the second peak is peak2_width_ratio times the first peak.
    Fit the first peak first, and fit two peaks together on second trail.
    
    """
    print(f'\n[fit_mapping_data_with_single_peak] {peak_start} ~ {peak_end}, {fit_method}')
    # [1] Validate input
    if array_data.shape[0] < 2:
        raise ValueError("array_data must have at least two rows: one for x-axis and one for y-intensities.")
    if fit_method not in ['Gaussian', 'Lorentzian', 'Voigt']:
        raise ValueError(f'Unknown fit_method: {fit_method}. Supported methods are "Gaussian", "Lorentzian", "Voigt".')
    print_status = False
    
    #[2] Get the number of data sets from the shape of the array
    num_data_sets = array_data.shape[0] - 1
    list_text_no_signal = []
    
    #[3] Extract the x-axis (wavenumber); compute baseline value
    x_spectral_unit = array_data[0, :]
    bl_int, bl_range = compute_baseline_stat(array_data, pct=80)

    #[4] Initialize an empty array to store fitting results
    result_shape = (0, 5) if fit_method in ['Gaussian', 'Lorentzian'] else (0, 6)
    array_fitting_result = np.empty(result_shape)
    text_fitting_logs = f'[{num_data_sets} datasets] Fitting with {fit_method} method.\n'
    
    #[5] Map fitting methods to corresponding functions
    fit_methods = {
        'Gaussian': M3PFF.fit_one_peak_gaussian,
        'Lorentzian': M3PFF.fit_one_peak_lorentzian,
        'Voigt': M3PFF.fit_one_peak_voigt
    }
    fit_function = fit_methods[fit_method]
    

    #[6] Fit the peaks by iterate over each data set.
    for i in range(num_data_sets):
        iter_y_intensity = array_data[i + 1, :]
        
        # [7] Print the current dataset number
        text_2 = f'\n[{i:04d}/{num_data_sets:04d}]'
        text_fitting_logs += text_2
        if print_status:
            print(text_2)
        
        try:
            i_fitting_result, text_fit, text_no_signal \
                = fit_function([peak_start, peak_end], 
                               x_spectral_unit, iter_y_intensity, 
                               bl_int, bl_range, use_peak_range_only)
        except Exception as e:
            i_fitting_result = [None] * result_shape[1]
            text_fit = f"Error fitting dataset {i}: {str(e)}"
            text_no_signal = None
        list_text_no_signal.append(text_no_signal)
        
        #[8] Append the fitting result and log
        array_fitting_result = np.vstack([array_fitting_result, i_fitting_result])
        text_fitting_logs += text_fit

        #[9] Selectively print fitting process.
        if i % 10 == 0:
            formatted_result = ',\t'.join([f'{val:.4f}' if val is not None else 'None' for val in i_fitting_result])
            print(f"[{i:04d}/{num_data_sets:04d}] {formatted_result}")


    return array_fitting_result, text_fitting_logs, list_text_no_signal






