def tkinter_select_file(dialog_title='Select a file', allow_close=False):
    """
    Necessary import statement:
    import os, sys, tkinter
    from tkinter import filedialog
    """
    #[1] Create a window (or container) for the Tkinter GUI (Graphical User Interface) toolkit.
    root = tkinter.Tk()
    root.withdraw()  # Hide the main window since we don't need to see it.
    root.lift()  # Bring the window to the front
    root.attributes('-topmost', True)  # Make it stay on top
    root.after(1, lambda: root.attributes('-topmost', False))  # Allow other windows to take focus after

    try:
        path_file = tkinter.filedialog.askopenfilename(title=dialog_title)
        if path_file:
            #[2] Extract the base name of the selected file.
            bsn_file = os.path.basename(path_file)
            #[3] Clean the path.
            path_file = os.path.normpath(path_file)
            print('--path_file:', path_file)
            return path_file, bsn_file
        else:
            #[4] Allow no file selecte.
            if allow_close:
                return None, None
            #[5] Exit the program if no file is selected.
            else:
                print('--No file selected. Exiting.')
                sys.exit()
    except Exception as e:
        print(f'--An error occurred: {e}')
        return None, None
    finally:
        #[6] Release resources.
        root.destroy()


