def find_excel_sheetname_with_keyword(path_xlsx, list_sheetname_kwd):
    """
    list_sheetname_kwd = ['Calib', 'TSD']
    If list_sheetname_kwd[0] cannot be found, print a warning and find the next list_sheetname_kwd[1].
    If all list_sheetname_kwd cannot be found, raise an error.
    """
    import openpyxl
    #[1] Check if list_sheetname_kwd is a list
    if not isinstance(list_sheetname_kwd, list):
        raise ValueError(f'The parameter "list_sheetname_kwd" must be a list. It is now a {type(list_sheetname_kwd)}')

    #[[2]] Load workbook
    wb = openpyxl.load_workbook(path_xlsx, read_only=True)
    sheetnames = wb.sheetnames

    #[[3]] Iterate through the keywords to find matches
    for i_sheetname_kwd in list_sheetname_kwd:
        # Ensure `sheetname_kwd` is a string before calling `.lower()`
        if not isinstance(i_sheetname_kwd, str):
            raise TypeError(f"Keyword '{i_sheetname_kwd}' is not a string.")
        
        list_sheetname_match = [name for name in sheetnames if i_sheetname_kwd.lower() in name.lower()]
        if list_sheetname_match:
            print(f'\n[find_excel_sheetname_with_keyword] Found matching sheets for keyword "{i_sheetname_kwd}": {list_sheetname_match}')
            return list_sheetname_match

    #[4] If no matches are found for any keyword, raise an error
    raise ValueError(f'\n[find_excel_sheetname_with_keyword] No sheet contains any of the keywords: {list_sheetname_kwd}')



