def calculate_data_density(array_data):
    x_spectral_unit = array_data[0, :]
    x_max = max(x_spectral_unit)
    x_min = min(x_spectral_unit)
    x_len = len(x_spectral_unit)
    data_density = x_len / (x_max - x_min)
    print(f'\n[calculate_data_density] {data_density:.03f} data points for every unit. ({x_max}, {x_min}, {x_len})')
    return data_density


def increase_data_density(array_data, target_data_density):
    """
    Resample array_data to the specified target_data_density.
    Supports multiple y-traces (shape: [N+1, M]).
    """
    # [1] Extract x and y
    x_spectral_unit = array_data[0, :]
    y_intensities = array_data[1:, :]

    # [2] Define new x-axis with consistent spacing (datum_size)
    datum_size = 1 / target_data_density
    x_min, x_max = np.min(x_spectral_unit), np.max(x_spectral_unit)

    #[3] Round x_min down and x_max up to the nearest multiple of datum_size
    x_min_perfect = np.floor(x_min / datum_size) * datum_size
    x_max_perfect = np.ceil(x_max / datum_size) * datum_size
    
    print(f'x_min_perfect, x_max_perfect = {x_min_perfect}, {x_max_perfect}')
    
    x_dense = np.arange(x_min_perfect, x_max_perfect + datum_size, datum_size)

    # [4] Interpolate each y trace
    y_dense_list = []
    for y_trace in y_intensities:
        f_interp = interp1d(x_spectral_unit, y_trace, kind='cubic', fill_value='extrapolate')
        y_dense = f_interp(x_dense)
        y_dense_list.append(y_dense)

    # [5] Stack x and interpolated y into new 2D array
    array_data_dense = np.vstack([x_dense] + y_dense_list)

    print(f'\n[increase_data_density] Original: {len(x_spectral_unit)} → New: {len(x_dense)} points')
    return array_data_dense


def compute_baseline_stat(array_data, pct=80):
    """
    Find baseline by averaging the lower pct% of the data.
    """
    #[1] Extract y_intensities from array_data.
    y_intensities = array_data[1:, :]
    y_intensities_1Dsorted = np.sort(y_intensities.flatten())
    y_intensities_lower_pct = y_intensities_1Dsorted[:int(len(y_intensities_1Dsorted) * pct / 100)]
    
    #[2] Baseline statistics.
    bl_int = np.mean(y_intensities_lower_pct)
    bl_range = np.max(y_intensities_lower_pct) - np.min(y_intensities_lower_pct)
    print(f'\n[compute_baseline_stat] (bl_int, bl_range): {bl_int:.3f}, {bl_range:.3f}')
    del y_intensities, y_intensities_1Dsorted, y_intensities_lower_pct
    gc.collect()
    return bl_int, bl_range



def compute_baseline_range_avg(array_data, x_range):
    """
    Find baseline by averaging intensity values within a specified x_range.
    """
    #[1] Extract x and y
    x_spectral_unit = array_data[0, :]
    y_intensities = array_data[1:, :]

    #[2] Handle x_range
    if not isinstance(x_range, (list, tuple)) or len(x_range) != 2:
        raise ValueError(f'Invalid format for x_range: {x_range}')
    x_min, x_max = x_range

    #[3] Get valid indices within x_range
    mask = (x_spectral_unit >= x_min) & (x_spectral_unit <= x_max)
    if not np.any(mask):
        raise ValueError(f"No data points found within range: {x_range}")
    
    #[4] Slice and flatten
    y_in_range = y_intensities[:, mask].flatten()

    #[5] Baseline statistics
    bl_int = np.mean(y_in_range)
    bl_range = np.max(y_in_range) - np.min(y_in_range)
    print(f'\n[compute_baseline_range_avg] (bl_int, bl_range): {bl_int:.3f}, {bl_range:.3f}')
    
    del y_intensities, y_in_range
    gc.collect()
    return bl_int, bl_range




