def smooth_array_data_with_Savitzky_Golay(array_data, window_length=11, polyorder=3):
    """
    window_length (int): The length of the filter window (must be a positive odd integer).
    polyorder (int): The order of the polynomial used to fit the samples.
    """
    # [1] Input validation
    if window_length % 2 == 0 or window_length <= 0:
        raise ValueError("window_length must be a positive odd integer")
    if polyorder >= window_length:
        raise ValueError("polyorder must be less than window_length")

    # [2] Extract the x-axis (wavenumber) from the first row
    x_spectral_unit = array_data[0, :]
    y_intensities = array_data[1:, :]

    # [3] Apply Savitzky-Golay filter to each row
    try:
        y_intensities_smoothed = np.apply_along_axis(
            lambda y: savgol_filter(y, window_length, polyorder), axis=1, arr=y_intensities)
    except Exception as e:
        print(f"Error during Savitzky-Golay filtering: {e}")
        raise

    return x_spectral_unit, y_intensities_smoothed


def smooth_spectrum_data(path_xlsx
                        , window_length=11, polyorder=3
                        , sheetname_input='02_Raw Data'
                        , sheetname_output='03_Filtered Data'):
    """
    The first row is the x-axis, 
    the second row is the y-intensity of the first data, 
    the third row is the y-intensity of the second data, 
    and so on.
    Do Savitzky-Golay filtering on each column except the first column.
    Save the smoothed data as sheetname_output.
    
    """
    print(f'\n[smooth_spectrum_data]  \t working on {os.path.basename(path_xlsx)} ...')
    
    # [2] Extract the x-axis (wavenumber) from the first column
    array_data = read_excel_sheet_into_2d_array_panda(path_xlsx, sheetname_input)
    x_spectral_unit, y_intensities_smoothed \
        = smooth_array_data_with_Savitzky_Golay(array_data, window_length, polyorder)
    
    # [4] Combine the x-axis and smoothed y-intensities and save
    combine_processed_y_with_x_and_save(x_spectral_unit, y_intensities_smoothed, path_xlsx, sheetname_output)
  



def downsample_spectrum_data(path_xlsx, 
                             sheetname_input='02_Raw Data', 
                             sheetname_output='04_Downsampled Data', 
                             downsample_factor=10):
    """
    In array_data (or sheet_input), the first row is the x-axis, 
    the second row is the y-intensity of the first data, 
    the third row is the y-intensity of the second data, 
    and so on.    
    """
    print(f'\n[downsample_spectrum_data]  \t working on {os.path.basename(path_xlsx)} ...')
    
    #[3] Check for valid size.
    array_data = read_excel_sheet_into_2d_array_panda(path_xlsx, sheetname_input)
    _, data_cnt = array_data.shape
    down_data_cnt = data_cnt // downsample_factor
    
    #[4] Report valid data.
    valid_data_cnt = down_data_cnt * downsample_factor 
    missed_data_cnt = data_cnt - valid_data_cnt
    print(f'\t data_cnt: {data_cnt}\n\t valid_data_cnt: {valid_data_cnt}\n\t missed_data_cnt: {missed_data_cnt}')
    if down_data_cnt <= 100:
        raise ValueError(f'down_data_cnt = {down_data_cnt} is too small. \
            Please check the downsample_factor ({downsample_factor}) and data_cnt ({data_cnt}).')
    
    #[3] Extract the x-axis (wavenumber) from the first column
    x_spectral_unit = array_data[0, :]
    y_intensities = array_data[1:, :]
    
    #[4] Downsample the data by averaging every nth point
    x_spectral_unit_down = np.mean(x_spectral_unit[:valid_data_cnt].reshape(-1, downsample_factor), axis=1)
    y_intensities_down = np.mean(y_intensities[:, :valid_data_cnt].reshape(y_intensities.shape[0], -1, downsample_factor), axis=2)
    
    #[5] Combine the downsampled x-axis and y-intensities and save
    combine_processed_y_with_x_and_save(x_spectral_unit_down, y_intensities_down, path_xlsx, sheetname_output)





def compute_outliers_mask(y_intensities, std_thr=None, diff_thr=None, val_thr=None):
    """
    Identifies outliers in a 2D array using three methods:
    1. Column STD: Marks values exceeding column mean by std_thr multiples of STD.
    2. Row Differential: Marks values with first-order differences exceeding diff_thr.
    3. Value Threshold: Marks values exceeding val_thr.
    """ 
    print(f'[compute_outliers_mask] std_thr={std_thr}, diff_thr={diff_thr}, val_thr={val_thr}')  
    #[1] Calculate column mean and standard deviation
    arr_col_mean = np.mean(y_intensities, axis=0)
    arr_col_std = np.std(y_intensities, axis=0)
    arr_col_std[arr_col_std == 0] = np.finfo(float).eps  # Replace zero std with a small value
    arr_2D_col_std_diff = np.abs(y_intensities - arr_col_mean) / arr_col_std
    
    #[2] Column STD-based outliers
    if std_thr is None or std_thr <= 0:
        arr_2D_outliers_mask = np.ones_like(y_intensities, dtype=bool) 
    else:
        arr_2D_outliers_mask = np.abs(y_intensities - arr_col_mean) > std_thr * arr_col_std
        
    # [3] Row differential-based outliers
    if diff_thr:
        arr_diffs = np.abs(np.diff(y_intensities, axis=1))
        row_outliers_mask = np.zeros_like(y_intensities, dtype=bool)
        row_outliers_mask[:, :-1] |= arr_diffs > diff_thr
        row_outliers_mask[:, 1:] |= arr_diffs > diff_thr
        arr_2D_outliers_mask |= row_outliers_mask
    
    # [4] Value threshold-based outliers
    if val_thr:
        arr_2D_outliers_mask |= y_intensities > val_thr

    #[15] Count the number of outliers.
    num_outliers = np.sum(arr_2D_outliers_mask)
    text_0_cnt = f'Number of outliers found: {num_outliers}' \
        if num_outliers > 0 else 'No outliers found.'
    print(text_0_cnt)
        
    return arr_2D_outliers_mask, arr_2D_col_std_diff, num_outliers, text_0_cnt





def compute_column_statistics(y_intensities):
    """
    Create a 2D array that has the same number of column with y_intensities.
    The first row is the maxium of each indivisual column in y_intensities.
    The second row is the mean of each indivisual column in y_intensities.
    The third row is the min of each indivisual column in y_intensities.
    The forth row is the std of each indivisual column in y_intensities.
    """
    #[1] Calculate the statistics
    arr_col_max = np.max(y_intensities, axis=0)
    arr_col_mean = np.mean(y_intensities, axis=0)
    arr_col_min = np.min(y_intensities, axis=0)
    arr_col_std = np.std(y_intensities, axis=0)
    
    #[2] Combine the results into a 2D array
    arr_col_stat = np.vstack((arr_col_max, arr_col_mean, arr_col_min, arr_col_std))
    
    return arr_col_stat

def print_surrounding_matrix(array_data, arr_2D_col_std_diff, arr_2D_outliers_mask, 
                             print_to_console=False):
    #[1] Shape of matrix.
    y_intensities = array_data[1:, :]
    h_point_ax0, w_wvnb_ax1 = arr_2D_outliers_mask.shape
    cnt_outliers = 1
    arr_col_stat = compute_column_statistics(y_intensities)
    
    #[2] Iterate through outliers.
    text_3_surrd = ''
    for i in range(h_point_ax0):
        for j in range(w_wvnb_ax1):
            ij_outlier_mask = arr_2D_outliers_mask[i, j]
            if ij_outlier_mask:
            
                #[9] Define the bounds for the 5x5 matrix
                i_min = max(i - 2, 0)
                i_max = min(i + 3, h_point_ax0)
                j_min = max(j - 2, 0)
                j_max = min(j + 3, w_wvnb_ax1)
                j_col_stat = np.round(arr_col_stat[:, j], 2).T
                
                #[10] Prepare to print the 5x5 matrix of the standard deviation differences.
                text_1_outlier = f'\n--\n[{cnt_outliers}] Outlier "{y_intensities[i, j]:.0f}" found at ({i}, {j}):'
                text_2_col_stat = f'(max, mean, min, std) = {j_col_stat}'
                arr_2D_outlier_surrounding = y_intensities[i_min:i_max, j_min:j_max].astype(int)
                text_3_val_matrix = f'actual value:\n{arr_2D_outlier_surrounding}'
                
                #[12] Print the 5x5 matrix of the standard deviation differences
                sub_arr_2D_col_std_diff = arr_2D_col_std_diff[i_min:i_max, j_min:j_max]
                fmt_sub_arr_2D_col_std_diff = np.array2string(sub_arr_2D_col_std_diff, formatter={'float_kind': lambda x: f"{x:.2f}"})
                text_4_std_matrix = f'std_diff:\n{fmt_sub_arr_2D_col_std_diff}'
                
                #[13] Append the outlier information to the list
                ij_text_outlier_all = f'{text_1_outlier}\n{text_2_col_stat}\n{text_3_val_matrix}\n{text_4_std_matrix}\n'
                if print_to_console:
                    print(ij_text_outlier_all)                
                
                #[16] Collect text.
                text_3_surrd += ij_text_outlier_all              
                cnt_outliers += 1
                
    return text_3_surrd


def report_outliers_in_spectrum_data(array_data, std_thr=0, diff_thr=200, val_thr=None, 
                                     collect_text=False, print_to_console=False):
    """
    In array_data, the first row is the x-axis,
    the second row is the y-intensity of the first data,
    the third row is the y-intensity of the second data,
    and so on.
    """
    print(f'\n[report_outliers_in_spectrum_data]')
    
    #[3] Compute outliers.
    y_intensities = array_data[1:, :]
    print(f'\n[y_intensities.shape] {y_intensities.shape}')
    arr_2D_outliers_mask, arr_2D_col_std_diff, num_outliers, text_0_cnt \
        = compute_outliers_mask(y_intensities, std_thr, diff_thr, val_thr)
    
    #[6] Create a list to store the indices of the outliers
    outl_i, outl_j = np.where(arr_2D_outliers_mask)
    list_std_diff = arr_2D_col_std_diff[outl_i, outl_j]
    list_outliers = y_intensities[outl_i, outl_j]
    text_outliers = ''
    #[7] Text record.
    if collect_text:
        timestamp = datetime.now().strftime("%Y-%m%d-%H%M%S")
        text_outliers += f'\n[report_outliers_in_spectrum_data] {timestamp}\n{text_0_cnt}\n'
    #[10] Organize df_outliers.
    if num_outliers > 0:
        df_outliers = pd.DataFrame({'Location (h)': outl_i,
                                    'Location (w)': outl_j,
                                    'Outlier': list_outliers,
                                    'STD Diff': list_std_diff})
        df_outliers = df_outliers.sort_values(by='STD Diff', ascending=False).reset_index(drop=True)
    else:
        df_outliers = pd.DataFrame(columns=['Location (h)', 'Location (w)', 'Outlier', 'STD Diff'])
    
    #[11] df_outliers to text log.
    if collect_text:
        text_2_df_outliers = tabulate(df_outliers, headers="keys", tablefmt="orgtbl")
        text_outliers += f'\n{text_2_df_outliers}\n'

    #[12] Print a 5x5 matrix around the outlier
    if num_outliers >= 100:
        text_3_skip = f'Skip printing the surrounding matrix. (Too many outliers: {num_outliers})'
        print(text_3_skip)
        if collect_text:
            text_outliers += f'\n{text_3_skip}\n'
    else:
        text_3_surrd = print_surrounding_matrix(y_intensities, arr_2D_col_std_diff, arr_2D_outliers_mask, print_to_console)
        if collect_text:
            text_3_surrd = f'\n{text_3_surrd}\n'
    
    return arr_2D_outliers_mask, df_outliers, text_outliers





def interpolate_outliers_in_spectrum_data(array_data, dir_save, is_Raman,
                                          std_thr=8, diff_thr=200, val_thr=None, max_proc=5,
                                          path_xlsx=None, sheetname_output='5_Corrected',
                                          show_itpl_process=False):
    """
    In array_data, the first row is the x-axis,
    the second row is the y-intensity of the first data,
    the third row is the y-intensity of the second data,
    and so on.
    Change outlier to none and interpolate new data point.
    """
    print(f'\n[interpolate_outliers_in_spectrum_data]')
    
    # [3] Compute outliers.
    text_outliers = ""
    
    #[4] Iterate through max_proc. Report and plot first, then fix outliers.
    print(f'max_proc = {max_proc}')
    for i, proc in enumerate(range(max_proc)):
        print(f'\n-- [{i:01d}/{max_proc}] ')
        #[5] Compute (or recompute) outliers.
        arr_2D_outliers_mask, df_outliers, i_text_outliers \
            = report_outliers_in_spectrum_data(array_data, std_thr, diff_thr, val_thr, True, False)
        num_outliers = len(df_outliers)
        print(f'-- [Proc {proc + 1}] Outlier outside {std_thr} STD: {num_outliers}.')
        text_outliers += f'{i_text_outliers}\n\n\n'
        
        #[5] Show interpolation process.
        if show_itpl_process:
            #[5] Plot data distribution.
            _, df_all_data, _ = report_outliers_in_spectrum_data(array_data, 0)
            plot_title = f'Distribution of Outliers by STD ({sheetname_output}, {proc})'
            path_save = os.path.join(dir_save, f'2-data distribution_{proc}.png')
            M4VIS.plot_data_distribution(df_all_data, plot_title, path_save)
            
            #[6] Plot overlapping spectra.
            plot_title = f'Overlapping Spectra ({sheetname_output}, {proc})'
            path_save = os.path.join(dir_save, f'1-ovlp spectra_{proc}.png')
            M4VIS.plot_overlapping_spectra(array_data, None, is_Raman, plot_title, path_save)
            
            del df_all_data
            gc.collect()
            
        #[7] Skip if no outliers found.
        if num_outliers == 0:
            print(f'-- No more outliers found with std_thr={std_thr}. Stopping process.')
            break
        
        # [8] Create a list to store the indices of the outliers, and change outliers to NaN.
        x_spectral_unit = array_data[0, :]
        y_intensities = array_data[1:, :]
        outlier_values = y_intensities[arr_2D_outliers_mask]
        y_intensities[arr_2D_outliers_mask] = np.nan
        
        # [13] Interpolate new datapoints only for rows containing outliers.
        print(f'-- Start iterating through each row that contain outliers in the original y_intensities array.')
        unique_rows_with_outliers = np.unique(np.where(arr_2D_outliers_mask)[0])
        cnt_row_with_outlier = len(unique_rows_with_outliers)
        print(f'unique_rows_with_outliers: {unique_rows_with_outliers}')
        for i in unique_rows_with_outliers:
            i_outlier_values = outlier_values[np.where(np.where(arr_2D_outliers_mask)[0] == i)].astype(int)
            print(f'-- Processing row {i:04d}/{cnt_row_with_outlier:04d}. \t Outliers: {i_outlier_values}')
            y_intensities[i, :] = pd.Series(y_intensities[i, :]).interpolate(method='linear', limit_direction='both').to_numpy()
    
    #[14] Plot the final data distribution.
    _, df_all_data, _ = report_outliers_in_spectrum_data(array_data, 0)
    plot_title = f'Distribution of Outliers by STD ({sheetname_output}, {proc + 1})'
    path_save = os.path.join(dir_save, f'2-data distribution_{proc + 1}(final).png')
    M4VIS.plot_data_distribution(df_all_data, plot_title, path_save)
    
    #[16] Plot overlapping spectra.
    plot_title = f'Overlapping Spectra ({sheetname_output}, {proc + 1})'
    path_save = os.path.join(dir_save, f'1-ovlp spectra_{proc + 1}.png')
    M4VIS.plot_overlapping_spectra(array_data, None, is_Raman, plot_title, path_save)
    del df_all_data, arr_2D_outliers_mask
    gc.collect()
    
    #[20] Combine the x-axis and smoothed y-intensities and save
    print(f'-- The next saving step might take 2 mins due to large data size.')
    M1BFI.print_variable_sizes(locals())
    #sys.exit()
    array_data_processed = combine_processed_y_with_x_and_save(x_spectral_unit, y_intensities, path_xlsx, sheetname_output)
    
    return array_data_processed, text_outliers






def rank_array_data_with_intensity_in_certain_range(array_data, peak_start, peak_end):
    """
    y_intensities according to each row's maximum value withint the window of peak_start, peak_end.
    
    
    """
    #[1] Read data into array
    x_spectral_unit = array_data[0, :]
    y_intensities = array_data[1:, :]

    #[2] Trim the data to the specified range
    array_data_trimmed = trim_data_to_certain_range(array_data, peak_start, peak_end)
    trimmed_y_intensities = array_data_trimmed[1:, :]

    #[3] Find the maximum intensity within the range for each row
    max_intensities = np.max(trimmed_y_intensities, axis=1)

    #[4] Rank the rows based on the maximum intensity (from high to low)
    ranked_indices = np.argsort(max_intensities)[::-1]

    #[5] Reorder the rows based on the ranking
    y_intensities_ranked = y_intensities[ranked_indices, :]

    #[6] Combine the x-axis and ranked y-intensities
    array_data_ranked = np.vstack((x_spectral_unit, y_intensities_ranked))

    return array_data_ranked








def sample_rows_from_array_data(array_data, sample_method, 
                                peak_start, peak_end,
                                diff_thr,
                                sample_chosen=10, path_xlsx=None, 
                                sheetname='04_Sporadic'):
    print(f'\n[sample_rows_from_array_data] {sample_method}, {sample_chosen}')
    
    #[1] Rank data
    array_data_ranked = rank_array_data_with_intensity_in_certain_range(array_data, peak_start, peak_end)
    
    #[2] Split x and y
    x_spectral_unit = array_data_ranked[0, :]
    y_intensities = array_data_ranked[1:, :]
    y_indices = np.arange(y_intensities.shape[0])

    #[3] Sampling based on methods
    if sample_method == 'top_n':
        selected_indices = y_indices[:sample_chosen]
    elif sample_method == 'bottom_n':
        selected_indices = y_indices[-sample_chosen:]
    elif sample_method == 'sporadically':
        step = max(1, len(y_indices) // sample_chosen)
        selected_indices = y_indices[::step][:sample_chosen]
    elif sample_method == 'fast_outliers_1diff':
        selected_indices = []
        for idx, spectrum in enumerate(y_intensities):
            max_diff = np.max(np.abs(np.diff(spectrum)))
            if max_diff > diff_thr:
                print(f'-- [{idx}] {max_diff}')
                selected_indices.append(idx)
    else:
        raise ValueError('Invalid sample_method. Choose from "top_n", "bottom_n", or "sporadically".')
    
    #[4] Stack selected spectra
    array_data_sampled = np.vstack((x_spectral_unit, y_intensities[selected_indices, :]))

    #[5] Optional: Save to Excel
    if path_xlsx is not None:
        save_2d_array_to_existing_excel(path_xlsx, array_data_sampled, sheetname)
    
    return array_data_sampled






def average_all_data_into_single_array(array_data, path_xlsx=None, sheetname='05-data average'):
    #[3] Extract the x-axis (wavenumber) from the first column
    x_spectral_unit = array_data[0, :]
    y_intensities = array_data[1:, :]
    
    #[4] Average all data in the array.
    y_intensities_avg = np.mean(y_intensities, axis=0)
    
    #[5] Combine the x-axis and smoothed y-intensities back into a DataFrame
    array_data_avg = np.vstack((x_spectral_unit, y_intensities_avg))
    
    #[6] Save the average data to a new sheet in the same Excel file
    if path_xlsx is not None:
        save_2d_array_to_existing_excel(path_xlsx, array_data_avg, sheetname)
    
    return array_data_avg



def trim_data_to_certain_range(array_data, peak_start, peak_end=None):
    """
    
    Trim the data to a certain range.
    """
    print(f'\n[trim_data_to_certain_range]')
    #[1] peak_start might be peak_range, causing peak_end=None.
    if peak_end is None:
        peak_start, peak_end = M3PFF.unpack_peak_range(peak_start)
    #[2] Report if array_data is already withing that range.
    x_spectral_unit = array_data[0, :]
    arr_peak_start = min(x_spectral_unit)
    arr_peak_end = max(x_spectral_unit)
    
    if peak_start <= arr_peak_start and arr_peak_end <= peak_end:
        print(f'-- array_data ({arr_peak_start}, {arr_peak_end}) already within that range ({peak_start}, {peak_end}). Skip trimming and return original list.')
        return array_data
    # [1] Find the index of the first value greater than or equal to peak_start
    start_index = np.where(array_data[0, :] >= peak_start)[0][0]
    # [2] Find the index of the last value less than or equal to peak_end
    end_index = np.where(array_data[0, :] <= peak_end)[0][-1]
    # [3] Trim the array by keeping all rows and slicing columns
    array_data_trimmed = array_data[:, start_index:end_index + 1]
    
    return array_data_trimmed







