def estimate_sigma_and_gamma_in_voigt_with_given_peak_FWHM(peak_FWHM_guess):
    """
    Estimate the sigma (standard deviation of Gaussian) and gamma (HWHM of Lorentzian)
    parameters for a Voigt profile given the peak FWHM (FWHM_V).
    
    Uses the approximate formula:
    FWHM_V ≈ 0.5346 * FWHM_L + sqrt(0.2166 * FWHM_L^2 + FWHM_G^2)
    where:
        FWHM_L = 2 * gamma
        FWHM_G = 2.3548 * sigma  (Gaussian FWHM = 2.3548 * sigma)
    """

    def fwhm_voigt_approx(sigma_gamma, target_fwhm):
        sigma, gamma = sigma_gamma
        if sigma < 0 or gamma < 0:
            return np.inf
        fwhm_g = 2.3548 * sigma
        fwhm_l = 2 * gamma
        fwhm_v = 0.5346 * fwhm_l + np.sqrt(0.2166 * fwhm_l**2 + fwhm_g**2)
        return (fwhm_v - target_fwhm) ** 2

    initial_guess = [peak_FWHM_guess / 3, peak_FWHM_guess / 3]
    #print(f'Initial guess (sigma, gamma): {initial_guess}')
    result = minimize(fwhm_voigt_approx, initial_guess, args=(peak_FWHM_guess,))
    
    if result.success:
        sigma_guess, gamma_guess = result.x
        return sigma_guess, gamma_guess
    else:
        raise RuntimeError("Optimization failed: could not estimate sigma and gamma.")





def remove_tailing_none_columns_from_2d_array(array_fitting_result):
    """
    Remove trailing columns that contain only None values from a 2D array.
    """
    #[1] Convert to a NumPy array if not already
    array_fitting_result = np.array(array_fitting_result, dtype=object)
    
    #[2] Check for trailing None columns
    mask = ~np.all(array_fitting_result == None, axis=0) 
    trimmed_array = array_fitting_result[:, mask] 
    col_num = trimmed_array.shape[1]
    print(f'\n[remove_tailing_none_columns_from_2d_array] The first {col_num} columns contain data.')
    
    return trimmed_array    
    
    



def convert_fitting_result_to_df_and_add_location(array_fitting_result, fit_method, mapping_size_xy=None):
    """
    Note: xFWHM" means it is not FWHM. For Gaussian, it is the sigma; for Lorentzian, it is gamma.
    We need to multiply it by coeff_sigma_or_gamma_to_FWHM to convert xFWHM to FWHM.
    """
    # [1] Ensure array_fitting_result is a NumPy array with consistent dimensions
    print(f'\n[convert_fitting_result_to_df_and_add_location]')
    try:
        array_fitting_result = np.array(array_fitting_result, dtype=object)
        if len(array_fitting_result.shape) != 2:
            raise ValueError("array_fitting_result must be a 2D array with consistent dimensions.")
    except ValueError as e:
        raise ValueError(f"Invalid array_fitting_result: {e}")
    
    #[2] Determine column titles and slice array_fitting_result based on the fit_method
    if fit_method == 'Gaussian':
        column_titles = ['loc_x', 'loc_y', 'fit_pos', 'fit_int', 'fit_sigma', 'fit_bl', 'fit_r2']
        array_fitting_result = array_fitting_result[:, :5]  # Gaussian fitting outputs 5 parameters.
    elif fit_method == 'Lorentzian':
        column_titles = ['loc_x', 'loc_y', 'fit_pos', 'fit_int', 'fit_gamma', 'fit_bl', 'fit_r2']
        array_fitting_result = array_fitting_result[:, :5]  # Lorentzian fitting outputs 5 parameters.
    elif fit_method == 'Voigt':
        column_titles = ['loc_x', 'loc_y', 'fit_pos', 'fit_int', 'fit_sigma', 'fit_gamma', 'fit_bl', 'fit_r2']
        array_fitting_result = array_fitting_result[:, :6]  # Voigt fitting outputs 6 parameters.
    elif fit_method == 'fit_two_peaks_lorentzian':
        column_titles = ['loc_x', 'loc_y', 
                         'fit_pos1', 'fit_int1', 'fit_gamma1', 
                         'fit_pos2', 'fit_int2', 'fit_gamma2', 
                         'fit_bl', 'fit_r2']
        array_fitting_result = remove_tailing_none_columns_from_2d_array(array_fitting_result)
    else:
        list_fitting_methods = ['fit_one_peak_gaussian', 
                                'fit_one_peak_lorentzian', 'fit_two_peaks_lorentzian',
                                'fit_one_peak_voigt']
        raise ValueError(f'Unknown fit_method: {fit_method}. Supported methods are {list_fitting_methods}.')
    
    #[2] Check if mapping size
    num_samples = array_fitting_result.shape[0]
    if mapping_size_xy is None:
        mapping_length = int(num_samples**0.5)
        if mapping_length**2 == num_samples:
            mapping_size_xy = [mapping_length, mapping_length]
        else:
            text_error_6 = f'Please provide correct mapping size.'\
                            f'Please provide correct mapping size.'
            raise ValueError(text_error_6)
    elif mapping_size_xy[0] * mapping_size_xy[1] != num_samples:
        raise ValueError('Please provide correct mapping size.')
    
    #[3] Create location indices
    loc_x, loc_y = np.meshgrid(range(mapping_size_xy[1]), range(mapping_size_xy[0]))
    loc_x = loc_x.flatten()
    loc_y = loc_y.flatten()
    
    #[5] Combine location indices with fitting results
    combined_results = np.column_stack((loc_x, loc_y, array_fitting_result))
    print(f'combined_results.shape = {combined_results.shape}')
    
    #[8] Create a DataFrame with appropriate column titles
    text_note = f'-- Note: \tThe "fit_xFWHM" in the column header means it is not FWHM.\n'\
                    f'\t\tFor Gaussian, it is the sigma; for Lorentzian, it is gamma.'
    print(text_note)
    df_fitting_result = pd.DataFrame(combined_results, columns=column_titles)
    
    return df_fitting_result
    

 
