#[6] Calibration - Start




def calibrate_data_with_rayleigh_peak(array_data_old, peak_range, 
                                      fit_method, rayleigh_peak, intensity_calib,
                                      path_xlsx, sheetname_output):
    """
    Calibrate the spectrum data based on the Rayleigh peak position and the desired intensity.
    The calibration shifts the peak to the desired position and adjusts the intensity.
    """
    print(f'\n[calibrate_data_with_rayleigh_peak] {fit_method}')
    # [1] Settings
    use_peak_range_only = True
    text_fit_log = ""
    is_Raman = True
    verbose = False

    # [2] Get the number of data sets from the shape of the array
    num_data_sets = array_data_old.shape[0] - 1

    # [3] Extract the x-axis (wavenumber); compute baseline value
    x_spectral_unit_old = array_data_old[0, :]
    bl_guess, bl_range = compute_baseline_stat(array_data_old, pct=80)

    # [4] Adjust the x_spectral_unit_old to x_spectral_unit_new with rayleigh_peak
    x_spectral_unit_new = x_spectral_unit_old - rayleigh_peak

    # [5] Initialize an empty list to store calibrated data
    y_intensity_new = np.empty((0, len(x_spectral_unit_old)))

    # [6] Iterate over each data set and fit the single Raman peak
    for i in range(num_data_sets):
        iter_y_intensity_old = array_data_old[i + 1, :]
        
        if fit_method == 'Gaussian':
            path_save = os.path.join('no_plt_show', '03_Boundary Check-1_1G.png')
            i_fitting_result, text_fit, _ \
                = M3PFF.fit_one_peak_gaussian(peak_range, x_spectral_unit_old, iter_y_intensity_old, bl_guess,
                                              is_Raman, False, path_save)
        elif fit_method == 'Lorentzian':
            path_save = os.path.join('no_plt_show', '03_Boundary Check-2_1L.png')
            i_fitting_result, text_fit, _ \
                = M3PFF.fit_one_peak_lorentzian(peak_range, x_spectral_unit_old, iter_y_intensity_old, bl_guess,
                                                is_Raman, False, path_save)
        elif fit_method == 'Voigt':
            path_save = os.path.join('no_plt_show', '03_Boundary Check-3_1V.png')
            i_fitting_result, text_fit, _ \
                = M3PFF.fit_one_peak_voigt(peak_range, x_spectral_unit_old, iter_y_intensity_old, bl_guess,
                                           is_Raman, False, path_save)
        else:
            list_fitting_methods = ['fit_one_peak_gaussian', 
                                    'fit_one_peak_lorentzian', 'fit_two_peaks_lorentzian',
                                    'fit_one_peak_voigt']
            raise ValueError(f'Unknown fit_method: {fit_method}. Supported methods are {list_fitting_methods}.')

        # [7] Append fitting log
        text_fit_log += text_fit

        # [8] Validate fitting result and adjust intensity
        if i_fitting_result[1] is not None:  # Ensure amplitude is valid
            iter_A = i_fitting_result[1]
            #[10] Extract working part from i_fitting_result
            i_fitting_result = i_fitting_result[:5] if fit_method in ['Gaussian', 'Lorentzian'] else i_fitting_result[:6]
            bl_fit = i_fitting_result[-2] 
            int_adj_ratio = intensity_calib / iter_A
            iter_y_intensity_new = iter_y_intensity_old * int_adj_ratio - bl_fit * (int_adj_ratio - 1)
        else:
            iter_y_intensity_new = iter_y_intensity_old  # Use original data if fitting fails

        # [9] Append the calibrated data to the new array
        y_intensity_new = np.vstack([y_intensity_new, iter_y_intensity_new[np.newaxis, :]])


        # [10] Log fitting progress
        if i % 10 == 0:
            non_none_i_fitting_result = [val for val in i_fitting_result if val is not None]
            formatted_result = ',\t'.join([f"{val:.4f}" if val is not None else "None" for val in non_none_i_fitting_result])
            print(f"[{i:04d}/{num_data_sets:04d}] {formatted_result}")
            

    # [11] Convert the list to a NumPy array
    y_intensity_new = np.array(y_intensity_new)
    array_data_new = combine_processed_y_with_x_and_save(x_spectral_unit_new, y_intensity_new, path_xlsx, sheetname_output)


    return array_data_new, text_fit_log



