def unpack_peak_range(peak_range, x_spectral_unit=None):
    # [1] Handle peak_range
    if (peak_range is None) and (x_spectral_unit is not None):
        peak_start = min(x_spectral_unit)
        peak_end = max(x_spectral_unit)
    elif not isinstance(peak_range, (list, tuple)) or len(peak_range) != 2:
        raise ValueError(f'Invalid format for peak_range: {peak_range}')
    else:
        peak_start, peak_end = peak_range
    return peak_start, peak_end





    
    
def peak_initial_guess(x_spectral_unit, i_y_intensity, 
                       peak_start, peak_end,
                       peak_pos_lower, peak_pos_upper,
                       bl_int, bl_range, range_to_width_r=0.25,
                       print_initial_guess=False):
    """
    Find the initial guess for the peak position, height, and width.
    range_to_width_r: the ratio of the range to the width.
    """
    
    #[1] Find the index of the maximum intensity in the specified range
    idx_max = np.argmax(i_y_intensity[(x_spectral_unit >= peak_start) & (x_spectral_unit <= peak_end)])
    #[2] Calculate the peak position, height, and width
    peak_position = x_spectral_unit[idx_max]
    peak_position = max(peak_pos_lower, min(peak_position, peak_pos_upper))
    
    #[5] Calculate peak_height within certain window.
    peak_height_low, peak_height_upp = compute_peak_pos_bounds_from_peak_range(peak_start, peak_end, 0.2)
    window_mask = (x_spectral_unit >= peak_height_low) & (x_spectral_unit <= peak_height_upp)
    peak_height = int(max(i_y_intensity[window_mask]) - bl_int)
    
    #[6] Compare range to see if there is signal.
    i_y_int_range = max(i_y_intensity) - min(i_y_intensity)
    #[7] If there is no signal, set peak_FWHM to very wirde.
    if i_y_int_range < bl_range:
        peak_FWHM = peak_end - peak_start
        text_no_signal = f'No signal. \t(i_y_int_range, bl_range) = {i_y_int_range:.2f}, {bl_range:.2f}'
    
    #[10] Calculate the width based on the specified range
    else:
        peak_FWHM = range_to_width_r * (peak_end - peak_start)
        text_no_signal = f'\t\t(i_y_int_range, bl_range) = {i_y_int_range:.2f}, {bl_range:.2f}'
    
    #[12] Optionally print the initial guess
    if print_initial_guess:
        print(f'Initial guess: \t\t{peak_position:.2f}, {peak_height:.2f}, {peak_FWHM:.2f}')
        
    return peak_position, peak_height, peak_FWHM, text_no_signal





def mark_peak_above_half_max(x_spectral_unit, i_y_intensity, peak_range, bl_int):
    # [1] Unpack the peak range and validate it
    peak_start, peak_end = unpack_peak_range(peak_range, x_spectral_unit)

    # [2] Mask the data within the specified range
    mask = (x_spectral_unit >= peak_start) & (x_spectral_unit <= peak_end)
    if not np.any(mask):
        raise ValueError(f"No data points found within the specified range: {peak_range}")

    x_crop = x_spectral_unit[mask]
    y_crop = i_y_intensity[mask]

    # [3] Find the index of the maximum intensity in the specified range
    idx_max = np.argmax(y_crop)
    peak_position = x_crop[idx_max]
    peak_height = y_crop[idx_max] - bl_int

    # [4] Compute half max and build mask
    half_max = peak_height / 2 + bl_int
    mask_above_half = y_crop >= half_max

    # [5] Create a full-length zero array and insert val_True where appropriate
    arr_half_max = np.full_like(i_y_intensity, bl_int)
    arr_half_max[mask] = np.where(mask_above_half, half_max, bl_int)

    return arr_half_max


def peak_initial_guess_and_signal_check(x_spectral_unit, i_y_intensity, 
                                        peak_range, bl_int, bl_range, verbose=False):
    """
    Quickly calculate initial guess for fitting.
    Also detect if this spectra has signal.
    2025-05-23 note: For Raman, x_spectral_unit is from small to large wavenumber.
    For PL, x_spectral_unit is from large to small eV.
    When calculating FWHM, do not use directional approach, which is prone to error.
    Use length approach: For i_y_intensity larger than half_max,
    crop out the corresponding x_spectral_unit and calculate 
    peak_FWHM = max(x_above_half_max) - min(x_above_half_max)
    """
    #[1] Unpack the peak range and validate it
    peak_start, peak_end = unpack_peak_range(peak_range, x_spectral_unit)

    #[2] Mask the data within the specified range
    mask = (x_spectral_unit >= peak_start) & (x_spectral_unit <= peak_end)
    if not np.any(mask):
        raise ValueError(f"No data points found within the specified range: {peak_range}")
    x_crop = x_spectral_unit[mask]
    y_crop = i_y_intensity[mask]

    #[3] Check if this spectra has obvious signal
    i_y_int_range = max(i_y_intensity) - min(i_y_intensity)
    
    #[4] If the signal is very weak.
    if i_y_int_range < bl_range * 1.2:
        peak_position = np.mean([peak_start, peak_end])
        peak_height = max(y_crop) - bl_int if len(y_crop) > 0 else 1  # Handle empty y_crop
        peak_FWHM = peak_end - peak_start
        text_no_signal = f'No signal. \t(i_y_int_range, bl_range) = {i_y_int_range:.2f}, {bl_range:.2f}'

    #[5] If there is signal.
    else:
        #[5.1] Find the index of the maximum intensity in the specified range
        idx_max = np.argmax(y_crop)
        peak_position = x_crop[idx_max]
        peak_height = y_crop[idx_max] - bl_int

        # [5.2] Find the FWHM (Full Width at Half Maximum) using length approach
        half_max = peak_height / 2 + bl_int
        mask_above_half = y_crop >= half_max
        if np.any(mask_above_half):
            x_above_half = x_crop[mask_above_half]
            peak_FWHM = max(x_above_half) - min(x_above_half)
        else:
            peak_FWHM = peak_end - peak_start  # FWHM cannot be determined
        text_no_signal = f'\t\t(i_y_int_range, bl_range) = {i_y_int_range:.2f}, {bl_range:.2f}'

    # [6] Return results
    if verbose:
        print(f'\n[peak_initial_guess_and_signal_check] {peak_position:.03f}, {peak_height:.03f}, {peak_FWHM:.03f}')
    return peak_position, peak_height, peak_FWHM, text_no_signal



def check_if_initial_guess_is_fesible(initial_guess, lower_bounds, upper_bounds, print_status=False):
    """
    Raise ValueError if initial_guess is not within the lower_bounds and upper_bounds.
    Indicate which parameter is out of bounds.
    """
    #[1] Print first. 
    if print_status is True:
        print(f'initial_guess: \t{initial_guess}')
        print(f'lower_bounds: \t{lower_bounds}')
        print(f'upper_bounds: \t{upper_bounds}')    
    #[2] Make sure all inputs have the same length
    if not (len(initial_guess) == len(lower_bounds) == len(upper_bounds)):
        text_error_1 = f'Lengths of initial_guess ({len(initial_guess)}), lower_bounds ({len(lower_bounds)}), and upper_bounds ({len(upper_bounds)}) must be the same.'
        print(text_error_1)
        raise ValueError(text_error_1)
    #[3] Iterate through initial_guess and check if it's within lower_bounds and upper_bounds
    for i, (guess, low, up) in enumerate(zip(initial_guess, lower_bounds, upper_bounds)):
        if not (low <= guess <= up):
            text_error_2 = f'Initial guess for parameter {i} is out of bounds: \n{guess:.03f} not in [{low:.03f}, {up:.03f}]'
            print(text_error_2)
            raise ValueError(text_error_2)
    return True



def compute_peak_pos_bounds_from_peak_range(peak_start, peak_end, window_to_range_r=0.25, peak_pos=None):
    """
    compute_peak_pos_bounds_from_peak_range
    Compute peak lower and upper boundry for initial guess.
    For example, if peak_start=200, peak_end=400.
    The range is 400-200=200.
    If window_to_range_r=1, the peak bound is 200~400.
    If window_to_range_r=0.5, the peak bound is 250~350.
    If window_to_range_r=0.25, the peak bound is 275~325.
    """
    #[1] Compute bounds.
    peak_center = (peak_start + peak_end) / 2
    peak_range = peak_end - peak_start
    peak_center_adj = window_to_range_r * peak_range / 2
    peak_pos_lower = peak_center - peak_center_adj
    peak_pos_upper = peak_center + peak_center_adj
    
    #[2] Correct if position is not inside of it.
    if peak_pos is not None:
        if peak_pos <= peak_pos_lower:
            print(f'{peak_pos:.03f} not in [{peak_pos_lower:.03f}, {peak_pos_upper:.03f}].')
            peak_pos_lower = peak_pos - peak_center_adj * 0.1
            print(f'Adjusted to [{peak_pos_lower:.03f}, {peak_pos_upper:.03f}].')
        elif peak_pos_upper <= peak_pos:
            print(f'{peak_pos:.03f} not in [{peak_pos_lower:.03f}, {peak_pos_upper:.03f}].')
            peak_pos_upper = peak_pos + peak_center_adj * 0.1
            print(f'Adjusted to [{peak_pos_lower:.03f}, {peak_pos_upper:.03f}].')
    return peak_pos_lower, peak_pos_upper




def check_if_fitting_result_too_close_to_boundaries(df_log):
    print(f'\n[check_if_fitting_result_too_close_to_boundaries]')
    collision_thrs = 0.05  # Threshold ratio for boundary collision
    list_warnings = []

    #[1] Iterate through each parameter column except 'Title' and 'R²'
    for col in df_log.columns:
        if col in ['Title', 'R²']:
            continue

        #[2] Extract lower, upper, and fitted values
        try:
            lower = float(df_log.loc[df_log['Title'] == 'Lower Bounds', col].values[0])
            upper = float(df_log.loc[df_log['Title'] == 'Upper Bounds', col].values[0])
            guess = float(df_log.loc[df_log['Title'] == 'Initial Guess', col].values[0])
            fit   = float(df_log.loc[df_log['Title'] == 'Fitting Result', col].values[0])
        except Exception as e:
            print(f"Skipping column '{col}' due to conversion error: {e}")
            continue

        #[3] Calculate the range and tolerance
        param_range = upper - lower
        tol = collision_thrs * param_range

        #[4] Check if fitted value is close to bounds
        text_hit = ''
        if abs(fit - upper) <= tol:
            if fit == upper:
                text_hit = 'Hit!'
            list_warnings.append(f'[Warning] \t"{col} ({fit})" is too close to its upper bound ({upper}). \t{text_hit}')
        elif abs(fit - lower) <= tol:
            if fit == upper:
                text_hit = 'Hit!'
            list_warnings.append(f'[Warning] \t"{col} ({fit})" is too close to its lower bound ({lower}). \t{text_hit}')
        elif abs(fit - guess) <= tol*2:
            list_warnings.append(f'[Sweet]   \t"{col} ({fit})" is very close to its intitial guess ({lower}).')
        

    #[5] Print all warnings
    for w in list_warnings:
        print(w)
        
    return list_warnings



