#[2] Area Calculation - Start




#[2] Area Calculation - Start

def gaussian_area(a1, sigma1):
    """
    Calculate the area under the Gaussian curve (without baseline).
    """
    area1 = a1 * sigma1 * np.sqrt(2 * np.pi)
    return area1


def lorentzian_area(a1, gamma1):
    """
    Calculate the area under the Lorentzian curve (without baseline).
    """
    area1 = a1 * np.pi * gamma1
    return area1


def voigt_area(a1, gamma1):
    """
    Calculate the area under the Voigt curve (without baseline).
    """
    area1 = a1 * np.pi * gamma1
    return area1


def voigt_area_approx(a1, sigma1, gamma1):
    """
    Approximate the area under the Voigt profile (without baseline).
    """
    #[1] Estimate the full FWHM of the Voigt profile
    f = 0.5346 * 2 * gamma1 + np.sqrt(0.2166 * (2 * gamma1) ** 2 + (2.355 * sigma1) ** 2)
    g_ratio = gamma1 / f

    #[2] Approximate Lorentzian weight η
    eta = 1.36603 * g_ratio - 0.47719 * g_ratio**2 + 0.11116 * g_ratio**3

    #[3] Approximate area (linear combination of Gaussian and Lorentzian contributions)
    area1 = a1 * (np.sqrt(2 * np.pi) * sigma1 * (1 - eta) + np.pi * gamma1 * eta)
    return area1


#[3] Simple Functions - Start




def single_gaussian(x, x01, a1, sigma1, bl):
    """
    x01 is the position.
    a1 is the height.
    sigma1*2 = FWHM    
    """
    # [1] Define the single Gaussian function
    Gaussian1 = a1 * np.exp(-0.5 * ((x - x01) / sigma1) ** 2)
    single_G = Gaussian1 + bl
    return single_G




def double_gaussian(x, 
                    x01, a1, sigma1, 
                    x02, a2, sigma2, bl):
    """
    x01 is the position.
    a1 is the height.
    sigma1*2 = FWHM    
    """
    # [1] Define the single Gaussian function
    Gaussian1 = a1 * np.exp(-0.5 * ((x - x01) / sigma1) ** 2)
    Gaussian2 = a2 * np.exp(-0.5 * ((x - x02) / sigma2) ** 2)
    doouble_G = Gaussian1 + Gaussian2 + bl
    return doouble_G



def triple_gaussian(x, 
                    x01, a1, sigma1, 
                    x02, a2, sigma2, 
                    x03, a3, sigma3, bl):
    """
    x01 is the position.
    a1 is the height.
    sigma1*2 = FWHM    
    """
    # [1] Define the single Gaussian function
    Gaussian1 = a1 * np.exp(-0.5 * ((x - x01) / sigma1) ** 2)
    Gaussian2 = a2 * np.exp(-0.5 * ((x - x02) / sigma2) ** 2)
    Gaussian3 = a3 * np.exp(-0.5 * ((x - x03) / sigma3) ** 2)
    doouble_G = Gaussian1 + Gaussian2 + Gaussian3 + bl
    return doouble_G




def single_lorentzian(x, x01, a1, gamma1, bl):
    """
    x01 is the position.
    a1 is the height.
    gamma1*2 = FWHM    
    """
    # [1] Define the single Lorentzian function
    Lorentzian1 = a1 * gamma1**2 / ((x - x01)**2 + gamma1**2)
    single_L = Lorentzian1 + bl
    return single_L



def double_lorentzian(x, x01, a1, gamma1, x02, a2, gamma2, bl):
    """
    x01 is the position.
    a1 is the height.
    gamma1*2 = FWHM    
    """
    # [1] Define the single Lorentzian function
    Lorentzian1 = a1 * gamma1**2 / ((x - x01)**2 + gamma1**2)
    Lorentzian2 = a2 * gamma2**2 / ((x - x02)**2 + gamma2**2)
    single_L = Lorentzian1 + Lorentzian2 + bl
    return single_L




def single_voigt(x, x01, a1, sigma1, gamma1, bl):
    """
    x01     : center position
    a1      : true peak height
    sigma1  : Gaussian sigma (FWHM_Gaussian = 2.355 * sigma1)
    gamma1  : Lorentzian HWHM (FWHM_Lorentzian = 2 * gamma1)
    bl      : baseline
    """
    # [1] Voigt profile (unnormalized)
    z = ((x - x01) + 1j * gamma1) / (sigma1 * np.sqrt(2))
    profile_raw = np.real(wofz(z)) / (sigma1 * np.sqrt(2 * np.pi))

    # [2] Normalize so the peak height is 1 (centered at x01)
    max_val = np.max(np.real(wofz(1j * gamma1 / (sigma1 * np.sqrt(2)))) / (sigma1 * np.sqrt(2 * np.pi)))
    profile_normalized = profile_raw / max_val

    # [3] Scale by a1 and add baseline
    profile_scaled = a1 * profile_normalized + bl
    return profile_scaled



#[3] Simple Functions - End





#[4] Try to fit - Start


def residuals_of_fitting_function(params, function, x, y):
    y_fit = function(x, *params)
    return y - y_fit


def try_to_fit_specific_function(function, x_spectral_unit, i_y_intensity,
                        initial_guess, lower_bounds, upper_bounds, 
                        max_nfev=5000, len_result=None):
    #[1] Validate len_result.
    if len_result is None:
        function_name = function.__name__
        if function_name in ['single_gaussian', 'single_lorentzian', 'triple_gaussian']:
            len_result = 5
        elif function_name in ['single_voigt']:
            len_result = 6
        elif function_name in ['double_gaussian', 'double_lorentzian']:
            len_result = 8
        elif function_name in ['triple_gaussian']:
            len_result = 11
        else:
            raise ValueError(f'Please prvide valid len_result ({len_result}) that work with function ({function_name}).')
    
    #[2] Choice of function = ['single_gaussian', 'double_gaussian', 'triple_gaussian']
    try:
        #[3] Perform least squares fitting
        result = least_squares(
            fun=residuals_of_fitting_function,
            x0=initial_guess,
            bounds=(lower_bounds, upper_bounds),
            args=(function, x_spectral_unit, i_y_intensity),
            max_nfev=max_nfev
        )
        fit_params = list(map(float, result.x))

        #[4] Generate fitted curve
        fitted_curve = function(x_spectral_unit, *fit_params)

        #[5] Compute R²
        residuals = i_y_intensity - fitted_curve
        ss_res = np.sum(residuals ** 2)
        ss_tot = np.sum((i_y_intensity - np.mean(i_y_intensity)) ** 2)
        fit_r2 = 1 - ss_res / ss_tot if ss_tot != 0 else None

        #[6] Assemble final output with padding to 11, this is for PL of 1 to 3 Gaussian peaks.
        fitting_result = fit_params + [fit_r2]
        fitting_result += [None] * (11 - len(fitting_result))
        return np.array(fitting_result)

    except Exception as e:
        #[7] Handle fitting failure
        print("Fitting failed:", str(e))
        if 'result' in locals():
            fit_params = list(result.x)
            fitting_result = fit_params + [None]
            fitting_result += [None] * (11 - len(fitting_result))
            return np.array(fitting_result)
        return np.array([None] * 11)




#[4] Try to fit - End







#[5] Final wrap up - Start
