def fit_two_peaks_lorentzian(peak_range, x_spectral_unit, i_y_intensity, bl_int, bl_range,
                            is_Raman=False, print_status=False, path_save=None):
    #[1] Overall settings.
    window_to_range_r = 0.30
    shift_2nd_peak = 4  # Assumed left shift for 2nd Lorentzian in Raman
    max_nfev = 5000
    visualize_fitting = False

    #[2] Ensure it's Raman
    if not is_Raman:
        raise ValueError(f'Currently, this "fit_two_peaks_lorentzian" function works for Raman fitting only. (is_Raman: {is_Raman})')
    
    #[3] Initial guess for 1st Lorentzian.
    peak_start, peak_end = unpack_peak_range(peak_range)
    peak_pos, peak_int, peak_FWHM, text_no_signal = \
        peak_initial_guess_and_signal_check(x_spectral_unit, i_y_intensity, peak_range, bl_int, bl_range)
    gamma = peak_FWHM / 2  # Lorentzian FWHM = 2*gamma
    peak_pos_lower, peak_pos_upper = compute_peak_pos_bounds_from_peak_range(peak_start, peak_end, window_to_range_r, peak_pos)
    gamma_lower = max(gamma * 0.0001, 0.0001)   
    
    #[4] Define initial_guess, lower_bounds, and upper_bounds.
    initial_guess_1 =   [peak_pos * 0.99,   peak_int * 0.8, gamma * 0.2, bl_int * 1.00]
    lower_bounds_1 =    [peak_pos_lower,    peak_int * 0.6, gamma_lower, bl_int * 0.9]
    upper_bounds_1 =    [peak_pos_upper,    peak_int * 2.0, gamma * 5, bl_int * 1.3]
    check_if_initial_guess_is_fesible(initial_guess_1, lower_bounds_1, upper_bounds_1, print_status)
    
    #[5] Fit the first Lorentzian.
    fitting_result_1L = try_to_fit_specific_function(single_lorentzian, x_spectral_unit, i_y_intensity, 
                                                     initial_guess_1, lower_bounds_1, upper_bounds_1, max_nfev)

    #[6] Optionally visualize 1L fitting result for debug.
    if visualize_fitting:
        #[11] Unpack fitting result to plot single Lorentzian fitting.
        print(f'fitting_result_1L: {fitting_result_1L}')
        x01, a1, gamma1, bl, r2  = fitting_result_1L[:5]
        y_fit_1L = single_lorentzian(x_spectral_unit, x01, a1, gamma1, bl)
        area_L = lorentzian_area(a1, gamma1)
        #[12] Visualize fitting.
        text_plot = f'[Fitting Result]\n\n'\
                    f'L1: {x01:.03f}, {a1:.03f}, {gamma1:.03f}\n'\
                    f'Area_1L = {area_L:.03f}\n\n'\
                    f'Bl = {bl:.03f}, R² = {r2:.03f}'
        plot_title = f'Raman Spectra with Single Lorentzian Fitting'
        array_data_fit = np.vstack([x_spectral_unit, i_y_intensity, y_fit_1L])
        M4VIS.plot_overlapping_spectra_for_fitting(array_data_fit, [400, 10000], is_Raman, plot_title, text_plot, None)
    
    #[5] Organize log as df_log.
    titles = ['Initial Guess', 'Lower Bounds', 'Upper Bounds', 'Fitting Result']
    data_for_df = {
        'Title': titles,
        'Pos 1':    [initial_guess_1[0], lower_bounds_1[0], upper_bounds_1[0], fitting_result_1L[0]],
        'Int 1':    [initial_guess_1[1], lower_bounds_1[1], upper_bounds_1[1], fitting_result_1L[1]],
        'Gamma 1':  [initial_guess_1[2], lower_bounds_1[2], upper_bounds_1[2], fitting_result_1L[2]],
        'Baseline': [initial_guess_1[3], lower_bounds_1[3], upper_bounds_1[3], fitting_result_1L[3]],
        'R²':       [np.nan, np.nan, np.nan, fitting_result_1L[4]]
    }
    df_log = pd.DataFrame(data_for_df)
    #M4VIS.plot_boundary_check(df_log, path_save)


    #[13] Define 2-peak parameters based on result.
    x01, a1, gamma1, bl, r2 = fitting_result_1L[:5]
    peak_pos_1 = x01
    peak_int_1 = a1 * 0.9
    gamma_1 = gamma1 * 0.85
    peak_pos_2 = peak_pos_1 + shift_2nd_peak
    peak_pos_2_lower = min([peak_pos_1 + 1, peak_pos_2])
    peak_int_2 = peak_int_1 * 0.10
    gamma_2_upper = 20
    gamma_2 = min(gamma_1 * 4, gamma_2_upper)
    
    #[3] Define initial_guess, lower_bounds, and upper_bounds.
    initial_guess_2 = [peak_pos_1,          peak_int_1,         gamma_1,        peak_pos_2,         peak_int_2,         gamma_2,        bl_int]
    lower_bounds_2 =  [peak_pos_1 * 0.9,    peak_int_1 * 0.8,   gamma_1 * 0.8,  peak_pos_2_lower,   peak_int_2 * 0.5,   gamma_2 * 0.2,  bl_int * 0.95]
    upper_bounds_2 =  [peak_pos_1 * 1.1,    peak_int_1 * 1.2,   gamma_1 * 1.2,  peak_pos_2 * 1.1,   peak_int_2 * 1.5,   gamma_2_upper,  bl_int * 1.20]
    check_if_initial_guess_is_fesible(initial_guess_2, lower_bounds_2, upper_bounds_2, print_status)
    
    #[15] Fit the two-peak Lorentzian.
    fitting_result_2L = try_to_fit_specific_function(double_lorentzian, x_spectral_unit, i_y_intensity,
                                                     initial_guess_2, lower_bounds_2, upper_bounds_2, max_nfev)


    #[16] Optionally visualize 1L fitting result for debug.
    if visualize_fitting:
        #[17] Unpack fitting result to plot double Lorentzian fitting.
        print(f'fitting_result_2L: {fitting_result_2L}')
        x01, a1, gamma1, x02, a2, gamma2, bl, r2 = fitting_result_2L[:8]
        y_fit_2L = double_lorentzian(x_spectral_unit, x01, a1, gamma1, x02, a2, gamma2, bl)
        y_fit_2L_1 = single_lorentzian(x_spectral_unit, x01, a1, gamma1, bl)
        y_fit_2L_2 = single_lorentzian(x_spectral_unit, x02, a2, gamma2, bl)
        area_1L = lorentzian_area(a1, gamma1)
        area_2L = lorentzian_area(a2, gamma2)  # Corrected to use a2 and gamma2 for the second peak
        total_area = area_1L + area_2L

        #[18] Visualize fitting.
        text_plot = f'[Fitting Result]\n\n'\
                    f'L1: {x01:.03f}, {a1:.03f}, {gamma1:.03f}\n'\
                    f'Area_1L = {area_1L:.03f} ({area_1L / total_area:.2%})\n\n'\
                    f'L2: {x02:.03f}, {a2:.03f}, {gamma2:.03f}\n'\
                    f'Area_2L = {area_2L:.03f} ({area_2L / total_area:.2%})\n\n'\
                    f'Bl = {bl:.03f}, R² = {r2:.03f}'
        plot_title = f'Raman Spectra with Double Lorentzian Fitting'
        array_data_fit = np.vstack([x_spectral_unit, i_y_intensity, y_fit_2L, y_fit_2L_1, y_fit_2L_2])  # Corrected to use y_fit_2L
        M4VIS.plot_overlapping_spectra_for_fitting(array_data_fit, [300, 3000], is_Raman, plot_title, text_plot, None)


    #[8] Organize log as df_log.
    titles = ['Initial Guess', 'Lower Bounds', 'Upper Bounds', 'Fitting Result']
    data_for_df = {
        'Title': titles,
        'Pos 1':    [initial_guess_2[0], lower_bounds_2[0], upper_bounds_2[0], fitting_result_2L[0]],
        'Int 1':    [initial_guess_2[1], lower_bounds_2[1], upper_bounds_2[1], fitting_result_2L[1]],
        'Gamma 1':  [initial_guess_2[2], lower_bounds_2[2], upper_bounds_2[2], fitting_result_2L[2]],
        'Pos 2':    [initial_guess_2[3], lower_bounds_2[3], upper_bounds_2[3], fitting_result_2L[3]],
        'Int 2':    [initial_guess_2[4], lower_bounds_2[4], upper_bounds_2[4], fitting_result_2L[4]],
        'Gamma 2':  [initial_guess_2[5], lower_bounds_2[5], upper_bounds_2[5], fitting_result_2L[5]],
        'Baseline': [initial_guess_2[6], lower_bounds_2[6], upper_bounds_2[6], fitting_result_2L[6]],
        'R²':       [np.nan, np.nan, np.nan, fitting_result_2L[7]]
    }
    df_log = pd.DataFrame(data_for_df)
    df_log_cal = df_log.apply(lambda col: col.map(lambda x: f"{x:.10f}" if isinstance(x, (float, int)) else x))
    text_fit = f'\n[Double Lorentzian] {text_no_signal}\n{tabulate(df_log, headers="keys", tablefmt="orgtbl")}\n'

    #[18] If print_status is True, we might debugging or other process that we need detailed info.
    if print_status is True:
        check_if_fitting_result_too_close_to_boundaries(df_log_cal)
        M4VIS.plot_boundary_check(df_log, path_save)  

    return fitting_result_2L, text_fit, text_no_signal





def fit_one_peak_voigt(peak_range, x_spectral_unit, i_y_intensity, bl_int, bl_range,
                       is_Raman=False, print_status=False, path_save=None):
    #[1] Overall settings.
    window_to_range_r = 0.30
    max_nfev = 5000

    #[2] Initial guess from Gaussian shape.
    peak_start, peak_end = unpack_peak_range(peak_range)
    peak_pos, peak_int, peak_FWHM, text_no_signal = \
        peak_initial_guess_and_signal_check(x_spectral_unit, i_y_intensity, peak_range, bl_int, bl_range)

    sigma = peak_FWHM / 2.355 * 1.0  # Voigt uses Gaussian sigma
    gamma = peak_FWHM / 2.0         # Voigt uses Lorentzian HWHM

    peak_pos_lower, peak_pos_upper = compute_peak_pos_bounds_from_peak_range(peak_start, peak_end, window_to_range_r, peak_pos)
    sigma_lower = max(sigma * 1e-7, 1e-7)
    gamma_lower = max(gamma * 0.0001, 0.0005)

    #[3] Define initial_guess, lower_bounds, and upper_bounds.
    initial_guess_1 =   [peak_pos * 0.99, peak_int, sigma * 0.5, gamma * 0.5, bl_int * 1.15]
    lower_bounds_1 =    [peak_pos_lower, peak_int * 0.8, sigma_lower, gamma_lower, bl_int * 0.9]
    upper_bounds_1 =    [peak_pos_upper, peak_int * 1.5, sigma * 1.2, gamma * 2, bl_int * 1.3]
    check_if_initial_guess_is_fesible(initial_guess_1, lower_bounds_1, upper_bounds_1, print_status)

    #[4] Fit Voigt peak.
    fitting_result_1V = try_to_fit_specific_function(single_voigt, x_spectral_unit, i_y_intensity, 
                                                     initial_guess_1, lower_bounds_1, upper_bounds_1, max_nfev)

    #[5] Organize log as df_log.
    titles = ['Initial Guess', 'Lower Bounds', 'Upper Bounds', 'Fitting Result']
    data_for_df = {
        'Title': titles,
        'Pos 1':    [initial_guess_1[0], lower_bounds_1[0], upper_bounds_1[0], fitting_result_1V[0]],
        'Int 1':    [initial_guess_1[1], lower_bounds_1[1], upper_bounds_1[1], fitting_result_1V[1]],
        'Sigma 1':  [initial_guess_1[2], lower_bounds_1[2], upper_bounds_1[2], fitting_result_1V[2]],
        'Gamma 1':  [initial_guess_1[3], lower_bounds_1[3], upper_bounds_1[3], fitting_result_1V[3]],
        'Baseline': [initial_guess_1[4], lower_bounds_1[4], upper_bounds_1[4], fitting_result_1V[4]],
        'R²':       [np.nan, np.nan, np.nan, fitting_result_1V[5]]
    }
    df_log = pd.DataFrame(data_for_df)
    df_log_cal = df_log.apply(lambda col: col.map(lambda x: f"{x:.10f}" if isinstance(x, (float, int)) else x))
    text_fit = f'\n[Single Voigt] {text_no_signal}\n{tabulate(df_log, headers="keys", tablefmt="orgtbl")}\n'
    
    #[18] If print_status is True, we might debugging or other process that we need detailed info.
    if print_status is True:
        check_if_fitting_result_too_close_to_boundaries(df_log_cal)
        M4VIS.plot_boundary_check(df_log, path_save)  
    return fitting_result_1V, text_fit, text_no_signal


def fit_two_peaks_gaussian(peak_range, x_spectral_unit, i_y_intensity, bl_int, bl_range,
                          is_Raman=False, print_status=False, path_save=None):
    #[1] Overall settings.
    window_to_range_r = 0.30
    shift_2nd_peak = -0.060 # Left shift of the second peak. Don't det this wrong, this is improtant.
    max_nfev = 5000
    
    #[2] Ensure it's PL.
    if is_Raman:
        raise ValueError(f'Currently, this "fit_two_peaks_gaussian" function works for PL fitting only. (is_Raman: {is_Raman})')
    
    #[3] Initial guess for 1st Gaussian.
    peak_start, peak_end = unpack_peak_range(peak_range)
    peak_pos, peak_int, peak_FWHM, text_no_signal \
        = peak_initial_guess_and_signal_check(x_spectral_unit, i_y_intensity, peak_range, bl_int, bl_range)
    peak_sigma = peak_FWHM / 2.355   # Definition of Gaussian to FWHM.
    peak_pos_lower, peak_pos_upper = compute_peak_pos_bounds_from_peak_range(peak_start, peak_end, window_to_range_r, peak_pos)
    sigma_lower = max(peak_sigma * 0.001, 0.001)
    
    #[6] Define initial_guess, lower_bounds, and upper_bounds.
    initial_guess_1 =   [peak_pos * 0.99,   peak_int * 0.8,     peak_sigma,         bl_int * 1.15]
    lower_bounds_1 =    [peak_pos_lower,    peak_int * 0.6,     sigma_lower,        bl_int * 0.9] 
    upper_bounds_1 =    [peak_pos_upper,    peak_int * 1.5,     peak_sigma * 2.5,   bl_int * 1.3]
    #check_if_initial_guess_is_fesible(initial_guess_1, lower_bounds_1, upper_bounds_1)

    #[7] Fit the first Gaussian.
    fitting_result_1G = try_to_fit_specific_function(single_gaussian, x_spectral_unit, i_y_intensity, 
                                            initial_guess_1, lower_bounds_1, upper_bounds_1, max_nfev)

    #[6] Define initial_guess, lower_bounds, and upper_bounds.
    """
    When tuning, change one at a time, do calculation, and press save.
    """
    x01, a1, sigma1, bl, r2  = fitting_result_1G[:5]
    peak_pos_1 = (x01 + peak_pos)/2
    peak_int_1 = a1 * 0.9       
    peak_sigma_1 = sigma1 * 0.7
    peak_pos_2 = peak_pos_1 + shift_2nd_peak
    peak_int_2 = peak_int_1 * 0.38
    peak_sigma_2 = peak_sigma_1 * 2.5
    initial_guess_2 = [peak_pos_1,      peak_int_1,         peak_sigma_1,             
                       peak_pos_2,      peak_int_2,         peak_sigma_2,       bl_int]
    lower_bounds_2 =  [peak_pos_1 - 0.05,   peak_int_1 * 0.8,   peak_sigma_1 * 0.8,             
                       peak_pos_2 - 0.05,   peak_int_2 * 0.8,   peak_sigma_2 * 0.8,     bl_int * 0.8]
    upper_bounds_2 =  [peak_pos_1 + 0.05,   peak_int_1 * 1.2,   peak_sigma_1 * 1.2,             
                       peak_pos_2 + 0.05,   peak_int_2 * 1.2,   peak_sigma_2 * 1.2,     bl_int * 1.2]
    check_if_initial_guess_is_fesible(initial_guess_2, lower_bounds_2, upper_bounds_2)
    
    #[7] Fit the second Gaussian.
    fitting_result_2G = try_to_fit_specific_function(double_gaussian, x_spectral_unit, i_y_intensity, 
                                            initial_guess_2, lower_bounds_2, upper_bounds_2, max_nfev)


    #[15] Organize log as df_log.
    titles = ['Initial Guess', 'Lower Bounds', 'Upper Bounds', 'Fitting Result']
    data_for_df = {
        'Title': titles,
        'Pos 1':    [initial_guess_2[0], lower_bounds_2[0], upper_bounds_2[0], fitting_result_2G[0]],
        'Int 1':    [initial_guess_2[1], lower_bounds_2[1], upper_bounds_2[1], fitting_result_2G[1]],
        'Sigma 1':  [initial_guess_2[2], lower_bounds_2[2], upper_bounds_2[2], fitting_result_2G[2]],
        'Pos 2':    [initial_guess_2[3], lower_bounds_2[3], upper_bounds_2[3], fitting_result_2G[3]],
        'Int 2':    [initial_guess_2[4], lower_bounds_2[4], upper_bounds_2[4], fitting_result_2G[4]],
        'Sigma 2':  [initial_guess_2[5], lower_bounds_2[5], upper_bounds_2[5], fitting_result_2G[5]],
        'Baseline': [initial_guess_2[6], lower_bounds_2[6], upper_bounds_2[6], fitting_result_2G[6]],
        'R²': [np.nan, np.nan, np.nan, fitting_result_2G[7]]}
    df_log = pd.DataFrame(data_for_df)
    df_log_cal = df_log.apply(lambda col: col.map(lambda x: f"{x:.10f}" if isinstance(x, (float, int)) else x))
    text_fit = f'\n[Double Gaussian] {text_no_signal}\n{tabulate(df_log, headers="keys", tablefmt="orgtbl")}\n'
    
    #[18] If print_status is True, we might debugging or other process that we need detailed info.
    if print_status is True:
        check_if_fitting_result_too_close_to_boundaries(df_log_cal)
        M4VIS.plot_boundary_check(df_log, path_save)  
    return fitting_result_2G, text_fit, text_no_signal





def fit_three_peaks_gaussian(peak_range, x_spectral_unit, i_y_intensity,bl_int, bl_range,
                          is_Raman=False, print_status=False, path_save=None):
    """
    2025-05-14
    Fit three overlapping peak to the i_y_intensity.
    y =   G_1(fit_pos1, fit_int1, fit_sigma1) 
        + G_2(fit_pos2, fit_int2, fit_sigma2) 
        + G_3(fit_pos3, fit_int3, fit_sigma3) + bl
    1. 
    """
    #[1] Overall settings.
    window_to_range_r = 0.30
    shift_2nd_peak = -0.060 # Left shift of the second peak. Don't det this wrong, this is improtant.
    max_nfev = 5000
    
    #[2] Ensure it's PL.
    if is_Raman:
        raise ValueError(f'Currently, this "fit_three_peaks_gaussian" function works for PL fitting only. (is_Raman: {is_Raman})')
    
    #[3] Initial guess for 1st Gaussian.
    peak_start, peak_end = unpack_peak_range(peak_range)
    peak_pos, peak_int, peak_FWHM, text_no_signal \
        = peak_initial_guess_and_signal_check(x_spectral_unit, i_y_intensity, peak_range, bl_int, bl_range)
    peak_sigma = peak_FWHM / 2.355   # Definition of Gaussian to FWHM.
    peak_pos_lower, peak_pos_upper = compute_peak_pos_bounds_from_peak_range(peak_start, peak_end, window_to_range_r, peak_pos)
    sigma_lower = max(peak_sigma * 0.001, 0.001)
    
    #[6] Define initial_guess, lower_bounds, and upper_bounds.
    initial_guess_1 =   [peak_pos * 0.99,   peak_int * 0.8,     peak_sigma,         bl_int * 1.15]
    lower_bounds_1 =    [peak_pos_lower,    peak_int * 0.6,     sigma_lower,        bl_int * 0.9] 
    upper_bounds_1 =    [peak_pos_upper,    peak_int * 1.5,     peak_sigma * 2.5,   bl_int * 1.3]
    #check_if_initial_guess_is_fesible(initial_guess_1, lower_bounds_1, upper_bounds_1)

    #[7] Fit the first Gaussian.
    fitting_result_1G = try_to_fit_specific_function(single_gaussian, x_spectral_unit, i_y_intensity, 
                                            initial_guess_1, lower_bounds_1, upper_bounds_1, max_nfev)

    #[6] Define initial_guess, lower_bounds, and upper_bounds.
    x01, a1, sigma1, bl, r2  = fitting_result_1G[:5]
    peak_pos_1 = (x01 + peak_pos)/2
    peak_int_1 = a1 * 0.9       
    peak_sigma_1 = sigma1 * 0.7
    peak_pos_2 = peak_pos_1 + shift_2nd_peak
    peak_int_2 = peak_int_1 * 0.38
    peak_sigma_2 = peak_sigma_1 * 2.5
    initial_guess_2 = [peak_pos_1,      peak_int_1,         peak_sigma_1,             
                       peak_pos_2,      peak_int_2,         peak_sigma_2,       bl_int]
    lower_bounds_2 =  [peak_pos_1 - 0.05,   peak_int_1 * 0.8,   peak_sigma_1 * 0.8,             
                       peak_pos_2 - 0.05,   peak_int_2 * 0.8,   peak_sigma_2 * 0.8,     bl_int * 0.8]
    upper_bounds_2 =  [peak_pos_1 + 0.05,   peak_int_1 * 1.2,   peak_sigma_1 * 1.2,             
                       peak_pos_2 + 0.05,   peak_int_2 * 1.2,   peak_sigma_2 * 1.2,     bl_int * 1.2]
    check_if_initial_guess_is_fesible(initial_guess_2, lower_bounds_2, upper_bounds_2)
    
    #[7] Fit the second Gaussian.
    fitting_result_2G = try_to_fit_specific_function(double_gaussian, x_spectral_unit, i_y_intensity, 
                                            initial_guess_2, lower_bounds_2, upper_bounds_2, max_nfev)

    #[6] Define initial_guess, lower_bounds, and upper_bounds.
    shift_3rd_peak = -0.1
    x01, a1, sigma1, x02, a2, sigma2, bl, r2  = fitting_result_2G[:8]
    peak_pos_1 = x01
    peak_int_1 = a1 * 0.65
    peak_sigma_1 = sigma1 * 0.7
    peak_pos_2 = x02 + 0.05
    peak_int_2 = a2 * 1.5
    peak_sigma_2 = sigma2 * 0.5
    peak_pos_3 = peak_pos_1 + shift_3rd_peak
    peak_int_3 = peak_int_2 * 0.45
    peak_sigma_3 = 0.085
    initial_guess_3 = [peak_pos_1, peak_int_1, peak_sigma_1,
                       peak_pos_2, peak_int_2, peak_sigma_2,            
                       peak_pos_3, peak_int_3, peak_sigma_3, bl]
    lower_bounds_3 = [peak_pos_lower,       peak_int_1 * 0.8, peak_sigma_1 * 0.6,             
                       peak_pos_2 - 0.05,   peak_int_2 * 0.8, peak_sigma_2 * 0.6, 
                       peak_pos_3 - 0.05,   peak_int_3 * 0.8, peak_sigma_3 * 0.8,  bl_int * 0.8]
    upper_bounds_3 = [peak_pos_upper,       peak_int_1 * 1.2, peak_sigma_1 * 1.4,             
                       peak_pos_2 + 0.05,   peak_int_2 * 1.2, peak_sigma_2 * 1.4, 
                       peak_pos_3 + 0.05,   peak_int_3 * 1.2, peak_sigma_3 * 1.2,bl_int * 1.2]
    check_if_initial_guess_is_fesible(initial_guess_3, lower_bounds_3, upper_bounds_3)

    #[7] Fit the third Gaussian.
    
    fitting_result_3G = try_to_fit_specific_function(triple_gaussian, x_spectral_unit, i_y_intensity, 
                                            initial_guess_3, lower_bounds_3, upper_bounds_3, max_nfev)

    print(f'fitting_result_3G = {fitting_result_3G}')

    #[15] Organize log as df_log.
    titles = ['Initial Guess', 'Lower Bounds', 'Upper Bounds', 'Fitting Result']
    data_for_df = {
        'Title': titles,
        'Pos 1':    [initial_guess_3[0], lower_bounds_3[0], upper_bounds_3[0], fitting_result_3G[0]],
        'Int 1':    [initial_guess_3[1], lower_bounds_3[1], upper_bounds_3[1], fitting_result_3G[1]],
        'Sigma 1':  [initial_guess_3[2], lower_bounds_3[2], upper_bounds_3[2], fitting_result_3G[2]],
        'Pos 2':    [initial_guess_3[3], lower_bounds_3[3], upper_bounds_3[3], fitting_result_3G[3]],
        'Int 2':    [initial_guess_3[4], lower_bounds_3[4], upper_bounds_3[4], fitting_result_3G[4]],
        'Sigma 2':  [initial_guess_3[5], lower_bounds_3[5], upper_bounds_3[5], fitting_result_3G[5]],
        'Pos 3':    [initial_guess_3[6], lower_bounds_3[6], upper_bounds_3[6], fitting_result_3G[6]],
        'Int 3':    [initial_guess_3[7], lower_bounds_3[7], upper_bounds_3[7], fitting_result_3G[7]],
        'Sigma 3':  [initial_guess_3[8], lower_bounds_3[8], upper_bounds_3[8], fitting_result_3G[8]],
        'Baseline': [initial_guess_3[9], lower_bounds_3[9], upper_bounds_3[9], fitting_result_3G[9]],
        'R²': [np.nan, np.nan, np.nan, fitting_result_3G[10]]}
    df_log = pd.DataFrame(data_for_df)
    df_log_cal = df_log.apply(lambda col: col.map(lambda x: f"{x:.10f}" if isinstance(x, (float, int)) else x))
    text_fit = f'\n[Triple Gaussian] {text_no_signal}\n{tabulate(df_log, headers="keys", tablefmt="orgtbl")}\n'
    
    #[18] If print_status is True, we might debugging or other process that we need detailed info.
    if print_status is True:
        check_if_fitting_result_too_close_to_boundaries(df_log_cal)
        M4VIS.plot_boundary_check(df_log, path_save)  
    return fitting_result_3G, text_fit, text_no_signal




