def dir_fit_to_path_fitting_record(dir_fit, bsn, ext):
    if dir_fit is None:
        return None
    else:
        print(f'-- dir_fit: {dir_fit}')
        path_fitting_record = os.path.join(dir_fit, f'{bsn}.{ext}')
        return path_fitting_record



def fit_spectrum_with_three_methods(array_data_trimmed, is_Raman, peak_range,
                                    sw4_plot_ovlp_spectra, plot_title, path_save, 
                                    dir_fit=None, png_tag='version tag for png',
                                    df_time=None, df_fit=None, df_R2=None, text_log=None):

    print('\n[fit_trimmed_spectrum_with_three_methods]')
    #[1] Settings.
    debug_switch = False     # This will print fitting process one by one.
    
    #[12] If dataframe is empty, create it with appropriate columns.
    if df_time is None:
        df_time = pd.DataFrame(columns=['Peak Range', 'Method', 'Time (sec)'])
    if df_fit is None:
        df_fit = pd.DataFrame(columns=['Peak Range', 'Method', 'Parameters'])
    if df_R2 is None:
        df_R2 = pd.DataFrame(columns=['Peak Range', 'Gaussian', 'Lorentzian', 'Voigt'])
    if text_log is None:
        text_log = f'(text_log was not provided.)\n\n-----\n[Peak Range] {peak_range[0]} ~ {peak_range[1]}\n'\
                    f'array_data_trimmed.shape: {array_data_trimmed.shape}\n'
    
    #[13] Unpack peak range.
    peak_start, peak_end = unpack_peak_range(peak_range)
    
    #[3] Separate x and y. Pack range.
    x_spectral_unit = array_data_trimmed[0, :]
    y_intensities = array_data_trimmed[1:, :].flatten()
    print(f'y_intensities.shape: {y_intensities.shape}')
    peak_range = [peak_start, peak_end]
    bl_int, bl_range = M2SDP.compute_baseline_stat(array_data_trimmed, pct=80)

    
    #[4] Optionally plot the trimmed spectrum.
    if sw4_plot_ovlp_spectra:
        M4VIS.plot_overlapping_spectra(array_data_trimmed, [400, None], is_Raman, plot_title, path_save)

    #[5] [Gaussian] Fit spectrum with single Gaussian.       
    t1 = time.time()
    path_boundary_check = dir_fit_to_path_fitting_record(dir_fit, f'01_1G-fit_{png_tag}', 'png')
    fitting_result_1G, text_fit, text_no_signal \
        = fit_one_peak_gaussian(peak_range, x_spectral_unit, y_intensities, bl_int, bl_range,
                                is_Raman, True, path_boundary_check)
    text_log += text_fit

    
    
    #[6] Optionally print the Gaussian fittting result to debug.
    if debug_switch:
        #[7] Unpack fitting result.
        print(f'fitting_result_1G: {fitting_result_1G}\n{text_fit}')
        x01, a1, sigma1, bl, r2  = fitting_result_1G[:5]
        y_fit_1G = single_gaussian(x_spectral_unit, x01, a1, sigma1, bl)
        area_G = gaussian_area(a1, sigma1)
        
        #[8] Visualize fitting.
        text_plot = f'[Fitting Result]\n\n'\
                    f'G1: {x01:.03f}, {a1:.03f}, {sigma1:.03f}\n'\
                    f'Area_1G = {area_G:.03f}\n\n'\
                    f'Bl = {bl:.03f}, R² = {r2:.03f}'
                    
        array_data_fit = np.vstack([array_data_trimmed, y_fit_1G])
        plot_title = f'Overlapping Spectra of Original Data and Gaussian Fitting Result'
        
        M4VIS.plot_overlapping_spectra_for_fitting(array_data_fit, [450, 650], is_Raman, 
                                                   plot_title, text_plot, None)

    
    #[9] [Lorentzian] Fit spectrum with single Lorentzian.      
    t2 = time.time()
    path_boundary_check = dir_fit_to_path_fitting_record(dir_fit, f'02_1L-fit_{png_tag}', 'png')
    fitting_result_1L, text_fit, text_no_signal \
        = fit_one_peak_lorentzian(peak_range, x_spectral_unit, y_intensities, bl_int, bl_range,
                                is_Raman, True, path_boundary_check)
    text_log += text_fit

    #[10] Optionally print the Lorentzian fittting result to debug.
    if debug_switch:
        #[11] Unpack fitting result.
        print(f'fitting_result_1L: {fitting_result_1L}\n{text_fit}')
        x01, a1, gamma1, bl, r2  = fitting_result_1L[:5]
        y_fit_1L = single_lorentzian(x_spectral_unit, x01, a1, gamma1, bl)
        area_L = lorentzian_area(a1, gamma1)

        #[12] Visualize fitting.
        text_plot = f'[Fitting Result]\n\n'\
                    f'L1: {x01:.03f}, {a1:.03f}, {gamma1:.03f}\n'\
                    f'Area_1L = {area_L:.03f}\n\n'\
                    f'Bl = {bl:.03f}, R² = {r2:.03f}'
                    
        array_data_fit = np.vstack([array_data_trimmed, y_fit_1L])
        plot_title = f'Overlapping Spectra of Original Data and Lorentzian Fitting Result'
        M4VIS.plot_overlapping_spectra_for_fitting(array_data_fit, [450, 650], is_Raman, bl_range,
                                                   plot_title, text_plot, None)

    #[13] [Voigt] Fit spectrum with single Voigt.           
    t3 = time.time()
    path_boundary_check = dir_fit_to_path_fitting_record(dir_fit, f'03_1V-fit_{png_tag}', 'png')
    fitting_result_1V, text_fit, text_no_signal \
        = fit_one_peak_voigt(peak_range, x_spectral_unit, y_intensities, bl_int, bl_range,
                                is_Raman, True, path_boundary_check)
    text_log += text_fit

    #[14] Optionally print the Lorentzian fittting result to debug.
    if debug_switch:
        #[15] Unpack fitting result.
        print(f'fitting_result_1V: {fitting_result_1V}\n{text_fit}')
        x01, a1, sigma1, gamma1, bl, r2  = fitting_result_1V[:6]
        y_fit_1V = single_voigt(x_spectral_unit, x01, a1, sigma1, gamma1, bl)
        area_V = voigt_area_approx(a1, sigma1, gamma1)

        #[16] Visualize fitting.
        text_plot = f'[Fitting Result]\n\n'\
                    f'V1: {x01:.03f}, {a1:.03f}, {sigma1:.03f}, {gamma1:.03f}\n'\
                    f'Area_1V = {area_V:.03f}\n\n'\
                    f'Bl = {bl:.03f}, R² = {r2:.03f}'
                    
        array_data_fit = np.vstack([array_data_trimmed, y_fit_1V])
        plot_title = f'Overlapping Spectra of Original Data and Voigit Fitting Result'
        M4VIS.plot_overlapping_spectra_for_fitting(array_data_fit, [450, 650], is_Raman, 
                                                   plot_title, text_plot, None)

    t4= time.time()

    #[18] Stackup and take a look
    plot_title = f'Overlapping Spectra of Original Data and Three Fitting Method'
    path_fitting_record = dir_fit_to_path_fitting_record(dir_fit, f'04_GLV-fit_{png_tag}', 'png')
    M4VIS.plot_overlapping_spectra_three_diff_fitting_method(array_data_trimmed, [450, None], 
                                                             plot_title, path_fitting_record, 
                                                             fitting_result_1G[:5], 
                                                             fitting_result_1L[:5], 
                                                             fitting_result_1V[:6])

    # [20] Append time data to df_time.
    df_time = pd.concat([
        df_time,
        pd.DataFrame([
            {'Peak Range': f'{peak_start} ~ {peak_end}', 'Method': 'Gaussian', 'Time (sec)': round(t2 - t1, 5)},
            {'Peak Range': f'{peak_start} ~ {peak_end}', 'Method': 'Lorentzian', 'Time (sec)': round(t3 - t2, 5)},
            {'Peak Range': f'{peak_start} ~ {peak_end}', 'Method': 'Voigt', 'Time (sec)': round(t4 - t3, 5)}
        ])
    ], ignore_index=True)

    # [20] Append fitting data to df_fit.
    df_fit = pd.concat([
        df_fit,
        pd.DataFrame([
            {'Peak Range': f'{peak_start} ~ {peak_end}', 
             'Method': 'Gaussian', 
             'Parameters': fitting_result_1G},
            {'Peak Range': f'{peak_start} ~ {peak_end}', 
             'Method': 'Lorentzian', 
             'Parameters': fitting_result_1L},
            {'Peak Range': f'{peak_start} ~ {peak_end}', 
             'Method': 'Voigt', 
             'Parameters': fitting_result_1V}])
    ], ignore_index=True)
    
    #[20] Append R² values to df_R2.
    df_R2 = pd.concat([
        df_R2,
        pd.DataFrame([
            {'Peak Range': f'{peak_start} ~ {peak_end}', 
             'Gaussian': fitting_result_1G[4], 
             'Lorentzian': fitting_result_1L[4], 
             'Voigt': fitting_result_1V[5]}
        ])
    ])

    return df_time, df_fit, df_R2, text_log




def fit_mapping_data_with_single_peak(array_data_trimmed, peak_range, fit_method, is_Raman):
    print(f'\n[fit_mapping_data_with_single_peak] {peak_range[0]} ~ {peak_range[1]}, {fit_method}')
    # [1] Validate input and settings.
    if array_data_trimmed.shape[0] < 2:
        raise ValueError("array_data must have at least two rows: one for x-axis and one for y-intensities.")
    if fit_method not in ['Gaussian', 'Lorentzian', 'Voigt']:
        list_fitting_methods = ['fit_one_peak_gaussian', 
                        'fit_one_peak_lorentzian', 'fit_two_peaks_lorentzian',
                        'fit_one_peak_voigt']
        raise ValueError(f'Unknown fit_method: {fit_method}. Supported methods are {list_fitting_methods}.')
    
    peak_start, peak_end = unpack_peak_range(peak_range)
    print_status = False
    
    # [2] Get the number of data sets from the shape of the array.
    num_data_sets = array_data_trimmed.shape[0] - 1
    list_text_no_signal = []
    
    # [3] Extract the x-axis (wavenumber); compute baseline value.
    x_spectral_unit = array_data_trimmed[0, :]
    bl_int, bl_range = M2SDP.compute_baseline_stat(array_data_trimmed, pct=80)

    # [4] Initialize an empty list to store fitting results.
    array_fitting_result = []
    text_fitting_logs = f'[{num_data_sets} datasets] Fitting with {fit_method} method.\n'
    
    # [5] Map fitting methods to corresponding functions.
    dic_fit_methods = {
        'Gaussian': fit_one_peak_gaussian,
        'Lorentzian': fit_one_peak_lorentzian,
        'Voigt': fit_one_peak_voigt
    }
    fit_function = dic_fit_methods[fit_method]

    # [6] Iterate over each dataset and fit the single Raman peak.
    for i in range(num_data_sets):
        i_y_intensity = array_data_trimmed[i + 1, :]

        # [7] Print the current dataset number.
        text_2 = f'\n[{i:04d}/{num_data_sets:04d}]'
        text_fitting_logs += text_2
        if print_status:
            print(text_2)

        try:
            # [8] Call the appropriate fitting function.
            i_fitting_result, text_fit, text_no_signal \
                = fit_function(peak_range, x_spectral_unit, i_y_intensity, bl_int, bl_range,
                                is_Raman, False, None)

        except Exception as e:
            i_fitting_result = [None] * (5 if fit_method in ['Gaussian', 'Lorentzian'] else 6)
            tb = traceback.format_exc()
            text_fit = f'Error fitting dataset {i}: {str(e)}\n{tb}'
            text_no_signal = None
        list_text_no_signal.append(text_no_signal)
        
        # [9] Append the fitting result and log.
        array_fitting_result.append(i_fitting_result)
        text_fitting_logs += text_fit
        
        #[10] Selectively print fitting process.
        formatted_result = ',\t'.join([f"{val:.4f}" if val is not None else "None" for val in i_fitting_result[:5]])
        if i_fitting_result[0] is None:
            print(f'-- [{i:04d}/{num_data_sets:04d}] {formatted_result}. \tFitting failed. \n{text_fit}')
        elif print_status:
            print(f'-- [{i:04d}/{num_data_sets:04d}] {formatted_result}.')
        elif i % 10 == 0:
            print(f'-- [{i:04d}/{num_data_sets:04d}] {formatted_result}.')

    #[11] Convert the list to a NumPy array after the loop.
    array_fitting_result = np.array(array_fitting_result)
    print(f'\n -- [fit_mapping_data_with_single_peak]  -- \n\n')
    return array_fitting_result, text_fitting_logs, list_text_no_signal



