def unpack_y_axis_limits(y_axis_limits, array_data, add_y_max=100):
    #[1] If y_axis_limits is not provided.
    if y_axis_limits is None:
        y_axis_max = np.max(array_data[1:, :]) // 100 * 100 + add_y_max
        if y_axis_max <= 1000:
            y_axis_max += 100
        y_axis_min = 400
    #[2] If y_axis_max is not provided.
    elif y_axis_limits[1] is None:
        y_axis_max = np.max(array_data[1:, :]) // 100 * 100 + add_y_max
        if y_axis_max <= 1000:
            y_axis_max += 100
        y_axis_min = y_axis_limits[0]
    elif not isinstance(y_axis_limits, (list, tuple)) or len(y_axis_limits) != 2:
        raise ValueError(f'Invalid format for y_axis_limits: {y_axis_limits}')
    else:
        y_axis_min, y_axis_max = y_axis_limits
    return y_axis_min, y_axis_max


# plot_all_spectra_overlapped
def plot_overlapping_spectra(array_data, y_axis_limits, is_Raman, plot_title, path_save=None):
    print(f'\n[plot_overlapping_spectra] \t Size of data: {array_data.shape}')
    eV_to_nm = 1239.841984
    #[1] Set plot
    fig, ax1 = plt.subplots(figsize=(16, 8))
    fs_title, fs_axis = 20, 16
    y_axis_min, y_axis_max = unpack_y_axis_limits(y_axis_limits, array_data)

    #[2] Get the number of data sets from the shape of the array
    num_data_sets = array_data.shape[0] - 1

    #[3] Extract the x-axis (wavenumber) from the first row
    x_spectral_unit = array_data[0, :]
    
    #[4] Set line width according to number of lines.
    if num_data_sets < 5:
        line_width = 3
    elif num_data_sets < 10:
        line_width = 2
    elif num_data_sets < 20:
        line_width = 1.5
    elif num_data_sets < 50:
        line_width = 1
    else:
        line_width = 0.5

    #[4] Iterate over each data set and plot it on the same axis
    for i in range(num_data_sets):
        iter_y_intensity = array_data[i + 1, :]
        ax1.plot(x_spectral_unit, iter_y_intensity, label=f'Data Set {i + 1}', 
                linewidth=line_width)

    #[5] Set x-axis labels and title. Show both the original eV and nm.
    if is_Raman:
        xlabel = r'Wavenumber (cm$^{-1}$)'
        ax1.set_xlabel(xlabel, fontsize=fs_axis)
    else:
        #[6] Bottom: eV
        ax1.set_xlabel('Energy (eV)', fontsize=fs_axis)
        ax1.set_xlim(x_spectral_unit.min(), x_spectral_unit.max())

        #[7] Top: Wavelength (nm)
        def eV_to_nm_axis(x): return eV_to_nm / x
        def nm_to_eV_axis(x): return eV_to_nm / x
        ax1_top = ax1.secondary_xaxis('top', functions=(eV_to_nm_axis, nm_to_eV_axis))
        #ax1_top.set_xlabel('Wavelength (nm)', fontsize=fs_axis)  # Hind top lable for clarity.

    #[9] Set y-axis labels and title
    ax1.set_ylabel('Intensity', fontsize=fs_axis)    
    ax1.set_ylim(y_axis_min, y_axis_max)
    ax1.set_title(plot_title, fontsize=fs_title)
    plt.tight_layout()

    #[10] Set more dense x-ticks
    ax1.xaxis.set_major_locator(plt.MaxNLocator(30))

    #[15] Optionally save the figure
    if path_save is not None:
        plt.savefig(path_save)
        plt.close()
        print(f'-- Plot saved to {path_save}')
    else:
        plt.show()





def plot_overlapping_spectra_three_diff_fitting_method(array_data, y_axis_limits,
                                                    plot_title, path_save,
                                                    gaussian_fit=None, lorentzian_fit=None, voigt_fit=None):
    print(f'\n[plot_overlapping_spectra_with_fitting] \t Size of data: {array_data.shape}')
    
    #[1] Set plot
    fig, ax1 = plt.subplots(figsize=(16, 8))
    fs_title, fs_axis = 20, 16
    y_axis_min, y_axis_max = unpack_y_axis_limits(y_axis_limits, array_data)

    #[2] Get the number of data sets from the shape of the array
    num_data_sets = array_data.shape[0] - 1

    #[3] Extract the x-axis (wavenumber) from the first row
    x_wavenumber = array_data[0, :]

    #[4] Iterate over each data set and plot it on the same axis
    for i in range(num_data_sets):
        iter_y_intensity = array_data[i + 1, :]
        ax1.plot(x_wavenumber, iter_y_intensity, label=f'Data Set {i + 1}', color='gray', linewidth=3)
        break

    #[5] Plot the Gaussian fit if provided: ([fit_pos, fit_int, fit_sigma1, fit_bl, fit_r2])
    if gaussian_fit is not None:
        if gaussian_fit.shape != (5,):
            raise ValueError(f'gaussian_fit must be a 1D array with shape (5,), {gaussian_fit}')
        x0_G, a_G, sigma_G, bl_G, r2_G = gaussian_fit
        y_intensity_G = M3PFF.single_gaussian(x_wavenumber, x0_G, a_G, sigma_G, bl_G)
        ax1.plot(x_wavenumber, y_intensity_G, label='Gaussian Fit', 
                 color='red', linestyle='-.', linewidth=2)

    #[6] Plot the Lorentzian fit if provided: ([fit_pos, fit_int, fit_gamma1, fit_bl, fit_r2])
    if lorentzian_fit is not None:
        if lorentzian_fit.shape != (5,):
            raise ValueError(f'lorentzian_fit must be a 1D array with shape (5,), {lorentzian_fit}')
        x0_L, a_L, gamma_L, bl_L, r2_L = lorentzian_fit
        y_intensity_L = M3PFF.single_lorentzian(x_wavenumber, x0_L, a_L, gamma_L, bl_L)
        ax1.plot(x_wavenumber, y_intensity_L, label='Lorentzian Fit', 
                 color='green', linestyle='--', linewidth=2)

    #[7] Plot the Voigt fit if provided: ([fit_pos, fit_int, fit_sigma1, fit_gamma1, fit_bl, fit_r2])
    if voigt_fit is not None:
        if voigt_fit.shape != (6,):
            raise ValueError(f'voigt_fit must be a 1D array with shape (6,), {voigt_fit}')
        x0_V, a_V, sigma_V, gamma_V, bl_V, r2_V = voigt_fit
        y_intensity_V = M3PFF.single_voigt(x_wavenumber, x0_V, a_V, sigma_V, gamma_V, bl_V)
        ax1.plot(x_wavenumber, y_intensity_V, label='Voigt Fit', 
                 color='blue', linestyle=':', linewidth=2)

    #[8] Set axis labels and title
    ax1.set_xlabel(r'Wavenumber ($cm^{-1}$)', fontsize=fs_axis)
    ax1.set_ylabel('Intensity', fontsize=fs_axis)    
    ax1.set_ylim(y_axis_min, y_axis_max)
    ax1.set_title(plot_title, fontsize=fs_title)

    #[9] Add text annotation for data statistics
    area_G = M3PFF.gaussian_area(a_G, sigma_G)
    area_L = M3PFF.lorentzian_area(lorentzian_fit[1], lorentzian_fit[2])
    area_V = M3PFF.voigt_area_approx(voigt_fit[1], voigt_fit[2], voigt_fit[3])
    text_plot = f'[Gaussian] (x01, a, sigma)\n'\
                f'G1: {x0_G:.03f}, {a_G:.03f}, {sigma_G:.03f}\n'\
                f'Area_G1 = {area_G:.03f}\n'\
                f'Bl = {bl_G:.03f}, R² = {r2_G:.04f}\n\n'\
                f'[Lorentzian] (x01, a, gamma)\n'\
                f'L1: {x0_L:.03f}, {a_L:.03f}, {gamma_L:.03f}\n'\
                f'Area_L1 = {area_L:.03f}\n'\
                f'Bl = {bl_L:.03f}, R² = {r2_L:.04f}\n\n'\
                f'[Voigt] (x01, a, sigma, gamma)\n'\
                f'V1: {x0_V:.03f}, {a_V:.03f}, {sigma_V:.03e}, {gamma_V:.03f}\n'\
                f'Area_V1 = {area_V:.03f}\n'\
                f'Bl = {bl_V:.03f}, R² = {r2_V:.04f}'
    print(f'{text_plot}')
    add_text_in_plot_with_new_line_and_tab(ax1, 0.01, 1.05, text_plot, 
                                           ft_size=16, color="#303030", family='monospace')
    
    #[10] Add legend at the upper right corner
    ax1.legend(loc='upper right', fontsize=fs_axis - 4)
    
    #[11] Set more dense x-ticks
    ax1.xaxis.set_major_locator(plt.MaxNLocator(30))

    #[15] Optionally save the figure
    if path_save is not None:
        plt.savefig(path_save)
        plt.close()
        print(f'-- Plot saved to {path_save}')
    else:
        plt.show()





