def plot_all_spectra_overlapped_using_fitting_result(df_fitting_result, x_spectral_unit, fit_method,
                                                     plot_title, path_save):
    print(f'\n[plot_all_spectra_overlapped_using_fitting_result] \t Size of data: {df_fitting_result.shape}')
    
    #[1] Set plot
    fig, ax1 = plt.subplots(figsize=(16, 8))
    fs_title, fs_axis = 20, 16
    
    #[2] Determine the fitting method
    if fit_method == 'Gaussian':
        for index, row in df_fitting_result.iterrows():
            fit_pos = row['fit_pos']
            fit_int = row['fit_int']
            fit_sigma = row['fit_sigma']
            fit_bl = row['fit_bl']
            y_fit = M3PFF.single_gaussian(x_spectral_unit, fit_pos, fit_int, fit_sigma, fit_bl)            
            ax1.plot(x_spectral_unit, y_fit, label=f'Data Set {index + 1}', linewidth=0.5)
    elif fit_method == 'Lorentzian':
        for index, row in df_fitting_result.iterrows():
            fit_pos = row['fit_pos']
            fit_int = row['fit_int']
            fit_gamma = row['fit_gamma']
            fit_bl = row['fit_bl']
            y_fit = M3PFF.single_lorentzian(x_spectral_unit, fit_pos, fit_int, fit_gamma, fit_bl)            
            ax1.plot(x_spectral_unit, y_fit, label=f'Data Set {index + 1}', linewidth=0.5)
    elif fit_method == 'Voigt':
        for index, row in df_fitting_result.iterrows():
            fit_pos = row['fit_pos']
            fit_int = row['fit_int']
            fit_sigma = row['fit_sigma']
            fit_gamma = row['fit_gamma']
            fit_bl = row['fit_bl']
            y_fit = M3PFF.single_voigt(x_spectral_unit, fit_pos, fit_int, fit_sigma, fit_gamma, fit_bl)            
            ax1.plot(x_spectral_unit, y_fit, label=f'Data Set {index + 1}', linewidth=0.5)
            
            
            
            
    else:
        list_fitting_methods = ['fit_one_peak_gaussian', 
                                'fit_one_peak_lorentzian', 'fit_two_peaks_lorentzian',
                                'fit_one_peak_voigt']
        raise ValueError(f'Unknown fit_method: {fit_method}. Supported methods are {list_fitting_methods}.')
    

    #[4] Set axis labels and title
    ax1.set_xlabel(r'Wavenumber ($cm^{-1}$)', fontsize=fs_axis)
    ax1.set_ylabel('Intensity', fontsize=fs_axis)    
    ax1.set_title(plot_title, fontsize=fs_title)
    
    #[5] Set more dense x-ticks
    ax1.xaxis.set_major_locator(plt.MaxNLocator(30))
    
    #[6] Save the figure
    plt.tight_layout()
    plt.savefig(path_save)
    plt.close()
    
    print(f'Plot saved to {path_save}')







