def compute_bins_by_width(data, bin_width):
    data = pd.to_numeric(data, errors='coerce')  # <- Convert to float, force invalid entries to NaN
    data = data[np.isfinite(data)]               # <- Keep only finite numbers
    data_min, data_max = data.min(), data.max()
    bins = np.arange(data_min, data_max + bin_width, bin_width)
    return bins


def plot_fitting_statistics_histogram(df_fitting_result, R2_thr=0.8, list_limits=[],
                            plot_title='Fitting Statistics', path_save=None):
    """
    if fit_method == 'Gaussian':
        column_titles = ['loc_x', 'loc_y', 'fit_pos', 'fit_int', 'fit_sigma', 'fit_bl', 'fit_r2']
    elif fit_method == 'Lorentzian':
        column_titles = ['loc_x', 'loc_y', 'fit_pos', 'fit_int', 'fit_gamma', 'fit_bl', 'fit_r2']
    elif fit_method == 'Voigt':
        column_titles = ['loc_x', 'loc_y', 'fit_pos', 'fit_int', 'fit_sigma', 'fit_gamma', 'fit_bl', 'fit_r2']
    """
    print(f'[plot_fitting_statistics_histogram]\n {df_fitting_result.columns[0]}') 
    # [1] Filter the DataFrame for good fits
    df_good_fits = df_fitting_result[df_fitting_result['fit_r2'] > R2_thr]
    if df_good_fits.empty:
        print("No data points meet the R2 threshold. Skipping plot.")
        return
    cnt_good_fit = len(df_fitting_result)
    print(f'cnt_good_fit = {cnt_good_fit}')
    

    # [2] Set up the figure and axes
    fs_title, fs_subtitle, fs_axis, fs_tick = 28, 26, 24, 20
    alpha_v = 0.7
    rwidth_v = 0.9
    linespace = 0.08
    ft_size = 24
    ft_family = 'monospace'
    ft_color = 'dimgray'

    # [3] Define columns to plot and their properties
    list_col = df_fitting_result.columns.tolist()
    #[4] If it's a Voigt fitting result.
    if len(list_col) == 8:
        fig, axes = plt.subplots(2, 3, figsize=(18, 12))
        plot_metadata = [
            ('fit_pos', 'Position (fit_pos)', 'Position Distribution', 'firebrick', df_good_fits, 
            0.2,   list_limits[0], list_limits[1]),
            ('fit_int', 'Intensity (fit_int)', 'Intensity Distribution', 'darkorange', df_good_fits, 
            200,   list_limits[2], list_limits[3]),
            ('fit_sigma', 'Width (fit_xFWHM)', 'Width Distribution',    'gold', df_good_fits, 
            0.2,   list_limits[4], list_limits[5]),
            ('fit_gamma', 'Width (fit_xFWHM)', 'Width Distribution',    'gold', df_good_fits, 
            0.2,   list_limits[4], list_limits[5]),
            ('fit_bl', 'Baseline (fit_bl)',     'Baseline Distribution', 'seagreen', df_good_fits, 
            2, list_limits[6], list_limits[7]),
            ('fit_r2', 'R² (fit_r2, all)',      'R² Distribution (all)', 'mediumpurple', df_fitting_result, 
            0.05,  list_limits[10], list_limits[11])]
    #[5] If it's a Lorentzian fitting result.
    elif list_col[4] == 'fit_gamma':
        fig, axes = plt.subplots(2, 3, figsize=(18, 12))
        plot_metadata = [
            ('fit_pos', 'Position (fit_pos)', 'Position Distribution', 'firebrick', df_good_fits, 
            0.2,   list_limits[0], list_limits[1]),
            ('fit_int', 'Intensity (fit_int)', 'Intensity Distribution', 'darkorange', df_good_fits, 
            200,   list_limits[2], list_limits[3]),
            ('fit_gamma', 'Width (fit_xFWHM)', 'Width Distribution',    'gold', df_good_fits, 
            0.2,   list_limits[4], list_limits[5]),
            ('fit_bl', 'Baseline (fit_bl)',     'Baseline Distribution', 'seagreen', df_good_fits, 
            2, list_limits[6], list_limits[7]),
            ('fit_r2', 'R² (fit_r2)',           'R² Distribution',      'dodgerblue', df_good_fits, 
            0.01,  list_limits[8], list_limits[9]),
            ('fit_r2', 'R² (fit_r2, all)',      'R² Distribution (all)', 'mediumpurple', df_fitting_result, 
            0.05,  list_limits[10], list_limits[11])]
    #[5] If it's a Gaussian fitting result.
    elif list_col[4] == 'fit_sigma':
        fig, axes = plt.subplots(2, 3, figsize=(18, 12))
        plot_metadata = [
            ('fit_pos', 'Position (fit_pos)', 'Position Distribution', 'firebrick', df_good_fits, 
            0.2,   list_limits[0], list_limits[1]),
            ('fit_int', 'Intensity (fit_int)', 'Intensity Distribution', 'darkorange', df_good_fits, 
            200,   list_limits[2], list_limits[3]),
            ('fit_sigma', 'Width (fit_xFWHM)', 'Width Distribution',    'gold', df_good_fits, 
            0.2,   list_limits[4], list_limits[5]),
            ('fit_bl', 'Baseline (fit_bl)',     'Baseline Distribution', 'seagreen', df_good_fits, 
            2, list_limits[6], list_limits[7]),
            ('fit_r2', 'R² (fit_r2)',           'R² Distribution',      'dodgerblue', df_good_fits, 
            0.01,  list_limits[8], list_limits[9]),
            ('fit_r2', 'R² (fit_r2, all)',      'R² Distribution (all)', 'mediumpurple', df_fitting_result, 
            0.05,  list_limits[10], list_limits[11])]
    #[6] If it's a Double Lorentzian (loc_x, loc_y, fit_pos1, fit_int1, fit_gamma1, fit_pos2, fit_int2, fit_gamma2, fit_bl, fit_r2]
    elif list_col[4] == 'fit_gamma1' and len(list_col) == 10:
        fig, axes = plt.subplots(3, 3, figsize=(18, 18))
        plot_metadata = [
            ('fit_pos1', 'Position (fit_pos1)',     'Position Distribution',    'firebrick',    df_good_fits, 
            0.5,   list_limits[0], list_limits[1]),
            ('fit_int1', 'Intensity (fit_int1)',    'Intensity Distribution',   'darkorange',   df_good_fits, 
            200,   list_limits[2], list_limits[3]),
            ('fit_gamma1', 'Width (fit_gamma1)',    'Width Distribution',       'gold',         df_good_fits, 
            0.2,   list_limits[4], list_limits[5]),
            ('fit_pos2', 'Position (fit_pos2)',     'Position Distribution',    'firebrick',     df_good_fits, 
            0.5, list_limits[6], list_limits[7]),
            ('fit_int2', 'Intensity (fit_int2)',    'Intensity Distribution',   'darkorange',   df_good_fits, 
            50,  list_limits[8], list_limits[9]),
            ('fit_gamma2', 'Width (fit_gamma2)',    'Width Distribution (all)', 'gold', df_fitting_result, 
            1,  list_limits[10], list_limits[11]),
            ('fit_bl', 'Baseline (fit_bl)',     'Baseline Distribution', 'seagreen', df_good_fits, 
            5, list_limits[12], list_limits[13]),
            ('fit_r2', 'R² (fit_r2)',           'R² Distribution',      'dodgerblue', df_good_fits, 
            0.01,  list_limits[14], list_limits[15]),
            ('fit_r2', 'R² (fit_r2, all)',      'R² Distribution (all)', 'mediumpurple', df_fitting_result, 
            0.05,  list_limits[16], list_limits[17])]
            
        print('Start from here next time. 2025-0602')
    else:
        raise ValueError(f'Please check if your fitting result is compatible with this visualization function.')
    
    #[6] Set stat_data.
    stat_data = {'Metric': ['Mean', 'STD', 'Max', 'Min']}

    # [7] Iterate through plots
    for i, (col, xlabel, title, color, df, bin_width, x_min, x_max) in enumerate(plot_metadata):
        # [8] Check if column exists
        if col not in df.columns:
            print(f"Column '{col}' not found in DataFrame. Skipping.")
            continue
        
        #[9] Skip empty data.
        values = pd.to_numeric(df[col], errors='coerce').dropna()
        if values.empty:
            print(f"Column '{col}' has no valid data. Skipping.")
            continue
        
        # [10] Histogram
        row_idx, col_idx = divmod(i, 3)
        if row_idx >= len(axes):  # Ensure we don't exceed the subplot grid
            raise ValueError(f"Subplot {i}, exceeds the subplot grid. ({col} at col {col_idx} row {row_idx}.)")
        
        #print(f'-- Plotting: {col} at col {col_idx} row {row_idx}.')
        
        # [9] Calculate statistics
        mean_v = values.mean()
        std_v = values.std()
        max_v = values.max()
        min_v = values.min()

        n, bins, patches = axes[row_idx][col_idx].hist(values, bins=compute_bins_by_width(values, bin_width), 
                                           color=color, alpha=alpha_v, rwidth=rwidth_v)
        axes[row_idx][col_idx].set_title(title, fontsize=fs_subtitle)
        axes[row_idx][col_idx].set_ylabel('Count', fontsize=fs_axis)
        axes[row_idx][col_idx].set_xlabel(xlabel, fontsize=fs_axis)
        axes[row_idx][col_idx].tick_params(axis='both', labelsize=fs_tick)
        axes[row_idx][col_idx].yaxis.set_major_locator(MaxNLocator(integer=True))
        
        #[11] Set axis limits.
        axes[row_idx][col_idx].set_ylim(top=1.4 * max(n))
        axes[row_idx][col_idx].set_xlim(left=x_min, right=x_max)
        
        #[12] Summary text
        text_plot = f'avg = {mean_v:.2f}\nstd = {std_v:.2f}\n({min_v:.2f} ~ {max_v:.2f})'
        add_text_in_plot_with_new_line_and_tab(axes[row_idx][col_idx], 0.02, 1.06, text_plot,
                                               linespace, ft_size, ft_color, ft_family)

        #[13] Store stats
        stat_data.setdefault(xlabel, []).extend([mean_v, std_v, max_v, min_v])

    # [15] Collect statistics into a DataFrame
    df_fitting_stat = pd.DataFrame(stat_data)

    # [16] Adjust layout 
    plt.suptitle(plot_title, fontsize=fs_title)
    plt.tight_layout(rect=[0, 0, 1, 0.9]) 
    plt.subplots_adjust(top=0.92)
    
    #[18] Optionally save the figure
    if path_save is not None:
        plt.savefig(path_save)
        plt.close()
        print(f'-- Plot saved to {path_save}')
    else:
        plt.show()
    
    #[20] Get useful stat.
    list_fitting_stat_mean = df_fitting_stat[df_fitting_stat['Metric'] == 'Mean'].iloc[0, 1:].tolist()
    list_fitting_stat_std = df_fitting_stat[df_fitting_stat['Metric'] == 'STD'].iloc[0, 1:].tolist() 
    return df_fitting_stat, list_fitting_stat_mean, list_fitting_stat_std

