#[5] Mapping visualization - Start.


def plot_mapping_visualization(dir_mapping_vis, df_fitting_result, 
                               peak_range, list_limits_mapping):
    """
    column_titles = ['loc_x', 'loc_y', 'fit_pos', 'fit_int', 'fit_xFWHM', 'fit_bl', 'fit_r2']
    Except for loc_x and loc_y, plot other as cmap='viridis'
    Use for loop to plot and save the image.
    Note: xFWHM" means it is not FWHM. For Gaussian, it is the sigma; for Lorentzian, it is gamma.
    We need to multiply it by coeff_sigma_or_gamma_to_FWHM to convert xFWHM to FWHM.
    """

    #[1] Font sizes for better visibility
    fs_title, fs_axis, fs_tick, fs_cbar = 32, 28, 24, 20  
    plt.figure(figsize=(8, 8))
    
    #[3] Except for loc_x and loc_y.
    peak_start, peak_end = M3PFF.unpack_peak_range(peak_range)
    column_titles = df_fitting_result.columns.tolist()[2:]
    print(f'[plot_mapping_visualization]\n df_fitting_result.columns: {df_fitting_result.columns}')        
    #df_fitting_result['fit_xFWHM'] *= coeff_sigma_or_gamma_to_FWHM

    #[4] Loop through each column to plot
    for i, i_col_title in enumerate(column_titles):
        i_path_save = os.path.join(dir_mapping_vis, f'{i:02d}_{i_col_title}.png')

        #[5] Create a new figure for each plot
        plt.figure(figsize=(8, 8))
        plt.title(f'{i_col_title} Mapping', fontsize=fs_title)

        #[6] Create a pivot table to reshape the data
        pivot_table = df_fitting_result.pivot(index='loc_y', columns='loc_x', values=i_col_title)
        
        #[7] Ensure numeric values and fill missing values
        pivot_table = pivot_table.astype(float).fillna(0)

        #[8] Plot the data
        im = plt.imshow(pivot_table, cmap='viridis', origin='upper', aspect='equal')
        cbar = plt.colorbar(im, fraction=0.04, pad=0.01)
        cbar.ax.yaxis.set_tick_params(labelsize=fs_cbar)

        #[9] Set color bar limits based on column
        # list_limits_mapping = [loc_min, loc_max, int_min, int_max, width_min, width_max, bl_min, bl_max, r2_min, r2_max]
        if i_col_title == 'fit_pos':
            im.set_clim(list_limits_mapping[0], list_limits_mapping[1])

        elif i_col_title == 'fit_int':
            im.set_clim(list_limits_mapping[2], list_limits_mapping[3])

        elif i_col_title in ['fit_xFWHM', 'fit_sigma', 'fit_gamma']:
            im.set_clim(list_limits_mapping[4], list_limits_mapping[5])
        
        elif i_col_title == 'fit_bl':
            im.set_clim(list_limits_mapping[6], list_limits_mapping[7])

        elif i_col_title == 'fit_r2':
            im.set_clim(list_limits_mapping[8], list_limits_mapping[9])
        
        #[11] Figure settings.
        plt.xlabel('coord_x', fontsize=fs_axis)
        plt.ylabel('coord_y', fontsize=fs_axis)
        plt.xticks(fontsize=fs_tick)
        plt.yticks(fontsize=fs_tick)
        
        #[12] Save the figure
        plt.tight_layout()
        plt.savefig(i_path_save)
        plt.close()






def plot_scatter_graph_for_pos_int_FWHM(list_df_fitting_result, list_data_title, list_limits_scatter,
                                        coeff_sigma_or_gamma_to_FWHM, R2_thr,
                                        plot_title, path_save=None):
    """
    column_titles in df_fitting_result:
    ['loc_x', 'loc_y', 'fit_pos', 'fit_int', 'fit_xFWHM', 'fit_bl', 'fit_r2']
    R2_thr = 0.8 usually.
    """
    print(f'\n[plot_scatter_graph_for_pos_int_FWHM]')
    #[1] Input validation
    cnt_df_set = len(list_df_fitting_result)
    if cnt_df_set not in [1, 2, 3, 4]:
        raise ValueError("Only 1 ~ 4 datasets are supported.")
    if cnt_df_set != len(list_data_title):
        raise ValueError("Mismatch between number of datasets and titles.")
    
    #[2] Create figure and 3D axis
    fig = plt.figure(figsize=(10, 10))
    ax = fig.add_subplot(111, projection='3d')
    fs_axis = 14
    fs_title = 16
    alpha_v = 0.3
    
    #[8] Iterate through datasets to plot.
    df_set_colors = ['orangered', 'seagreen', 'dodgerblue', 'purple'] 
    #colors = ['seagreen', 'dodgerblue', 'orangered', 'purple'] 
    markers = ['o', '^', 's', 'D']
    for idx, (i_df, i_title) in enumerate(zip(list_df_fitting_result, list_data_title)):
        df_scatter = i_df[i_df['fit_r2'] > R2_thr]
        print(f'-- Plotting {i_title} ... \n{tabulate(df_scatter.head(), headers="keys", tablefmt="orgtbl")}')
        if df_scatter.empty:
            print(f"Filtered dataframe {idx+1} is empty. Skipping.")
            continue
        
        #[9] Extract data, convert xFWHM, scale the marker size.
        xs = df_scatter['fit_pos'].values
        ys = df_scatter['fit_int'].values
        zs = df_scatter['fit_xFWHM'].values * coeff_sigma_or_gamma_to_FWHM
        rs = df_scatter['fit_r2'].values
        rs_scaled = (rs - R2_thr) * 2000 + 10
        
        #[10] Plot the scatter graph
        ax.scatter(xs, ys, zs, s=rs_scaled, c=df_set_colors[idx], marker=markers[idx], label=i_title, alpha=alpha_v)    

    #[12] Set labels and title
    ax.set_xlabel('Position (x₀)', fontsize=fs_axis)
    ax.set_ylabel('Intensity (A)', fontsize=fs_axis)
    ax.set_zlabel('Width (FWHM)', fontsize=fs_axis)
    ax.set_title(plot_title, fontsize=fs_title)
    
    #[12]
    if list_limits_scatter is not None:
        ax.set_xlim(list_limits_scatter[0], list_limits_scatter[1])
        ax.set_ylim(list_limits_scatter[2], list_limits_scatter[3])
        ax.set_zlim(list_limits_scatter[4], list_limits_scatter[5])
    
    #[15] Add legend
    ax.legend(loc='lower left')
    
    #[15] Optionally save the figure
    plt.tight_layout()
    if path_save is not None:
        plt.savefig(path_save)
        plt.close()
        print(f'-- Plot saved to {path_save}')
    else:
        plt.show()
    
    
    return fig, ax









def plot_boxplot_for_pos_int_FWHM(list_df_fitting_result, list_data_title, list_limits_scatter,
                                        coeff_sigma_or_gamma_to_FWHM, R2_thr, h_or_v_layout,
                                        plot_title, path_save):
    """
    column_titles in df_fitting_result:
    ['loc_x', 'loc_y', 'fit_pos', 'fit_int', 'fit_xFWHM', 'fit_bl', 'fit_r2']
    R2_thr = 0.8 usually.
    """
    print(f'\n[plot_boxplot_for_pos_int_FWHM]')
    
    # [1] Input validation
    cnt_df_set = len(list_df_fitting_result)
    if cnt_df_set not in [1, 2, 3, 4]:
        raise ValueError("Only 1 ~ 4 datasets are supported.")
    if cnt_df_set != len(list_data_title):
        raise ValueError("Mismatch between number of datasets and titles.")
    
    # [2] Filter datasets based on R2 threshold
    list_df_fitting_result = [i_df[i_df['fit_r2'] > R2_thr] for i_df in list_df_fitting_result]
    
    # [3] Extract data for boxplots
    pos_data = [i_df['fit_pos'].dropna() for i_df in list_df_fitting_result]
    int_data = [i_df['fit_int'].dropna() for i_df in list_df_fitting_result]
    xFWHM_data = [i_df['fit_xFWHM'].dropna() * coeff_sigma_or_gamma_to_FWHM for i_df in list_df_fitting_result]
    
    # [4] Define metadata for plotting
    plot_metadata = [
        ('fit_pos', 'Position (fit_pos)', 'Position Distribution', pos_data, 
         list_limits_scatter[0], list_limits_scatter[1]),
        ('fit_int', 'Intensity (fit_int)', 'Intensity Distribution', int_data, 
         list_limits_scatter[2], list_limits_scatter[3]),
        ('fit_xFWHM', 'Width (fit_xFWHM)', 'Width Distribution', xFWHM_data, 
         list_limits_scatter[4], list_limits_scatter[5])]
    
    # [5] Create figure and axes
    if h_or_v_layout == 'h':
        fig, axes = plt.subplots(1, 3, figsize=(15, 6))
        fs_suptitle, fs_subtitle, fs_axis, fs_tick, fs_legend = 24, 24, 22, 20, 12
    elif h_or_v_layout == 'v':
        fig, axes = plt.subplots(3, 1, figsize=(6, 18))
        fs_suptitle, fs_subtitle, fs_axis, fs_tick, fs_legend = 26, 24, 22, 20, 12
    else:
        raise ValueError(f'h_or_v_layout should be "h" or "v", received {h_or_v_layout}.')
    df_set_colors = ['orangered', 'seagreen', 'dodgerblue', 'purple']
    horizontal_legend_for_h_layout = False
    
    # [6] Iterate through plot_metadata and create boxplots
    for i, (col, xlabel, title, data, y_min, y_max) in enumerate(plot_metadata):
        ax = axes[i]
        boxplots = ax.boxplot(data, patch_artist=True, showfliers=False)
        
        # [7] Color each box according to dataset colors
        for patch, color in zip(boxplots['boxes'], df_set_colors[:cnt_df_set]):
            patch.set_facecolor(color)
            patch.set_edgecolor(color)
        
        # [8] Customize median, whiskers, and caps
        for median in boxplots['medians']:
            median.set(color='lightgray', linewidth=2)
        for whisker in boxplots['whiskers']:
            whisker.set(color='black')
        for cap in boxplots['caps']:
            cap.set(color='black')
        
        # [9] Set titles, labels, and axis limits
        ax.set_title(title, fontsize=fs_subtitle)
        ax.set_xlabel(xlabel, fontsize=fs_axis)
        ax.set_ylabel('Values', fontsize=fs_axis)
        ax.tick_params(axis='both', labelsize=fs_tick)
        ax.set_ylim(y_min, y_max)
    
    # [11] Add legend 
    legend_labels = [f"{i + 1}. {list_data_title[i]}" for i in range(cnt_df_set)]
    legend_handles = [plt.Line2D([0], [0], color=df_set_colors[i], lw=4) for i in range(cnt_df_set)]
    # [12] Lower center, horizontally
    if h_or_v_layout == 'h':
        if horizontal_legend_for_h_layout:
            fig.legend(legend_handles, legend_labels, loc='lower center', fontsize=fs_legend, 
                       frameon=False)
            plt.suptitle(plot_title, fontsize=fs_suptitle)
        # [13] Upper right, vertically
        else:
            fig.legend(legend_handles, legend_labels, loc='upper right', fontsize=fs_legend, bbox_to_anchor=(1.0, 1.0), 
                       frameon=False)
            plt.suptitle(plot_title, fontsize=fs_suptitle, x=0.02, y=0.97, ha='left')
    #[15] Vertical plot only put legand at the bottom center vertically.
    else:
        fig.legend(legend_handles, legend_labels, loc='lower center', fontsize=fs_legend, bbox_to_anchor=(0.5, 0.009), 
                       frameon=False)
        plot_title = plot_title.replace('Comparison', 'Comparison\n')
        plt.suptitle(plot_title, fontsize=fs_suptitle)
           
    # [16] Adjust layout.
    if h_or_v_layout == 'h':
        plt.tight_layout(rect=[0.01, 0.01, 0.99, 0.99])
        plt.subplots_adjust(top=0.75, wspace=0.4)
    else:
        plt.tight_layout(rect=[0.01, 0.01, 0.99, 0.99])
        plt.subplots_adjust(top=0.91, bottom=0.12)
    
    #[18] Optionally save the figure.
    if path_save is not None:
        plt.savefig(path_save)
        plt.close()
        print(f'-- Plot saved to {path_save}')
    else:
        plt.show()
    







def generate_circular_view_init(elve_azim_center, elve_azim_start, cnt_point, clockwise=True):
    """
    Default: elev=30 and azim=-60
    elve_start -> elve_min -> elve_center -> elve_max -> elve_start
    azim_start -> azim_center -> azim_max -> azim_center -> azim_start
    
    elve_azim_center = (30, 40) # Center elevation and azimuth
    elve_azim_start = (30, 70) # Start elevation and azimuth
    
    """
    elve_center, azim_center = elve_azim_center
    elve_start, azim_start = elve_azim_start
    #[1] Calculate the angular distances
    delta_elve = elve_start - elve_center
    delta_azim = azim_start - azim_center
    #[2] Determine the direction of rotation
    direction = 1 if clockwise else -1
    #[3] Calculate the step size for a full circle
    angle_step = 360 / cnt_point
    view_init_list = []
    for i in range(cnt_point):
        #[4] Calculate the new angle
        angle = i * angle_step * direction
        rad_angle = np.radians(angle)
        #[5] Calculate the new positions
        elve = elve_center + delta_elve * np.cos(rad_angle) - delta_azim * np.sin(rad_angle)
        azim = azim_center + delta_elve * np.sin(rad_angle) + delta_azim * np.cos(rad_angle)
        view_init_list.append([int(elve), int(azim)])
    view_init_list = view_init_list[:-1]  # Remove the last viewpoint that duplicate with the first viewpoint.
    return view_init_list





def convert_plot_to_gif(fig, ax, list_view_init, path_save, duration=100):
    """
    Converts a 3D Matplotlib plot to a GIF by rotating the plot using predefined view angles.
    Parameters:
    - fig: Matplotlib figure object.
    - ax: Matplotlib 3D axis object.
    - list_view_init: List of tuples/lists containing (elevation, azimuth) angles.
    - filename: Name of the output GIF file.
    - duration: Duration of each frame in the GIF in milliseconds.
    """
    print(f'\n[convert_plot_to_gif]')
    def update_view(angle):
        ax.view_init(elev=angle[0], azim=angle[1])
        return fig,
    #[2] Create an animation
    anim = FuncAnimation(fig, update_view, frames=list_view_init, blit=False, repeat=True)
    #[3] Save animation as GIF
    anim.save(path_save, writer='pillow', fps=1000/duration)








def plot_boundary_check(df_log, path_save=None):
    print('\n[plot_boundary_check]')

    #[1] Filter relevant columns (excluding 'Title' and 'R²')
    fs_title, fs_axis, fs_tick, fs_num = 16, 14, 12, 10
    param_cols = [col for col in df_log.columns if col not in ['Title', 'R²']]
    y_labels = param_cols
    y_pos = np.arange(len(y_labels))
    fig_high = int(len(df_log.columns)/2 * 1.2)
    fig, ax = plt.subplots(figsize=(10, fig_high))

    for i, col in enumerate(param_cols):
        try:
            lower = float(df_log.loc[df_log['Title'] == 'Lower Bounds', col].values[0])
            upper = float(df_log.loc[df_log['Title'] == 'Upper Bounds', col].values[0])
            guess = float(df_log.loc[df_log['Title'] == 'Initial Guess', col].values[0])
            fit   = float(df_log.loc[df_log['Title'] == 'Fitting Result', col].values[0])
        except Exception as e:
            print(f"Skipping column '{col}' due to conversion error: {e}")
            continue

        #[2] Normalize to [0, 1] for plotting
        def norm(val): return (val - lower) / (upper - lower) if upper != lower else 0.5
        x_guess = norm(guess)
        x_fit = norm(fit)

        #[3] Draw horizontal line between bounds
        ax.hlines(y=i, xmin=0, xmax=1, color='lightgray', linewidth=1)

        #[4] Draw vline for lower and upper bound, and show value
        ax.vlines(x=0, ymin=i - 0.2, ymax=i + 0.2, color='black', linewidth=1)
        if 'sigma' in col.lower() or 'gamma' in col.lower():
            ax.text(-0.02, i, f"{lower:.3e}", ha='right', va='center', fontsize=fs_num)
        else:
            ax.text(-0.02, i, f"{lower:.3f}", ha='right', va='center', fontsize=fs_num)
        ax.vlines(x=1, ymin=i - 0.2, ymax=i + 0.2, color='black', linewidth=1)
        ax.text(1.18, i, f"{upper:.3f}", ha='right', va='center', fontsize=fs_num)

        #[4] Draw yellow triangle for initial guess, and show value
        ax.plot(x_guess, i, marker='^', color='orange', markersize=fs_num, label='Initial Guess' if i == 0 else "")
        ax.text(x_guess, i - 0.08, f"{guess:.3f}", ha='center', va='bottom', fontsize=10, color='black')  # Text above the triangle

        #[5] Draw green circle for fitted result, and show value
        ax.plot(x_fit, i, marker='o', color='green', markersize=fs_num, label='Fitting Result' if i == 0 else "")
        if 'sigma' in col.lower() or 'gamma' in col.lower():
            ax.text(x_fit, i + 0.15, f"{fit:.3e}", ha='center', va='top', fontsize=10, color='black')
        else:
            ax.text(x_fit, i + 0.15, f"{fit:.3f}", ha='center', va='top', fontsize=10, color='black')

    #[6] Formatting
    bsn = os.path.splitext(os.path.basename(path_save))[0] if path_save else None
    text_title = f"Relative Positions of Initial Guess and Fitting Result {f'({bsn})' if bsn else ''}"
    ax.set_yticks(y_pos)
    ax.set_yticklabels(y_labels, fontsize=fs_tick-4)
    ax.set_xlim(-0.2, 1.2)
    ax.set_xticks([0, 0.5, 1.0])
    ax.set_xticklabels(['Lower Bound', 'Midpoint', 'Upper Bound'], fontsize=fs_tick)
    ax.set_xlabel("Parameter Range (Normalized)", fontsize=fs_axis)
    ax.set_ylabel("Fitting\nParameters", fontsize=fs_axis)
    ax.set_title(text_title, fontsize=fs_title)
    ax.invert_yaxis()
    ax.grid(True, axis='x', linestyle='--', alpha=0.5)
    ax.legend(loc='lower right', bbox_to_anchor=(0.0, 0.95), framealpha=0.5)

    plt.tight_layout(rect=[0.02, 0, 0.98, 1])
    
    #[15] Optionally save the figure
    if path_save is not None:
        plt.savefig(path_save)
        plt.close()
        print(f'-- Plot saved to {path_save}')
    else:
        plt.show()
    return











