import subprocess, threading
import tkinter as tk
from tkinter import filedialog
import os

def run_python_file_after_button_click(root, entry_filepath, terminal_output, path_py, *args):
    global current_process
    def run_subprocess():
        global current_process
        filepath_working = entry_filepath.get() if 'dir_working' in args else None          
        if 'dir_working' in args and not filepath_working:
            terminal_output.insert(tk.END, "Error: Please specify a working directory.\n")      
            terminal_output.see(tk.END)                        
            root.update()                                   
            return
        
        if not path_py:
            terminal_output.insert(tk.END, "Error: Python script path is empty.\n")
            terminal_output.see(tk.END)
            root.update()
            return
        
        if not os.path.isfile(path_py):
            terminal_output.insert(tk.END, f"Error: Python script not found at {path_py}.\n")
            terminal_output.see(tk.END)
            root.update()
            return

        try:
            command = ["python", path_py]
            if filepath_working:
                command.append(filepath_working)
            
            terminal_output.delete(1.0, tk.END)
            text_opening = f'Starting the python file {path_py} with parameters: {args}. \nMight take a few seconds to start the subprocess. Please wait.\n\n'
            terminal_output.insert(tk.END, text_opening)
            terminal_output.see(tk.END)
            root.update()

            current_process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            
            while current_process.poll() is None:
                line = current_process.stdout.readline()
                if not line:
                    break
                terminal_output.insert(tk.END, line)
                terminal_output.see(tk.END)
                root.update()
            
            stdout, stderr = current_process.communicate()
            if stdout:
                terminal_output.insert(tk.END, stdout)
            if stderr:
                terminal_output.insert(tk.END, f"Errors:\n{stderr}\n")
            terminal_output.see(tk.END)
        except Exception as e:
            terminal_output.insert(tk.END, f"Error running the Python file: {str(e)}\n")
            terminal_output.see(tk.END)
        finally:
            current_process = None
    
    thread = threading.Thread(target=run_subprocess)
    thread.start()

def terminate_subprocess_on_close(root, current_process):
    if current_process and current_process.poll() is None:
        current_process.terminate()
        current_process = None
    root.destroy()

def browse_directory(tk_lable):
    dir_selected = filedialog.askdirectory()
    if dir_selected:
        tk_lable.delete(0, tk.END)
        tk_lable.insert(0, dir_selected)

def browse_file(tk_lable):
    file_selected = filedialog.askopenfilename(filetypes=[("Text files", "*.txt"), ("All files", "*.*")])
    if file_selected:
        tk_lable.delete(0, tk.END)
        tk_lable.insert(0, file_selected)

