def save_dict_as_txt(dict_obj, path_txt):
    with open(path_txt, 'w') as file:
        for key, value in dict_obj.items():
            file.write(f"{key}:{value}\n")
    return path_txt



def relocate_single_file(i_old_path, dir_new):
    file_name = os.path.basename(i_old_path)
    destination_path = os.path.join(dir_new, file_name)

    #[2] Move the file and handle potential naming conflicts
    try: 
        shutil.move(i_old_path, destination_path)
        
    #[3] Handle the cases if file already exists.
    except shutil.Error:
        bsn_ext = os.path.splitext(file_name)
        suffix = 1
        new_file_name = f'{bsn_ext[0]}_dup{suffix}{bsn_ext[1]}'
        new_destination_path = os.path.join(dir_new, new_file_name)

        while os.path.exists(new_destination_path):
            suffix += 1
            new_file_name = f'{bsn_ext[0]}_dup{suffix}{bsn_ext[1]}'
            new_destination_path = os.path.join(dir_new, new_file_name)

        shutil.move(i_old_path, new_destination_path)


def list_path_files_relocate(list_path, dir_dest):
    #[1] Make directory
    make_dir_if_not_exist(dir_dest)
    #[2] Iterate through the file list to move files
    for i_path in list_path:
        relocate_single_file(i_path, dir_dest)


def relocate_single_folder(dir_original, dir_destination_parent, delete_original=True):
    """
    Relocate all files from a folder to a new directory. 
    If the destination directory does not exist, it will be created.
    """
    print(f'\n[relocate_single_folder] dir_original = {dir_original}')
    
    #[1] Check if the directory exists
    if not os.path.isdir(dir_original):
        raise FileNotFoundError(f'The directory {dir_original} was not found.')
    
    #[2] Get the list of files in the directory
    list_files = [os.path.join(dir_original, file) for file in os.listdir(dir_original) if os.path.isfile(os.path.join(dir_original, file))]
    
    #[3] Create a new directory to move the files
    dir_new = os.path.join(dir_destination_parent, os.path.basename(dir_original))
    make_dir_if_not_exist(dir_new)
    
    #[4] Relocate files to the new directory
    list_path_files_relocate(list_files, dir_new)
    
    #[5] Optionally delete the original folder if specified
    if delete_original:
        try:
            os.rmdir(dir_original)
            print(f'-- Original folder {dir_original} deleted.')
        except OSError:
            print(f'-- Could not delete {dir_original}. Ensure it is empty or not in use.')
    
    #[6] Final report
    print(f'-- Finished relocating {len(list_files)} files from {dir_original} to {dir_new}.')
    return dir_new



def rank_file_by_date_and_select_only_last_few(list_dirs, keep_only=20, print_bsn=False):
    """
    Sort a list of directory names based on the datetime pattern at the end of each string,
    and return the latest `last_cnt` entries.

    Example input:
    ['[002]_P01_(0,2)_2025-0503-0035', '[009]_P01_(1,4)_2025-0502-1955', '[009]_P01_(1,4)_2025-0502-1957']

    Returns the most recent entries sorted by datetime.
    """
    def extract_datetime(s):
        match = re.search(r'(\d{4}-\d{4}-\d{4})', s)
        if not match:
            return datetime.min  # fallback for invalid entries
        try:
            return datetime.strptime(match.group(1), "%Y-%m%d-%H%M")
        except ValueError:
            return datetime.min
    #[1] Sort the list based on extracted datetime
    sorted_list = sorted(list_dirs, key=extract_datetime, reverse=True)
    
    #[2] Keep only the specified number of entries
    list_dirs_selected = sorted_list[:keep_only]
    list_dirs_not_selected = sorted_list[keep_only:]
    
    #[3] Extract base names for printing
    list_bsns_selected = [os.path.basename(dir_path) for dir_path in list_dirs_selected]
    list_bsns_not_selected = [os.path.basename(dir_path) for dir_path in list_dirs_not_selected]
    
    if print_bsn:
        print(f'\n--  Selected directories: \n{list_bsns_selected}', end='\n\n')
        print(f'\n--  Not selected directories: \n{list_bsns_not_selected}', end='\n\n')
    
    return list_dirs_selected, list_bsns_selected, list_dirs_not_selected, list_bsns_not_selected


