def compute_figsize_from_image_size(h, w, dpi_v=100):
    """
    1. Compute figsize from image size.
    2. dpi: dots per inch.
    """
    fig_width = w // dpi_v
    fig_height = h // dpi_v
    fig_chart = min(fig_width, fig_height) * 0.3
    return fig_width, fig_height, fig_chart




def open_image_and_average_col_and_row(path_img):
    """
    1. Open image, convert to grayscale, average columns and rows into avg_cols, and avg_rows.
    """  
    #[2] Read image, grayscale, average.
    dpi_v = 100
    arrimg = cv2.imread(path_img)
    h, w = arrimg.shape[:2]
    print(f'\n[open_image_and_average_col_and_row] arrimg.shape = {arrimg.shape}')
    fig_width, fig_height, fig_chart = compute_figsize_from_image_size(h, w, dpi_v)
    gray = cv2.cvtColor(arrimg, cv2.COLOR_BGR2GRAY)
    mean_cols = np.mean(gray, axis=0)
    mean_rows = np.mean(gray, axis=1)
    
    #[1] Plot color intensity.
    arrimg_h = M4V.plot_color_intensity(mean_cols, 'h', (fig_width, fig_chart), dpi_v)
    arrimg_v = M4V.plot_color_intensity(mean_rows, 'v', (fig_height, fig_chart), dpi_v)
    
    return mean_cols, mean_rows, arrimg


def determine_where_to_cut(arr_mean, thrs=250, pad=2):
    """
    Create arr_keep of zeros with the same shape as arr_mean.
    If the value of arr_mean is greater than thrs, set it 0, else set it 1.
    In a for loop, if continuous 1s are longer than min_keep_width, record the index.
    For a given array, find the first and last index of 1.
    list_sec_idx will have a format of [[1_sec_start, 1_sec_end], [2_sec_start, 2_sec_end], ...]
    """
    #[1] Create arr_keep of zeros with the same shape as arr_mean.
    arr_keep = np.where(arr_mean > thrs, 0, 1)

    # [2] Initialize list to store section indices.
    list_sec_idx = []
    first_index = None

    # [3] Iterate through arr_keep to find the start and end indices of each section.
    for i in range(len(arr_keep)):
        if arr_keep[i] == 1:
            #[4] Start of a new section.
            if first_index is None:
                first_index = max(0, i - pad)  # Ensure index is not negative.
        elif arr_keep[i] == 0:
            #[5] End of a section.
            if first_index is not None:
                last_index = min(len(arr_keep), i + pad)  # Ensure index is within bounds.
                list_sec_idx.append([first_index, last_index])
                first_index = None  # Reset for the next section.

    # [6] Handle case where the array ends with a section to keep.
    if first_index is not None:
        last_index = min(len(arr_keep), len(arr_keep) + pad)
        list_sec_idx.append([first_index, last_index])

    return list_sec_idx



def generate_cut_visualization_array(mean_cols_or_rows, list_sec_idx):
    """
    Generate a visualization array for the sections to cut from the image.
    arr_cut_vis should have the same length as arr_img.
    For each section in list_sec_idx, set the corresponding rows in arr_cut_vis to 255.
    """
    arr_cut_vis = np.zeros_like(mean_cols_or_rows)
    for i_sec in list_sec_idx:
        start, end = i_sec
        arr_cut_vis[start:end] = 255
    return arr_cut_vis



def cut_image_into_sections(list_arrimg_tobecut, list_sec_idx, cutting_direction='v'):
    """
    Cut the image into sections based on the provided indices.
    list_arrimg_tobecut is a list of arrimgs to be cut.
    list_sec_idx will have a format of [[1_sec_start, 1_sec_end], [2_sec_start, 2_sec_end], ...]
    If min(arrimg_cut.shape) < 3, skip the image.
    """
    print(f'\n[cut_image_into_sections] Number of images: {len(list_arrimg_tobecut)}, First image size: {list_arrimg_tobecut[0].shape}')
    list_arrimg_cut = []
    # [1] Iterate through list_arrimg_tobecut to cut the image into sections.
    for i, arrimg in enumerate(list_arrimg_tobecut):
        # [2] Iterate through list_sec_idx to cut the image into sections.
        for j, i_sec in enumerate(list_sec_idx):
            start, end = i_sec
            # [3] Append the sliced section of the image to the list.
            if cutting_direction == 'v':
                arrimg_cut = arrimg[:, start:end]
            else:
                arrimg_cut = arrimg[start:end]
                
            #[4] Skip if the cut image is too small.
            if min(arrimg_cut.shape) < 3:
                continue
            list_arrimg_cut.append(arrimg_cut)
            print(f'Image {i}, Sec{j}, Size: {arrimg_cut.shape}')
    return list_arrimg_cut



def save_cut_images(list_arrimg_cut,  list_sec_idx_col, list_sec_idx_row, 
                    batch_label, dir_save):
    #[1] Count index range horizontally and vertically.
    len_row = len(list_sec_idx_row)
    len_col = len(list_sec_idx_col)
    
    #[3] Iterate through the list of cut images and save each one.
    for i, i_arrimg_cut in enumerate(list_arrimg_cut):
        # [4] Determine the section index for the current image.
        idx_row = i // len_col
        idx_col = i % len_col
        
        # [5] Create a filename for the cut image.
        bsn_img = f'P{batch_label}_({idx_row},{idx_col}).png'
        path_save = os.path.join(dir_save, bsn_img)
        
        # [6] Save the cut image.
        print(f'--Saving cut image: {bsn_img}, size = {i_arrimg_cut.shape}')
        cv2.imwrite(path_save, i_arrimg_cut)
        
    #[7] Clean up.
    del i_arrimg_cut, list_arrimg_cut
    gc.collect()










