def analyze_pallet_image_color(arrimg):
    """
    Analyze the color palette of an image.
    """
    # [1] Reduce the image size to around 2000 to 3000 pixels.
    h, w, _ = arrimg.shape
    target_pixels = 2500
    
    #[2] Resize the image if it exceeds the target size.
    if h * w > target_pixels:
        scale_factor = (target_pixels / (h * w)) ** 0.5
        new_h, new_w = int(h * scale_factor), int(w * scale_factor)
        arrimg = cv2.resize(arrimg, (new_w, new_h), interpolation=cv2.INTER_AREA)

    # [2] Flatten the image array and count color occurrences.
    pixels = arrimg.reshape(-1, 3)  # Flatten to a list of RGB values.
    color_counts = Counter(map(tuple, pixels))  # Count occurrences of each color.
    
    #[3] Set the color with max occurrences as reference.
    occ_thres = max(color_counts.values()) * 0.5 

    # [3] Get the colors that have more than occ_thres occurrences.
    dominant_colors = [color for color, count in color_counts.items() if count > occ_thres]

    # [4] Convert colors to RGB and HEX formats.
    list_RGB = [f'{color[0]}, {color[1]}, {color[2]}' for color in dominant_colors]
    list_HEX = [f'#{color[0]:02x}{color[1]:02x}{color[2]:02x}' for color in dominant_colors]

    return list_RGB, list_HEX




