def plot_color_intensity(arr_1D_color, h_or_v, figsize_v=None, dip_v=100):
    """
    1. Plot color intensity of arr_1D_color.
    2. h_or_v: 'h' for horizontal, 'v' for vertical.
    """
    print(f'\n[plot_color_intensity] arr_1D_color.shape = {arr_1D_color.shape}')
    # [1] Process size
    if (figsize_v is None) or (dip_v is None):
        fig = plt.figure(figsize=(10, 5), dpi=dip_v)
    else:
        fig = plt.figure(figsize=figsize_v, dpi=dip_v)
    
    # [2] Settings
    canvas = FigureCanvas(fig)
    ax = plt.gca()
    
    # [3] Plot data
    if h_or_v == 'h':
        plt.plot(arr_1D_color, color='gray')
    elif h_or_v == 'v':
        arr_1D_color = np.transpose(arr_1D_color)
        plt.plot(arr_1D_color, color='gray')
    else:
        raise ValueError("h_or_v must be either 'h' or 'v'.")
    
    # [4] Configure scientific notation for y-axis
    ax.set_ylim(0, 260)
    
    # [5] Apply tight layout
    plt.tight_layout()
    
    # [6] Render the plot to a NumPy array
    canvas.draw()
    width, height = canvas.get_width_height()
    arrimg = np.frombuffer(canvas.tostring_rgb(), dtype='uint8').reshape(height, width, 3)
    plt.close(fig)  # Close the figure to free memory
    return arrimg




