def plot_color_int_and_concatenate_images(list_mean_cols, list_mean_rows, arrimg_main, path_save=None):
    """
    1. Concatenate arrimg_h at the bottom of arrimg_main.
    2. Rotate arrimg_v 90 degrees clockwise.
    3. Concatenate arrimg_v at the left of arrimg_main.
    4. Adjust sizes by adding white padding to the smaller image.
    """
    #[1] Settings
    dpi_v = 100
    
    #[3] Get dimensions of all images
    h_main, w_main = arrimg_main.shape[:2]
    fig_width, fig_height, fig_chart = M2D.compute_figsize_from_image_size(h_main, w_main, dpi_v)
    arrimg_h = plot_color_intensity_list_of_arr(list_mean_cols, 'h', (fig_width, fig_chart), dpi_v)
    arrimg_v = plot_color_intensity_list_of_arr(list_mean_rows, 'v', (fig_height, fig_chart), dpi_v)
    arrimg_v_rotated = np.rot90(arrimg_v, k=-1)
    h_horiz, w_horiz = arrimg_h.shape[:2]
    h_vert_rot, w_vert_rot = arrimg_v_rotated.shape[:2]
    
    #[4] Rotate the vertical image 90 degrees clockwise
    print(f'arrimg_main.shape = {arrimg_main.shape}')
    print(f'arrimg_h.shape = {arrimg_h.shape}')
    print(f'arrimg_v_rotated.shape = {arrimg_v_rotated.shape}')
    
    # [2] Adjust widths by padding with white columns if necessary
    if w_main < w_horiz:
        arrimg_main = np.pad(arrimg_main, ((0, 0), (0, w_horiz - w_main), (0, 0)), mode='constant', constant_values=255)
    elif w_main > w_horiz:
        arrimg_h = np.pad(arrimg_h, ((0, 0), (w_main - w_horiz, 0), (0, 0)), mode='constant', constant_values=255)

    # Concatenate arrimg_main and arrimg_h vertically
    arrimg_combined_horiz = np.concatenate((arrimg_main, arrimg_h), axis=0)
    h_combined, w_combined = arrimg_combined_horiz.shape[:2]
    print(f'arrimg_combined_horiz.shape = {arrimg_combined_horiz.shape}')

    # [3] Adjust heights by padding with white rows if necessary
    if h_combined > h_vert_rot:
        arrimg_v_rotated = np.pad(arrimg_v_rotated, ((0, h_combined - h_vert_rot), (0, 0), (0, 0)), mode='constant', constant_values=255)
    elif h_combined < h_vert_rot:
        arrimg_combined_horiz = np.pad(arrimg_combined_horiz, ((0, h_vert_rot - h_combined), (0, 0), (0, 0)), mode='constant', constant_values=255)

    # [4] Concatenate the rotated vertical image with the combined horizontal image
    arrimg_output = np.concatenate((arrimg_v_rotated, arrimg_combined_horiz), axis=1)

    #[5] Clean up memory
    del arrimg_combined_horiz, arrimg_h, arrimg_v, arrimg_main
    gc.collect()

    #[6] Optionally save the image.
    if path_save is not None:
        cv2.imwrite(path_save, arrimg_output)
        print(f'[open_image_and_sum_col_and_row] Image saved to: {path_save}')


    return arrimg_output


def putTextSmooth(image, text, org, fontFace, fontScale, color, thickness, smooth_iterations=3):
    #[1] Adjust smooth_iterations if thickness is less than 1
    if thickness == 1:
        smooth_iterations = 2
    elif thickness < 1:
        raise ValueError('Thickness must be an integer greater than or equal to 1.')
    
    for i in range(smooth_iterations):
        # Draw the text with decreasing thickness
        cv2.putText(image, text, org, fontFace, fontScale, color, thickness - i, cv2.LINE_AA)


def single_color_arrimg(Label, list_RGB_or_HEX, height_width_padding=[50, 500, 10], show_img=True):
    """
    1. Label: is a string of text less than 10 characters.
    2. list_RGB_or_HEX: is a list of RGB ('188, 108, 37') or HEX color ('#283618') strings.
    3. Show the Label as text on the left, its width is text_width.
    4. Show the color as small vertical rectangles arranged horizontally, its width is  non_text_width.
    5. The  width of each rectangle is (non_text_width - padding * 2) // num_colors.
    6. The height of each rectangle is img_height - padding * 2.
    """
    # [1] Settings.
    img_height, img_width, padding = height_width_padding
    text_width = img_width * 0.30
    non_text_width = img_width - text_width
    
    #[2] Unpack the list_RGB_or_HEX.
    if isinstance(list_RGB_or_HEX, str):
        list_RGB_or_HEX = [list_RGB_or_HEX]
    elif isinstance(list_RGB_or_HEX, list):
        if len(list_RGB_or_HEX) == 1 and isinstance(list_RGB_or_HEX[0], str):
            list_RGB_or_HEX = [list_RGB_or_HEX[0]]
    num_colors = len(list_RGB_or_HEX)
    
    
    # [3] The size of each single color rectangle.
    i_c_height = img_height - padding * 2
    i_c_width = (non_text_width - padding * 2) // num_colors
    
    # [4] Create a blank white image
    arrimg_color = np.ones((img_height, img_width, 3), dtype=np.uint8) * 255

    # [5] Draw each color as vertical rectangle
    for i, RGB_or_HEX in enumerate(list_RGB_or_HEX):
        #[6] Identify and convert color
        if RGB_or_HEX.startswith('#') and len(RGB_or_HEX) == 7:
            hex_color = RGB_or_HEX
            rgb_color = tuple(int(hex_color[i:i + 2], 16) for i in (1, 3, 5))
        elif ',' in RGB_or_HEX:
            rgb_color = tuple(map(int, RGB_or_HEX.split(',')))
            hex_color = '#{:02x}{:02x}{:02x}'.format(*rgb_color)
        else:
            raise ValueError(f"Invalid color format: {RGB_or_HEX}")

        # [9] Define rectangle corners (horizontal layout)
        top_left = (int(text_width + padding + i * i_c_width), int(padding))
        bottom_right = (int(text_width + padding + (i + 1) * i_c_width - 1), int(padding + i_c_height))

        # [11] Draw the rectangle on the image
        cv2.rectangle(arrimg_color, top_left, bottom_right, rgb_color, -1)

    # [6] Add label text at the left
    text_position = (10, img_height - 20)  # Lower left corner
    putTextSmooth(arrimg_color, Label, text_position, cv2.FONT_HERSHEY_SIMPLEX, 1.0, (32, 32, 32), 2)

    # [7] Optionally show the image
    if show_img:
        cv2.imshow('Color Palette', arrimg_color)
        cv2.waitKey(0)
        cv2.destroyAllWindows()

    return arrimg_color

def draw_df_pallet_color(df_pallet, dir_save, label_save):
    """
    1. df_pallet columns=['Label', 'list_RGB', 'list_HEX']
    2. Save the image if path_save is provided.
    3. Each set has 10 pallets. If exceed, create a new image.
    """
    # [1] Settings
    img_height, img_width, padding = 100, 1000, 5
    height_width_padding = [img_height, img_width, padding]
    img_width = 500
    max_palettes_per_image = 10

    # [2] Calculate number of sets needed
    num_palettes = len(df_pallet)
    num_set = (num_palettes + max_palettes_per_image - 1) // max_palettes_per_image 

    list_images = []  # list to hold images

    #[3] Iterate through the number of images
    for img_idx in range(num_set):
        start_idx = img_idx * max_palettes_per_image
        end_idx = min(start_idx + max_palettes_per_image, num_palettes)
        i_df_pallet = df_pallet.iloc[start_idx:end_idx]

        # [4] Create individual palette images
        list_images = []
        for i, row in i_df_pallet.iterrows():
            label = f'[{i:03d}] {row["Label"]}'
            list_RGB_or_HEX = ast.literal_eval(row['list_HEX'])
            palette_img = single_color_arrimg(label, list_RGB_or_HEX, height_width_padding, False)
            list_images.append(palette_img)

        # [5] Stack palettes vertically
        img_height = height_width_padding[0] * len(list_images)
        arrimg_combined = np.vstack(list_images)

        list_images.append(arrimg_combined)

        # [6] Optionally save each combined image
        if dir_save and label_save:
            save_path = f'{dir_save}/{label_save}_{img_idx+1:02d}.png'
            cv2.imwrite(save_path, arrimg_combined)
            print(f"Saved image to {save_path}")

    # [7] Optionally combine all images into one big image
    final_img = np.vstack(list_images)
    print(f'Final combined image shape: {final_img.shape}')

    # [8] Clean up memory
    gc.collect()

    return final_img






