def attempts_to_draw(list_HEX, style_func_name, dict_draw_setting, path_save, cnt_atmp=10):
    """
    Dynamically call the style function by its name.
    """
    # Retrieve the function object from its name
    style_func = globals().get(style_func_name)
    if not callable(style_func):
        raise ValueError(f"Function '{style_func_name}' not found or is not callable.")

    # Iterate through the number of attempts
    for i_atmp in range(cnt_atmp):
        # Construct a new path for each attempt without modifying the original path_save
        attempt_path_save = os.path.join(
            os.path.dirname(path_save),
            f'{os.path.splitext(os.path.basename(path_save))[0]}_{i_atmp:02d}.png'
        )
        style_func(list_HEX, dict_draw_setting, attempt_path_save)



def process_bkgd_color_input_format(bkgd_color):
    """
    Tuple: (255, 255, 255)
    List: [255, 255, 255]
    String representation of either: "(255, 255, 255)" or "[255, 255, 255]"
    None or empty string (defaults to white)
    """
    print(f'bkgd_color: {bkgd_color}')
    type_bkgd_color = type(bkgd_color)
    print(f'type_bkgd_color: {type_bkgd_color}')
    # [2] Process background color
    if bkgd_color is None or bkgd_color == '':
        print('This function does not support transparent background. Resetting to white.')
        bkgd_color = (255, 255, 255)
    elif isinstance(bkgd_color, str):
        try:
            # Try parsing as a tuple/list string
            bkgd_color = ast.literal_eval(bkgd_color)
        except (ValueError, SyntaxError):
            print(f'Failed to parse background color: {bkgd_color}. Resetting to white.')
            bkgd_color = (255, 255, 255)
    if isinstance(bkgd_color, (list, tuple)):
        bkgd_color = tuple(int(x) for x in bkgd_color)
            
    return bkgd_color



def unpack_dict_draw_setting_and_format(dict_draw_setting):
    """
    Put all codes of processing the dict_draw_setting here.
    
    """
    #[1] Process format and unpack.
    img_h = int(dict_draw_setting.get('img_h', 1000))
    img_w = int(dict_draw_setting.get('img_w', 1000))
    bkgd_color = dict_draw_setting.get('bkgd_color', (255, 255, 255))
    bkgd_alpha = float(dict_draw_setting.get('bkgd_alpha', 0.9))
    pos_x_mu = float(dict_draw_setting.get('pos_x_mu', 0.5))
    pos_x_sigma = float(dict_draw_setting.get('pos_x_sigma', 0.1))
    pos_y_mu = float(dict_draw_setting.get('pos_y_mu', 0.5))
    pos_y_sigma = float(dict_draw_setting.get('pos_y_sigma', 0.1))
    size_mu = float(dict_draw_setting.get('size_mu', 0.1))
    size_sigma = float(dict_draw_setting.get('size_sigma', 0.05))
    alpha_mu = float(dict_draw_setting.get('alpha_mu', 0.5))
    alpha_sigma = float(dict_draw_setting.get('alpha_sigma', 0.1))
    count_obj = int(dict_draw_setting.get('count_obj', 20))
    inner_ratio_thres = float(dict_draw_setting.get('inner_ratio_thres', 0.8))
    
    #[5] Make sure bkgd_color is a tuple with three int.
    if isinstance(bkgd_color, (list, tuple)):
        bkgd_color = tuple(int(x) for x in bkgd_color)
    
    
    return [img_h, img_w,
        bkgd_color, bkgd_alpha,
        pos_x_mu, pos_x_sigma,
        pos_y_mu, pos_y_sigma,
        size_mu, size_sigma,
        alpha_mu, alpha_sigma,
        count_obj, inner_ratio_thres]


def gaussian_circles_v01(list_HEX, dict_draw_setting, path_save=None):
    """
    Create an image with overlapping semi-transparent colored circles blended using cv2.addWeighted.
    This will always use a 3-channel non-transparent background.
    """
    # [1] Unpack validated settings
    [img_h, img_w,
     bkgd_color, bkgd_alpha,
     pos_x_mu, pos_x_sigma,
     pos_y_mu, pos_y_sigma,
     size_mu, size_sigma,
     alpha_mu, alpha_sigma,
     count_obj, inner_ratio_thres] = unpack_dict_draw_setting_and_format(dict_draw_setting)

    # [3] Initialize canvas
    arrimg = np.full((img_h, img_w, 3), bkgd_color, dtype=np.uint8)

    # [4] Convert hex list if needed
    if isinstance(list_HEX, str):
        try:
            list_HEX = ast.literal_eval(list_HEX)
        except Exception as e:
            print(f"[ERROR] Invalid HEX list: {e}")
            list_HEX = ['#000000']

    # [5] Draw circles
    for _ in range(count_obj):
        # [6] Random color
        color_hex = np.random.choice(list_HEX)
        rgb = tuple(int(color_hex[i:i+2], 16) for i in (1, 3, 5))

        # [7] Random Gaussian position, size, and alpha
        pos_x = int(np.random.normal(pos_x_mu * img_w, pos_x_sigma * img_w))
        pos_y = int(np.random.normal(pos_y_mu * img_h, pos_y_sigma * img_h))
        radius = max(1, int(np.random.normal(size_mu * img_h, size_sigma * img_h)))
        alpha = np.clip(np.random.normal(alpha_mu, alpha_sigma), 0, 1)

        # [8] Create overlay and blend
        overlay = arrimg.copy()
        cv2.circle(overlay, (pos_x, pos_y), radius, rgb, -1)
        arrimg = cv2.addWeighted(overlay, alpha, arrimg, 1 - alpha, 0)

    # [9] Save if needed
    if path_save is not None:
        cv2.imwrite(path_save, arrimg)

    return arrimg









def gaussian_circles_v02(list_HEX, dict_draw_setting, path_save=None):
    """
    Create an image with overlapping semi-transparent colored circles blended using cv2.addWeighted.
    This will alway use 4-channel transparent background.
    """
    #[1] Unpack dict_draw_setting
    [img_h, img_w,
     bkgd_color, bkgd_alpha,
     pos_x_mu, pos_x_sigma,
     pos_y_mu, pos_y_sigma,
     size_mu, size_sigma,
     alpha_mu, alpha_sigma,
     count_obj, inner_ratio_thres] = unpack_dict_draw_setting_and_format(dict_draw_setting)
    
    # [1] If bkgd_color is empty or None, reset bkgd_alpha = 0 and set a default color
    if not bkgd_color:
        bkgd_color = (255, 255, 255)  # Default to white
        bkgd_alpha = 0
    elif isinstance(bkgd_color, str):
        bkgd_color = ast.literal_eval(bkgd_color)

    # [2] Create a blank RGBA image
    arrimg = np.zeros((img_h, img_w, 4), dtype=np.uint8)  
    arrimg[:, :, :3] = bkgd_color 
    arrimg[:, :, 3] = int(bkgd_alpha * 255) 
        
    # [3] Convert string to list if needed
    if isinstance(list_HEX, str):
        list_HEX = ast.literal_eval(list_HEX)

    # [4] Draw circles
    for _ in range(count_obj):
        #[6] Random color
        color_hex = np.random.choice(list_HEX)
        rgb = tuple(int(color_hex[i:i+2], 16) for i in (1, 3, 5))

        #[8] Random Gaussian position, size, and alpha
        pos_x = int(np.random.normal(pos_x_mu * img_w, pos_x_sigma * img_w))
        pos_y = int(np.random.normal(pos_y_mu * img_h, pos_y_sigma * img_h))
        radius = max(1, int(np.random.normal(size_mu * img_h, size_sigma * img_h)))
        alpha = np.clip(np.random.normal(alpha_mu, alpha_sigma), 0, 1)

        #[10] Temporary overlay
        overlay = arrimg.copy()
        cv2.circle(overlay, (pos_x, pos_y), radius, rgb, -1)

        # [12] Blend only RGB channels
        for c in range(3):  # RGB only
            arrimg[:, :, c] = cv2.addWeighted(overlay[:, :, c], alpha,
                                            arrimg[:, :, c], 1 - alpha, 0)

    # [15] Save if needed
    if path_save is not None:
        cv2.imwrite(path_save, arrimg)

    return arrimg
    















def check_circle_edge(pos_x, pos_y, radius, img_h, img_w, inner_ratio_thres=0.8):
    """
    inner_circle is located at the center of the image, 
    and with the radius of center_circle_r = min(img_h, img_w) * inner_ratio_thres * 0.5
    For circles described by (pos_x, pos_y, radius),
    if the distance from the center of image to (pos_x, pos_y) is larger than radius + center_circle_r,
    return True (circle edge is outside the inner circle), otherwise False.    
    """
    # [1] Define the center and radius of the inner circle
    center_x = img_w * 0.5
    center_y = img_h * 0.5
    center_circle_r = min(img_h, img_w) * inner_ratio_thres * 0.5

    # [2] Calculate the distance from the circle center to the center of the inner circle
    distance_to_center = ((pos_x - center_x) ** 2 + (pos_y - center_y) ** 2) ** 0.5

    # [3] Compute the distance of the circle edge to the inner circle
    # The circle edge is outside the inner circle if the distance from the center
    # to the circle center is greater than the sum of the radius and the inner circle radius
    if distance_to_center > radius + center_circle_r:
        return True  # Circle edge is outside the inner circle
    else:
        return False  # Circle edge is inside or overlaps with the inner circle
    

def gaussian_circles_v03(list_HEX, dict_draw_setting, path_save=None):
    """
    Create an image of img_h x img_w pixels with a random color background
    This will remove circles too close to the center.
    """
    #[1] Unpack dict_draw_setting
    [img_h, img_w,
     bkgd_color, bkgd_alpha,
     pos_x_mu, pos_x_sigma,
     pos_y_mu, pos_y_sigma,
     size_mu, size_sigma,
     alpha_mu, alpha_sigma,
     count_obj, inner_ratio_thres] = unpack_dict_draw_setting_and_format(dict_draw_setting)
    
    # [2] Initialize base image
    if bkgd_color is None or bkgd_color == '':
        arrimg = np.zeros((img_h, img_w, 4), dtype=np.uint8)  # Transparent RGBA
    else:
        arrimg = np.zeros((img_h, img_w, 4), dtype=np.uint8)
        arrimg[:, :] = list(bkgd_color) + [255]

    # [3] Convert string to list if needed
    if isinstance(list_HEX, str):
        list_HEX = ast.literal_eval(list_HEX)

    # [4] Draw circles
    for _ in range(count_obj):
        # [5] Choose color
        color_hex = np.random.choice(list_HEX)
        rgb = tuple(int(color_hex[i:i+2], 16) for i in (1, 3, 5))

        # [6] Sample position, size, alpha
        cnt_circle_attempt = 0
        while cnt_circle_attempt < 10:
            pos_x = int(np.random.normal(pos_x_mu * img_w, pos_x_sigma * img_w))
            pos_y = int(np.random.normal(pos_y_mu * img_h, pos_y_sigma * img_h))
            radius = max(1, int(np.random.normal(size_mu * img_h, size_sigma * img_h)))
            cnt_circle_attempt += 1
            #[7] If successfully find a allowed circle, break.
            if check_circle_edge(pos_x, pos_y, radius, img_h, img_w, inner_ratio_thres):
                break
            #[7] If not, continue.
            elif cnt_circle_attempt >= 10:
                print(f"[WARN] Failed to place circle after 10 attempts.")
                continue

        alpha = int(255 * np.clip(np.random.normal(alpha_mu, alpha_sigma), 0, 1))

        # [7] Create an overlay with same shape
        overlay = np.zeros_like(arrimg)
        cv2.circle(overlay, (pos_x, pos_y), radius, rgb + (alpha,), -1)

        # [8] Alpha blending (manual per-channel)
        alpha_overlay = overlay[:, :, 3:] / 255.0
        alpha_base = arrimg[:, :, 3:] / 255.0
        out_alpha = alpha_overlay + alpha_base * (1 - alpha_overlay)
        out_rgb = (
            overlay[:, :, :3] * alpha_overlay +
            arrimg[:, :, :3] * alpha_base * (1 - alpha_overlay)
        ) / np.maximum(out_alpha, 1e-5)

        arrimg[:, :, :3] = out_rgb.clip(0, 255).astype(np.uint8)
        arrimg[:, :, 3] = (out_alpha * 255).clip(0, 255).astype(np.uint8).squeeze()
        #[9] Printing slows down the function a lot.
        #print(f'[{i:03d}/{count_obj:03d}] {pos_x}, {pos_y}, {radius}, {alpha}')

    # [10] Save (convert to BGRA for OpenCV)
    if path_save is not None:
        cv2.imwrite(path_save, cv2.cvtColor(arrimg, cv2.COLOR_RGBA2BGRA))

    return arrimg












