def run_path_py_as_subprocess_and_redirect_output(path_py, root, terminal_output, *args):
    """
    This will pass the *args to the path_py as command line arguments,
    and run the python file at path_py, 
    and redirect its output to the terminal_output Text widget in real-time.
    """
    def run_subprocess():
        try:
            # [1] Check if the Python script exists
            if not os.path.isfile(path_py):
                terminal_output.insert(tk.END, f'\n[ERROR] Python script not found: {path_py}\n')
                terminal_output.see(tk.END)
                root.update()
                return

            # [2] Prepare the command with arguments
            command = ["python", "-u", path_py] + list(args)

            # [3] Clear the terminal output widget
            terminal_output.delete(1.0, tk.END)
            terminal_output.insert(tk.END, f'\n[INFO] Running: {" ".join(command)}\n')
            terminal_output.see(tk.END)
            root.update()

            # [4] Run the subprocess
            process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

            # [5] Read and display the output in real-time
            while True:
                # Read a line from stdout
                line = process.stdout.readline()
                if line:
                    terminal_output.insert(tk.END, line)
                    terminal_output.see(tk.END)
                    root.update()
                # Break the loop if the process has finished and no more output is available
                if process.poll() is not None and not line:
                    break

            # [6] Capture any remaining output
            stdout, stderr = process.communicate()
            if stdout:
                terminal_output.insert(tk.END, stdout)
            if stderr:
                terminal_output.insert(tk.END, f"[ERROR] {stderr}\n")
            terminal_output.see(tk.END)

        except Exception as e:
            terminal_output.insert(tk.END, f"[ERROR] Exception occurred: {str(e)}\n")
            terminal_output.see(tk.END)

    # [7] Run the subprocess in a separate thread to avoid blocking the GUI
    thread = threading.Thread(target=run_subprocess)
    thread.start()





def terminate_subprocess_on_close(root, current_process):
    if current_process and current_process.poll() is None:
        current_process.terminate()
        current_process = None
    root.destroy()

