def section_pallet_view(frame, dir_pallets,
                        outer_canvas_length=400,
                        inner_img_length=360):
    """
    Read '.jpg' files from dir_pallets, display the first one in this frame.
    At the bottom, add two flip-page-like buttons to go to the next or previous image.
    """
    # [1] Filter image files
    list_allow_ext = ['.jpg', '.jpeg', '.png']
    image_files = [os.path.join(dir_pallets, f) for f in os.listdir(dir_pallets)
                   if os.path.splitext(f)[1].lower() in list_allow_ext]
    if not image_files:
        tk.Label(frame, text="No image files found.", font=("Arial", 12)).pack(pady=10)
        return

    # [2] Add title at the top
    title_label = tk.Label(frame, text='Pallets', font=("Arial", 12, "bold"))
    title_label.pack(pady=(5, 0))

    # [3] Setup image index and label container
    current_index = tk.IntVar(value=0)

    # [4] Image viewer section
    image_canvas = tk.Canvas(frame, 
                             width=outer_canvas_length, 
                             height=outer_canvas_length, bg="white", relief="sunken")
    image_canvas.pack(pady=(10, 5))

    image_name_label = tk.Label(frame, text="", font=("Arial", 10))
    image_name_label.pack()

    # [5] Update image display
    def update_image():
        img_path = image_files[current_index.get()]
        pil_img = Image.open(img_path).convert("RGB")
        pil_img = pil_img.resize((inner_img_length, inner_img_length), 
                                 Image.Resampling.LANCZOS)
        img_tk = ImageTk.PhotoImage(pil_img)

        image_canvas.delete("all")  # Clear the canvas
        image_canvas.create_image(outer_canvas_length // 2, outer_canvas_length // 2, image=img_tk)
        image_canvas.image = img_tk  # Keep a reference to avoid garbage collection
        image_name_label.config(text=os.path.basename(img_path))

    # [6] Navigation controls
    def prev_or_next_image(action):
        if action == 'next' and current_index.get() < len(image_files) - 1:
            current_index.set(current_index.get() + 1)
            update_image()
        elif action == 'prev' and current_index.get() > 0:
            current_index.set(current_index.get() - 1)
            update_image()

    nav_frame = tk.Frame(frame)
    nav_frame.pack(pady=(5, 15))

    btn_prev = tk.Button(nav_frame, text="Previous", command=lambda: prev_or_next_image('prev'))
    btn_prev.pack(side=tk.LEFT, padx=10)

    btn_next = tk.Button(nav_frame, text="Next", command=lambda: prev_or_next_image('next'))
    btn_next.pack(side=tk.LEFT, padx=10)

    # [7] Initial image load
    update_image()


def current_content_size(root):
    # [1] Get the total height and width of the window in pixels
    width = root.winfo_width()
    height = root.winfo_height()

    # [2] Calculate the total height occupied by widgets in pixels
    total_widget_height = 0
    for child in root.winfo_children():
        widget_y = child.winfo_y()  # Y-coordinate of the widget relative to the parent
        widget_height = child.winfo_height()  # Height of the widget
        total_widget_height = max(total_widget_height, widget_y + widget_height)

    # [3] Calculate the remaining vertical space in pixels
    height_remain = height - total_widget_height

    return width, height, height_remain



def fix_section_two_column_height(sec_two_columns, left_column, height_v, pad=20):
    """
    Fix the height of the two-column section and its left/right frames.
    """
    # Set fixed height on both parent and children frames
    fixed_height = height_v + pad

    sec_two_columns.configure(height=fixed_height)
    sec_two_columns.grid_propagate(False)

    for column in sec_two_columns.winfo_children():
        column.configure(height=fixed_height - pad)
        column.grid_propagate(False)


class TextRedirector:
    """
    Redirects stdout or stderr to a tkinter Text widget.
    """
    def __init__(self, text_widget):
        self.text_widget = text_widget

    def write(self, message):
        self.text_widget.insert(tk.END, message)
        self.text_widget.see(tk.END)  # Auto-scroll to the end

    def flush(self):
        pass  # Required for compatibility with sys.stdout


def section_terminal_output(root, row_v=2):
    """
    Creates a terminal output section with a scrollbar that adapts to fill the remaining vertical height.
    """
    # [1] Create the terminal output frame
    sec_terminal_window = tk.Frame(root)
    sec_terminal_window.grid(row=row_v, column=0, padx=10, pady=10, sticky="nsew")  # Place in the next grid row and expand

    # [2] Add a Text widget for terminal output
    terminal_output = tk.Text(sec_terminal_window, bg="lightgray", relief="sunken", height=20, wrap=tk.WORD)
    terminal_output.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

    # [3] Add a scrollbar for the terminal output
    scrollbar = tk.Scrollbar(sec_terminal_window, command=terminal_output.yview)
    scrollbar.pack(side=tk.RIGHT, fill=tk.Y)
    terminal_output.config(yscrollcommand=scrollbar.set)

    # [4] Ensure the terminal window expands when the window resizes
    root.grid_rowconfigure(2, weight=1)  # Allow the terminal window to expand vertically
    root.grid_columnconfigure(0, weight=1)  # Allow horizontal expansion if needed

    return terminal_output






