def change_a_line_of_code_in_py_file_with_start_end(path_python, line_start, line_end, replace_in_between):
    """
    Find a line in the given python file that looks like:
    anthropic_api_key = 'put-your-api-key-here' # put-your-api-key-here.
    And change it into:
    anthropic_api_key = 'replace_in_between' # put-your-api-key-here.
    And save.
    """
    #print('\n[change_a_line_of_code_in_py_file]')
    basename = os.path.basename(path_py)
    with open(path_python, 'r') as file:
        lines = file.readlines()
    modified = False
    for i, line in enumerate(lines):
        if line.strip().startswith(line_start) and line.strip().endswith(line_end):
            old_in_between = line.replace(line_start,'').replace(line_end,'')
            lines[i] = f"{line_start}{replace_in_between}{line_end}\n"
            modified = True
            print(f"--In {basename}, replace '{old_in_between}' in the designated location with '{replace_in_between[:20]}'.")
            break
    if modified:
        with open(path_python, 'w') as file:
            file.writelines(lines)


def change_a_line_of_code_in_py_file_with_start(path_python, str_start, replace_after_str_start):
    """
    1. Find a line in the given python file that looks like:
    anthropic_api_key = 'real-api-key' # put-your-api-key-here.
    2. And change it into:
    anthropic_api_key = 'put-your-api-key-her' # put-your-api-key-here.
    3. And save.
    [Example use]
    line_start = "_api_key='"
    replace_after_line_start = "put-your-api-key-here'#put-your-api-key-here."
    change_a_line_of_code_in_py_file_with_start(path_py, line_start, replace_after_line_start)
    """
    #print('\n[change_a_line_of_code_in_py_file_with_start]')
    basename = os.path.basename(path_python)
    with open(path_python, 'r') as file:
        lines = file.readlines()
    modified = False
    for i, line in enumerate(lines):
        if str_start in line:
            before_str_start = line.split(str_start)[0]
            old_after_str_start = line.replace(str_start,'')
            lines[i] = f"{before_str_start}{str_start}{replace_after_str_start}\n"
            modified = True
            print(f"--In {basename}, replace '{old_after_str_start}' in the designated location with '{replace_after_str_start[:20]}'.")
            break
    if modified:
        with open(path_python, 'w') as file:
            file.writelines(lines)



