def get_max_and_min_displ_coors(path_xlsx):
    #[1] Read the first sheet in path_xlsx as df_step.
    df_step = pd.read_excel(path_xlsx)
    
    #[2] Get the [coor1_x, coor1_y, coor2_x, coor2_y] of the max and min d_l
    max_displ_row = df_step.loc[df_step['d_l'].idxmax()]
    min_displ_row = df_step.loc[df_step['d_l'].idxmin()]
                                
    #[3] Get start and end of the coordinates
    max_start = (max_displ_row['coor1_x'], max_displ_row['coor1_y'])
    max_end = (max_displ_row['coor2_x'], max_displ_row['coor2_y'])
    max_len = math.sqrt((max_end[0] - max_start[0])**2 + (max_end[1] - max_start[1])**2)
    
    min_start = (min_displ_row['coor1_x'], min_displ_row['coor1_y'])
    min_end = (min_displ_row['coor2_x'], min_displ_row['coor2_y'])
    min_len = math.sqrt((min_end[0] - min_start[0])**2 + (min_end[1] - min_start[1])**2)
    
    #[4] Convert coordinates to integer if needed for other uses:
    max_start_int = (int(max_start[0]), int(max_start[1]))
    max_end_int = (int(max_end[0]), int(max_end[1]))
    min_start_int = (int(min_start[0]), int(min_start[1]))
    min_end_int = (int(min_end[0]), int(min_end[1]))
    return (max_start_int, max_end_int, max_len, min_start_int, min_end_int, min_len)






