def plot_3D_data_space(arr_XYZ, figsize, focus_range, d_size, fs_axis, fs_label, elve_azim):
    #[1] Customize
    cmap = 'viridis'
    title = None
    xlabel, ylabel, zlabel = 'X', 'Y', 'Z'
    show_colorbar = False

    #[2] Create figure and 3D axis
    fig = plt.figure(figsize=figsize)
    ax = fig.add_subplot(111, projection='3d')
    
    # For the points inside the focus_range, plot with alpha=1.
    x_min, x_max, y_min, y_max = focus_range
    mask = ((arr_XYZ[:, 0] >= x_min) & (arr_XYZ[:, 0] <= x_max) &
            (arr_XYZ[:, 1] >= y_min) & (arr_XYZ[:, 1] <= y_max))
    in_focus = arr_XYZ[mask]
    out_of_focus = arr_XYZ[~mask]

    # Plot points in focus
    ax.scatter(in_focus[:, 0], in_focus[:, 1], in_focus[:, 2], 
               c=in_focus[:, 2], cmap=cmap, s=d_size, alpha=0.9)

    # Plot the rest of the points with alpha=0.5
    ax.scatter(out_of_focus[:, 0], out_of_focus[:, 1], out_of_focus[:, 2], 
               c=out_of_focus[:, 2], cmap=cmap, s=d_size, alpha=0.06)
    
    #[3] Set labels and title
    ax.set_xlabel(xlabel, fontsize=fs_axis)
    ax.set_ylabel(ylabel, fontsize=fs_axis)
    ax.set_zlabel(zlabel, fontsize=fs_axis)
    
    #[4] Adjust tick parameters
    ax.tick_params(labelsize=fs_label)
    
    # Set axes position
    plt.subplots_adjust(left=0.02, right=0.98, bottom=0.02, top=0.98)

    #ax.set_position([0.2, 0.2, 0.8, 0.8])  # [left, bottom, width, height]

    #[5] View settings
    elev, azim = elve_azim if elve_azim is not None else (30, -60)
    ax.view_init(elev, azim)

    #[6] Adjust alpha
    for label in ax.get_xticklabels() + ax.get_yticklabels() + ax.get_zticklabels():
        label.set_alpha(0.5)
    
    #[7] Set z-axis limits
    max_z = np.max(arr_XYZ[:, 2])
    ax.set_zlim(0, 1.5 * max_z)

    #[8] Return array image
    buf = io.BytesIO()
    plt.savefig(buf, format='png', pad_inches=0)
    plt.close(fig)
    buf.seek(0)
    img = Image.open(buf)
    arr_img = cv2.cvtColor(np.array(img), cv2.COLOR_RGB2BGR)

    return arr_img


