def generate_3d_dataset_linearly_spaced(space_length, data_density, cone_slope):
    data_count_1D = int(data_density * space_length) + 1
    arr_X = np.linspace(-space_length / 2, +space_length / 2, data_count_1D)
    arr_Y = np.linspace(-space_length / 2, +space_length / 2, data_count_1D)
    arr_X, arr_Y = np.meshgrid(arr_X, arr_Y)
    arr_Z = cone_slope * np.sqrt(arr_X**2 + arr_Y**2)
    arr_XYZ = np.dstack((arr_X, arr_Y, arr_Z))
    arr_XYZ = arr_XYZ.reshape(-1, arr_XYZ.shape[2])
    return arr_XYZ


def generate_3d_dataset_random(data_count_3D, cone_slope, space_length):
    half_length = space_length / 2
    arr_XY = np.random.rand(data_count_3D, 2) * space_length - half_length
    arr_Z = cone_slope * np.sqrt(arr_XY[:, 0]**2 + arr_XY[:, 1]**2) 
    arr_XYZ = np.hstack((arr_XY, arr_Z[:, np.newaxis])) 
    return arr_XYZ







def generate_random_coordinate_list(list_min, list_max, length, round=None):
  """
  Generates a list of random coordinates within the specified ranges,
  optionally rounding the coordinates to a desired number of decimal places.

  Args:
      list_min: A list containing the minimum values for each dimension.
      list_max: A list containing the maximum values for each dimension.
      length: The number of random coordinates to generate.
      round: The number of decimal places to round to (default: None, no rounding).

  Returns:
      A list of random coordinates, where each coordinate is a list itself,
      rounded to the specified number of decimal places if round is not None.
  """

  if len(list_min) != len(list_max):
    raise ValueError("list_min and list_max must have the same length")

  dimension = len(list_min)

  # Generate random values within the ranges
  random_coords = np.random.rand(length, dimension) * (np.array(list_max) - np.array(list_min)) + np.array(list_min)

  # Round if desired
  if round is not None:
    random_coords = np.around(random_coords, round)

  return random_coords.tolist()










def find_gradient_and_angle_old(list_dspls, list_coor2, path_image, displ_std_limit, xy_std_limit):
    """
    [Input]
    list_coor2 is a list of list (x,y) coordinates of datapoints on a 2D image.
    list_dspls is the displacement value of each data point.
    Try to find the direction of the gradient. That is, to which direction of (x,y) does the value list_dspls decrease.
    """
    print('\n[find_gradient_and_angle]')
    #[1] Prepare data
    list_dspls = [dspl for dspl in list_dspls if not np.isnan(dspl)]
    if not list_dspls:  # Check if list_dspls is empty after removing NaN values
        print("--Error: list_dspls contains only NaN values or is empty.")
        return
    list_coor2 = np.array(list_coor1)
    list_x_coor, list_y_coor = list_coor2[:, 0], list_coor2[:, 1]
    combined_data = np.column_stack((list_x_coor, list_y_coor, list_dspls))
    
    # [1] Prepare data
    list_dspls = [dspl for dspl in list_dspls if not np.isnan(dspl)]  # Remove NaN values
    if not list_dspls:
        print("--Error: list_dspls contains only NaN values or is empty.")
        return

    list_coor2 = np.array(list_coor2)
    list_x_coor, list_y_coor = list_coor2[:, 0], list_coor2[:, 1]

    #[2] Fit a 2D normal distribution to the data
    means, covariances = norm.fit(np.column_stack((list_x_coor, list_y_coor)))
    print(f'(means, covariances) = {means}, {covariances}')
    
    
    #[2] Perform linear regression on all data points
    # Calculate the best fit line's slope and intercept
    slope, intercept = np.polyfit(list_x_coor, list_dspls, 1)
    gradient = slope
    print(f'--Gradient: {gradient}; Intercept {intercept}')
    
    #[3] Calculate mean positions and displacements
    sorted_data = combined_data[combined_data[:, 2].argsort()]
    dir_pct = 0.10
    num_points = int(len(sorted_data) * dir_pct)
    bottom_pct_data = sorted_data[:num_points]
    top_pct_data = sorted_data[-num_points:]
    bot_pct_x_coor, bot_pct_y_coor, bot_pct_dspls = np.mean(bottom_pct_data, axis=0)
    top_pct_x_coor, top_pct_y_coor, top_pct_dspls = np.mean(top_pct_data, axis=0)
    print(f'--Bottom 10% (bot_pct_x_coor, bot_pct_y_coor, bot_pct_dspls) = ({bot_pct_x_coor}, {bot_pct_y_coor}, {bot_pct_dspls})')
    print(f'--Top 10%    (top_pct_x_coor, top_pct_y_coor, top_pct_dspls) = ({top_pct_x_coor}, {top_pct_y_coor}, {top_pct_dspls})')


    #[5] Calculate the distance between bot10 and top10 mean coordinates
    top_bot_dist = np.sqrt((top_pct_x_coor - bot_pct_x_coor) ** 2 + (top_pct_y_coor - bot_pct_y_coor) ** 2)
    top_bot_diff = (top_pct_dspls - bot_pct_dspls) / 2 
    theta_deg = np.degrees(np.arctan2(top_bot_diff, top_bot_dist))
    print(f'--Theta of rotation: {theta_deg}')
    
    #[6] Distance to the origin
    dist_to_O = bot_pct_dspls/gradient
    print(f'--Distance to Origin: {dist_to_O}')

    #[7] Draw the arrow
    image = cv2.imread(path_image)
    max_y, max_x = image.shape[:2]
    arrow_thold = 0.5
    X_max_width_ratio = max(top_pct_x_coor, bot_pct_x_coor)/max_x
    Y_max_width_ratio = max(top_pct_y_coor, bot_pct_y_coor)/max_y
    if X_max_width_ratio < arrow_thold and Y_max_width_ratio < arrow_thold:
        print(f'--Larger arrow. (X_max_width_ratio, Y_max_width_ratio) = ({X_max_width_ratio}, {Y_max_width_ratio})')
        vx, vy = (bot_pct_x_coor - top_pct_x_coor), (bot_pct_y_coor - top_pct_y_coor)
        all_ext, head_ext = 0.5, 1.2
        arrow_start_x, arrow_start_y = int(top_pct_x_coor - all_ext* vx), int(top_pct_y_coor - all_ext* vy)
        arrow_end_x, arrow_end_y = int(bot_pct_x_coor + head_ext* all_ext* vx), int(bot_pct_y_coor + head_ext* all_ext* vy)
    else:
        print(f'--Normal arrow. (X_max_width_ratio, Y_max_width_ratio) = ({X_max_width_ratio}, {Y_max_width_ratio})')
        arrow_start_x, arrow_start_y = int(top_pct_x_coor), int(top_pct_y_coor)
        arrow_end_x, arrow_end_y = int(bot_pct_x_coor), int(bot_pct_y_coor)

    print(f'--Arrow start (x, y) = ({arrow_start_x}, {arrow_start_y})', )
    print(f'--Arrow end (x, y) = ({arrow_end_x}, {arrow_end_y})', )
    
    cv2.arrowedLine(image, (arrow_start_x, arrow_start_y), (arrow_end_x, arrow_end_y), (131, 93, 222), 10, tipLength=0.2)
    
    
    #[8] Add text  displ_std_limit, xy_std_limit
    now = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
    text = (f'[{now}]\n'
            f'STD Limits (displ, xy): {displ_std_limit}, {xy_std_limit}\n'
            f'Direction sampling pct: {dir_pct}\n'
            f'Match     : {len(list_dspls)} [points]\n'
            f'Gradient  : {gradient:.4f} [dspl/pixel]\n'
            f'Rotation  : {theta_deg:.4f} [degree]\n'
            f'Dist to O : {dist_to_O:.4f} [pixel]\n'
            )
    add_text_to_opencv_image(cv2image = image, text = text
                            , start_x = 30, start_y = 60, line_spacing = 40
                            , font_scale = 1, font_color = (24, 13, 13), thickness = 2)

    #[9] Save the result with a modified file name to indicate marking
    img_ext = os.path.splitext(path_image)[1]
    path_marked_image = path_image.replace(img_ext, '_4-arrow' + img_ext)
    cv2.imwrite(path_marked_image, image)

    return theta_deg, gradient, dist_to_O


def find_gradient_and_angle(list_dspls, list_coor2, path_image, displ_std_limit, xy_std_limit):
    """
    [Input]
    list_coor2 is a list of list (x,y) coordinates of datapoints on a 2D image.
    list_dspls is the displacement value of each data point.
    Try to find the average direction of the gradient that has the quickest decrease in list_dspls.

    [Output]
    gradient_direction: A 2D vector representing the direction of quickest decrease, 
                        where positive values indicate (+right, +down) in the image coordinates.
    """
    
    print('\n[find_gradient_and_angle]')
        
    #[1] Prepare data
    list_dspls = [dspl for dspl in list_dspls if not np.isnan(dspl)]  # Remove NaN values
    if not list_dspls:  # Check if list_dspls is empty after removing NaN values
        print("--Error: list_dspls contains only NaN values or is empty.")
        return

    list_coor2 = np.array(list_coor2)
    if len(list_coor2) != len(list_dspls):
        print("--Error: Coordinates and displacements list must have the same length.")
        return


    list_coor2 = np.array(list_coor2)
    list_x_coor, list_y_coor = list_coor2[:, 0], list_coor2[:, 1]
    combined_data = np.column_stack((list_x_coor, list_y_coor, list_dspls))

    #[2-1] Fit a 2D normal distribution to the data
    weights = np.exp(-np.array(list_dspls) / np.std(list_dspls))
    weighted_mean = np.average(list_coor2, axis=0, weights=weights)
    # Estimate the covariance matrix weighted by displacement values
    covariances = np.cov(list_coor2.T, aweights=weights)
    print(f'(weights.shape, weighted_mean, covariances) = {weights.shape}, {weighted_mean}, {covariances}')
    
    #[2-2] Extract major axis (direction of greatest spread) from covariance matrix
    eigenvalues, eigenvectors = np.linalg.eig(covariances)
    major_axis = eigenvectors[:, np.argmax(eigenvalues)]
    
    #[3] Calculate gradient direction based on major axis
    # Invert major axis if displacement decreases along the positive direction
    if np.mean(list_dspls) < list_dspls[0]:  # Check if displacement decreases positively
        major_axis *= -1

    # Normalize the major axis to represent direction
    gradient_direction = major_axis / np.linalg.norm(major_axis)
    print(f'--Gradient direction: {gradient_direction}')
    
    #[4] Calculate the magnitude of the gradient (slope)
    # Perform linear regression on all data points to calculate the best fit line's slope and intercept
    slope, intercept = np.polyfit(list_x_coor, list_dspls, 1, full=True)[:2]
    gradient = slope
    print(f'--Gradient: {gradient}; Intercept: {intercept}')

    
    #[5] Calculate statistics for displacement values
    sorted_data = combined_data[combined_data[:, 2].argsort()]
    num_points = int(len(sorted_data) * 0.1)
    bottom_pct_data = sorted_data[:num_points]
    top_pct_data = sorted_data[-num_points:]
    bot_pct_x_coor, bot_pct_y_coor, bot_pct_dspls = np.mean(bottom_pct_data, axis=0)
    top_pct_x_coor, top_pct_y_coor, top_pct_dspls = np.mean(top_pct_data, axis=0)
    print(f'--Bottom 10% (bot_pct_x_coor, bot_pct_y_coor, bot_pct_dspls) = ({bot_pct_x_coor}, {bot_pct_y_coor}, {bot_pct_dspls})')
    print(f'--Top 10% (top_pct_x_coor, top_pct_y_coor, top_pct_dspls) = ({top_pct_x_coor}, {top_pct_y_coor}, {top_pct_dspls})')

    #[6] Determine angle of gradient using mean positions
    dx = top_pct_x_coor - bot_pct_x_coor
    dy = top_pct_y_coor - bot_pct_y_coor
    theta_rad = np.arctan2(dy, dx)  # Angle in radians
    theta_deg = np.degrees(theta_rad)  # Convert to degrees
    print(f'--Theta of gradient: {theta_deg}')
    
    #[7] Calculate distance to the origin based on intercept
    dist_to_O = -intercept / gradient
    print(f'--Distance to Origin: {dist_to_O}')
   
    
    # [8] Draw the arrow
    image = cv2.imread(path_image)
    max_y, max_x = image.shape[:2]
    arrow_thold = 0.5
    X_max_width_ratio = max(top_pct_x_coor, bot_pct_x_coor)/max_x
    Y_max_width_ratio = max(top_pct_y_coor, bot_pct_y_coor)/max_y
    if X_max_width_ratio < arrow_thold and Y_max_width_ratio < arrow_thold:
        print(f'--Larger arrow. (X_max_width_ratio, Y_max_width_ratio) = ({X_max_width_ratio}, {Y_max_width_ratio})')
        vx, vy = (bot_pct_x_coor - top_pct_x_coor), (bot_pct_y_coor - top_pct_y_coor)
        all_ext, head_ext = 0.5, 1.2
        arrow_start_x, arrow_start_y = int(top_pct_x_coor - all_ext* vx), int(top_pct_y_coor - all_ext* vy)
        arrow_end_x, arrow_end_y = int(bot_pct_x_coor + head_ext* all_ext* vx), int(bot_pct_y_coor + head_ext* all_ext* vy)
    else:
        print(f'--Normal arrow. (X_max_width_ratio, Y_max_width_ratio) = ({X_max_width_ratio}, {Y_max_width_ratio})')
        arrow_start_x, arrow_start_y = int(top_pct_x_coor), int(top_pct_y_coor)
        arrow_end_x, arrow_end_y = int(bot_pct_x_coor), int(bot_pct_y_coor)

    print(f'--Arrow start (x, y) = ({arrow_start_x}, {arrow_start_y})', )
    print(f'--Arrow end (x, y) = ({arrow_end_x}, {arrow_end_y})', )
    
    cv2.arrowedLine(image, (arrow_start_x, arrow_start_y), (arrow_end_x, arrow_end_y), (131, 93, 222), 10, tipLength=0.2)
    
    sys.exit()
    # [9] Add text displ_std_limit, xy_std_limit
    displ_std_limit, xy_std_limit = str(displ_std_limit), str(xy_std_limit)
    now = str(datetime.now().strftime("%Y-%m-%d_%H-%M-%S"))
    text = (f'[{now}]\n'
            f'STD Limits (displ, xy): {displ_std_limit}, {xy_std_limit}\n'
            f'Match     : {len(list_dspls)} [points]\n'
            f'Gradient  : {gradient:.4f} [dspl/pixel]\n'
            f'Rotation  : {theta_deg:.4f} [degree]\n'
            f'Dist to O : {dist_to_O:.4f} [pixel]\n'
            )
    add_text_to_opencv_image(cv2image = image, text = text
                                    , start_x = 30, start_y = 60, line_spacing = 40
                                    , font_scale = 1, font_color = (13, 130, 240), thickness = 2)

    # [10] Save the result with a modified file name to indicate marking
    img_ext = os.path.splitext(path_image)[1]
    path_marked_image = path_image.replace(img_ext, '_4-arrow' + img_ext)
    cv2.imwrite(path_marked_image, image)
    
    
    return theta_deg, gradient, dist_to_O




def train_to_fit_the_invert_cone(list_coor2, list_dspls, initial_ctr_rot, initial_cone_slope, initial_lr, num_epochs, text_log):
    """
    [Goal]
        Optimizes the parameters x_ctr_rot, y_ctr_rot, and cone_slope to minimize the loss using linear regression.
    [Args]
        list_coor2: list of coordinates in (x, y)
        list_dspls: list of displacement, a single value. Just regard as the elevation of invert cone.
        ctr_rot: center of rotation (x, y) in raster coordinate.
        cone_slope: the ratio the invert cone rises for every one unit away from the center of rotation.
        learning_rate: the learning rate for gradient descent
        num_epochs: the number of epochs to train the model
    [Note]
        1. Define the origin as the upper left corner of the image.
        2. Use raster coordinate system where x-axis increases to the right and the y-axis increases downward.
    """
    print('\n[train_to_fit_the_invert_cone]')
    #[1] Initialize parameters
    x_ctr_rot, y_ctr_rot = initial_ctr_rot
    cone_slope = initial_cone_slope
    learning_rate = initial_lr

    #[2] Convert input lists to numpy arrays
    X = np.array(list_coor2)
    Y = np.array(list_dspls)
    low_loss_cnt = 0
    dont_remove_data_yet = 0
    dont_set_cone_slope_yet = 0
    list_loss = []
    list_lr = []
    list_ctr_rot = []
    list_cone_slope = []
    list_grads = []
    text_in_for = ''

    #[3] Train the model for the specified number of epochs
    for epoch in range(num_epochs):
        #[4] Forward pass
        #print(f'(X[:, 0], X[:, 1]): {X[:, 0]}, {X[:, 1]}')
        x_CR2P = x_ctr_rot + X[:, 0]
        y_CR2P = y_ctr_rot + X[:, 1]
        cone_elev = cone_slope * np.sqrt(x_CR2P**2 + y_CR2P**2)
        y_pred = cone_elev

        #[5] Calculate loss and update learning rate
        loss = np.mean((y_pred - Y)**2)
        text = ''
        allow_lower_lr = num_epochs * 0.1
        if len(list_loss) > 0 and loss/list_loss[-1] < 2:
            loss_decrease_ratio = loss/list_loss[-1]
            text = f'loss_decrease_ratio: {loss_decrease_ratio}'
            if loss_decrease_ratio > 0.9999999999 and epoch >=10:
                low_loss_cnt += 1
                if low_loss_cnt > 3:
                    text = f'[{epoch+1}]\n--[Good enough] Early stop triggered by low_loss_cnt ({low_loss_cnt}) and loss_decrease_ratio ({loss_decrease_ratio}).\n'
                    text_in_for += text
                    print(text)
                    break
            elif loss_decrease_ratio > 0.999999999 and len(list_loss) > allow_lower_lr:
                learning_rate = initial_lr * 1e-10
            elif loss_decrease_ratio > 0.99999999 and len(list_loss) > allow_lower_lr:
                learning_rate = initial_lr * 1e-9
            elif loss_decrease_ratio > 0.9999999 and len(list_loss) > allow_lower_lr:
                learning_rate = initial_lr * 1e-7
            elif loss_decrease_ratio > 0.999999 and len(list_loss) > allow_lower_lr:
                learning_rate = initial_lr * 1e-5
            elif loss_decrease_ratio > 0.99999 and len(list_loss) > allow_lower_lr:
                learning_rate = initial_lr * 1e-3
            elif loss_decrease_ratio > 0.9999 and len(list_loss) > allow_lower_lr:
                learning_rate = initial_lr * 1e-1
        list_loss.append(loss)
        list_lr.append(learning_rate)
        
        #[6] Record
        list_ctr_rot.append([x_ctr_rot, y_ctr_rot])
        list_cone_slope.append(cone_slope)

        #[7] Backward pass (gradient calculation)
        grad_x = np.mean(2 * (y_pred - Y) * cone_slope * x_CR2P / np.sqrt(x_CR2P**2 + y_CR2P**2))
        grad_y = np.mean(2 * (y_pred - Y) * cone_slope * y_CR2P / np.sqrt(x_CR2P**2 + y_CR2P**2))
        grad_cone_slope = np.mean(2 * (y_pred - Y) * np.sqrt(x_CR2P**2 + y_CR2P**2))

        #[8] Update parameters
        x_ctr_rot -= learning_rate * grad_x
        y_ctr_rot -= learning_rate * grad_y
        if loss > 1e6 and dont_remove_data_yet <= 0:
            """cone_slope = initial_cone_slope
            max_index = np.argmax(list_dspls)  # Get the index of the maximum value in Y
            min_index = np.argmin(list_dspls)  # Get the index of the minimum value in Y
            cnt_before = len(list_dspls)
            # Remove the elements at max_index and min_index from both X and Y
            # It's important to remove the larger index first to avoid shifting the index of the other element
            if max_index > min_index:
                list_coor2.pop(max_index)
                list_dspls.pop(max_index)
                list_coor2.pop(min_index)
                list_dspls.pop(min_index)
            else:
                list_coor2.pop(min_index)
                list_dspls.pop(min_index)
                list_coor2.pop(max_index)
                list_dspls.pop(max_index)
            cnt_after = len(list_dspls)"""
            text = f'[{epoch+1}]\n--Loss larger than 1e6 ({loss}). Removing max and min data point for better fitting.\n'\
                    f'--Number of data (before, after) = {cnt_before}, {cnt_after}\n'
            text_in_for += text
            print(text)
            #[8-2] Reset coordinates to original values.
            x_ctr_rot, y_ctr_rot = initial_ctr_rot[0] * 0.1, initial_ctr_rot[1] * 0.1
            cone_slope = initial_cone_slope * 0.1
            dont_remove_data_yet = 5
        else:
            cone_slope -= learning_rate * grad_cone_slope * 0.00005
            dont_remove_data_yet -= 1
        
        list_grads.append([x_ctr_rot, y_ctr_rot, cone_slope])
        # The loss is very sensitive to the cone_slope, 0.005 is too big, 1e-5 might be too slow. 1e-4 too fast.

        #[9] Print progress
        text = f'  Epoch [{epoch+1}/{num_epochs}]  Loss: {loss:.6f}. Learning rate: {learning_rate:.2e}\n'\
                f'    (grad_x, grad_y, grad_cone_slope) = {grad_x:.6f}, {grad_y:.6f}, {grad_cone_slope:.6f}\n'\
                f'    (x_ctr_rot, y_ctr_rot) = {x_ctr_rot}, {y_ctr_rot}\n'
        print(text)

        #[10] Check if cone_slope becomes negative
        dont_set_cone_slope_yet -=1
        if cone_slope < 0 and dont_set_cone_slope_yet <= 0:
            cone_slope = initial_cone_slope * 100
            x_ctr_rot = x_ctr_rot + np.random.rand()*initial_lr*200-100
            y_ctr_rot = y_ctr_rot + np.random.rand()*initial_lr*200-100
            text = f'[{epoch+1}]\n--[cone_slope < 0] set cone_slope to {cone_slope} and randomize ctr_rot.\n'
            text_in_for += text
            print(text)
            dont_set_cone_slope_yet = 3

    
    df = pd.DataFrame({'Learning Rate': list_lr,
                        'Center Rotation': list_ctr_rot,
                        'Cone Slope': list_cone_slope,
                        'Gradients (x_ctr_rot, y_ctr_rot, cone_slope)': list_grads,
                        'Loss': list_loss})
    df.index.name = 'epoch'
    text_log += f'\n{tabulate(df, headers="keys", tablefmt="orgtbl")}\n\n{text_in_for}\n\n'

    print()
    #[9] Return optimized parameters and final loss
    return list_ctr_rot, list_cone_slope, list_loss, list_lr, text_log










def train_to_fit_the_invert_cone(list_coor2_x, list_coor2_y, list_d_l, initial_ctr_rot_x, initial_ctr_rot_y, initial_cone_slope, initial_lr, num_epochs, text_log):
    """
    [Goal]
        Optimizes the parameters x_ctr_rot, y_ctr_rot, and cone_slope to minimize the loss using linear regression.
    [Args]
        list_coor2: list of coordinates in (x, y)
        list_d_l: list of displacement, a single value. Just regard as the elevation of invert cone.
        ctr_rot: center of rotation (x, y) in raster coordinate.
        cone_slope: the ratio the invert cone rises for every one unit away from the center of rotation.
        learning_rate: the learning rate for gradient descent
        num_epochs: the number of epochs to train the model
    [Note]
        1. Define the origin as the upper left corner of the image.
        2. Use raster coordinate system where x-axis increases to the right and the y-axis increases downward.
    """
    print('\n[train_to_fit_the_invert_cone]')
    #[1] Initialize parameters
    assert len(list_coor2_x) == len(list_coor2_y) == len(list_d_l), "Input arrays must have the same length"
    x_ctr_rot, y_ctr_rot = initial_ctr_rot_x, initial_ctr_rot_y
    cone_slope = initial_cone_slope
    learning_rate = initial_lr

    #[2] Convert input lists to numpy arrays
    X = np.column_stack((np.array(list_coor2_x), np.array(list_coor2_y)))
    Y = np.array(list_d_l)
    # the rest of the code ... 
    
    low_loss_cnt = 0
    dont_remove_data_yet = 0
    dont_set_cone_slope_yet = 0
    list_loss, list_loss_dr = [], []
    list_lr = []
    list_ctr_rot_x = [x_ctr_rot]
    list_ctr_rot_y = [y_ctr_rot]
    list_cone_slope = [cone_slope]
    list_grad_x, list_grad_y, list_grad_cone_slope = [], [], []
    text_in_for = ''
    allow_lower_lr = max(num_epochs * 0.1, 3)

    #[3] Train the model for the specified number of epochs
    for epoch in range(num_epochs):
        #[4] Start appending from the second iteration to keep list in the same length during dataframe construction.
        if epoch >= 1:
            list_ctr_rot_x.append(x_ctr_rot)
            list_ctr_rot_y.append(y_ctr_rot)
            list_cone_slope.append(cone_slope)
        
        
        #[4] Forward pass
        #print(f'(X[:, 0], X[:, 1]): {X[:, 0]}, {X[:, 1]}')
        x_CR2P = x_ctr_rot + X[:, 0] # CR2P = Center of rotation to point
        y_CR2P = y_ctr_rot + X[:, 1]
        cone_elev = cone_slope * np.sqrt(x_CR2P**2 + y_CR2P**2)
        y_pred = cone_elev

        #[5] Calculate loss and update learning rate
        loss = np.mean((y_pred - Y)**2)
        list_loss.append(loss)
        text = ''
        
        #[10] Update learning rate
        if len(list_loss) >= 2 and loss/list_loss[-1] < 2:
            loss_decrease_ratio = loss/list_loss[-1]
            list_loss_dr.append(loss_decrease_ratio)
            text = f'loss_decrease_ratio: {loss_decrease_ratio}'
            if epoch >= int(num_epochs * 0.3) and list_loss_dr[-1] > 0.9999 and len(list_loss) > allow_lower_lr:
                learning_rate = initial_lr * 1e-1
            elif epoch >= int(num_epochs * 0.6) and list_loss_dr[-1] > 0.99999 and len(list_loss) > allow_lower_lr:
                learning_rate = initial_lr * 1e-2
            elif epoch >= int(num_epochs * 0.9) and list_loss_dr[-1] > 0.999999 and len(list_loss) > allow_lower_lr:
                learning_rate = initial_lr * 1e-3
            elif list_loss_dr[-1] > 0.9999999999 and epoch >=10:
                low_loss_cnt += 1
                if low_loss_cnt > 3:
                    #[10-1] Early stop
                    text = f'[{epoch+1}]--[Good enough] Early stop triggered by low_loss_cnt ({low_loss_cnt}) and loss_decrease_ratio ({loss_decrease_ratio}).\n'
                    text_in_for += text
                    print(text)
                    #[10-2] Make lengths of the lists in the dataframe the same.
                    list_lr.append(learning_rate)
                    grad_x = np.mean(2 * (y_pred - Y) * cone_slope * x_CR2P / np.sqrt(x_CR2P**2 + y_CR2P**2))
                    grad_y = np.mean(2 * (y_pred - Y) * cone_slope * y_CR2P / np.sqrt(x_CR2P**2 + y_CR2P**2))
                    grad_cone_slope = np.mean(2 * (y_pred - Y) * np.sqrt(x_CR2P**2 + y_CR2P**2))
                    list_grad_x.append(grad_x)
                    list_grad_y.append(grad_y)
                    list_grad_cone_slope.append(grad_cone_slope)
                    break
                learning_rate = initial_lr * 1e-4
        else:
            list_loss_dr.append(None)
        list_lr.append(learning_rate)
        
        #[6] Record
        

        #[7] Backward pass (gradient calculation)
        grad_x = np.mean(2 * (y_pred - Y) * cone_slope * x_CR2P / np.sqrt(x_CR2P**2 + y_CR2P**2))
        grad_y = np.mean(2 * (y_pred - Y) * cone_slope * y_CR2P / np.sqrt(x_CR2P**2 + y_CR2P**2))
        grad_cone_slope = np.mean(2 * (y_pred - Y) * np.sqrt(x_CR2P**2 + y_CR2P**2))

        #[8] Update parameters
        x_ctr_rot -= learning_rate * grad_x
        y_ctr_rot -= learning_rate * grad_y
        cone_slope -= learning_rate * grad_cone_slope * 1e-10
        """if loss > 1e20:
            cone_slope = initial_cone_slope
            max_index = np.argmax(list_d_l)  # Get the index of the maximum value in Y
            min_index = np.argmin(list_d_l)  # Get the index of the minimum value in Y
            cnt_before = len(list_d_l)
            # Remove the elements at max_index and min_index from both X and Y
            # It's important to remove the larger index first to avoid shifting the index of the other element
            if max_index > min_index:
                list_coor2_x.pop(max_index)
                list_coor2_y.pop(max_index)
                list_d_l.pop(max_index)
                list_coor2_x.pop(min_index)
                list_coor2_y.pop(min_index)
                list_d_l.pop(min_index)
            else:
                list_coor2_x.pop(min_index)
                list_coor2_y.pop(min_index)
                list_d_l.pop(min_index)
                list_coor2_x.pop(max_index)
                list_coor2_y.pop(max_index)
                list_d_l.pop(max_index)
            cnt_after = len(list_d_l)
            text = f'[{epoch+1}]\n--Loss larger than 1e20 ({loss}). Removing max and min data point for better fitting.\n'\
                    f'--Number of data (before, after) = {cnt_before}, {cnt_after}\n'
            text_in_for += text
            print(text)
        elif loss > 1e6 and dont_remove_data_yet <= 0:
            #[8-2] Reset coordinates to original values.
            reduce_ctr_rot = 0.1
            x_ctr_rot, y_ctr_rot = initial_ctr_rot_x * reduce_ctr_rot, initial_ctr_rot_y * reduce_ctr_rot
            cone_slope = initial_cone_slope * reduce_ctr_rot
            text = f'[{epoch+1}]\n--Loss larger than 1e6 ({loss}). Reinitialize x_ctr_rot, y_ctr_rot, and cone_slope use {reduce_ctr_rot} times the original value.\n'
            text_in_for += text
            print(text)
            dont_remove_data_yet = 5
        else:
            cone_slope -= learning_rate * grad_cone_slope * 0.00005
            dont_remove_data_yet -= 1"""
        
        list_grad_x.append(grad_x)
        list_grad_y.append(grad_y)
        list_grad_cone_slope.append(grad_cone_slope)
        # The loss is very sensitive to the cone_slope, 0.005 is too big, 1e-5 might be too slow. 1e-4 too fast.

        #[9] Print progress
        text = f'  Epoch [{epoch+1}/{num_epochs}]  Loss: {loss:.6f}. Learning rate: {learning_rate:.2e}\n'\
                f'    (grad_x, grad_y, grad_cone_slope) = {grad_x:.6f}, {grad_y:.6f}, {grad_cone_slope:.6f}\n'\
                f'    (x_ctr_rot, y_ctr_rot, cone_slope) = {x_ctr_rot}, {y_ctr_rot}, {cone_slope}\n'
        print(text)

        #[10] Check if cone_slope becomes negative
        dont_set_cone_slope_yet -=1
        if cone_slope < 0 and dont_set_cone_slope_yet <= 0:
            cone_slope = initial_cone_slope * 100
            x_ctr_rot = x_ctr_rot + np.random.rand()*initial_lr*200-100
            y_ctr_rot = y_ctr_rot + np.random.rand()*initial_lr*200-100
            text = f'[{epoch+1}]\n--[cone_slope < 0] set cone_slope to {cone_slope} and randomize ctr_rot.\n'
            text_in_for += text
            print(text)
            dont_set_cone_slope_yet = 3

    
    #[18] Dataframe length check.
    print(f'[list_lr] {len(list_lr)}')
    print(f'[list_ctr_rot_x] {len(list_ctr_rot_x)}')
    print(f'[list_ctr_rot_y] {len(list_ctr_rot_y)}')
