def cubic_window_loss_search(arrimg2, 
                            arrimg1, 
                            list_x, list_y, list_r,
                            dic_hyperp,
                            text_log):
    
    #[3] Unpacking the dictionary into individual variables
    scope_penalty = dic_hyperp['scope_penalty']  
    loss_cal_selection = dic_hyperp['loss_cal_selection']
    power_of = dic_hyperp['power_of']
    

    #[7] Create meshgrid
    X_mesh, Y_mesh, Z_mesh = np.meshgrid(list_x, list_y, list_r)
    
    #[10] Calculate losses for each position
    list_loss_eff = []
    for cnt, (x, y, z) in enumerate(zip(np.ravel(X_mesh), np.ravel(Y_mesh), np.ravel(Z_mesh))):
        print(f'[{cnt}] {x:.2f}, {y:.2f}, {z:0.4f}. ', end = '\t')
        iter_shift = [x, y, z]
        arrimg1_rot = rotate_image(arrimg1, iter_shift)
        
        #[12] Calculate loss
        loss, pixel_eff, loss_eff, text = arrimg_subtraction_loss_selector(loss_cal_selection, 
                                                                        arrimg2, arrimg1_rot, 
                                                                        iter_shift, 
                                                                        power_of, 
                                                                        scope_penalty)
        list_loss_eff.append(loss_eff)
        
    arr_loss_eff = np.array(list_loss_eff).reshape(X_mesh.shape)
    
    #[15] Get the position of the minimum loss
    min_loss_idx = np.unravel_index(np.argmin(arr_loss_eff, axis=None), arr_loss_eff.shape)
    min_loss_value = arr_loss_eff[min_loss_idx]
    
    #[17] Return the index of point with minimum loss
    text = f'\n--[min_loss_idx] {min_loss_idx}\n'\
           f'--  x, y, r, loss_eff: {X_mesh[min_loss_idx]}, {Y_mesh[min_loss_idx]}, {Z_mesh[min_loss_idx]}, {arr_loss_eff[min_loss_idx]}\n'
    text_log += text
    
    return (X_mesh, Y_mesh, Z_mesh, arr_loss_eff, min_loss_idx, text_log)


    




















def compute_gradients_with_tx_rot(loss_cal_selection, 
                                    arrimg1, arrimg2, 
                                    loss, loss_eff, 
                                    tx, dir2ctr_x, dir2ctr_y, rot_degree, 
                                    scope_penalty, 
                                    eps, rot_eps_constraint):
    #[1] Gradient with respect to ctr_rot_x
    tx_plus = tx + eps
    ctr_rot_x = dir2ctr_x * tx_plus
    ctr_rot_y = dir2ctr_y * tx_plus
    shift_tx_plus = [ctr_rot_x, ctr_rot_y, rot_degree]
    arrimg1_tx_plus = rotate_image(arrimg1, shift_tx_plus)
    loss_tx_plus, _, loss_eff_tx_plus, _ = arrimg_subtraction_loss_mse_normal(loss_cal_selection, 
                                                                       arrimg2, arrimg1_tx_plus, 
                                                                       shift_tx_plus, scope_penalty)
    grad_tx = (loss_eff_tx_plus - loss_eff) / eps

    #[2] Gradient with respect to rot_degree
    angle_eps = eps * rot_eps_constraint
    r_plus = rot_degree + angle_eps
    ctr_rot_x = dir2ctr_x * tx
    ctr_rot_y = dir2ctr_y * tx
    shift_r_plus = [ctr_rot_x, ctr_rot_y, r_plus]
    arrimg1_r_plus = rotate_image(arrimg1, shift_r_plus)
    loss_r_plus, _, loss_eff_r_plus, _ = arrimg_subtraction_loss_mse_normal(loss_cal_selection, 
                                                                     arrimg2, arrimg1_r_plus, 
                                                                     shift_r_plus, scope_penalty)
    grad_r = (loss_eff_r_plus - loss_eff) / angle_eps
    
    #[3] Print text for debugging. (Don't change the spaces here, it will affect the tab.)
    text =  f'--tx, tx_plus, shift_tx_plus:             \t{tx:.10f}, \t{tx_plus:.10f}, \t{shift_tx_plus}\n'\
            f'--rot_degree, r_plus, shift_r_plus:       \t{rot_degree:.10f},     \t{r_plus:.10f},     \t{shift_r_plus}\n'\
            f'----loss_eff_tx_plus, loss_eff, grad_tx:    \t{loss_eff_tx_plus:.10f},    \t{loss_eff:.10f}, \t{grad_tx:.10f}\n'\
            f'----loss_eff_r_plus, loss_eff, grad_r:    \t{loss_eff_r_plus:.10f}, \t{loss_eff:.10f}, \t{grad_r:.10f}\n'
    #print(text)
    return (grad_tx, grad_r, text)






def train_tx_rot_to_minimize_substraction_loss_eff(arrimg2, arrimg1, 
                                                init_tx, dir2ctr_x, dir2ctr_y, init_rot_degree,
                                                scope_penalty, eps, init_lr, num_epochs, text_log):
    """
    [Goal]
        arrimg2, arrimg1 are two images but shifted (translation + rotation) a little bit.
        Optimizes the parameters t and, rot_degree to minimize the loss using linear regression.
        t is a step that controls the point moves along a line to create center of rotation.
        
    [Args]
        arrimg2: image after rotated (rotation with x, y, c)
        arrimg1: image before rotated.
        tx: step in s direction torward center of rotation
        dir2ctr_x: x coordinate of direction to the center.
        dir2ctr_y: y coordinate of direction to the center.
        rot_degree: the degree the arrimg1 should be rotated to coincide with arrimg2. 
        init_lr: the learning rate for gradient descent
        num_epochs: the number of epochs to train the model
        text_log: log file
    [Note]
        1. Define the origin as the upper left corner of the image as the raster coordinate do.
        2. Use raster coordinate system where x-axis increases to the right and the y-axis increases downward.
    """
    print('\n[train_to_fit_the_invert_cone]')
    
    
    #[1] Initialize parameters
    tx = init_tx
    ctr_rot_x =  dir2ctr_x * init_tx
    ctr_rot_y = dir2ctr_y * init_tx
    rot_degree = init_rot_degree
    
    #[2] Hyperparameter settings
    loss_cal_selection = 1
    rot_eps_constraint = 1
    rot_update_constraint = 1    
    # 1 Means no constraint, use 1e-1 or 1e-2 if necessary. 
    # AdamOptimizer_track_lr might have already done a good job for us.
    min_epoch = num_epochs*0.3
    power_of = 2
     
    #[3] Initiate AdamOptimizer_track_lr 
    tx_optimizer = AdamOptimizer_track_lr(lr=init_lr, beta1=0.8, beta2=0.999, epsilon=eps)
    rot_optimizer = AdamOptimizer_track_lr(lr=init_lr, beta1=0.8, beta2=0.999, epsilon=eps)
 
    #[4] Define numbers and objects.
    list_tx, list_x, list_y, list_r = [tx], [ctr_rot_x], [ctr_rot_y], [rot_degree]
    list_loss, list_loss_eff, list_pixel_eff = [], [], []
    list_grad_tx, list_grad_r = [], []
    text_in_for_loop = ''
    
    #[5] Print initial valuse
    text = f'\n[Initial Value]\t(tx, ctr_rot_x, ctr_rot_y, rot_degree) = {tx:.10f}, {ctr_rot_x:.10f}, {ctr_rot_y:.10f}, {rot_degree:.10f}\n'
    print(text)
    text_log += text
    
    #[8] Train the model for the specified number of epochs
    for epoch in range(num_epochs):
        #[10] Start appending from the second iteration to keep list in the same length during dataframe construction.
        if epoch >= 1:
            list_tx.append(tx)
            list_x.append(ctr_rot_x)
            list_y.append(ctr_rot_y)
            list_r.append(rot_degree)
            
        
        #[11] Rotate arrimg1 with current_proposed_shift.
        current_proposed_shift = [ctr_rot_x, ctr_rot_y, rot_degree]
        arrimg1_rot = rotate_image(arrimg1, current_proposed_shift)
        
        #[12] Calculate loss
        (loss, pixel_eff, loss_eff, text) = arrimg_subtraction_loss_selector(loss_cal_selection, 
                                                                        arrimg2, arrimg1_rot, 
                                                                        current_proposed_shift, 
                                                                        power_of, 
                                                                        scope_penalty)
        list_loss.append(loss)
        list_pixel_eff.append(pixel_eff)
        list_loss_eff.append(loss_eff)

        #[15] Backward pass (gradient calculation)
        (grad_tx, 
         grad_r, 
         text) = compute_gradients_with_tx_rot(loss_cal_selection, 
                                                arrimg1, arrimg2, 
                                                loss, loss_eff, 
                                                tx, dir2ctr_x, dir2ctr_y, rot_degree, 
                                                scope_penalty, 
                                                eps, rot_eps_constraint)
        
        #[16] Record gradients
        text_in_for_loop += f'\nEpoch [{epoch+1}/{num_epochs}] eps: {eps} \n{text}'
        list_grad_tx.append(grad_tx)
        list_grad_r.append(grad_r)

        #[18] Update primary parameters using Adam optimizer
        tx -= tx_optimizer.update(grad_tx)
        rot_degree -= rot_optimizer.update(grad_r) * rot_update_constraint
        
        #[19] Update secondary parameters
        ctr_rot_x = dir2ctr_x * tx
        ctr_rot_y = dir2ctr_y * tx
        current_proposed_shift = ctr_rot_x, ctr_rot_y, rot_degree
        
        #[20] Find lowest list_loss_eff
        lowest_loss_eff = np.min(list_loss_eff)
        last_five_loss_eff = list_loss_eff[-5:]

        #[21] Check if the lowest loss efficiency is NOT in the last five records
        if (lowest_loss_eff not in last_five_loss_eff) and (epoch >= min_epoch):
            text = f'\nEpoch [{epoch+1}/{num_epochs}]--[Good enough] lowest_loss_eff ({lowest_loss_eff:2f}) is not in the last_five_loss_eff.\n'\
                    f'last_five_loss_eff: {last_five_loss_eff}'
            text_in_for_loop += text
            print(text)
            break


        """#[25] Check if rot_degree accidently become zero
        if rot_degree == 0:
            rot_degree = list_r[-1] """
            
        #[26] Print progress
        text =  f'\nEpoch [{epoch+1}/{num_epochs}] loss_eff: \t{loss_eff:.0f}.\n'\
                f'    (grad_tx, grad_r) =                   \t{grad_tx:.4f}, \t{grad_r:.4f}\n'\
                f'    (tx, ctr_rot_x, ctr_rot_y, rot_degree) = \t{tx:.4f}, \t{ctr_rot_x:.4f}, \t{ctr_rot_y:.4f}, \t{rot_degree:.4f}'
        print(text)

    #[30] Gather learning rate from Adam optimizer after training
    list_lr_tx = tx_optimizer.lr_history  # Access as attribute (with out "()"), not method (with "()").
    list_lr_rot = rot_optimizer.lr_history 
    
    #[33] Dataframe length check.
    df_length_check = False
    if df_length_check:
        print(f'[lr_hist_tx] {len(list_lr_tx)}')
        print(f'[list_lr_rot] {len(list_lr_rot)}')
        print(f'[list_grad_tx] {len(list_grad_tx)}')
        print(f'[list_grad_r] {len(list_grad_r)}')
        print(f'[list_x] {len(list_tx)}')
        print(f'[list_x] {len(list_x)}')
        print(f'[list_y] {len(list_y)}')
        print(f'[list_r] {len(list_r)}')
        print(f'[list_loss] {len(list_loss)}')
        print(f'[list_loss_eff] {len(list_loss_eff)}')
        print(f'[list_pixel_eff] {len(list_pixel_eff)}')
    
    #[34] Create dataframe for the training process.
    df_train_recrod_txrot = pd.DataFrame({
                            'list_lr_tx': list_lr_tx,
                            'list_lr_rot': list_lr_rot,
                            'list_grad_tx': list_grad_tx,
                            'list_grad_r': list_grad_r,
                            'list_tx': list_tx,
                            'list_x': list_x,
                            'list_y': list_y,
                            'list_r': list_r,
                            'list_loss': list_loss,
                            'list_loss_eff': list_loss_eff,
                            'list_pixel_eff': list_pixel_eff,
                        })

    df_train_recrod_txrot.index.name = 'epoch'
    text_log += f'\n{tabulate(df_train_recrod_txrot, headers="keys", tablefmt="orgtbl", floatfmt=".10f")}\n\n{text_in_for_loop}\n\n'
    print()
    #[35] Return optimized parameters and final loss
    return (df_train_recrod_txrot, text_log)


























def recover_lists_from_df_train_recrod_txrot(df_train_record_txrot):
    """
    This function reads the following dataframe into lists
    df_train_recrod = pd.DataFrame({ 'list_lr_tx': list_lr_tx,
                            'list_lr_rot': list_lr_rot,
                            'list_grad_tx': list_grad_tx,
                            'list_grad_r': list_grad_r,
                            'list_tx': list_tx,
                            'list_x': list_x,
                            'list_y': list_y,
                            'list_r': list_r,
                            'list_loss': list_loss,
                            'list_loss_eff': list_loss_eff,
                            'list_pixel_eff': list_pixel_eff,
                        })
    """
    #[1] Extracting each list from the dataframe columns
    list_lr_tx = df_train_record_txrot['list_lr_tx'].tolist()
    list_lr_rot = df_train_record_txrot['list_lr_rot'].tolist()
    list_grad_tx = df_train_record_txrot['list_grad_tx'].tolist()
    list_grad_r = df_train_record_txrot['list_grad_r'].tolist()
    list_tx = df_train_record_txrot['list_tx'].tolist()
    list_x = df_train_record_txrot['list_x'].tolist()
    list_y = df_train_record_txrot['list_y'].tolist()
    list_r = df_train_record_txrot['list_r'].tolist()
    list_loss = df_train_record_txrot['list_loss'].tolist()
    list_loss_eff = df_train_record_txrot['list_loss_eff'].tolist()
    list_pixel_eff = df_train_record_txrot['list_pixel_eff'].tolist()
    
    #[2] Return the index of the row with lowest 
    idx_lowest_loss_eff = df_train_record_txrot['list_loss_eff'].idxmin()
    
    return (list_lr_tx, list_lr_rot,
            list_grad_tx, list_grad_r,
            list_tx, list_x, list_y, list_r,
            list_loss, list_loss_eff, list_pixel_eff), idx_lowest_loss_eff









