def plot_loss_and_learning_rate_record(list_loss, list_loss_eff, list_lr, iter_bsn, text_note, path_save):
    epochs = range(1, len(list_loss) + 1)  # Assuming epochs start from 1 to the length of list_loss
    fig, ax1 = plt.subplots(figsize=(8, 4))

    #[1] Plot Loss and Effective Loss on primary axis
    fs_axis = 16
    fs_title = 20
    fs_info = 12
    ax1.set_xlabel('Epoch', fontsize = fs_axis)
    ax1.set_ylabel('Loss', fontsize = fs_axis)  # Normal axis color for loss
    ax1.plot(epochs, list_loss, 'orange', label='Loss')  # Loss curve in orange
    
    #[2] Calculate scaling factor for effective loss
    mean_list_loss = np.mean(list_loss)
    mean_list_loss_eff = np.mean(list_loss_eff)
    ratio = mean_list_loss / mean_list_loss_eff
    mag_diff_zeros = int(math.log10(ratio)) 
    first_number = math.floor(ratio / (10 ** mag_diff_zeros))
    loss_eff_mtp = first_number * (10 ** mag_diff_zeros)
    
    #[3] Scale smaller list_loss_eff for better plotting.
    ax1.plot(epochs, [x * loss_eff_mtp for x in list_loss_eff], 'turquoise', label=f'Effective Loss x{loss_eff_mtp:.1e}')  # Effective Loss curve
    ax1.tick_params(axis='y')
    ax1.set_title(f'Training Loss and Learning Rate of {iter_bsn}', fontsize = fs_title)
    ax1.legend(loc='upper left')

    #[2] Display the additional text without a border using plt.figtext()
    plt.figtext(0.10, 0.80, text_note, fontsize=fs_info,
                verticalalignment='top', horizontalalignment='left',
                color='black', fontfamily='monospace')  # Specifying monospace font

    #[3] Plot Learning Rate on secondary axis
    ax2 = ax1.twinx()
    ax2.set_ylabel('Learning Rate', fontsize = fs_axis)  # Normal axis color for learning rate
    ax2.plot(epochs, list_lr, color='green', label='Learning Rate')  # Learning rate curve in green
    ax2.tick_params(axis='y')
    
    list_lr_max, list_lr_min = max(list_lr), min(list_lr)
    ax2.set_ylim(list_lr_min*0.1, list_lr_max*10)
    ax2.set_yscale('log')  # Log scale for learning rate

    fig.tight_layout()
    plt.savefig(path_save)




def plot_2loss_and_2learning_rate_record(list_loss, list_loss_eff, list_lr_tx, list_lr_rot, iter_bsn, text_note, path_save):
    epochs = range(1, len(list_loss) + 1)  # Assuming epochs start from 1 to the length of list_loss
    fig, ax1 = plt.subplots(figsize=(8, 8))

    #[1] Plot Loss and Effective Loss on primary axis
    fs_axis = 16
    fs_title = 20
    fs_info = 12
    ax1.set_xlabel('Epoch', fontsize = fs_axis)
    ax1.set_ylabel('Loss', fontsize = fs_axis)  # Normal axis color for loss
    
    #[2] Calculate scaling factor for effective loss
    mean_list_loss = np.mean(list_loss)
    mean_list_loss_eff = np.mean(list_loss_eff)
    ratio = mean_list_loss / mean_list_loss_eff
    mag_diff_zeros = int(math.log10(ratio))
    first_number = math.floor(ratio / (10 ** mag_diff_zeros))
    loss_eff_mtp = first_number * (10 ** mag_diff_zeros)
    list_loss_eff_adj = [x * loss_eff_mtp for x in list_loss_eff]

    #[3] Plot Loss and Effective Loss on primary axis
    l1 = ax1.plot(epochs, list_loss, 'orange', label='Loss')
    l2 = ax1.plot(epochs, list_loss_eff_adj, 'turquoise', label=f'Effective Loss x{loss_eff_mtp:.1e}')  # Effective Loss curve
    
    #[4] Set ylim for ax1
    list_lr_max, list_lr_min = max(max(list_loss), max(list_loss_eff_adj)), min(min(list_loss), min(list_loss_eff_adj))
    ax1.set_ylim(list_lr_min * 0.9, list_lr_max * 1.1)
    ax1.tick_params(axis='y')
    ax1.set_title(f'Training Loss and Learning Rate of {iter_bsn}', fontsize = fs_title)

    #[6] Plot Learning Rate on secondary axis
    ax2 = ax1.twinx()
    ax2.set_ylabel('Learning Rate', fontsize = fs_title) 
    l3 = ax2.plot(epochs, list_lr_tx, color='green', label='Learning rate of tx', linestyle='-')
    l4 = ax2.plot(epochs, list_lr_rot, color='lawngreen', label='Learning rate of rot', linestyle='-')

    #[8] Set ylim for ax2
    list_lr_max, list_lr_min = max(max(list_lr_tx), max(list_lr_rot)), min(min(list_lr_tx), min(list_lr_rot))
    ax2.set_ylim(list_lr_min * 0.8, list_lr_max * 1.1)
    ax2.tick_params(axis='y')

    #[9] Combine legends from both axes
    handles, labels = [], []
    for l in [l1, l2, l3, l4]:
        handles.extend(l)
        labels.extend([h.get_label() for h in l])
    ax1.legend(handles, labels, loc='upper right')

    #[7] Adding the additional text with monospace font.
    plt.subplots_adjust(left=0.1, right=0.90, bottom=0.3, top=0.9)
    plt.figtext(0.05, 0.25, text_note, fontsize=fs_info, va="top", ha="left", fontfamily='monospace')

    #[8] Save the figure
    plt.savefig(path_save)







def plot_2D_optimization_process_xyLoss_old(list_x, list_y, title_x, title_y, list_loss, list_marker_idx, title_plot, text_note, path_save):
    """
    Plot control rotation points with sizes based on cone slope values and a color gradient.

    :param list_ctr_rot: List of [x, y] coordinates.
    :param list_cone_slope: List of cone slope values to determine the size of each point.
    :param path_save: Path where the plot will be saved.
    """
    xy_same_range = False
    flip_y_axis = False
    
    #[1] Create figure and 3D axis
    fig, ax = plt.subplots(figsize=(8, 8))
    fs_axis = 14
    fs_title = 18
    fs_info = 12
    
    #[2] Convert lists to numpy array for easier manipulation
    xs = np.array(list_x)
    ys = np.array(list_y)
    
    #[3] Normalize epoch from 0 to 1 for viridis color bar.
    arr_loss = np.array(list_loss)
    arr_epoch = np.arange(len(arr_loss))
    norm = Normalize(vmin=arr_epoch.min(), vmax=arr_epoch.max())
    colors = [plt.cm.viridis(norm(epoch)) for epoch in arr_epoch]
    
    #[6] Normalize loss values for size scaling
    min_loss, max_loss = arr_loss.min(), arr_loss.max()
    arr_norm_loss = (arr_loss - min_loss) / (max_loss - min_loss) * 200 + 50
    
    #[7-1] Plot each point with size corresponding to its loss value.
    sc = ax.scatter(xs, ys, s=arr_norm_loss, c=colors, alpha=0.7)
    #[7-2] Mark the first and last points with special markers.
    ax.scatter(xs[0], ys[0], marker='+', s=400, color='chartreuse')      # GT
    #[7-3] Add other special markers list_marker_idx = [1st_end, 2nd_start, opt]
    ax.scatter(xs[list_marker_idx[0]], ys[list_marker_idx[0]], marker='+', s=300, color='dodgerblue')        # Start
    ax.scatter(xs[list_marker_idx[-1]], ys[list_marker_idx[-1]], marker='*', s=300, color='red', alpha=0.5)        # Opt
    
    #[8] Determine the range for the axes
    if xy_same_range:
        range_x = np.max(xs) - np.min(xs)
        range_y = np.max(ys) - np.min(ys)
        range_for_xy = max(range_x, range_y) * 2  # Need to be larger. 1.5 will Miss the first point.
        xlim_min, xlim_max = np.mean(xs) - 0.5 * range_for_xy, np.mean(xs) + 0.5 * range_for_xy
        ylim_min, ylim_max = np.mean(ys) - 0.5 * range_for_xy, np.mean(ys) + 0.5 * range_for_xy
        
        #[9] Use the broader of the ranges to set both axes
        ax.set_xlim(xlim_min, xlim_max)
        ax.set_ylim(ylim_min, ylim_max)
    
    #[12] Labels and title.
    ax.set_xlabel(title_x, fontsize=fs_axis)
    ax.set_ylabel(title_y, fontsize=fs_axis)
