def putTextSmooth(image, text, org, fontFace, fontScale, color, thickness, smooth_iterations=3):
    for i in range(smooth_iterations):
        # Draw the text with decreasing thickness
        current_thickness = max(thickness - i, 1)
        cv2.putText(image, text, org, fontFace, fontScale, color, current_thickness, cv2.LINE_AA)


def plot_2D_scatter(list_x, list_y, title_x, title_y, ylim, title_plot, path_save=None):
    #[1] Create figure and axis
    fig, ax = plt.subplots(figsize=(12, 12))
