    fs_title = 44
    fs_tick = 28
    
    #[2] Plot each point with size corresponding to its loss value
    size = 160
    sc = ax.scatter(np.array(list_x), np.array(list_y), s=size, 
                    c=np.array(list_y), cmap='cool', alpha=0.5, edgecolors='none')

    #[3] Labels and title
    ax.set_xlabel(f'{title_x}', fontsize=fs_axis)
    ax.set_ylabel(f'{title_y}', fontsize=fs_axis)
    ax.set_xlim(0, max(list_x)*1.05)
    
    if ylim: 
        ax.set_ylim(ylim)
        
