    text_put = f'Total Points: {len(list_x)}'  # Example text
    fontScale, thickness = 1.2, 2  # Font size and thickness
    putTextSmooth(arr_plot, text_put, org, fontFace, fontScale, color, thickness, smooth_iterations=3)
    
    return arr_plot


