def check_image_size(list_paths):
    #[1] Supported image file extensions
    list_ext = ['.jpg', '.jpeg', '.png']
    
    #[2] Initialize lists to store data
    list_bsn = []  # Base filenames
    list_h = []    # Heights
    list_w = []    # Widths
    
    for path in list_paths:
        ext = os.path.splitext(path)[1].lower()  # Get file extension in lowercase
        if ext in list_ext:
            try:
                with Image.open(path) as img:
                    width, height = img.size  # Get image dimensions
                    list_bsn.append(os.path.basename(path))  # Store base filename
                    list_h.append(height)  # Store height
                    list_w.append(width)   # Store width
            except Exception as e:
                print(f"Error reading image {path}: {e}")
    
    #[3] Determine if all images have the same size
    if len(list_h) > 0 and len(list_w) > 0:
        if_same_size = all((h == list_h[0] and w == list_w[0]) for h, w in zip(list_h, list_w))
    else:
        if_same_size = False
    
    #[4] Combine data into a DataFrame
    df_image_size = pd.DataFrame({
        "Filename": list_bsn,
        "Height": list_h,
        "Width": list_w
    })
    print(tabulate(df_image_size, headers='keys', tablefmt='orgtbl'))
    
    return df_image_size, if_same_size


def reduce_image_size_with_exif(path_img, resize_ratio=None, path_save=None):
    print(f'\n[reduce_image_size_with_exif] \t{os.path.basename(path_img)}, \tresize_ratio = {resize_ratio},', end='')

    # [1] Read the image using PIL to retain EXIF data
    try:
        pil_img = Image.open(path_img)
        exif_data = pil_img.info.get('exif')
        arrimg = cv2.cvtColor(np.array(pil_img), cv2.COLOR_RGB2BGR)  # Convert to OpenCV format
    except Exception as e:
        raise FileNotFoundError(f"Failed to open image at path '{path_img}'. Error: {e}")

    # [2] Resize the image
    if resize_ratio:
        if not resize_ratio < 2:
            raise ValueError(f'It is advisable to have resize_ratio less than 2. Please check. {resize_ratio}')
        h, w = arrimg.shape[:2]
        new_width = int(w * resize_ratio)
        new_height = int(h * resize_ratio)
        new_pixel = new_width * new_height
        print(f'\t(new_width, new_height, new_pixel) = {new_width}, {new_height}, {new_pixel}')
        arrimg_reduced = cv2.resize(arrimg, (new_width, new_height), interpolation=cv2.INTER_NEAREST)
    else:
        arrimg_reduced = arrimg

    # [3] Save the image with EXIF data
    if path_save:
        try:
            reduced_pil_img = Image.fromarray(cv2.cvtColor(arrimg_reduced, cv2.COLOR_BGR2RGB))
            if exif_data:
                reduced_pil_img.save(path_save, exif=exif_data)
            else:
                reduced_pil_img.save(path_save)
        except Exception as e:
            raise IOError(f"Failed to save image at path '{path_save}'. Error: {e}")

    return arrimg_reduced

#[3] Image Size Reduction - End

