def run_python_file_after_button_click(path_py, *args):
    global current_process
    def run_subprocess():
        global current_process
        #[1] Get the directory from the entry field (if required)
        dir_working = working_dir_entry.get() if 'dir_working' in args else None
        if 'dir_working' in args and not dir_working:
            terminal_output.insert(tk.END, "Error: Please specify a working directory.\n")
            terminal_output.see(tk.END)  # Ensure the message is visible
            root.update()  # Update the GUI dynamically
            return
        
        try:
            #[2] Command to run the Python file with optional arguments
            command = ["python", path_py]
            if dir_working:
                command.append(dir_working)
            
            #[3] Clear the terminal output and display the initial message
            terminal_output.delete(1.0, tk.END)
            text_opening = f'Starting {path_py} with parameters: {args}. \nMight take a few seconds to start the subprocess. Please wait.\n\n'
            terminal_output.insert(tk.END, text_opening)
            terminal_output.see(tk.END)  # Ensure the message is visible
            root.update()  # Update the GUI dynamically

            #[4] Run the command and capture the output
            current_process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
            
            #[5] Read the output line by line and update the terminal dynamically
            while current_process.poll() is None:  # Check if the process is still running
                line = current_process.stdout.readline()
                if not line:  # Break the loop if there is no more output
                    break
                terminal_output.insert(tk.END, line)  # Insert the new output
                terminal_output.see(tk.END)           # Scroll to the latest line
                root.update()                         # Update the GUI dynamically
            
            #[6] Capture and display any errors
            stdout, stderr = current_process.communicate()
            if stdout:
                terminal_output.insert(tk.END, stdout)
            if stderr:
                terminal_output.insert(tk.END, f"Errors:\n{stderr}\n")
            terminal_output.see(tk.END)
        except Exception as e:
            terminal_output.insert(tk.END, f"Error running the Python file: {str(e)}\n")
            terminal_output.see(tk.END)
        finally:
            current_process = None
    
    # Run the subprocess in a separate thread
    thread = threading.Thread(target=run_subprocess)
    thread.start()

def terminate_subprocess_on_close():
    global current_process
    if current_process and current_process.poll() is None:  # Check if the subprocess is running
        current_process.terminate()  # Terminate the subprocess
        current_process = None  # Clear the reference
    root.destroy()  # Close the application

