def point_to_line_distance(point, line_start, line_end):
    line_vec = line_end - line_start
    point_vec = point - line_start
    line_len = np.linalg.norm(line_vec)
    line_unitvec = line_vec / line_len
    projection = np.dot(point_vec, line_unitvec)
    closest_point = line_start + projection * line_unitvec
    distance = np.linalg.norm(point - closest_point)
    return distance

def integer_combination_close_to_line(arr_input, range_ratio, arr_mag = [0.5, 0.5, 10], to_line=1):
    """
    A line can be drawn from point_start to point_end.
    Around this line with distance of to_line is a cylinder.
    list every integer data point in this cylinder into a dataframe.
    
    """
    print('\n[integer_combination_close_to_line]')
    #[1] Enlarge the last element of the array.
    arr_input_r_mag = np.multiply(np.array(arr_input), arr_mag)
    
    #[2] Adjust to_line distanct according to magnification.
    to_line = to_line / np.linalg.norm(arr_mag)

    #[3] Define start and end.
    point_start = arr_input_r_mag / range_ratio
    point_end = arr_input_r_mag * range_ratio
    print(f'--Point (start, input, end) = {point_start}, {arr_input_r_mag}, {point_end}')
    
    #[4] Define the bounding box for the search space
    min_bounds = np.floor(np.minimum(point_start, point_end) - to_line).astype(int)
    max_bounds = np.ceil(np.maximum(point_start, point_end) + to_line).astype(int)
    
    #[5] Iterate through possible integer combinations within the bounding box
    valid_points = []
    for x in range(min_bounds[0], max_bounds[0] + 1):
        print(f' x={x} ', end='')
        for y in range(min_bounds[1], max_bounds[1] + 1):
            for z in range(min_bounds[2], max_bounds[2] + 1):
                point = np.array([x, y, z])
                if point_to_line_distance(point, point_start, point_end) <= to_line:
                    valid_points.append(point)
    
    #[6] Normalize valid points
    valid_points = np.divide(np.array(valid_points), arr_mag)
    
    #[6] Store the valid points in a DataFrame
    df_cylinder = pd.DataFrame(valid_points, columns=['x', 'y', 'z'])
    cnt = len(df_cylinder)
    print(f'--Data point count: {cnt}')
    
    return df_cylinder, cnt



def plot_df_cylinder_in_3D(df_cylinder, path_save, flip_y_axis=True):
    """
    Visualize the datapoints in 3D.
    """
    fig = plt.figure(figsize=(10, 8))
    ax = fig.add_subplot(111, projection='3d')
    k = 3
    
    #[1] Extracting the x, y, z coordinates from the DataFrame
    x = df_cylinder['x']
    y = df_cylinder['y']
    z = df_cylinder['z']
    
    #[2] Plotting the points
    ax.scatter(x, y, z, c='blue', marker='o', alpha=0.01)
    
    #[3] Optionally flip the y-axis
    if flip_y_axis:
        ax.invert_yaxis()
    
    #[4] Labels
    ax.set_xlabel('X axis')
    ax.set_ylabel('Y axis')
    ax.set_zlabel('Z axis')
    
    #[5] Setting z limit to k times its range
    x_range = x.max() - x.min()
    x_mid = (x.max() + x.min()) / 2
    ax.set_zlim(x_mid - k * x_range / 2, x_mid + k * x_range / 2)
    y_range = y.max() - y.min()
    y_mid = (y.max() + y.min()) / 2
    ax.set_zlim(y_mid - k * y_range / 2, y_mid + k * y_range / 2)
    z_range = z.max() - z.min()
    z_mid = (z.max() + z.min()) / 2
    ax.set_zlim(z_mid - k * z_range / 2, z_mid + k * z_range / 2)
    
    #[6] Title
    ax.set_title('3D Visualization of Integer Points in Cylinder')
    
    #[6] Save or show plot
    plt.savefig(path_save)
    print(f'Plot saved at {path_save}')
    
    return fig, ax




