list_last_loss = []
list_avg_x_vector, list_avg_y_vector = [], []
list_opt_ctr_rot_x, list_opt_ctr_rot_y, list_opt_cone_slope = [], [], []

#[10] Take data from one dataframe, which is the matching result from 2 images.
for cnt, (iter_df, iter_text_title) in enumerate(zip(list_of_dfs, list_of_sheetnames)):
    #[11] Text log for every pari of batch
    list_processed_sheetnames.append(list_of_sheetnames[cnt])
    text = f'--------------------\n[{cnt+1}] {iter_text_title}\n'
    text_log += text

    #[12] Recover data from dataframe.
    (list_coor1_x, list_coor1_y
    , list_coor2_x, list_coor2_y
    , list_d_x, list_d_y, list_d_l) = MRD.recover_lists_from_df_one_pair(iter_df)
    
    #[13] Set initial values
    ratio_to_ctr_rot = 1
    initial_ctr_rot_x = ratio_to_ctr_rot * list_ctr_rot_x[cnt]
    initial_ctr_rot_y = ratio_to_ctr_rot * list_ctr_rot_y[cnt]
    initial_rot_degree = list_rot_degree[cnt] * list_rot_ang_dir[cnt]
    initial_cone_slope = list_mean_grad_l[cnt]
        
    #[14] Set training hyperparameters
    initial_lr = 0.01
    num_epochs = 100
    
    
    #[15] Fit the invert cone
    (list_ctr_rot_x, list_ctr_rot_y, list_cone_slope
     , list_loss, lisr_lr, text_log) = ICM.train_to_fit_the_invert_cone(list_coor2_x, list_coor2_y
                                                       , list_d_l
                                                       , initial_ctr_rot_x, initial_ctr_rot_y, initial_cone_slope
                                                       , initial_lr, num_epochs, text_log)
     
    #[17] Extract optimized result from the last item in the list.
    opt_ctr_rot_x, opt_ctr_rot_y, opt_cone_slope = list_ctr_rot_x[-1], list_ctr_rot_y[-1], list_cone_slope[-1]
    list_opt_ctr_rot_x.append(opt_ctr_rot_x)
    list_opt_ctr_rot_y.append(opt_ctr_rot_y)
    list_opt_cone_slope.append(opt_cone_slope)
    
