    print(f'[opt_cone_slope] {opt_cone_slope}')
    print(f'[last loss] {last_loss}\n')
    

    #[18] Calculate rotation angle
    dist_ctr_rot = np.sqrt(opt_ctr_rot_x**2 + opt_ctr_rot_y**2)
    cone_elve = dist_ctr_rot * opt_cone_slope
    opt_rot_degree = np.arcsin((cone_elve/2)/dist_ctr_rot)*2
    list_opt_rot_degree.append(opt_rot_degree)
    print(f'[opt_rot_degree] {opt_rot_degree} degree.')

    #[19] Record data
    timestamp = datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
