sys.path.append(r'D:\01_Floor\a_Ed\09_EECS\10_Python\00_Classes and Functions')
import F04_EXLDF as F04_EXLDF       #type: ignore

import MRD_0_module as MRD #type: ignore        MRD = Material Rotation Detection
import ISL_0_module as ISL #type: ignore        ISL = Image Substraction Loss
import ICM_0_module as ICM #type: ignore        ICM = Invert Cone Model


def recover_lists_from_df_trails(df_trails):
    list_x_opt = df_trails['x_opt'].tolist()
    list_y_opt = df_trails['y_opt'].tolist()
    list_r_opt = df_trails['r_opt'].tolist()
    list_x_GTset = df_trails['x_GT(set)'].tolist()
    list_y_GTset = df_trails['y_GT(set)'].tolist()
    list_r_GTset = df_trails['r_GT(set)'].tolist()
    list_x_GTcorr = df_trails['x_GT(corr)'].tolist()
    list_y_GTcorr = df_trails['y_GT(corr)'].tolist()
    list_r_GTcorr = df_trails['r_GT(corr)'].tolist()
    list_err_x = df_trails['error (x)'].tolist()
    list_err_y = df_trails['error (y)'].tolist()
    list_err_r = df_trails['error (r)'].tolist()
    list_e_abs_avg = df_trails['e_abs_avg'].tolist()
    
    return (list_x_opt, list_y_opt, list_r_opt,
            list_x_GTset, list_y_GTset, list_r_GTset,
            list_x_GTcorr, list_y_GTcorr, list_r_GTcorr,
            list_err_x, list_err_y, list_err_r, list_e_abs_avg)

    
def plot_2D_error_trend(list_x, list_y, list_z, title_x, title_y, title_z, title_plot, path_save):
    xy_same_range = True
    flip_y_axis = True
    
    # [1] Create figure and 2D axis
    fig, ax = plt.subplots(figsize=(8, 8))
    fs_axis = 20
    fs_title = 22
    fs_info = 12
    
    # [2] Convert lists to numpy array for easier manipulation
    xs = np.array(list_x)
    ys = np.array(list_y)
    
    # [3] Normalize z values from 0 to 1 for color bar
    arr_z = np.array(list_z)
    norm = plt.Normalize(np.min(arr_z), np.max(arr_z))  # Normalize the z values between min and max of arr_z
    
    # [4] Create color map using viridis
    cmap = plt.cm.viridis
    norm_colors = cmap(norm(arr_z))  # Use the normalized values of arr_z for color mapping
    norm_alpha = 0.2 + 0.8 * norm(arr_z)

    # [5] Plot each point with size corresponding to its loss value
    sc = ax.scatter(xs, ys, s=200, c=norm_colors, alpha=norm_alpha)

    # [6] Determine the range for the axes
    if xy_same_range:
        range_x = np.max(xs) - np.min(xs)
        range_y = np.max(ys) - np.min(ys)
        range_for_xy = max(range_x, range_y) * 1.6  # Adjust the range to not miss any point
        xlim_min, xlim_max = np.mean(xs) - 0.5 * range_for_xy, np.mean(xs) + 0.5 * range_for_xy
        ylim_min, ylim_max = np.mean(ys) - 0.5 * range_for_xy, np.mean(ys) + 0.5 * range_for_xy
        
        # [7] Use the broader of the ranges to set both axes
        ax.set_xlim(xlim_min, xlim_max)
        ax.set_ylim(ylim_min, ylim_max)
    
    # [8] Labels and title
    ax.set_xlabel(title_x, fontsize=fs_axis)
    ax.set_ylabel(title_y, fontsize=fs_axis)
    ax.set_title(title_plot, fontsize=fs_title)
    
    # [9] Axes appearance adjustments
    ax.xaxis.set_major_formatter(ScalarFormatter(useMathText=True))
    ax.yaxis.set_major_formatter(ScalarFormatter(useMathText=True))
    ax.ticklabel_format(style='sci', axis='x', scilimits=(0, 0))
    ax.ticklabel_format(style='sci', axis='y', scilimits=(0, 0))
    
    # [10] Flip the y-axis to simulate raster coordinates
    if flip_y_axis:
        ax.set_ylim(ax.get_ylim()[::-1])
    
    # [11] Change subplot size
    plt.subplots_adjust(left=0.15, right=0.85, bottom=0.15, top=0.85)
    
    # [12] Add percentage labels next to each data point
    for i in range(len(xs)):
        #[13] Add text for data with larger error.
        if abs(arr_z[i]) >= 0.05:
            text = f'{arr_z[i]*100:.2f}%'
            ax.text(xs[i], ys[i], text, fontsize=10, ha='right', va='bottom')
            
    # [13] Adding color bar to indicate the scale of loss
    cbar_ax = fig.add_axes([0.90, 0.15, 0.02, 0.7])  # Specify the position of the color bar
    cbar = plt.colorbar(sc, cax=cbar_ax)
    cbar.set_label(title_z)
    
    # [20] Save or show plot
    plt.savefig(path_save)
    plt.close()


