def read_the_txt_file_in_dir_if_file_name_contain(dir_img_folder, file_name):
    latest_path_txt = None
    latest_string_txt = None
    latest_mod_time = -1

    #[1] Iterate through the files in the directory
    for path_file in os.listdir(dir_img_folder):
        #[2] Check if the file name contains the specified string and if it's a text file
        if file_name in path_file and path_file.endswith('.txt'):
            path_txt = os.path.join(dir_img_folder, path_file)
            #[3] Get the modification time of the file
            mod_time = os.path.getmtime(path_txt)
            if mod_time > latest_mod_time:
                latest_mod_time = mod_time
                latest_path_txt = path_txt
                #[4] Read the content of the file
                with open(latest_path_txt, 'r') as file:
                    latest_string_txt = file.read()
    
    return latest_path_txt, latest_string_txt



def read_info_from_string(input_string):
    # Use regular expressions to find the desired values
    corr_match = re.search(r'\[Corrected center of rotation \(COR\)\]\s+(-?\d+),\s+(-?\d+)', input_string)
    rot_degree_match = re.search(r'rot_degree:\s+(-?\d+)', input_string)  # Adjusted to handle negative values

    if corr_match and rot_degree_match:
        x_corr = int(corr_match.group(1))
        y_corr = int(corr_match.group(2))
        r_real = int(rot_degree_match.group(1))
    else:
        raise ValueError("The input string does not contain the required information in the expected format.")
    
    return x_corr, y_corr, r_real




def append_text_to_txt(path_txt, text_to_append, char_preview): # This code will not rename the file.
    #[] Check if the path_txt exists
    if not os.path.exists(path_txt):
        print(f'[append_text_to_txt] File not found:\n {path_txt}')
        sys.exit()
    try:
        with open(path_txt, 'a') as file:  #a = append, w = write
            file.write(text_to_append)
            preview = text_to_append[:char_preview].replace('\n', '\n >> ')
            print(f'[read_text_from_txt] content quick view:\n >> {preview}')
            file.close()
    except Exception as e:
        print(f'[append_text_to_txt] An error occurred while reading the file:\n {str(e)}')
        sys.exit()    



dir_img_folder = r'D:\01_Floor\a_Ed\09_EECS\10_Python\04_OngoingTools\2023-0919_Image Mismatch Detection\04-IMD_Rotation Pictures\R25'

