    if cnt == 0:
        #[20] The 0th image.
        image_t1 = iter_bsn
        continue 
    else:
        image_t2 = iter_bsn
    
    #[22] Text log for every pari of batch
    iter_bsn_noExt = os.path.splitext(iter_bsn)[0]
