"""
[TFQA-3_test GPT2 with TFQA]
Purpose: Ask GPT2 to answer TFQA questions.
Author: Meng-Chi Ed Chen
Date: 2023-12-03
Reference:
    1. https://huggingface.co/docs/transformers/main_classes/text_generation
    2. https://huggingface.co/gpt2-xl
    3. https://github.com/sylinrl/TruthfulQA
    

Status: Complete.
"""

import sys, os, time
import pandas as pd
import TFQA_F as TFQA_F #type: ignore
from transformers import GPT2Tokenizer, GPT2LMHeadModel
import torch
#[] Check if GPU is available and set the device accordingly. AMD graphic card won't work.
device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
print(f"Using device: {device}")

#[] Inmport questions from cvs into dataframe


def ask_GPT2_on_PC(question, max_length, temperature):
    # Avalible models: "gpt2", "gpt2-medium", "gpt2-large", "gpt2-xl"
    
    """
    # If running in for loop, move these three lines out of the for loop.
    from transformers import GPT2Tokenizer, GPT2LMHeadModel
    tokenizer = GPT2Tokenizer.from_pretrained(model_name)
    model = GPT2LMHeadModel.from_pretrained(model_name)
    """
    inputs = tokenizer.encode(question, return_tensors="pt")

    max_length = max_length         # Don't need too be to long. It will start making up things.
    num_return_sequences = 1        # Number of answers to generate.
    no_repeat_ngram_size = 2        # The size of n-grams that cannot be repeated in the generated text.
    temperature = temperature       # The value used to model the randomness of the output (lower means less random).

    output = model.generate(
        inputs,
        max_length = max_length,
        num_return_sequences = num_return_sequences,
        no_repeat_ngram_size = no_repeat_ngram_size,
        temperature = temperature,
        pad_token_id = tokenizer.eos_token_id
    )
    answer = tokenizer.decode(output[0], skip_special_tokens=True)
    return answer

#path_TFQA = '/content/drive/MyDrive/Colab Notebooks/01_Data/01_TFQA/TruthfulQA.xlsx'
path_TFQA = TFQA_F.tkinter_select_file(dialog_title = 'Select TruthfulQA Question Excel (in .xlsx)')
df_TFQA = TFQA_F.read_excel_into_df(path_TFQA)
list_Ques = df_TFQA['Question']
print(list_Ques)


#[] Start asking questions.
model_name = "gpt2-xl" # gpt2-xl is the GPT-2 1.5B model used as the baseline on TruthfulQA's README.md.
list_Ans = []
list_Time = []
len_Ques = len(list_Ques)
tokenizer = GPT2Tokenizer.from_pretrained(model_name)
model = GPT2LMHeadModel.from_pretrained(model_name)

for index, iter_Q in enumerate(list_Ques):
    print(f'\n[{index}/{len_Ques}]----------')
    start_time = time.time()
    #[] Set max_length to 100 and temperature to 0 when running for TruthfulQA test.
    answer = ask_GPT2_on_PC(iter_Q, 200, 0)
    #[] This truncates the rest of the nonsense.
    result = TFQA_F.extract_meaningful_answer(answer, '\n', 2)
    print('\n[Generated Answer]:', result, end = '\n')
    end_time = time.time()
    time_thie_Ques = end_time - start_time
    list_Ans.append(result)
    list_Time.append(round(time_thie_Ques, 2))
    avg_time = sum(list_Time)/len(list_Time)
    time_to_finish = round((len_Ques-index)*avg_time/60, 2)
    print(f'---(Average time per question: {round(avg_time, 2)} sec.)')
    print(f'---(Still need {time_to_finish} mins to finish {len_Ques-index-1} questions.)', end = '\n\n')
print('[Finish asking all the questions]')
    

#[] Save generated answer
print('')
df_TFQA['Generated Answer'] = list_Ans
df_TFQA['Time Cost(s)'] = list_Time
dir_excel = os.path.dirname(path_TFQA)
basename_excel = os.path.basename(path_TFQA).replace('.xlsx', '_(' + model_name + ')ans.xlsx')
TFQA_F.save_df_as_excel(df_TFQA, dir_excel, basename_excel, '1-with_gen_ans')
print('[Complete]')

