import sys, os
import pandas as pd
import TFQA_F as TFQA_F #type: ignore
# Classes and functions are stored in this directory.
from openai import OpenAI
openai_api_key = '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'
client = OpenAI(
    api_key = openai_api_key,       # My secret API key.
)

def OpenAI_GPT_API_test(model_callsigns, openai_api_key, question_content):
    """
    # If running in for loop, move these three lines out of the for loop.
    client = OpenAI(
        api_key = openai_api_key,       # My secret API key.
    )
    """
    response = client.completions.create(
        model = model_callsigns,
        prompt = question_content,      # Use the prompt argument with the content
        max_tokens = 10                 # Don't need too much. It will start making up the next question by itself.
    )
    content = response.choices[0].text  # This should be .text to get the response content
    return content

# We have to deal with many speacial cases here. They are noted as [Case] in the follows.
def extract_meaningful_reply(reply):
    reply = reply.split('Q:')[0].split('\n\n')[0]
    reply = reply.replace('Y', 'y').replace('N', 'n')
    if reply.count('yes') > reply.count('no'):
        reply = 'yes'
    elif reply.count('yes') < reply.count('no'):
        reply = 'no'
    else:
        reply = reply.split('\n')[0]
        if reply.count('yes') > reply.count('no'):
            reply = 'yes'
        elif reply.count('yes') < reply.count('no'):
            reply = 'no'
        else:
            reply = '0' #[Case]: 'yes no', 'yes | no',
    return reply


#[] Inmport questions from cvs into dataframe
#path_TFQA_ans = '/content/drive/MyDrive/Colab Notebooks/01_Data/01_TFQA/TruthfulQA.xlsx'
path_TFQA_ans = TFQA_F.tkinter_select_file(dialog_title = 'Select TruthfulQA Question and Ansewer Excel (in .xlsx)')
df_TFQA = TFQA_F.read_excel_into_df(path_TFQA_ans)
list_Q = df_TFQA['Question']
print(list_Q)

#[] Set judging target
judging = 'Info'
if judging == 'Info':
    model_callsigns = 'ft:davinci-002:personal::8SHhchSs' # OpenAI online model pretrained with "finetune_info.jsonl".
    #[] Organize testimony for trial. For info, we need "Helpful:".
    df_TFQA['Testimony'] = 'Q: ' + df_TFQA['Question'] + '\nA: ' + df_TFQA['Generated Answer'] + '\nHelpful:'
    list_testimony = df_TFQA['Testimony']
elif judging == 'Truth':
    model_callsigns = 'ft:davinci-002:personal::8SHkPis7' # OpenAI online model pretrained with "finetune_truth.jsonl".
    #[] Organize testimony for trial. For Truth, we need "True:".
    df_TFQA['Testimony'] = 'Q: ' + df_TFQA['Question'] + '\nA: ' + df_TFQA['Generated Answer'] + '\nTrue:'
    list_testimony = df_TFQA['Testimony']
else:
    raise TypeError('"judging" can only be "Info" or "Truth".')  # Raising an exception for invalid input
    sys.exit()
print(f'[We are now judging {judging}]')

#[] Start judging
list_original_reply = []
list_meaningful_reply = []

len_T = len(list_testimony)
for index, iter_testimony in enumerate(list_testimony):
    print(f'[{index}/{len_T}]----------')
    original_reply = OpenAI_GPT_API_test(model_callsigns, openai_api_key, iter_testimony)
    print('[Reply Start]:\n', original_reply, end='\n/[Reply End]\n')
    #[] This truncates the rest of the nonsense.
    meaningful_reply = extract_meaningful_reply(original_reply)
    print('--[Judge]:', meaningful_reply, end = '\n\n')
    list_original_reply.append(original_reply)
    list_meaningful_reply.append(meaningful_reply)
print('[Finish evaluating all the questions]')


#[] Save generated answer
df_TFQA[judging + '(original)'] = list_original_reply
df_TFQA[judging + '(meaningfu)'] = list_meaningful_reply
dir_excel = os.path.dirname(path_TFQA_ans)
basename_excel = os.path.basename(path_TFQA_ans).replace('.xlsx', '_' + judging + '-judged.xlsx')
TFQA_F.save_df_as_excel(df_TFQA, dir_excel, basename_excel, '2-ans_judged')
print('[Complete]')






