import os, sys
import pandas as pd
#[Text] start

def tkinter_select_file(dialog_title = 'Open'):
    import tkinter as tk
    from tkinter import filedialog
    root = tk.Tk()
    root.withdraw()
    file_path = filedialog.askopenfilename(title = dialog_title)
    print('file_path:', file_path)
    return file_path

def read_text_from_txt(path_txt, char_preview):
    try:
        with open(path_txt, 'r') as file:
            content = file.read()
            print('[read_txt] content quick view:\n', content[:char_preview])
        return content
    except FileNotFoundError:
        print(f'[read_txt] File not found:\n {path_txt}')
        sys.exit()
    except Exception as e:
        print(f'[read_txt] An error occurred while reading the file:\n {str(e)}')
        sys.exit()

def datetime_string():
    import datetime
    #[] Get current datetime and create opening_of_append.
    now = datetime.datetime.now()       
    current_date = now.strftime("%Y-%m-%d")
    current_time = now.strftime("%H%M%S")
    current_datetime = current_date + '_' + current_time
    return current_datetime

def append_text_to_txt(path_txt, text_to_append, char_preview): # This code will not rename the file.
    #[] Check if the path_txt exists
    if not os.path.exists(path_txt):
        print(f'[append_txt] File not found:\n {path_txt}')
        sys.exit()
    #[] Get current datetime and create opening_of_append.
    current_datetime = datetime_string()
    opening_of_append = '\n\n--\n[' + current_datetime + ']\n\n'
    try:
        with open(path_txt, 'a') as file:  #a = append, w = write
            file.write(opening_of_append)
            file.write(text_to_append)
            print('[append_txt] content quick view:\n', text_to_append[:char_preview], '\n')
            file.close()
    except Exception as e:
        print(f'[append_txt] An error occurred while reading the file:\n {str(e)}')
        sys.exit()  
        
def tkinter_select_file(dialog_title = 'Open'):
    import tkinter as tk
    from tkinter import filedialog
    dialog_title = 'Pick a file'
    root = tk.Tk().withdraw()
    file_path = filedialog.askopenfilename(title = dialog_title)
    print('file_path:', file_path)
    return file_path


def extract_meaningful_answer(reply, separator, part):
    splited_reply = reply.split(separator, part + 1)
    for index, iter_part in enumerate(splited_reply):
        print(f'splited_reply[{index}] = {iter_part}')
    try:
        the_one_splited_reply = splited_reply[part]
    except IndexError:
        return splited_reply[0]
    return the_one_splited_reply

def read_excel_into_df(path_excel):
    print('[read_csv_into_df]')
    df = pd.read_excel(path_excel)
    # print('--[dataframe headers]:', df.columns.values, end='\n')
    return df

def save_df_as_excel(df, dir_excel, basename_excel, sheet_name):
    if not os.path.exists(dir_excel):
        os.makedirs(dir_excel)
    path_excel = os.path.join(dir_excel, basename_excel)
    writer = pd.ExcelWriter(path_excel, engine='xlsxwriter')
    df.to_excel(writer, sheet_name=sheet_name, index=True)
    writer.save()
    return path_excel


# End of [TFQA_F.py]




