path_image = r'D:\01_Floor\a_Ed\09_EECS\10_Python\04_OngoingTools\2024-0406_Color Recommendation GCN\01-CRG_Sample Artistic Image\1665_Girl_with_a_Pearl_Earring.jpg'
dir_imagename = os.path.splitext(path_image)[0]
