def generate_cylinder_points_in3D(start, end, radius, dens_theta=12, dens_vec=50):
    """
    start = np.array([x1, y1, z1])  # The starting end coordinate of the cylinder.
    end = np.array([x2, y2, z2])    # The ending end coordinate of the cylinder.
    radius = 20                     # The radius of the cylinder.
    dens_theta = 12                 # Number of points around the cylinder circumference.
    dens_vec = 50                   # Number of points along the height of the cylinder.
    """
    #[1] Compute the vector along the cylinder's height and its magnitude.
    v = end - start
    mag = np.linalg.norm(v)
    
    #[2] Normalize the vector along the cylinder's height.
    v_norm = v / mag
    
    #[3] Generate two orthogonal vectors in the plane of the circle.
    if v_norm[0] != 0 or v_norm[1] != 0:  # Check if the normal vector is not parallel to the z-axis.
        n1 = np.array([-v_norm[1], v_norm[0], 0])
    else:  # If the normal vector is parallel to the z-axis.
        n1 = np.array([1, 0, 0])
    
    #[4] Normalize n1 and get the second orthogonal vector using the cross product.
    n1 = n1 / np.linalg.norm(n1)
    n2 = np.cross(v_norm, n1)

    #[5] Create grids for the cylinder's height and angle.
    t = np.linspace(0, mag, dens_vec)  # Linear spacing along the cylinder's height.
    theta = np.linspace(0, 2 * np.pi, dens_theta)  # Angular spacing around the cylinder.
    t, theta = np.meshgrid(t, theta)  # Generate mesh grids for t and theta.

    #[6] Compute x, y, and z coordinates of the cylinder's surface points.
    cyl_x = start[0] + v_norm[0] * t + radius * np.sin(theta) * n1[0] + radius * np.cos(theta) * n2[0]
    cyl_y = start[1] + v_norm[1] * t + radius * np.sin(theta) * n1[1] + radius * np.cos(theta) * n2[1]
    cyl_z = start[2] + v_norm[2] * t + radius * np.sin(theta) * n1[2] + radius * np.cos(theta) * n2[2]
    
    return cyl_x, cyl_y, cyl_z


def plot_a_cylinder(start, end, radius, dens_theta, dens_vec, text_title, path_save=None):
    """
    Plot a 3D circle given a center, normal vector, and radius.
    """

    #[1] Generate points on the circle's surface.
    cyl_x, cyl_y, cyl_z = generate_cylinder_points_in3D(start, end, radius, dens_theta, dens_vec)

    #[2] Create figure and 3D axis.
    fig = plt.figure(figsize=(8, 8))
    ax = fig.add_subplot(111, projection='3d')
    fs_title = 20
    fs_axis = 14

    #[3] Plot the surface.
    ax.plot_surface(cyl_x, cyl_y, cyl_z, color='green', alpha=0.5)
    
    #[4] Set axis limits.
    ax.set_xlim(0, 255)
    ax.set_ylim(0, 255)
    ax.set_zlim(0, 255)
    
    # [5] Set labels and title.
    ax.set_xlabel('X', fontsize=fs_axis)
    ax.set_ylabel('Y', fontsize=fs_axis)
    ax.set_zlabel('Z', fontsize=fs_axis)
    ax.set_title(text_title, fontsize=fs_title)
    
    #[6] Save or show the plot.
    if path_save:
        plt.savefig(path_save)
        print(f'Plot saved at {path_save}')
    else:
        plt.show()

    return fig, ax


