#[1] Resize image - Start

def reduce_image_size(path_img, resize_ratio=None, path_save=None):
    print(f'\n[reduce_image_size] \t{os.path.basename(path_img)}, \tresize_ratio = {resize_ratio},', end='')
    #[1] Read the image using cv2
    arrimg = cv2.imread(path_img)
    if arrimg is None:
        raise FileNotFoundError(f"Image at path '{path_img}' not found.")

    #[2] Resize the image
    if resize_ratio:
        if not resize_ratio < 2:
            raise ValueError(f'It is advisible to have resize_ratio less than 2. Please check. {resize_ratio}')
        h, w = arrimg.shape[:2]
        new_width = int(w * resize_ratio)
        new_height = int(h * resize_ratio)
        new_pixel = new_width * new_height
        print(f'\t(new_width, new_height, new_pixel) = {new_width}, {new_height}, {new_pixel}')
        arrimg_reduced = cv2.resize(arrimg, (new_width, new_height), interpolation=cv2.INTER_NEAREST)

    #[3] Save the image
    if path_save:
        cv2.imwrite(path_save, arrimg_reduced)
    return arrimg_reduced

#[1] Resize image - End






#[2] Pixel - Start





def sample_2D_or_3D_arrimg_to_dataframe(arrimg, list_axis_name):
    # [1] Check if arrimg is a colored image.
    if len(arrimg.shape) <= 2:
        raise ValueError(f'The arrimg should be a color image. It currently has a shape of {arrimg.shape}, please check.')      
    
    # [2] Check size of image: If it exceeds the pixel limit, raise error.
    pixel_limit = 1e5
    h, w, c = arrimg.shape
    if h*w >= pixel_limit:
        raise ValueError(f'The image has {h*w} pixels, please reduce to less than {pixel_limit} pixels.')
    
    # [3] Prepare coordinates of the image
    coor_X, coor_Y = np.meshgrid(np.arange(w), np.arange(h))
    arr_coor_X = coor_X.flatten()
    arr_coor_Y = coor_Y.flatten()
    
    # [4] Convert arrimg into a 2D array
    arr_2D = arrimg.reshape(-1, c)

    if len(arrimg.shape) == 3:  
        # [5] Color Image: Create dataframe for color image with coordinates and pixel values
        title_X, title_Y, title_Z = list_axis_name
        xs, ys, zs = arr_2D.T
        df_img = pd.DataFrame({'coor_X': arr_coor_X, 
                               'coor_Y': arr_coor_Y, 
                               f'{title_X}': xs, 
                               f'{title_Y}': ys, 
                               f'{title_Z}': zs})
        
    elif len(arrimg.shape) == 2:  
        # [6] Grayscale Image: Create dataframe for grayscale image with coordinates and pixel values
        title = list_axis_name[0]
        xs = arr_2D.T[0]
        df_img = pd.DataFrame({'coor_X': arr_coor_X, 
                               'coor_Y': arr_coor_Y, 
                               f'{title}': xs})    
        
    else:   
        raise ValueError(f'Please check the data format of arrimg. It currently has a shape of {arrimg.shape}.')    

    return df_img



def mean_color_of_image(path_img):
    #[1] Read the image
    arrimg = cv2.imread(path_img)
    
    #[3] Resize the image
    arrimg_resized =  reduce_image_size(path_img, resize_ratio=0.01, path_save=None)
    
    #[5] Calculate the mean color
    arr_color_mean = arrimg_resized.mean(axis=(0, 1))
    print(f'--\t{os.path.basename(path_img)} color (BGR): {arr_color_mean}')
    return arr_color_mean


#[2] Pixel - End






#[3] Math - start

def array_data_pca_extract_vector(arr_data):
    #[1] Input examination.
    if len(arr_data.shape) != 2:
        raise ValueError('The input arr_data should be a 2D array with every row as a datum and every column as a dimension.')
    print(f'\n[array_data_pca_extract_vector] \n The input arr_data has a shape of {arr_data.shape}.')

    #[2] Singular Value Decomposition (SVD)
    U, S, Vh = np.linalg.svd(arr_data, full_matrices=True) 
    rod_center = np.mean(arr_data, axis=0)
    rod_vector = Vh[0]
    print(f'rod_center = \t{rod_center}\nrod_vector = \t{rod_vector}')
    
    return rod_center, rod_vector
    

def check_if_a_point_is_within_the_rod_like_color_space(sample_color, 
                                                        rod_center, 
                                                        rod_vector, 
                                                        d_to_center=40, 
                                                        d_to_vector=6):
    """
    Along the XYZ vector of rod_vector, draw a line through rod_center.
    A rod-like shape is defined as points within d_to_vector to this line,
    and d_to_center to the rod_vector.
    If sample_color is within this region, return True, otherwise False.    
    """
    #[1] Calculate the vector from rod_center to sample_color
    vector_to_point = sample_color - rod_center
    
    #[2] Calculate the projection of vector_to_point onto rod_vector
    projection_length = np.dot(vector_to_point, rod_vector) / np.linalg.norm(rod_vector)
    
    #[3] Calculate the perpendicular distance to the rod_vector
    perpendicular_distance = np.linalg.norm(np.cross(vector_to_point, rod_vector)) / np.linalg.norm(rod_vector)
    
    #[4] Check if the point lies within the rod-like shape
    in_the_rod = (perpendicular_distance <= d_to_vector) and (np.abs(projection_length - d_to_center) <= d_to_center)
    
    return in_the_rod

def single_image_background_check(path_img,
                                  rod_center, 
                                  rod_vector, 
                                  d_to_center=40, 
                                  d_to_vector=6):
    
    #[1] Read image and get img_mean_color.
    arrimg_reduced = reduce_image_size(path_img, resize_ratio=0.01, path_save=None)
    h, w, c = arrimg_reduced.shape
    arr_2D = arrimg_reduced.reshape(-1, c)
    img_mean_color = np.mean(arr_2D, axis=0)  # Compute mean along columns (BGR channels)
    
    #[2] Check if within rod.
    in_the_rod = check_if_a_point_is_within_the_rod_like_color_space(img_mean_color, 
                                                                    rod_center, 
                                                                    rod_vector, 
                                                                    d_to_center, 
                                                                    d_to_vector)
    return in_the_rod

#[3] Math - end


#[4] Color Space - Start

def convert_from_BGR_to_HSV_array_color_space(arrimg_BGR):
    # [1] Convert BGR image to HSV color space
    arrimg_HSV = cv2.cvtColor(arrimg_BGR, cv2.COLOR_BGR2HSV)
    
    return arrimg_HSV


    

#[4] Color Space - End


