from torchvision import transforms


#[1] Lock the random seed for reproducibility
seed = 42
random.seed(seed)
np.random.seed(seed)
torch.manual_seed(seed)
torch.cuda.manual_seed(seed)
torch.backends.cudnn.deterministic = True
torch.backends.cudnn.benchmark = False


def save_df_as_excel_overwrite(df, path_xlsx, sheet_name):
    print('\n[save_df_as_excel_overwrite]')
    #[1] Make dir if not exist.
    dir_excel = os.path.dirname(path_xlsx)
    if not os.path.exists(dir_excel):
        os.makedirs(dir_excel)

    #[2] Use openpyxl to preserve existing sheets
    if os.path.exists(path_xlsx):
        with pd.ExcelWriter(path_xlsx, engine='openpyxl', mode='a', if_sheet_exists='replace') as writer:
            df.to_excel(writer, sheet_name=sheet_name, index=True)
    else:
        with pd.ExcelWriter(path_xlsx, engine='openpyxl') as writer:
            df.to_excel(writer, sheet_name=sheet_name, index=True)

    print(f'--Dataframe saved to {path_xlsx} in sheet {sheet_name}', end='\n\n')

#[11] Custom dataset loader
class Dataset_OM_Image(Dataset):
    def __init__(self, dir_data, path_excel_annotation, sheetname):
        self.dir_data = dir_data
        self.df_ant = pd.read_excel(path_excel_annotation, sheet_name=sheetname)
        self.transform = transforms.Compose([
            transforms.Resize((128, 128)),
            transforms.ToTensor(),
        ])

    def __len__(self):
        return len(self.df_ant)

    def __getitem__(self, idx):
        row = self.df_ant.iloc[idx]
        path_img = os.path.join(self.dir_data, row['bsnext'])
        try:
            image = Image.open(path_img).convert('RGB')
            image = self.transform(image)
        except FileNotFoundError:
            print(f"Warning: Image {path_img} not found. Skipping this file.")
            return None

        region = row['region']
        feature = int(row['feature'])

        region_map = {'background': 0, 'edge': 1, 'corner': 2, 'substrate': 3}
        region = region_map[region]

        return image, region, feature

    def get_annotations(self):
        return self.df_ant


#[17] Define the CNN model
class CNN_OM_Image_Classifier(nn.Module):
    def __init__(self):
        super(CNN_OM_Image_Classifier, self).__init__()

        # [1] First layer: Convolutional layer with 16 filters, kernel size 3x3
        self.features = nn.Sequential(
            nn.Conv2d(3, 16, 3, padding=1),  # Input: 3x128x128, Output: 16x128x128
            nn.ReLU(inplace=True),
            nn.BatchNorm2d(16),
            nn.MaxPool2d(2, 2),              # Output: 16x64x64

            # [2] Second layer: Convolutional layer with 32 filters, kernel size 3x3
            nn.Conv2d(16, 32, 3, padding=1), # Input: 16x64x64, Output: 32x64x64
            nn.ReLU(inplace=True),
            nn.BatchNorm2d(32),
            nn.MaxPool2d(2, 2),              # Output: 32x32x32

            # [3] Third layer: Convolutional layer with 64 filters, kernel size 3x3
            nn.Conv2d(32, 64, 3, padding=1), # Input: 32x32x32, Output: 64x32x32
            nn.ReLU(inplace=True),
            nn.BatchNorm2d(64),
            nn.MaxPool2d(2, 2),              # Output: 64x16x16

            # [4] Fourth layer: Convolutional layer with 128 filters, kernel size 3x3
            nn.Conv2d(64, 128, 3, padding=1), # Input: 64x16x16, Output: 128x16x16
            nn.ReLU(inplace=True),
            nn.BatchNorm2d(128),
            nn.AdaptiveAvgPool2d((4, 4))      # Output: 128x4x4
        )

        # [5] First fully connected layer: Flattened input to 256 units
        self.classifier = nn.Sequential(
            nn.Linear(128 * 4 * 4, 256),      # Input: 128*4*4=2048, Output: 256
            nn.ReLU(inplace=True),
            nn.Dropout(0.5),

            # [6] Second fully connected layer: 256 units to 128 units
            nn.Linear(256, 128),              # Input: 256, Output: 128
            nn.ReLU(inplace=True),
            nn.Dropout(0.5)
        )

        # [7] Output layer for region classification: 4 classes (region types)
        self.region_head = nn.Linear(128, 4)  # Input: 128, Output: 4

        # [8] Output layer for feature classification: 1 output (binary classification)
        self.feature_head = nn.Linear(128, 1) # Input: 128, Output: 1

    def forward(self, x):
        x = self.features(x)
        x = torch.flatten(x, 1)
        x = self.classifier(x)

        region = self.region_head(x)
        feature = torch.sigmoid(self.feature_head(x))
        return region, feature

#[18] Define the custom loss function
class CustomLoss(nn.Module):
    def __init__(self):
        super(CustomLoss, self).__init__()
        self.criterion_region = nn.CrossEntropyLoss(reduction='mean')
        self.criterion_feature = nn.BCELoss(reduction='mean')

    def forward(self, region_pred, feature_pred, region_true, feature_true):
        loss_region = self.criterion_region(region_pred, region_true)
        loss_feature = self.criterion_feature(feature_pred.squeeze(), feature_true.float())

        total_loss = loss_region + loss_feature
        return total_loss
import torch.optim as optim

