def check_image_dataset_filename(list_paths):
    """
    File name examples: 
    T0919_R2-corn_F1-T_rot(+20)_3HV_exp(-30).png
    T0286_R1-edge_F1-T_rot(+00)_0O.png
    T1655_R3-subs_F0-F_rot(+40)_0O.png
    """
    #[1] Report size.
    cnt_total = len(list_paths)    
    print(f'\n[check_image_dataset_filename] There are total {cnt_total} files.')
    list_single_file_result = []
    cnt_fail = 0

    #[3] Iterate through files.
    for cnt, i_path in enumerate(list_paths):
        
        #[4] Print current check.
        dir_name = os.path.dirname(i_path)
        bsnext = os.path.basename(i_path)
        list_string = bsnext.split('_')
        print(f'[{cnt:04d}/{cnt_total:04d}] {bsnext}\t', end='')
        
        #[5] First part should be "Tnnnn"
        if list_string[0][0] == 'T' and list_string[0][1:].isnumeric():
            rule1 = True
        else:
            print(f'[violate rule1] {list_string[0]}\t')
        
        #[6] Second part should be R0-bkgd, R1-edge, R2-corn, R3-subs.
        if list_string[1] in ['R0-bkgd', 'R1-edge', 'R2-corn', 'R3-subs']:
            rule2 = True
        else:
            print(f'[violate rule2] {list_string[1]}\t')

        #[7] Third part should be R0-bkgd, R1-edge, R2-corn, R3-subs.
        if list_string[2] in ['F0-F', 'F1-T']:
            rule3 = True
        else:
            print(f'[violate rule3] {list_string[2]}\t')
        
        #[10] Single file result.
        single_file_result = all([rule1, rule2, rule3])
        if single_file_result is not True:
            cnt_fail += 1
        print(f'\t Result: {single_file_result}')
        list_single_file_result.append(single_file_result)
        
    #[15] Final result.
    batch_file_result = all(list_single_file_result)
    print(f'-- Final result: {batch_file_result}. Fail/Total = {cnt_fail}/{cnt_total}.')

