import json
import boto3
import logging
import uuid

s3 = boto3.client('s3')

def lambda_handler(event, context):
    logger = logging.getLogger()
    logger.setLevel(logging.INFO)
    
    # [0] Log the incoming event for debugging
    logger.info(f"Received event: {json.dumps(event)}")
    
    # [1] Handle preflight OPTIONS request for CORS
    if event.get('httpMethod') == 'OPTIONS':
        logger.info('Handling OPTIONS request')
        return {
            'statusCode': 200,
            'headers': {
                'Access-Control-Allow-Origin': 'https://edchen1240.com',
                'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
                'Access-Control-Allow-Headers': 'Content-Type'
            },
            'body': ''
        }
    
    # [2] Generate a unique filename using UUID
    file_name = f"{uuid.uuid4()}.jpg"
    
    # [3] Generate presigned URL
    bucket_name = 'b01-photo-add-datetime-and-location-input'
    try:
        presigned_post = s3.generate_presigned_post(
            Bucket=bucket_name,
            Key=file_name,  # Use the unique filename
            ExpiresIn=300  # URL valid for 5 minutes
        )
    except Exception as e:
        logger.error(f"Error generating presigned URL: {str(e)}")
        return {
            'statusCode': 500,
            'headers': {
                'Access-Control-Allow-Origin': 'https://edchen1240.com',
                'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
                'Access-Control-Allow-Headers': 'Content-Type'
            },
            'body': json.dumps(f'Error generating presigned URL: {str(e)}')
        }

    logger.info(f"Presigned URL generated: {presigned_post}")
    
    return {
        'statusCode': 200,
        'headers': {
            'Access-Control-Allow-Origin': 'https://edchen1240.com',
            'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
            'Access-Control-Allow-Headers': 'Content-Type'
        },
        'body': json.dumps(presigned_post)
    }

# End of [02_Lambda_presigned URL-3 (works).py]




