#[1] Mathpix API functions - Start


def Mathpix_API_PDF(path_pdf, dir_output):
    #[1] Status
    
    #[3] Set options
    options = {
        "conversion_formats": {"tex.zip": True},  # Request LaTeX format as output.
        "math_inline_delimiters": ["$", "$"],  # Use inline math delimiters.
        "math_display_delimiters": ["\\[", "\\]"],  # Correct display math delimiters.
        "rm_spaces": False,  # Don't remove extra spaces in equations.
    }
    
    #[4] Get response.
    r = requests.post("https://api.mathpix.com/v3/pdf",
        headers={
            "app_id": M0KEY.MATHPIX_APP_ID,
            "app_key": M0KEY.MATHPIX_APP_KEY
        },
        data={
            "options_json": json.dumps(options)
        },
        files={
            "file": open(path_pdf,"rb")
        }
    )
    
    #[6] Check if request is successful
    if r.status_code == 200:
        response_data = r.json()
        print(json.dumps(response_data, indent=4, sort_keys=True))
        
        #[8] Extract download links for the converted LaTeX (tex.zip)
        tex_zip_url = response_data.get("tex.zip", None)
        if tex_zip_url:
            print(f"LaTeX (tex.zip) available for download at: {tex_zip_url}")
            
            #[10] Download the tex.zip file to the specified output directory
            tex_zip_response = requests.get(tex_zip_url)
            if tex_zip_response.status_code == 200:
                # Create the output directory if it doesn't exist
                M2PER.make_dir_if_not_exist(dir_output)
                
                # Define the path for saving the file
                output_file_path = os.path.join(dir_output, "output_tex.zip")
                
                # Write the content of the zip file to the output directory
                with open(output_file_path, 'wb') as f:
                    f.write(tex_zip_response.content)
                
                print(f"LaTeX (tex.zip) has been saved to: {output_file_path}")
            else:
                print(f"Failed to download the tex.zip file. Status code: {tex_zip_response.status_code}")
        else:
            print("LaTeX file not available in the response.")
    else:
        print(f"Error: {r.status_code}")
        print(r.text)
        
        









