import numpy as np
import matplotlib.pyplot as plt
from scipy.integrate import simps

def v(y):
    return y**2

def solve_schrodinger(h, N):
    y = np.arange(-N*h, (N+1)*h, h)
    v_y = v(y)
    
    def shoot(energy):
        psi = np.zeros_like(y)
        psi[0] = 0
        psi[1] = 1e-5
        
        for i in range(1, len(y)-1):
            psi[i+1] = ((2 + h**2 * (v_y[i] - energy)) * psi[i] - psi[i-1])
            print(f'[{i:04d}] \t h = {h}, \t energy = {energy}.')
        
        return psi[-2] - psi[1]  # Check for symmetry
    
    # Bisection method to find ground state energy
    e_min, e_max = 0.9999999995343387,0.9999999994179234
    while e_max - e_min > 1e-12:
        e_mid = (e_min + e_max) / 2
        print(f'-- e_mid = {e_mid}. \t (e_max, e_min) = ({e_max},{e_min})')
        if shoot(e_min) * shoot(e_mid) < 0:
            e_max = e_mid
        else:
            e_min = e_mid
    
    energy = (e_min + e_max) / 2
    
    # Compute wavefunction
    psi = np.zeros_like(y)
    psi[0] = 0
    psi[1] = 1e-5
    for i in range(1, len(y)-1):
        psi[i+1] = ((2 + h**2 * (v_y[i] - energy)) * psi[i] - psi[i-1])
    
    # Normalize wavefunction
    norm = np.sqrt(simps(psi**2, y))
    psi /= norm
    
    return energy, psi, y

def exact_solution(y):
    return (1/np.pi)**(1/4) * np.exp(-y**2/2)

def calculate_error(h):
    N = int(10/h)  # Ensure the domain is large enough
    energy, psi, y = solve_schrodinger(h, N)
    psi_exact = exact_solution(y)
    return np.mean(np.abs(psi - psi_exact))



# Generate data points
h_values = np.logspace(-4, 0, 100)
w_values = [calculate_error(h) for h in h_values]

# Plot results
plt.figure(figsize=(10, 8))
plt.loglog(h_values, w_values, 'b-')
plt.xlabel('h')
plt.ylabel('w(h)')
plt.title('Error w(h) vs. Step Size h')
