def solve_sho_numerov(h, epsilon_guess, y_max):
    N = int(y_max / h)
    y = np.linspace(-y_max, y_max, 2*N+1)
    wave_function = np.zeros_like(y)
    
    # Initial conditions
    wave_function[0] = 0
    wave_function[1] = h  # Small non-zero value
    
    k2 = 2 * (epsilon_guess - y**2)
    
    for j in range(1, 2*N):
        wave_function[j+1] = (2 * wave_function[j] * (1 - 5*h**2*k2[j]/12) 
                              - wave_function[j-1] * (1 + h**2*k2[j-1]/12)) / (1 + h**2*k2[j+1]/12)
    
    return wave_function, epsilon_guess

