def find_energy_eigenvalue(h, y_max, eps_lower, eps_upper):
    tolerance = 1e-8
    
    while eps_upper - eps_lower > tolerance:
        eps_mid = (eps_lower + eps_upper) / 2
        wave_function, _ = solve_sho_numerov(h, eps_mid, y_max)
