def solve_simple_harmonic_oscillator(h, epsilon_guess, y_max):
    N = int(y_max / h)
    y = np.linspace(-y_max, y_max, 2*N+1)
    y_power = 4
    wave_function = np.zeros_like(y)
    print(f'\n[solve_simple_harmonic_oscillator] {N}')
    
    # Initial conditions
    wave_function[0] = 0
    wave_function[1] = 1e-50

    # Shooting method
    for j in range(1, 2*N):
        wave_function[j+1] = ((2 + h**2 * (y[j]**y_power - epsilon_guess)) * wave_function[j] - wave_function[j-1])

    return wave_function
   
def find_energy_eigenvalue(h, y_max, eps_lower, eps_upper):
    tolerance = 1e-10
    while eps_upper - eps_lower > tolerance:
        eps_mid = (eps_lower + eps_upper) / 2
        wave_function = solve_simple_harmonic_oscillator(h, eps_mid, y_max)
        print(f'-- eps_mid = {eps_mid}. \t (upper, lower) = ({eps_upper},{eps_lower})')
        if wave_function[-1] > 0:
            eps_lower = eps_mid
        else:
            eps_upper = eps_mid
    energy = (eps_lower + eps_upper) / 2
    return energy
    

def normalize(y, wave_function):
    norm = np.sqrt(np.trapz(wave_function**2, y))
    return wave_function / norm 

def scale_y2_wrt_y1_using_max_in_range(list_x, list_y1, list_y2, range_find_max=[-0.1, 0.1]):
    #[1] Filter indices of list_x in range_find_max, and find max_y1_in_range.
    indices_in_range = [i for i, x in enumerate(list_x) if range_find_max[0] <= x <= range_find_max[1]]
    
    #[2] Find max of list_y1 and list_y2 in the range, and Compute scale_factor.
    max_y1_in_range = max([list_y1[i] for i in indices_in_range])
    max_y2_in_range = max([list_y2[i] for i in indices_in_range])
    scale_factor = max_y1_in_range / max_y2_in_range if max_y2_in_range != 0 else 1.0
    
    #[3] Scale list_y2.
    list_y2_scaled = [y2 * scale_factor for y2 in list_y2]
    
    return list_y2_scaled


def exact_sho(y):
    psi_exact = np.pi**(-0.25) * np.exp(-y**2/2)
    return psi_exact

def calculate_error(y, psi_numeric, psi_exact):
    return np.sqrt(np.mean((psi_numeric - psi_exact)**2))

