import os, sys, cv2
import numpy as np
import pandas as pd
from tabulate import tabulate
from datetime import datetime
import matplotlib.pyplot as plt

dir_save = r'D:\01_Floor\a_Ed\09_EECS\10_Python\04_OngoingTools\2024-1018_QSP HW Simulation\QSP-01_HW06-3'

import numpy as np
from scipy.optimize import minimize
from scipy.integrate import simps

def psi(y, nf, alpha, beta, gamma):
    #[1] Include normalization factor (nf) as one of the parameter.
    psi_val = (1/nf) * y * np.exp(-beta * y**2 / 2) * (1 + alpha * y + gamma * y**2)
    return psi_val

def fc_v(y):
    result = []
    for value in y:
        if value < 0:
            v = 10**3 
        else:
            v = value**3
        result.append(v) 
    return result

def energy(params, y):
    alpha, beta, gamma = params
    #[1] Unnormalized psi, get nf, and calculate normalized psi. 
    psi_unnorm = psi(y, 1, alpha, beta, gamma)
    normalization_factor = np.sqrt(simps(psi_unnorm**2, y))
    psi_val = psi(y, normalization_factor, alpha, beta, gamma)
    
    #[3] Second derivative of psi (d2psi)
    d2psi = (beta**2 * y**2 - beta - 2*alpha*beta*y - 1) * psi_val
    
    #[4] Kinetic and potential energy
    kinetic = -d2psi * psi_val
    potential = fc_v(y) * psi_val**2
    numerator = simps(kinetic + potential, y)
    denominator = simps(psi_val**2, y)
    
    return numerator / denominator


def plot_potential_and_prob_distr(y, alpha_opt, beta_opt, gamma_opt, path_save):
    #[1] Unnormalized psi, get nf, and calculate normalized psi. 
    psi_unnorm = psi(y, 1, alpha_opt, beta_opt, gamma_opt)
    normalization_factor = np.sqrt(simps(psi_unnorm**2, y))
    psi_val = psi(y, normalization_factor, alpha_opt, beta_opt, gamma_opt)
    
    # Calculate the probability density (psi^2) and potential
    psi_squared = psi_val**2
    potential = fc_v(y)
    fs_title = 16
    fig, ax1 = plt.subplots(figsize=(10, 6))
    
    #[5] Plot the potential on the left y-axis
    ax1.plot(y, potential, 'g-', label='Potential (V(y))')
    ax1.set_xlabel("y")
    ax1.set_ylim(0, max(potential) * 1.2)  # Set y-limits for the left axis
    ax1.set_ylabel("Potential V(y)", color='g')
    ax1.tick_params(axis='y', labelcolor='g')
    ax1.grid(True)
    
    #[6] Create a second y-axis to plot the probability density
    ax2 = ax1.twinx()
    ax2.plot(y, psi_squared, 'b--', label='Probability Density |ψ(y)|²')
    ax2.set_ylim(0, max(psi_squared) * 1.2)  # Set y-limits for the right axis
    ax2.set_ylabel("Probability Density |ψ(y)|²", color='b')
    ax2.tick_params(axis='y', labelcolor='b')
    
    #[7] Add titles and legends
    plt.title("Potential and Probability Density of Ground State", fontsize=fs_title)
    ax1.legend(loc='upper left')
    ax2.legend(loc='upper right')
    
    #[8] Add text to the plot
    text =  f'Normalization factor:  {normalization_factor:.6f}\n'\
            f'Optimized alpha:       {alpha_opt:.6f}\n'\
            f'Optimized beta:        {beta_opt:.6f}\n'\
            f'Optimized gamma:       {gamma_opt:.6f}\n'\
            f'Approx. ground state energy: {result.fun:.6f}'
    plt.text(2.0, 0.9, text, fontsize=10, fontfamily='monospace', color='black', ha='left', va='center', wrap=True)
    
    #[9] Save the plot
    plt.savefig(path_save)
    plt.close()
    return text

#[1] Set up the domain
y = np.linspace(-1, 12, 200)

#[5] Initial guess for alpha and beta
initial_guess = [0.5, 0.5, 0.5]

#[10] Perform the optimization
result = minimize(energy, initial_guess, args=(y), method='Nelder-Mead')
#result = minimize(energy, initial_guess, args=(y,), method='Nelder-Mead')

#[15] Extract the optimized parameters
alpha_opt, beta_opt, gamma_opt = result.x

#[20] Plot the optimized wavefunction
timestamp = datetime.now().strftime("%Y-%m%d-%H%M%S")
path_save = os.path.join(dir_save, f'plot_potential_and_prob_distr_{timestamp}.jpg')
text = plot_potential_and_prob_distr(y, alpha_opt, beta_opt, gamma_opt, path_save)
print(text)

def check_normalization(y, alpha_opt, beta_opt, gamma_opt):
    psi_unnorm = psi(y, 1, alpha_opt, beta_opt, gamma_opt)
    normalization_factor = np.sqrt(simps(psi_unnorm**2, y))

    # Normalize psi
    psi_val = psi(y, normalization_factor, alpha_opt, beta_opt, gamma_opt)
    
    # Re-normalize to ensure total integral of psi_squared = 1
    integral_psi_squared = simps(psi_val**2, y)
    psi_val_normalized = psi_val / np.sqrt(integral_psi_squared)

    # Check normalization
    norm_check = simps(psi_val_normalized**2, y)
    print(f"Normalization factor: {normalization_factor}")
    print(f"Integral of psi_squared over y after re-normalization: {norm_check}")

# Run normalization check again after revising the code
check_normalization(y, alpha_opt, beta_opt, gamma_opt)





