from scipy import linalg

def u_n(n, y, y_max):
    return np.sqrt(1/y_max) * np.cos((2*n-1)*np.pi*y/(2*y_max))

def kinetic_matrix_element(n, m, y_max):
    if n == m:
        return ((2*n-1)**2 * np.pi**2) / (4 * y_max**2)
    else:
        return 0

def potential_matrix_element(n, m, y_max, N_y):
    y = np.linspace(-y_max, y_max, N_y+1)
    h = 2*y_max / N_y
    integrand = u_n(n, y, y_max) * y**4 * u_n(m, y, y_max)
    return h * np.sum(integrand)

def compute_ground_state(N, y_max, N_y):
    H = np.zeros((N, N))
    for n in range(1, N+1):
        for m in range(1, N+1):
            H[n-1, m-1] = kinetic_matrix_element(n, m, y_max) + potential_matrix_element(n, m, y_max, N_y)
    
    eigenvalues, eigenvectors = linalg.eigh(H)
    return eigenvalues[0], eigenvectors[:, 0]

