import os, sys
import numpy as np
import pandas as pd
from scipy import linalg
from tabulate import tabulate
from datetime import datetime
import matplotlib.pyplot as plt

dir_save = r'D:\01_Floor\a_Ed\09_EECS\10_Python\04_OngoingTools\2024-1018_QSP HW Simulation\QSP-04_HW12-3'

import numpy as np
import matplotlib.pyplot as plt
import os
from datetime import datetime
from scipy.optimize import fsolve, root


#[1] Constants
k_B = 8.617333262145e-5  # Boltzmann constant in eV/K
T_min, T_max = 2, 3700  # Temperature range in K
arr_T = np.linspace(T_min, T_max)  # Temperature array #[1] Temperature range

"""
For silicon doped with phosphorus:    E_C = E_D + 0.045 eV
For N-doped diamond:                  E_C = E_D + 1.6 eV
For P-doped diamond:                  E_C = E_D + 0.57 eV
Set E_V as 0 and use E_g = E_C - E_V to calculate E_C.
"""
E_V = 0

#[2] Silicon Constants
E_g_Si = 1.12  # Band gap for Silicon in eV
abv_E_D_Si = 0.045  # Donor level for Silicon in eV
N_C_Si = 2.86e19 * (arr_T / 300) ** (3 / 2)
N_V_Si = 3.10e19 * (arr_T / 300) ** (3 / 2) 
N_D_Si = 1e15

#[3] Diamond Constants
E_g_Dia = 5.5  # Band gap for Diamond in eV
abv_E_D_NDia = 1.6  # Donor energy for N-doped diamond in eV
abv_E_D_PDia = 0.57  # Donor energy for P-doped diamond in eV
N_V_Dia = N_V_Si  # Diamond valence band density approximation
N_C_Dia = 2*N_C_Si  #[4] Diamond conduction band density approximation
N_D_Dia = 1e15


def solve_cubic_y_equation(E_g, abv_E_D, N_D, N_C, N_V, k_B, arr_T):
    #[1] Ensure all inputs are arrays with the same length as arr_T
    arr_T = np.asarray(arr_T)
    n = len(arr_T)
    E_d = E_g - abv_E_D # E_d = E_D but just use a different name here.
    
    #[2] Preallocate arrays
    arr_n = np.zeros_like(arr_T, dtype=float)
    arr_p = np.zeros_like(arr_T, dtype=float)
    y_vals = np.zeros_like(arr_T, dtype=float)
    
    #[5] Solve for each value in arr_T
    for i in range(n):
        kB_T = k_B * arr_T[i]
        coef_ans = 'ver2'
        
        if coef_ans == 'ver1':
            A = N_V[i] * np.exp(-E_g / kB_T)
            B = 2 * N_V[i] * np.exp(- E_d / kB_T) + N_D
            C = -N_C[i]
            D = -2 * N_C[i] * np.exp(abv_E_D / kB_T)
        elif coef_ans == 'ver2':
            A = 2*N_V[i] * np.exp(-E_g / kB_T)
            B = N_V[i] * np.exp(- E_d / kB_T)
            C = N_D * np.exp(E_g - E_d / kB_T) - 2 * N_C[i]
            D = N_C[i] * np.exp(-abv_E_D / kB_T)
        
        #[8] Coefficients of the cubic equation
        coeffs = [A, B, C, D]
        
        #[10] Solve the cubic equation
        if i < 50:
            y_guess = 6e4
        elif i < 200:
            y_guess = 5.2e4
        else:
            y_guess = 1e3  # Generic fallback guess for higher temperatures

        #[12] Use fsolve to refine the root
        def cubic_eq(y):
            return A * y**3 + B * y**2 + C * y + D

        y = fsolve(cubic_eq, y_guess)[0]

        #[14] Handle edge cases: filter real, positive roots
        if y <= 0:
            roots_y = np.roots(coeffs)
            real_positive_roots = roots_y[np.isreal(roots_y) & (np.real(roots_y) > 0)]
            y = max(real_positive_roots.real) if len(real_positive_roots) > 0 else 0

        
        #[16] Finalize arrays
        y_vals[i] = y
        arr_n[i] = N_C[i] / y if y > 0 else 0
        arr_p[i] = A * y if y > 0 else 0
    return arr_n, arr_p


def carrier_concentrations(E_g, y_eq, N_C, N_V, arr_T):
    arr_T = np.maximum(arr_T, 1e-3)
    p = y_eq * N_V * np.exp(-E_g / (k_B * arr_T))
    n = N_C / y_eq
    
    return n, p


def plot_carrier_concerntration(arr_T, arr_n, arr_p, arr_xlim, arr_ylim, t_lable, t_title, path_save):
    plt.figure(figsize=(8, 6))
    plt.plot(arr_T, arr_n, label=f'Electron Concentration {t_lable}', color='blue')
    plt.plot(arr_T, arr_p, label=f'Hole Concentration {t_lable}', color='red')
    plt.yscale("log")
    plt.xlabel("Temperature (K)")
    plt.ylabel("Carrier Concentration (cm^-3)")
    plt.xlim(arr_xlim)
    plt.ylim(arr_ylim)
    plt.legend()
    plt.title(t_title)
    plt.grid(True, which='both', linestyle='--', linewidth=0.5)
    plt.savefig(path_save)






# [8] Silicon Plot
E_c_Si = E_g_Si - E_V
E_D_Si = E_c_Si - abv_E_D_Si
arr_n_Si, arr_p_Si = solve_cubic_y_equation(E_g_Si, abv_E_D_Si, N_D_Si, N_C_Si, N_V_Si, k_B, arr_T)
arr_xlim = [0, 800]
arr_ylim = [1e12, 1e16]
t_lable = '(Si)'
t_title = 'Carrier Concentrations in n-type Silicon vs Temperature'
timestamp = datetime.now().strftime("%y%m%d-%H%M")
path_save = os.path.join(dir_save, f'{timestamp}_v1-1-Silicon.jpg')
plot_carrier_concerntration(arr_T, arr_n_Si, arr_p_Si, arr_xlim, arr_ylim, t_lable, t_title, path_save)


# [9] Diamond (N-doped)
E_c_Dia = E_g_Dia - E_V
E_D_NDia = E_c_Dia - abv_E_D_NDia
arr_n_DiaN, arr_p_DiaN = solve_cubic_y_equation(E_g_Dia, abv_E_D_NDia, N_D_Dia, N_C_Dia, N_V_Dia, k_B, arr_T)
arr_xlim = [0, 3500]
arr_ylim = [1e12, 1e18]
t_lable = '(N-Doped Diamond)'
t_title = 'Carrier Concentrations for N-Doped Diamond'
timestamp = datetime.now().strftime("%y%m%d-%H%M")
path_save = os.path.join(dir_save, f'{timestamp}_v1-2-N Diamond.jpg') 
plot_carrier_concerntration(arr_T, arr_n_DiaN, arr_p_DiaN, arr_xlim, arr_ylim, t_lable, t_title, path_save)


# [10] Diamond (P-doped)
E_c_Dia = E_g_Dia - E_V
E_D_PDia = E_c_Dia - abv_E_D_PDia
arr_n_DiaP, arr_p_DiaP = solve_cubic_y_equation(E_g_Dia, abv_E_D_PDia, N_D_Dia, N_C_Dia, N_V_Dia, k_B, arr_T)
arr_xlim = [0, 3500]
