import os, sys
import numpy as np
import pandas as pd
from scipy import linalg
from tabulate import tabulate
from datetime import datetime
import matplotlib.pyplot as plt

dir_save = r'D:\01_Floor\a_Ed\09_EECS\10_Python\04_OngoingTools\2024-1018_QSP HW Simulation\QSP-04_HW12-3'


import numpy as np
import matplotlib.pyplot as plt
from scipy.optimize import brentq

# Constants
k_B = 8.617333262145e-5  # Boltzmann constant in eV/K
T_min, T_max = 1, 800  # Reduced temperature range for stability
arr_T = np.linspace(T_min, T_max, 500)

# Silicon constants
E_g_Si = 1.12  # Band gap for Silicon in eV
abv_E_D_Si = 0.045  # Donor level for Silicon in eV
N_C_Si = 2.86e19 * (arr_T / 300) ** (3 / 2)
N_V_Si = 3.10e19 * (arr_T / 300) ** (3 / 2)

# Function to find the real root
def find_root(E_g, E_C, E_D, N_C, N_V, T):
    A = N_V * np.exp(-E_g / (k_B * T))
    B = 2 * N_V * np.exp((E_C - E_D) / (k_B * T)) + N_D
    C = -N_C
    D = -2 * N_C * np.exp((E_C - E_D) / (k_B * T))
    
    def cubic(y):
        return A * y**3 + B * y**2 + C * y + D
    
    y_root = brentq(cubic, 1e-10, 1e10)
    return y_root

# Carrier concentrations
def carrier_concentrations(E_g, y_eq, N_C, N_V, T):
    p = y_eq * N_V * np.exp(-E_g / (k_B * T))
    n = N_C / y_eq
    return n, p

# Silicon Plot
E_c_Si = E_g_Si
E_D_Si = E_c_Si - abv_E_D_Si
N_D = 1e15  # Assume a doping density

n_Si = np.zeros_like(arr_T)
p_Si = np.zeros_like(arr_T)

for i, T in enumerate(arr_T):
    y_eq = find_root(E_g_Si, E_c_Si, E_D_Si, N_C_Si[i], N_V_Si[i], T)
    n_Si[i], p_Si[i] = carrier_concentrations(E_g_Si, y_eq, N_C_Si[i], N_V_Si[i], T)

plt.figure()
plt.plot(arr_T, n_Si, label="Electron Concentration (Si)", color='blue')
plt.plot(arr_T, p_Si, label="Hole Concentration (Si)", color='red')
plt.yscale("log")
plt.xlabel("Temperature (K)")
plt.ylabel("Carrier Concentration (cm$^{-3}$)")
plt.legend()
plt.title("Carrier Concentrations for Silicon")
plt.show()












# End of [QSP-07_HW12-3_v2.py]




