# Constants for the potential
G = 1  # Gravitational constant (arbitrary units)
M = 1  # Mass of the central body
L = 1  # Angular momentum (arbitrary units)
m = 1  # Particle mass

# Effective potential function
def effective_potential(r):
    return -G * M / r + L**2 / (2 * m * r**2)

# Range for radial distances
r = np.linspace(0.1, 6, 500)  # Avoid r = 0 to prevent division by zero

# Values of total energy for different cases
E_circular = effective_potential(2)  # Example circular orbit at r = 2
E_elliptical = E_circular - 0.1      # Slightly less energy
E_hyperbolic = E_circular + 0.1      # Slightly more energy

# Plot the effective potential
plt.figure(figsize=(10, 6))
plt.plot(r, effective_potential(r), label="Effective Potential $V_{eff}(r)$", color='black')
plt.axhline(E_circular, color='blue', linestyle='--', label="Circular Orbit Energy $E_{circular}$")
plt.axhline(E_elliptical, color='green', linestyle='--', label="Elliptical Orbit Energy $E_{elliptical}$")
plt.axhline(E_hyperbolic, color='red', linestyle='--', label="Hyperbolic Orbit Energy $E_{hyperbolic}$")

# Annotate stable circular orbit
plt.scatter([2], [E_circular], color='blue', label="Circular Orbit at $r=2$", zorder=5)

# Formatting the plot
plt.xlabel("Radial Distance $r$")
plt.ylabel("Energy / Potential")
plt.title("Effective Potential and Orbit Classification")
plt.legend()
plt.grid()
plt.xlim(0, 6)
plt.ylim(-1, 1)  # Adjust based on potential behavior



# Save the plot
timestamp = datetime.now().strftime("%y%m%d-%H%M")
path_save = os.path.join(dir_save, f'{timestamp}_Effective Potential and Orbit Classification.jpg')
plt.savefig(path_save)


