def OpenAI_text_embedding(model_name, openai_api_key, content_for_embedding):
    """
    Embedding models (https://openai.com/api/pricing/)
    text-embedding-3-small      ($0.020 / 1M tokens)    20743
    text-embedding-3-large      ($0.130 / 1M tokens)    42039
    text-embedding-ada-002      ($0.100 / 1M tokens)    20936
    """
    #print('\n[OpenAI_text_embedding]')
    openai_api_url = f"https://api.openai.com/v1/embeddings"
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Bearer {openai_api_key}"}
    data = {
        "input": content_for_embedding,
        "model": model_name}
    response = requests.post(openai_api_url, headers=headers, data=json.dumps(data))
    if response.status_code == 200:
        response_data = response.json()
        embedding = response_data["data"][0]["embedding"]
        return embedding
    else:
        print("Error:", response.status_code, response.text, sep='\n')
        return None

