import os, sys, cv2
import numpy as np
import pandas as pd
from tabulate import tabulate
from datetime import datetime
import matplotlib.pyplot as plt

import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import Dataset, DataLoader
from sklearn.model_selection import train_test_split




import torch.nn as nn

class EmbeddingScoreNet(nn.Module):
    def __init__(self, input_dim, hidden_dim=512, num_layers=3):
        #[1] Check layers.
        super(EmbeddingScoreNet, self).__init__()
        if num_layers < 2 or num_layers > 5:
            raise ValueError("num_layers must be between 2 and 5.")
        if hidden_dim <= num_layers**2 or hidden_dim % (2 ** num_layers) != 0:
            raise ValueError("hidden_dim must be larger than 2 to the power of num_layers, and can be divided by 2")
        layers = []
        current_dim = input_dim
        
        #[2] Create hidden layers dynamically
        for i in range(num_layers - 1):
            next_dim = hidden_dim // (2 ** i)  # Reduce dimensions by half at each layer
            layers.append(nn.Linear(current_dim, next_dim))
            layers.append(nn.ReLU())
            current_dim = next_dim
        
        #[3] Add final output layer
        layers.append(nn.Linear(current_dim, 1))
        
        self.model = nn.Sequential(*layers)

    def forward(self, x):
        return self.model(x)

    
    

# Custom dataset
class EmbeddingScoreDataset(Dataset):
    def __init__(self, embeddings, scores):
        self.embeddings = torch.FloatTensor(embeddings)
        self.scores = torch.FloatTensor(scores)

    def __len__(self):
        return len(self.scores)

    def __getitem__(self, idx):
        return self.embeddings[idx], self.scores[idx]

# Function to prepare data
def prepare_data(X, y, test_size=0.2, val_size=0.1, batch_size=32):
    # First, split into training+validation and testing
    X_train_val, X_test, y_train_val, y_test = train_test_split(X, y, test_size=test_size, random_state=42)
    
    # Then, split training+validation into training and validation
    val_split = val_size / (1 - test_size)  # Adjust validation size based on training+validation size
    X_train, X_val, y_train, y_val = train_test_split(X_train_val, y_train_val, test_size=val_split, random_state=42)
    
    # Create datasets
    train_dataset = EmbeddingScoreDataset(X_train, y_train)
    val_dataset = EmbeddingScoreDataset(X_val, y_val)
    test_dataset = EmbeddingScoreDataset(X_test, y_test)
    
    # Create data loaders
    train_loader = DataLoader(train_dataset, batch_size=batch_size, shuffle=True)
    val_loader = DataLoader(val_dataset, batch_size=batch_size)
    test_loader = DataLoader(test_dataset, batch_size=batch_size)
    
    return train_loader, val_loader, test_loader

# Function to train the model
def train_model(model, train_loader, val_loader, num_epochs, learning_rate):
    criterion = nn.MSELoss()
    optimizer = optim.Adam(model.parameters(), lr=learning_rate)
    list_epoch, list_tl, list_vl = [], [], []
    
    for epoch in range(num_epochs):
        #[1] Training phase
        model.train()
        running_loss = 0.0
        for embeddings, scores in train_loader:
            optimizer.zero_grad()
            outputs = model(embeddings)
            loss = criterion(outputs.squeeze(), scores)
            loss.backward()
            optimizer.step()
            running_loss += loss.item()
        
        avg_train_loss = running_loss / len(train_loader)
        list_tl.append(avg_train_loss)
        
        #[2] Validation phase
        model.eval()
        val_loss = 0.0
        with torch.no_grad():
            for embeddings, scores in val_loader:
                outputs = model(embeddings)
                loss = criterion(outputs.squeeze(), scores)
                val_loss += loss.item()
        
        avg_val_loss = val_loss / len(val_loader)
        list_vl.append(avg_val_loss)
        
        #[3] Print losses for the epoch
        list_epoch.append(epoch + 1)
        print(f'Epoch {epoch + 1:03d}/{num_epochs:03d}, '\
                f'Train Loss Mean: {avg_train_loss:.4f}, '\
                f'Validation Loss: {avg_val_loss:.4f}')
    
    #[5] Collect into dataframe.
    df_train = pd.DataFrame({'list_epoch': list_epoch,
                             'list_tl': list_tl,
                             'list_vl': list_vl})
    return df_train






# Function to evaluate the model
def evaluate_model(model, test_loader):
    model.eval()
    predictions = []
    actual_scores = []
    with torch.no_grad():
        for embeddings, scores in test_loader:
            outputs = model(embeddings)
            predictions.extend(outputs.squeeze().tolist())
            actual_scores.extend(scores.tolist())
    
    correlation = np.corrcoef(predictions, actual_scores)[0, 1]
    print(f"Correlation between predicted and actual scores: {correlation:.4f}")
    return correlation


    












def visualize_pca_fit(X_train_pca, X_test_pca, y_train, y_test, save_path):
    """
    Visualize the PCA fitting using the first two principal components and save the plot as a JPG.

    Parameters:
        X_train_pca (numpy array): Transformed training data in PCA space.
        X_test_pca (numpy array): Transformed testing data in PCA space.
        y_train (numpy array): Training labels.
        y_test (numpy array): Testing labels.
        save_path (str): Path to save the visualization as a JPG.
    """
    plt.figure(figsize=(10, 8))

    # Scatter plot for the training set
    plt.scatter(X_train_pca[:, 0], X_train_pca[:, 1], c=y_train, cmap='viridis', alpha=0.7, label='Train')
    # Scatter plot for the testing set
    plt.scatter(X_test_pca[:, 0], X_test_pca[:, 1], c=y_test, cmap='cool', alpha=0.7, label='Test')

    # Plot settings
    plt.colorbar(label='Score')
    plt.title('PCA Visualization (First Two Principal Components)')
    plt.xlabel('Principal Component 1')
    plt.ylabel('Principal Component 2')
    plt.legend()
    plt.grid()

    # Save as a JPEG
    plt.savefig(save_path, format='jpg', dpi=300)
    plt.close()

