def add_text_in_plot_with_new_line_and_tab(ax, pos_x, pos_y, text, 
                                           linespace=0.05, ft_size=12, color='gray',
                                           tab_replacement='    '):
    #[1] Replace tabs with spaces
    formatted_text = text.replace("\t", tab_replacement)
    
    #[2] Add text line by line
    lines = formatted_text.split("\n")
    i_pos_y = pos_y
    for i, line in enumerate(lines):
        #[3] Adjust position for each line.
        if line and (line[0] == '[' or line[-1] == ':'): 
            i_pos_y -= linespace * 1.5
        else:
            i_pos_y -= linespace 
        
        #[4] Add text.
        ax.text(
            pos_x, i_pos_y,
            line,
            transform=ax.transAxes,
            fontsize=ft_size, 
            color = color,
            verticalalignment='top',
            horizontalalignment='left')    



def plot_training_result(df_train, text, path_save=None):
    #[1] Plot settings
    plt.figure(figsize=(10, 6))
    ax = plt.gca()

    #[2] Plot training and validation loss
    list_epoch = df_train['list_epoch'].tolist()
    list_tl = df_train['list_tl'].tolist()
    list_vl = df_train['list_vl'].tolist()
    plt.plot(list_epoch, list_tl, marker='o', label='Training Loss')
    plt.plot(list_epoch, list_vl, marker='s', label='Validation Loss')
    plt.xlabel('Epoch')
    plt.ylabel('Loss')
    plt.xlim(0, len(list_epoch) + 1)
    y_max = (max(max(list_tl), max(list_vl)) * 1.1) // 10 * 10
    plt.ylim(0, )  # Adjust ylim dynamically
    plt.title('Training and Validation Loss Over Epochs')
    plt.legend()
    plt.grid()

    #[3] Add text box with provided information
    add_text_in_plot_with_new_line_and_tab(ax, 0.50, 0.70, text, 0.04, 12, tab_replacement='    ')

    #[4] Save the plot
    if path_save:
        plt.savefig(path_save, bbox_inches='tight')  # Use tight bounding box for better saving
        print(f'-- Plot saved at: {path_save}')
    else:
        plt.show()










