#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Created on Thu Oct  3 14:08:22 2024

@author: tyyang
"""


import refinitiv.data as rd
import pandas as pd
import matplotlib.pyplot as plt

def get_QQQ_tickers():
    df = pd.read_csv('./QQQ-holdings.csv')
    tickers = df[df['Symbol'] != '--'].Symbol.values.tolist()
    return [ticker + '.O' for ticker in tickers]

def resembling(df, target):
    ticker = df['Instrument'].iloc[0].replace('.O', '')
    df = df[['Date', target]]
    df['Year'] = df['Date'].dt.year
    df = df.groupby('Year').last().reset_index()
    df.drop(columns=['Date'], inplace=True)
    df.columns = ['Year', ticker]
    return df

def get_refinitiv_data(tickers, fields, target_column):
    df_list = []
    failed_list = []

    for ticker in tickers:
        try:
            df = rd.get_data(
                universe=[ticker],
                fields=fields,
                parameters={'Period': 'FY0', 'Frq': 'FY', 'SDate': 0, 'EDate': '-24'}
            )
            df_list.append(df)
        except Exception as e:
            print(f"{ticker} failed: {e}")
            failed_list.append(ticker)

    if df_list:
        merged_df = resembling(df_list[0], target_column)

        for df in df_list[1:]:
            df = resembling(df, target_column)
            merged_df = pd.merge(merged_df, df, on="Year", how="outer")

        return merged_df, failed_list
    else:
        return pd.DataFrame(), failed_list

# Main execution
tickers = get_QQQ_tickers()

rd.open_session()

# Get ESG Score data
fields_esg = ['TR.TRESGScore.date', 'TR.TRESGScore']
merged_esg_df, failed_esg = get_refinitiv_data(tickers, fields_esg, 'ESG Score')

# Get Pricing data
fields_price = ['TR.PriceClose.date', 'TR.PriceClose']
merged_price_df, failed_price = get_refinitiv_data(tickers, fields_price, 'Price Close')

# If you need to handle failed tickers, you can do so here:
print(f"Failed ESG tickers: {failed_esg}")
print(f"Failed Pricing tickers: {failed_price}")



for ticker in tickers:
    try:
        fig, ax = plt.subplots()
        ticker = ticker.replace('.O', '')
        e_data = merged_esg_df[['Year', ticker]]
        p_data = merged_price_df[['Year', ticker]]
        ep_data = pd.merge(e_data, p_data, on="Year", how="left")
        ep_data.columns = ['Year', 'ESG Score', 'Price']
        
        norm_esg = (ep_data['ESG Score'] - ep_data['ESG Score'].min()) / (ep_data['ESG Score'].max() - ep_data['ESG Score'].min())
        norm_price = (ep_data['Price'] - ep_data['Price'].min()) / (ep_data['Price'].max() - ep_data['Price'].min())
        ax.scatter(norm_esg, norm_price)
        ax.set_xlabel('ESG Score')
        ax.set_ylabel('Stock Price')
        ax.set_title(ticker)
    except:
        print(ticker)

# End of [get_esg_score_and_price.py]




