#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Created on Wed Oct  2 21:23:19 2024

@author: tyyang
"""


import refinitiv.data as rd
import pandas as pd
from refinitiv.data.content import esg


def get_QQQ_tickers():
    df = pd.read_csv('./QQQ-holdings.csv')
    tickers = df[df['Symbol'] != '--'].Symbol.values.tolist()
    return tickers

def resembling(df, target):
    ticker = df['Instrument'].iloc[0].replace('.O', '')
    df = df[['Date', target]]
    df['Year'] = df['Date'].dt.year
    df = df.groupby('Year').last().reset_index()
    df.drop(columns=['Date'], inplace=True)
    df.columns = ['Year', ticker]
    return df

tickers = get_QQQ_tickers()

rd.open_session()

# =============================================================================
# ESG Score
# =============================================================================
df_list = []
failed_list = []
for ticker in tickers:
    ticker = ticker + '.O'
    try:
        df = rd.get_data(
            universe=[ticker],
            fields=[
                'TR.TRESGScore.date',
                'TR.TRESGScore',
                'TR.EnvironmentPillarScore',
                'TR.SocialPillarScore',
                'TR.GovernancePillarScore'],
            parameters={'Period':'FY0', 'Frq':'FY', 'SDate':0, 'EDate':'-24'})
        df_list.append(df)
    except:
        print(f"{ticker} failed ...")
        failed_list.append(ticker)
        tickers.remove(ticker)

# ----------- #
# ESG #
# ----------- #
merged_df = df_list[0]
merged_df = resembling(merged_df, "ESG Score")

for df in df_list[1:]:
    df = resembling(df, "ESG Score")
    merged_df = pd.merge(merged_df, df, on="Year", how="outer")  

esg_score = merged_df[merged_df['Year'] == 2022].iloc[:, 1:].T

# ----------- #
# Environment #
# ----------- #
merged_df = df_list[0]
merged_df = resembling(merged_df, "Environmental Pillar Score")

for df in df_list[1:]:
    df = resembling(df, "Environmental Pillar Score")
    merged_df = pd.merge(merged_df, df, on="Year", how="outer")  

e_score = merged_df[merged_df['Year'] == 2022].iloc[:, 1:].T

result = pd.merge(esg_score, e_score, left_index=True, right_index=True)
result.columns = ['ESG Score', 'E Score']

result.to_csv('LSEG_Score.csv')
