# 
# =============================================================================
parser = argparse.ArgumentParser()
parser.add_argument("--pdf_path", type=str, default=None)
parser.add_argument("--pdf_url", type=str, default=None)
parser.add_argument("--basic_info_dir", type=str, default='data/basic_info')
parser.add_argument("--llm_name", type=str, default='gpt-3.5-turbo')
parser.add_argument("--answers_dir", type=str, default='data/answers')
parser.add_argument("--assessment_dir", type=str, default='data/assessment')
parser.add_argument("--vector_db_dir", type=str, default='data/vector_db')
parser.add_argument("--retrieved_chunks_dir", type=str, default='data/retrieved_chunks')
parser.add_argument("--user_qa_dir", type=str, default='data/user_qa')
parser.add_argument("--user_question", type=str, default='')
parser.add_argument("--answer_length", type=int, default=50)
parser.add_argument("--detail", action='store_true', default=False)
parser.add_argument("--top_k", type=int, default=20)
args = parser.parse_args()

report_dir  = 'SP500_2022'
report_paths = os.listdir(report_dir)
report_paths = [os.path.join(report_dir, f) for f in report_paths]

failed_files = []
for pdf_path in report_paths:
    try:
        if pdf_path:
            report_name = os.path.basename(pdf_path)
        else:
            assert (args.pdf_url is not None)
            report_name = args.pdf_url.split('/')[-1]
        assert report_name.endswith('.pdf')
        report_name = report_name.replace('.pdf', '')
        
        

        # =============================================================================
        # Test Report 
        # This part the program will extract the most relevent information related to QUERIES 
        # from the ESG report. 
        # =============================================================================
        report = ESGReport(
            path=pdf_path,
            url=pdf_url,
            store_path=os.path.join(destination_dir, report_name + '.pdf'),
            db_path=os.path.join(vector_db_dir, report_name),
            retrieved_chunks_path=os.path.join(retrieved_chunks_dir, report_name)
        )
        
        
        # =============================================================================
        # Find GRI related Promt
        # =============================================================================
        gri_prompt = PromptTemplate(template=GRI_PROMPTS, input_variables=["context"])
        
        message = [
            SystemMessage(content=SYSTEM_PROMPT),
            HumanMessage(content=gri_prompt.format(
                         context=_docs_to_string(report.section_text_dict['gri_302_1'], with_source=True)))
        ]
        
        llm = ChatOpenAI(temperature=0, max_tokens=512)
        
        output_text = llm(message).content
        
        data = json.loads(output_text)
        
        def replace_sources(data, source_list):
            for item in data["points"]:
                # Extract the index from the "source" field (e.g., "Source: 714")
                match = re.search(r'Source: (\d+)', item["source"])
                if match:
                    index = int(match.group(1))  # Get the index as an integer
                    # Use the index to replace with the corresponding value from source_list
                    if 0 <= index < len(source_list):
                        item["source"] = source_list[index]  # Replace with the value from source_list
                    else:
                        item["source"] = "Unknown Source"  # Handle out-of-bounds index
            return data
        
        updated_data = replace_sources(data, report.page_idx)
        updated_json_text = json.dumps(updated_data, indent=4)
        
        summary_json_path = os.path.join(summary_json_dir, report_name)
        
        if not os.path.exists(summary_json_path):
            os.makedirs(summary_json_path)
        
        with open(os.path.join(summary_json_path, 'summary.json'), 'w') as f:
            json.dump(updated_data, f, indent=4)  # indent for pretty formatting
        
    except:
        print(f"Failed :{pdf_path}")
        failed_files.append(pdf_path)

