"""
[ERC_M1.py]
Purpose: The modual for ESG report crawler.
Author: tyyang, 
Modify: Meng-Chi Ed Chen
Date: 2024-11-21
Reference:
    1.
    2.

Status: Complete.
"""


import os
import requests
import pandas as pd
import logging
from selenium import webdriver
from selenium.webdriver.common.by import By
from selenium.webdriver.support.ui import WebDriverWait
from selenium.webdriver.support import expected_conditions as EC
from pathlib import Path
import Levenshtein



# Constants
BASE_URL = 'https://www.responsibilityreports.com/Companies?search='
PDF_XPATH = "//a[contains(@href, '.pdf')]"
COMPANY_LINK_XPATH = "//span[@class='companyName']/a"
BUTTON_CLASS = "btn_archived view_annual_report"

# Function to compare names
def compare_names(name1, name2):
    """Calculate normalized Levenshtein similarity score between two names."""
    distance = Levenshtein.distance(name1, name2)
    max_len = max(len(name1), len(name2))
    similarity = 1 - distance / max_len
    return similarity

# Function to find target link
def find_target_link(links, company_name):
    """Select the best matching link for the company name."""
    if len(links) == 1:
        return links[0]
    
    min_similarity = 0.0
    target_link = None
    company_name_clean = company_name.lower().replace('-', '').replace(' ', '')
    
    for link in links:
        href = link.get_attribute('href')
        name = href.split('/')[-1].replace('-', '').lower()
        similarity = compare_names(name, company_name_clean)
        
        if similarity > min_similarity:
            min_similarity = similarity
            target_link = link
    
    return target_link

# Function to download PDF
def download_pdf(pdf_url, output_folder):
    """Download a PDF from the provided URL."""
    try:
        response = requests.get(pdf_url, stream=True)
        response.raise_for_status()

        output_filename = Path(output_folder) / pdf_url.split('/')[-1]
        
        with open(output_filename, 'wb') as file:
            for chunk in response.iter_content(chunk_size=1024):
                if chunk:
                    file.write(chunk)
        logging.info(f"Downloaded: {output_filename}")
    except Exception as e:
        logging.error(f"Failed to download {pdf_url}: {e}")

# Function to download ESG reports
def download_esg_report(ticker, target_year, output_folder, company_name=None):
    """Fetch and download ESG reports for a specific company."""
    driver = webdriver.Chrome()
    
    try:
        # Open the page for the company
        driver.get(BASE_URL + ticker)
        WebDriverWait(driver, 10).until(EC.presence_of_element_located((By.XPATH, COMPANY_LINK_XPATH)))

        # Find company link
        links = driver.find_elements(By.XPATH, COMPANY_LINK_XPATH)
        target_link = find_target_link(links, company_name)
        
        if target_link is None:
            logging.warning(f'{ticker}: Cannot find company link')
            return
        
        target_link.click()
        
        # Find PDF links
        wait = WebDriverWait(driver, 10)
        pdf_links = wait.until(EC.presence_of_all_elements_located((By.XPATH, PDF_XPATH)))

        href_list = []
        for link in pdf_links:
            href = link.get_attribute('href')
            if href not in href_list:
                href_list.append(href)

        # Download the target year's PDF
        for href in href_list:
            report_name = href.split('/')[-1]
            year_str = report_name.split('_')[-1][:-4]

            if year_str.isdigit():
                year = int(year_str)
                if year == target_year:
                    download_pdf(href, output_folder)
                    return
        logging.info(f"No reports found for {ticker} in year {target_year}")
    
    except Exception as e:
        logging.error(f"Error processing {ticker}: {e}")
    
    finally:
        driver.quit()
        

def filter_file_in_dir_with_keywords(dir_folder, list_kwd_yes_or_1=[], list_kwd_no_or_2=[], print_bsn = False):
    print(f'\n[filter_file_in_dir_with_keywords] dir_folder = {dir_folder}')
    #[1] Check if directory exists
    if not os.path.isdir(dir_folder):
        raise FileNotFoundError(f'The directory {dir_folder} was not found.')
    
    #[2] Get list of files in the directory, no folders.
    list_bsns = [file for file in os.listdir(dir_folder) if os.path.isfile(os.path.join(dir_folder, file))]
    cnt_before = len(list_bsns)
    
    #[3] Filter names by keywords to select (if list_kwd_yes_or_1 is not empty list).
    if list_kwd_yes_or_1 != []:
        list_bsns = [file for file in list_bsns if any(keyword in file for keyword in list_kwd_yes_or_1)]
    
    #[4] Filter names by keywords to discard (if list_kwd_no_or_2 is not empty list).
    if list_kwd_no_or_2 != []:
        list_bsns = [file for file in list_bsns if not any(keyword in file for keyword in list_kwd_no_or_2)]
        
    #[5] Generate file paths and orint
    list_paths = [os.path.join(dir_folder, file) for file in list_bsns]
    cnt_after = len(list_bsns)
    if print_bsn:
        print(f'\n--  Count (before, after) = {cnt_before}, {cnt_after}. list_bsns: \n{list_bsns}', end='\n\n')
    return list_paths, list_bsns
# End of [ERC_M1.py]




