def crop_image_interface(i, image_path, save_dir, crop_size):
    """
    Opens an image for interactive cropping.
    Allows the user to click on the image to position a fixed-size crop box.
    """
    #[1] Initial settings.
    crop_width, crop_height = crop_size
    create_crop_box = True  # Default to show the crop box at the center
    end_the_loop = False
    single_img_crop = 0
    window_name = f'Image Cropper | size={crop_size}, r=reset, c=crop, n=next, q=quit.'

    #[3] Load the image
    image = cv2.imread(image_path)
    clone = image.copy()
    status_message = f'[{i:03d}] Processing: {i_path_img}'
    print(status_message)
    
    #[5] Initialize the crop box at the center of the image
    center_x, center_y = image.shape[1] // 2, image.shape[0] // 2
    top_left = (center_x - crop_width // 2, center_y - crop_height // 2)
    
    cv2.namedWindow(window_name)

    def click_and_crop(event, x, y, flags, param):
        nonlocal top_left, create_crop_box
        if event == cv2.EVENT_LBUTTONDOWN:
            # Calculate the top-left corner of the crop box
            x1 = max(0, x - crop_width // 2)
            y1 = max(0, y - crop_height // 2)
            x1 = min(x1, image.shape[1] - crop_width)  # Ensure the box fits
            y1 = min(y1, image.shape[0] - crop_height)
            top_left = (x1, y1)
            create_crop_box = True
            status_message = f'-- Mouse clicked at: ({x}, {y})'
            print(status_message)

    cv2.setMouseCallback(window_name, click_and_crop)

    while True:
        #[9] Detect if the window is closed
        if cv2.getWindowProperty(window_name, cv2.WND_PROP_VISIBLE) < 1:
            end_the_loop = True
            break

        #[10] Display the cropping box on the image
        display_image = clone.copy()
        if create_crop_box:
            x1, y1 = top_left
            x2, y2 = x1 + crop_width, y1 + crop_height
            cv2.rectangle(display_image, (x1, y1), (x2, y2), (0, 255, 0), 2)
        cv2.imshow(window_name, display_image)
        
        key = cv2.waitKey(1) & 0xFF
        #[15] Reset the crop box to the center
        if key == ord("r"):
            create_crop_box = True
            top_left = (center_x - crop_width // 2, center_y - crop_height // 2)
            image = clone.copy()
            status_message = '-- Crop box reset to center'
            print(status_message)

        # Confirm the crop
        elif key == ord("c"):
            if create_crop_box:
                x1, y1 = top_left
                x2, y2 = x1 + crop_width, y1 + crop_height
                cropped_image = clone[y1:y2, x1:x2]
                single_img_crop += 1
                bsn_ext = os.path.basename(image_path)
                bsn, ext = os.path.splitext(bsn_ext)
                save_path = os.path.join(save_dir, f'{bsn}_c{single_img_crop}{ext}')
                while os.path.exists(save_path):
                    single_img_crop += 1
                    save_path = os.path.join(save_dir, f'{bsn}_c{single_img_crop}{ext}')
                cv2.imwrite(save_path, cropped_image)
                status_message = f'-- Cropped image saved at: {save_path}'
                print(status_message) 

        # Quit without saving
        elif key == ord("n"):
            end_the_loop = False
            break

        # Quit the program
        elif key == ord("q"):
            end_the_loop = True
            break
        


    cv2.destroyAllWindows()
    return end_the_loop





#[1] Get the directory path from the command-line arguments
if len(sys.argv) < 2:
    message = (
        f"\nlen(sys.argv) = {len(sys.argv)}. sys.argv = {sys.argv}.\n"
        "This code is designed to be run from the terminal using a batch file and requires an input argument (typically a directory address).\n"
        "Please run the code using the batch file (.bat), or comment out this check if you are running it in a different environment.\n"
    )
    print(message)
    raise ValueError(message)
    sys.exit()

#[2] Remove trailing double-quote and slash if any
dir_current = sys.argv[1].rstrip('\"').rstrip('/')      
print(f'\nCurrent directory: {dir_current}')
#dir_folder = r'D:\05_Datasets\2024-1120_SEM Unet Dataset\01_Raw (convert to JPG)'
dir_folder = dir_current

#[2] Create processed folder.
dir_processed = os.path.join(dir_folder, '01_Processed')
M1F.make_dir_if_not_exist(dir_processed)

#[3] Create cropped folder.
dir_crop = os.path.join(os.path.dirname(dir_folder), '03_Cropped') 
M1F.make_dir_if_not_exist(dir_crop)

#[5] Filter files.
list_kwd_yes_or_1 = ['.jpg']
list_kwd_no_or_2 = ['_c', '_crop', '.bat']
list_paths, list_bsns = M1F.filter_file_in_dir_with_keywords(dir_folder, list_kwd_yes_or_1, list_kwd_no_or_2, False)

#[8] Crop size setting.
crop_size = (512, 512)

#[1] Check if list is empty.
if len(list_paths) == 0:
    print(f'The list is empty. Close in 5 seconds.')
    time.sleep(5)

for i, i_path_img in enumerate(list_paths):
    print(f'[{i:03d}] Processing: {i_path_img}')
    end_the_loop = crop_image_interface(i, i_path_img, dir_crop, crop_size)
    
    #[5] Check exit status.
    if end_the_loop is True:
        break
    else:
        M1F.relocate_single_file(i_path_img, dir_processed)

#[8] Complete
print('\nCompleted. Close in 5 seconds.')
time.sleep(5)


