import pandas as pd
from tabulate import tabulate
from datetime import datetime
import matplotlib.pyplot as plt
from PIL import Image


def check_training_data_directory(dir_data, list_allow_ext=['.jpg', '.png'], image_size_h_w = [512, 512], print_status=False):
    print('\n[check_training_data_directory]')
    #[1] Validate the directory path
    if not os.path.isdir(dir_data):
        raise ValueError(f'-- The provided directory {dir_data} does not exist.')
    list_path_error, list_bsnext_error = [], []
    
    #[2] Get a list of files in the directory with allowed extensions
    list_path = [os.path.join(dir_data, f) for f in os.listdir(dir_data) \
        if os.path.isfile(os.path.join(dir_data, f)) and os.path.splitext(f)[1].lower() in list_allow_ext]
    
    if not list_path:
        raise ValueError(f'-- No files with allowed extensions {list_allow_ext} found in {dir_data}.')

    #[3] Iterate through files
    for i, i_path in enumerate(list_path):
        i_bsnext = os.path.basename(i_path)
        if print_status:
            print(f'[{i:03d}] Processing {i_bsnext}. ', end='')
        
        try:
            #[5] Open image and check its size
            with Image.open(i_path) as img:
                if img.size == tuple(image_size_h_w[::-1]):  # PIL uses (width, height)
                    if print_status:
                        print('-- OK')
                else:
                    print(f'-- Size mismatch! {i_bsnext} \n Found {img.size}, expected {tuple(image_size_h_w[::-1])}.')
                    list_path_error.append(i_path)
                    list_bsnext_error.append(i_bsnext)
        except Exception as e:
            print(f'-- Error reading file: {e}')
            
    #[5] Final report.
    cnt_error = len(list_bsnext_error)
    if cnt_error == 0:
        print(f'-- All images are qualified.')
    else:
        print(f'-- Total {cnt_error} images are not qualified.')
    return i_path, i_bsnext



# End of [SUN_M2_Image.py]




