import os, sys, cv2, shutil
import numpy as np
import pandas as pd
from tabulate import tabulate
from datetime import datetime
import matplotlib.pyplot as plt



import torch
import torch.nn as nn
import torch.optim as optim
from torch.utils.data import DataLoader, Dataset
from torchvision import transforms
from PIL import Image



"""

I'm working on a python ML project of building a Unet for MoS2 SEM image embedding. 

1. The Unet will have encoder to turn input image with the size of 512x512x1 (in grayscale) into 
    a 8x8 bottleneck, and a decode will turn the dense representation of bottleneck back to 
    the original image with the size of 512x512x1. There will also be skip connections.
2. In generation mode (from the 8x8 bottleneck to decode to 512x512x1 grayscale image),    
    the skip connection will start with random noise.
3. The encoding and decoding stages are expect 
    to be 512x512x1 - 128x128x1 - 32x32x1 - 8x8x1, and 8x8x1 is the bottleneck embedding size.
4. Since this U-Net is intended to be used with either its encoder alone or its decoder alone, 
    to maintain  flexibility and robustness, I will use learnable skip connection, 
    introduce perturbed and dropout during training, and weighted skip connection at different layer.
5. The dimension for the bottleneck will be 8x8 to force model to learn more dense representation.
6. For every a few lines of code, add a comment in a style of #[1], #[2], and #[3] 
    to explain the code. Feel free to add a few more comments, but don't comment 
    every single line as it can be excessive. Correct the grammar and style in these comments.

"""

#[1] Data loader (every training image are expected to be 512x512 grayscale jpg or png.)
def create_SEM_image_dataloader(image_dir, batch_size=1, shuffle=True):
    #[1] The images are first converted to tensors and then normalized to have a mean of 0.5 and std deviation of 0.5.
    transform = transforms.Compose([transforms.ToTensor(),transforms.Normalize((0.5,), (0.5,))])
    
    #[2] Define the dataset class to handle loading SEM images from a directory
    class SEMDataset(Dataset):
        def __init__(self, image_dir, transform=None):
            #[3] Initialize the dataset with the directory path and optional transformation
            self.image_dir = image_dir
            self.transform = transform
            self.image_filenames = os.listdir(image_dir)  # Load all filenames in the directory

        def __len__(self):
            #[4] Return the number of images in the dataset
            return len(self.image_filenames)

        def __getitem__(self, idx):
            #[5] Retrieve an image based on the index provided
            img_name = os.path.join(self.image_dir, self.image_filenames[idx])  # Get the full path of the image
            image = Image.open(img_name).convert('L')  # Open the image and convert it to grayscale
            
            #[6] Apply the transformation pipeline if it is defined
            if self.transform:
                image = self.transform(image)
            return image  # Return the transformed image

    #[7] Create an instance of the dataset using the SEMDataset class and provided transformations
    dataset = SEMDataset(image_dir, transform)
    dataloader = DataLoader(dataset, batch_size=batch_size, shuffle=shuffle)
    return dataloader



#[5] 
class ConvBlock(nn.Module): # Keep #[1] numbering comment to maintian readability.
    print('[ConvBlock]')
    def __init__(self, in_channels, out_channels, dropout_p=0.0):
        super(ConvBlock, self).__init__()
        self.conv = nn.Sequential(
            nn.Conv2d(in_channels, out_channels, kernel_size=3, stride=1, padding=1),
            nn.ReLU(inplace=True),
            nn.Dropout(p=dropout_p),
            nn.Conv2d(out_channels, out_channels, kernel_size=3, stride=1, padding=1),
            nn.ReLU(inplace=True),
            nn.Dropout(p=dropout_p)
        )

    def forward(self, tensor_in):
        tensor_out = self.conv(tensor_in)
        print(f'tensor_in.size = \t{tensor_in.size()}')
        print(f'tensor_out.size = \t{tensor_out.size()}')
        return tensor_out


class DownBlock(nn.Module): # Do not remove numbering comment to maintian readability.
    print('[DownBlock]')
    def __init__(self, in_channels, out_channels, dropout_p=0.0):
        super(DownBlock, self).__init__()
        #[1] First conv block, then downsample
        self.conv = ConvBlock(in_channels, out_channels, dropout_p=dropout_p)
        #[2] Downsample by factor of 4
        self.downsample = nn.Conv2d(out_channels, out_channels, kernel_size=4, stride=4)

    def forward(self, x):
        x_skip = self.conv(x)
        x_down = self.downsample(x_skip)
        return x_skip, x_down


class UpBlock(nn.Module):
    print('[UpBlock]')
    def __init__(self, in_channels, out_channels, dropout_p=0.0):
        super(UpBlock, self).__init__()
        #[1] Use upsampling by factor of 4 (to reverse the down)
        self.upsample = nn.ConvTranspose2d(in_channels, out_channels, kernel_size=4, stride=4)
        #[2] Change the input channels of the conv block to match the concatenated tensor
        self.conv = ConvBlock(in_channels + out_channels, out_channels, dropout_p=dropout_p)

    def forward(self, x, skip, skip_weight=1.0):
        #[5] Perform upsampling
        x = self.upsample(x)
        
        #[6] Ensure skip and x dimensions match
        if x.shape[2:] != skip.shape[2:]:
            # Adjust skip dimensions to match x
            diff_h = skip.shape[2] - x.shape[2]
            diff_w = skip.shape[3] - x.shape[3]
            skip = skip[:, :, diff_h // 2: -diff_h // 2, diff_w // 2: -diff_w // 2]
        
        #[7] Weighted skip connection
        x = torch.cat([x, skip * skip_weight], dim=1)
        
        #[8] Apply convolution
        x = self.conv(x)
        return x






class SEM_UNet(nn.Module):
    print('[SEM_UNet]')
    def __init__(self, in_channels=1, out_channels=1, dropout_p=0.1, use_learnable_skip=True):
        super(SEM_UNet, self).__init__()

        #[1] Encoder blocks
        self.enc1 = DownBlock(in_channels, 64, dropout_p=dropout_p)    # 512->128
        self.enc2 = DownBlock(64, 128, dropout_p=dropout_p)            # 128->32
        self.enc3 = DownBlock(128, 256, dropout_p=dropout_p)           # 32->8

        #[2] Bottleneck (8x8)
        self.bottleneck = ConvBlock(256, 256, dropout_p=dropout_p)

        #[3] Decoder blocks
        self.dec1 = UpBlock(256, 128, dropout_p=dropout_p)
        self.dec2 = UpBlock(128, 64, dropout_p=dropout_p)
        self.dec3 = UpBlock(64, 32, dropout_p=dropout_p)

        #[5] Final layer
        self.final_conv = nn.Conv2d(32, out_channels, kernel_size=1)

        #[8] Learnable skip weights
        if use_learnable_skip:
            self.skip_weights = nn.Parameter(torch.ones(3))
        else:
            self.skip_weights = None

    def encode(self, x):
        #[11] Returns embedding at 8x8 and skip connections
        s1, x = self.enc1(x)
        s2, x = self.enc2(x)
        s3, x = self.enc3(x)
        x = self.bottleneck(x)
        return x, (s1, s2, s3)

    def decode(self, embedding, skips=None, use_random_skips=False):
        #[16] If decoder is used alone, generate random noise for missing skip connections.
        if skips is None:
            device = embedding.device
            s3 = torch.randn((embedding.size(0), 256, 32, 32), device=device)
            s2 = torch.randn((embedding.size(0), 128, 128, 128), device=device)
            s1 = torch.randn((embedding.size(0), 64, 512, 512), device=device)
        else:
            s1, s2, s3 = skips

        if use_random_skips:
            #[18] Add random perturbation noise
            s1 = s1 + torch.randn_like(s1) * 0.1
            s2 = s2 + torch.randn_like(s2) * 0.1
            s3 = s3 + torch.randn_like(s3) * 0.1
        
        #[19] Use skip weights if available
        if self.skip_weights is not None:
            w1, w2, w3 = self.skip_weights
        else:
            w1, w2, w3 = 1.0, 1.0, 1.0

        x = self.dec1(embedding, s3, skip_weight=w3)
        x = self.dec2(x, s2, skip_weight=w2)
        x = self.dec3(x, s1, skip_weight=w1)
        x = self.final_conv(x)
        return x

    def forward(self, x=None, embedding=None, mode='encode', use_random_skips=False):
        if mode == 'encode':
            emb, _ = self.encode(x)
            return emb
        elif mode == 'decode':
            out = self.decode(embedding, skips=None, use_random_skips=use_random_skips)
            return out
        elif mode == 'autoencode':
            emb, skips = self.encode(x)
            out = self.decode(emb, skips=skips, use_random_skips=use_random_skips)
            return out, emb
        else:
            raise ValueError("mode must be one of ['encode', 'decode', 'autoencode']")





def train_sem_unet(model, dataloader, num_epochs, learning_rate, criterion, optimizer, device):
    #[2] Initialize lists to track epoch numbers and losses.
    list_epoch, list_tl, list_vl = [], [], []

    #[3] Loop through epochs.
    for epoch in range(num_epochs):
        model.train()  # Set the model to training mode
        running_loss = 0.0
        
        #[4] Training phase
        for i, inputs in enumerate(dataloader):
            inputs = inputs.to(device)
            optimizer.zero_grad()  # Zero gradients for the optimizer

            outputs, _ = model(inputs, mode='autoencode')  # Forward pass
            loss = criterion(outputs, inputs)  # Compute loss
            
            loss.backward()  # Backpropagation
            optimizer.step()  # Optimize weights
            
            running_loss += loss.item()

        avg_train_loss = running_loss / len(dataloader)
        list_tl.append(avg_train_loss)

        #[5] Print training loss for the epoch
        list_epoch.append(epoch + 1)
        print(f'Epoch {epoch + 1:03d}/{num_epochs:03d}, Train Loss Mean: {avg_train_loss:.4f}')
    
    #[6] Compile results into a DataFrame
    df_train = pd.DataFrame({'Epoch': list_epoch, 'Train Loss': list_tl})
    return df_train



# End of [SUN_M3_ML.py]




