def combine_two_pdf_pages_into_one_single_page(path_PDF1, page_PDF1, path_PDF2, page_PDF2, direction, path_save):
    #[1] Read PDF files using PyMuPDF for rendering as images
    pdf1 = fitz.open(path_PDF1)
    pdf2 = fitz.open(path_PDF2)
    
    pix1 = pdf1.load_page(page_PDF1 - 1).get_pixmap()  # Render page as an image
    pix2 = pdf2.load_page(page_PDF2 - 1).get_pixmap()

    img1 = BytesIO(pix1.tobytes("png"))  # Convert to PNG and store in memory
    img2 = BytesIO(pix2.tobytes("png"))

    #[2] Get page sizes
    page1_width = pix1.width
    page1_height = pix1.height
    page2_width = pix2.width
    page2_height = pix2.height

    if direction == 'left_and_right':
        #[3] Combine pages side-by-side
        combined_width = page1_width + page2_width
        combined_height = max(page1_height, page2_height)
    elif direction == 'top_and_bottom':
        #[4] Combine pages top-and-bottom
        combined_width = max(page1_width, page2_width)
        combined_height = page1_height + page2_height
    else:
        raise ValueError("Invalid direction. Use 'left_and_right' or 'top_and_bottom'.")

    #[5] Create combined page using ReportLab
    packet = BytesIO()
    c = canvas.Canvas(packet, pagesize=(combined_width, combined_height))

    if direction == 'left_and_right':
        # Draw page1 on the left
        c.drawImage(img1, 0, 0, width=page1_width, height=page1_height)
        # Draw page2 on the right
        c.drawImage(img2, page1_width, 0, width=page2_width, height=page2_height)
    elif direction == 'top_and_bottom':
        # Draw page1 on the top
        c.drawImage(img1, 0, page2_height, width=page1_width, height=page1_height)
        # Draw page2 on the bottom
        c.drawImage(img2, 0, 0, width=page2_width, height=page2_height)

    c.save()
    packet.seek(0)

    # Create a new PDF with the combined page
    new_pdf = PdfReader(packet)
    output = PdfWriter()

    # Add the combined page to the output PDF
    output.add_page(new_pdf.pages[0])

    #[3] Save the result
    with open(path_save, "wb") as output_stream:
        output.write(output_stream)






def get_pdf_info(path_PDF, print_nicely=True):
    print(f'[get_pdf_info]\n{path_PDF}\n{os.path.basename(path_PDF)}')
    #[1] Get PDF info.
    with fitz.open(path_PDF) as pdf:
        info = {
            "page_count": pdf.page_count,
            "metadata": pdf.metadata,
            "is_encrypted": pdf.is_encrypted,
            "permissions": pdf.permissions,
            "toc": pdf.get_toc(),
            "page_labels": pdf.get_page_labels(),
            "file_size": os.path.getsize(path_PDF)  # Get file size in bytes
        }
        
    #[3] Optionally print_nicely with presentable format.
    if print_nicely:
        print("\nPDF Information:")
        for key, value in info.items():
            print(f"{key}: {value}")
        
    return info






def PDF_date_created_avoid_unknown(pdf):
    date_created_str = pdf.metadata.get("creationDate", "Unknown")
    if date_created_str != "Unknown":
        try:
            date_created = datetime.strptime(date_created_str, "D:%Y%m%d%H%M%S").strftime("%Y-%m%d-%H%M%S")
        except ValueError:
            date_created = "Unknown"
    else:
        date_created = "Unknown"
    return date_created



def single_PDF_statistics(path_PDF):
    """
    Count the number of pages, words, and figures in a single PDF file.
    """
    cnt_page = 0
    cnt_word = 0
    cnt_fig = 0

    #[1] Open the PDF file
    with fitz.open(path_PDF) as pdf:
        cnt_page = pdf.page_count
        date_created = PDF_date_created_avoid_unknown(pdf)

        #[2] Iterate through each page
        for page_num in range(cnt_page):
            page = pdf.load_page(page_num)
            text = page.get_text("text")
            words = text.split()
            cnt_word += len(words)
            cnt_fig += len(page.get_images(full=True))  # Count the number of figures on the page

    file_size_MB = round(os.path.getsize(path_PDF) / 1048576, 2)

    return date_created, cnt_page, cnt_word, cnt_fig, file_size_MB


def count_PDF_statistics_in_given_dir(dir_PDF):
    """
    Count the number of pages, words, and figures in all PDF files in a given directory.
    """
    #[1] Filter list of .pdf files.
    list_kwd_yes_or_1 = ['.pdf', '.PDF']
    list_kwd_no_or_2 = []
    list_paths_PDF, list_bsns_PDF = M1F.filter_file_in_dir_with_keywords(dir_PDF, list_kwd_yes_or_1, list_kwd_no_or_2, False)
    
    #[2] Initialize a DataFrame to store the results
    df_PDF = pd.DataFrame(columns=['File Name', 
                                   'Date Created', 
                                   'Page Count', 
                                   'Word Count', 
                                   'Figure Count', 
                                   'File Size (MB)'])

    #[3] Iterate through each PDF file and count pages, words, and figures
    for i, i_path in enumerate(list_paths_PDF):
        date_created, cnt_page, cnt_word, cnt_fig, file_size_MB = M2P.single_PDF_statistics(i_path)
        df_PDF = pd.concat([df_PDF, pd.DataFrame({
            'File Name': [os.path.basename(i_path)[:30]], 
            'Date Created': [date_created],
            'Page Count': [cnt_page], 
            'Word Count': [cnt_word],
            'Figure Count': [cnt_fig],
            'File Size (MB)': [file_size_MB]
        })], ignore_index=True)

    return df_PDF
