import tkinter as tk
from tkinter import scrolledtext

class LineBreakRemover:
    def __init__(self, master, dark_theme=True):
        self.master = master
        self.master.title("Line Break Remover")
        
        # [3] Set dark theme
        if dark_theme:
            self.bg_color = "#333333"  # Dark grey background
            self.text_color = "#FFFFFF"  # White text
            self.btn_color = "#444444"  # Lighter grey for buttons
            self.input_bg_color = "#555555"  # Darker grey for text input areas
            
            #[6] Configure the root window background and top bar (might not work on all systems)
            self.master.config(bg=self.bg_color)
            try:
                self.master.wm_attributes('-alpha', 0.95)  # Slightly transparent
                self.master.tk_setPalette(background=self.bg_color, foreground=self.text_color, activeBackground=self.btn_color, activeForeground=self.text_color)
            except:
                print("Top window bar color modification is not supported on your system.")
            
        self.create_widgets()

    def create_widgets(self):
        # Input Text area
        self.input_label = tk.Label(
            self.master,
            text="Input Text:",
            bg=self.bg_color,
            fg=self.text_color
        )
        self.input_label.pack()
        
        self.input_text = scrolledtext.ScrolledText(
            self.master,
            height=20,
            width=100,
            bg=self.input_bg_color,
            fg=self.text_color,
            insertbackground=self.text_color,  # Cursor color
            relief=tk.FLAT
        )
        self.set_scrollbar_color(self.input_text)
        self.input_text.pack()

        # Button Frame
        self.button_frame_1 = tk.Frame(self.master, bg=self.bg_color)
        self.button_frame_1.pack(pady=10)

        # Buttons
        self.remove_button = tk.Button(
            self.button_frame_1,
            text="Remove Line Breaks",
            bg=self.btn_color,
            fg=self.text_color,
            activebackground=self.bg_color,
            activeforeground=self.text_color,
            command=self.remove_line_breaks
        )
        self.remove_button.pack(side=tk.LEFT, padx=10)

        self.clear_button = tk.Button(
            self.button_frame_1,
            text="Clear All",
            bg=self.btn_color,
            fg=self.text_color,
            activebackground=self.bg_color,
            activeforeground=self.text_color,
            command=self.clear_all
        )
        self.clear_button.pack(side=tk.LEFT, padx=10)

        # Output Text area
        self.output_label = tk.Label(
            self.master,
            text="Output Text:",
            bg=self.bg_color,
            fg=self.text_color
        )
        self.output_label.pack()
        
        self.output_text = scrolledtext.ScrolledText(
            self.master,
            height=20,
            width=100,
            bg=self.input_bg_color,
            fg=self.text_color,
            insertbackground=self.text_color,  # Cursor color
            relief=tk.FLAT
        )
        self.set_scrollbar_color(self.output_text)
        self.output_text.pack()
    
    def set_scrollbar_color(self, scrolled_widget):
        # Modify the scrollbar colors
        for wid in scrolled_widget.pack_slaves():
            if isinstance(wid, tk.Scrollbar):
                wid.config(bg=self.btn_color)

    def remove_line_breaks(self):
        input_text = self.input_text.get("1.0", tk.END)
        processed_text = self.process_text(input_text)
        self.output_text.delete("1.0", tk.END)
        self.output_text.insert(tk.END, processed_text)

    def process_text(self, input_text):
        lines = input_text.split('\n')
        processed_lines = []
        # [5] Iterate through each line in the text.
        for i, i_line in enumerate(lines):
            # [6] Check if the current line is followed by a blank line.
            if i < len(lines) - 1 and lines[i+1].strip() == "":
                # [7] Preserve the line break after lines followed by a blank line.
                processed_lines.append(i_line + '\n')
            # [8] If the end of a line is "." and the next character is a capital letter, it might be a new paragraph.
            elif i < len(lines) - 1 and i_line.strip()[-1] == '.' and lines[i+1].strip()[0].isupper():
                processed_lines.append(i_line + '\n\n')
            # [9] Add non-blank lines to the processed list, appending a space instead of a newline.
            elif i_line.strip() != "":
                processed_lines.append(i_line + ' ')
        # [10] Join the processed lines into the final output and strip any leading/trailing spaces or newlines.
        output_text = ''.join(processed_lines).strip()
        return output_text



    def clear_all(self):
        self.input_text.delete("1.0", tk.END)
        self.output_text.delete("1.0", tk.END)




root = tk.Tk()
app = LineBreakRemover(root)
root.mainloop()

