@app.route('/upload', methods=['POST'])
def upload():
    if 'image' in request.files:
        img = request.files['image']
        img_path = os.path.join(dir_upload, img.filename)
        img.save(img_path)
        # [3] Return the relative path to the image
        return {'image_url': f'/static/uploads/{timestamp}/{img.filename}'}
    return {'error': 'No file uploaded'}, 400

# [4] Serve static files
@app.route('/static/<path:path>')
def send_static(path):
    return send_from_directory('static', path)

#[5] Function to open the web browser
def open_browser():
    webbrowser.open(f'http://127.0.0.1:5000/')

if __name__ == '__main__':
    # [6] Run the browser in a separate thread
    threading.Thread(target=open_browser).start()
    app.run(debug=True, use_reloader=False)




# End of [DEI-10_Backend.py]




