def make_dir_if_not_exist(dir_to_make=None):
    #[1] If dir_to_make is not provided, make a dir at current directory with timestamp as folder name.
    if dir_to_make is None:
        dir_current = os.path.dirname(os.path.abspath(__file__))
        timestamp = datetime.now().strftime("%Y-%m%d-%H%M%S")
        dir_to_make = os.path.join(dir_current, f'{timestamp}_dir_name')
        
    #[2] Make dir.
    try:
        os.mkdir(dir_to_make)
        print("--Directory wasn't exists. Just made one.")
    except FileExistsError:
        print("--Directory already exists. Skipping directory creation.")

def tkinter_select_directory(dialog_title='Select a directory'):
    """
    Necessary import statement:
    import os, sys, tkinter
    from tkinter import filedialog
    """
    #[1] Initiate and hide the main window.
    root = tkinter.Tk()
    root.withdraw()
    
    try:
        path_dir = tkinter.filedialog.askdirectory(title=dialog_title)
        if path_dir:
            #[2] Extract the base name of the selected directory.
            bsn_dir = os.path.basename(path_dir)
            #[3] Clean the path and append the trailing separator.
            path_dir = os.path.normpath(path_dir) + os.sep
            print('--path_dir:', path_dir)
            return path_dir, bsn_dir
        else:
            #[4] Exit the program if no directory is selected.
            print('--No directory selected. Exiting.')
            sys.exit()
    except Exception as e:
        print(f'--An error occurred: {e}')
        return None, None
    finally:
        #[5] Clean up and destroy the Tkinter window.
        root.destroy()
        



def get_dir_size(path='.'):
    total = 0
    for entry in os.scandir(path):
        if entry.is_file():
            # [1] Add the size of the file to the total
            total += entry.stat().st_size
        elif entry.is_dir():
            # [2] Recursively add the size of the directory
            total += get_dir_size(entry.path)
    return total

def find_folder_size_and_file_count(dir_target):
    #[1] Get list of folder basenames in the target directory
    list_bsn_folder = [f for f in os.listdir(dir_target) if not os.path.isfile(os.path.join(dir_target, f))]
    
    #[2] Initialize lists to store folder sizes and file counts
    list_folder_size_mb = []
    list_file_count = []
    
    #[3] Calculate folder sizes and file counts
    for bsn_folder in list_bsn_folder:
        path_folder = os.path.join(dir_target, bsn_folder)
        list_folder_size_mb.append(round(get_dir_size(path_folder) / 1048576))
        list_file_count.append(sum(len(files) for _, _, files in os.walk(path_folder)))
    
    #[4] Create a DataFrame with folder statistics
    df_dir_target = pd.DataFrame({
        'Folder Name': list_bsn_folder,
        'Size (Mb)': list_folder_size_mb,
        'Number of Files': list_file_count
    })
    
    #[5] Find folder with max size and max file count
    if not df_dir_target.empty:
        bsn_folder_max_size = df_dir_target.loc[df_dir_target['Size (Mb)'].idxmax(), 'Folder Name']
        val_folder_max_size = df_dir_target['Size (Mb)'].max()
        bsn_folder_max_file = df_dir_target.loc[df_dir_target['Number of Files'].idxmax(), 'Folder Name']
        val_folder_max_file = df_dir_target['Number of Files'].max()
    else:
        print('No folders found in the given directory.')
        bsn_folder_max_size = val_folder_max_size = bsn_folder_max_file = val_folder_max_file = None
    
    #[6] Return folder statistics and max size/file count information
    return df_dir_target, bsn_folder_max_size, val_folder_max_size, bsn_folder_max_file, val_folder_max_file








