def setup_and_sample_with_lo_loss(lo, glycan_iupac, lambda_=1.0, num_designs=8):
    from RFdiffusion import run_diffusion

    name = "lectin_guided"
    contigs = "A:50"
    pdb = "/content/glycan_with_anchors.pdb"
    iterations = 200
    hotspot = ""
    symmetry = "none"
    order = 1
    chains = ""
    add_potential = True
    use_beta_model = True
    visual = "none"
    partial_T = "auto"

    path = name
    while os.path.exists(f"outputs/{path}_0.pdb"):
        path = name + "_" + ''.join(random.choices(string.ascii_lowercase + string.digits, k=5))

    flags = {
        "contigs": contigs,
        "pdb": pdb,
        "order": order,
        "iterations": iterations,
        "symmetry": symmetry,
        "hotspot": hotspot,
        "path": path,
        "chains": chains,
        "add_potential": add_potential,
        "num_designs": num_designs,
        "use_beta_model": use_beta_model,
        "visual": visual,
        "partial_T": partial_T
    }

    for k, v in flags.items():
        if isinstance(v, str):
            flags[k] = v.replace("'", " ").replace('"', ' ')

    contigs, copies = run_diffusion(**flags)

    designs = []
    for i in tqdm(range(num_designs)):
        design_path = f"outputs/{path}_{i}.pdb"
        if not os.path.exists(design_path):
            continue

        with open(design_path, "r") as f:
            pdb_str = f.read()
        pdb_str = fix_pdb(pdb_str, contigs)

        seq = ""
        for line in pdb_str.splitlines():
            if line.startswith("ATOM") and line[13:15].strip() == "CA":
                res = line[17:20].strip()
                aa = AA3_to_AA1.get(res, "X")
                seq += aa

        lo_score = lo(seq, glycan_iupac)
        lo_loss = -lo_score

        designs.append({
            "seq": seq,
            "pdb": pdb_str,
            "lo_score": lo_score,
            "lo_loss": lo_loss,
            "design_path": design_path
        })

    designs.sort(key=lambda x: x['lo_loss'])
    return designs

def iterative_lo_guided_sampling(lo, glycan_iupac, lambda_=1.0, num_iterations=5, num_designs_per_round=8):
    """
    Iteratively generate RFdiffusion designs and select best candidate using LectinOracle.
    The best design from each round influences the next by re-running RFdiffusion.
    """
    best_score = -np.inf
    best_design = None

    for iteration in tqdm(range(num_iterations)):
        print(f"\n--- Iteration {iteration + 1} ---")
        results = setup_and_sample_with_lo_loss(lo, glycan_iupac, lambda_=lambda_, num_designs=num_designs_per_round)
        top = results[0]

        print(f"Top sequence: {top['seq']}")
        print(f"Predicted LectinOracle score: {top['lo_score']:.4f}")

        if top['lo_score'] > best_score:
            best_score = top['lo_score']
            best_design = top

    print("\n=== Best Overall Design ===")
    print("Sequence:", best_design['seq'])
    print("LectinOracle Score:", best_design['lo_score'])

    return best_design
