import prody as pr
import numpy as np
import glycosylator as gl
import pandas as pd
from pathlib import Path

def load_glycan(glycan_pdb_path):
    glycan = pr.parsePDB(glycan_pdb_path)
    hetatm = glycan.select('hetero')
    if hetatm is None:
        raise ValueError("No HETATM entries found in glycan PDB.")
    return hetatm

def compute_center_of_mass(atomgroup):
    coords = atomgroup.getCoords()
    return coords.mean(axis=0)

def generate_dummy_anchors(center, num_dummies=2, offset=7.0, chain_id='A'):
    ag = pr.AtomGroup('dummy_anchors')
    coords = []
    names = []
    resnames = []
    resnums = []
    chids = []
    elements = []

    for i in range(num_dummies):
        direction = np.random.randn(3)
        direction /= np.linalg.norm(direction)
        coord = center + direction * offset

        coords.append(coord)
        names.append('CA')
        resnames.append('ALA')
        resnums.append(i + 1)
        chids.append(chain_id)
        elements.append('C')

    ag.setCoords(np.array(coords))
    ag.setNames(names)
    ag.setResnames(resnames)
    ag.setResnums(resnums)
    ag.setChids(chids)
    ag.setElements(elements)

    return ag, resnums

def merge_and_write_with_remarks(glycan_atoms, dummy_atoms, output_pdb_path):
    # Combine glycan and dummy atoms
    hybrid = glycan_atoms.copy()
    hybrid += dummy_atoms

    # Collect motif metadata
    motif_resnums = set(glycan_atoms.getResnums())
    motif_chains = set(glycan_atoms.getChids())
    motif_resnames = set(glycan_atoms.getResnames())
    motif_atomnames = set(glycan_atoms.getNames())
    print(motif_resnums)
    print(motif_chains)
    print(motif_resnames)
    print(motif_atomnames)


    with open(output_pdb_path, 'w') as f:
        pr.writePDBStream(f, hybrid)

def write_motif_mask(residue_ids, output_mask_path):
    with open(output_mask_path, 'w') as f:
        f.write(','.join(str(r) for r in residue_ids))


iupac = (
    "HexA(a1-4)GlcNAc(a1-4)HexA(a1-4)GlcNAc(a1-4)HexA(a1-4)GlcNAc(a1-4)HexA(a1-4)Man"
)

# Build the 3D glycan object
glyc = gl.glycan(iupac)
# '/content/drive/MyDrive/Colab_Notebooks_glycan_better/new_glycan_pdbs/'
# Write out the glycan as a PDB
glycan_pdb = '/content/drive/MyDrive/Colab_Notebooks/glycans_better/new_glycan_pdbs/'+iupac+'.pdb'
glyc.to_pdb(glycan_pdb)

output_pdb = '/content/drive/MyDrive/Colab_Notebooks/glycans_better/new_glycan_pdbs/anchored_'+iupac+'.pdb'
output_mask = '/content/drive/MyDrive/Colab_Notebooks/glycans_better/new_glycan_pdbs/motif_mask_'+iupac+'.txt'

# Load and annotate
glycan = load_glycan(glycan_pdb)
center = compute_center_of_mass(glycan)
dummy_anchors, anchor_ids = generate_dummy_anchors(center, num_dummies=2, offset=7.0)
merge_and_write_with_remarks(glycan, dummy_anchors, output_pdb)
write_motif_mask(anchor_ids, output_mask)

