def safe_glycan_to_graph(glycan, libr):
    try:
        result = glycan_to_graph(glycan, libr=libr)
        
        # Debug the output format
        if result is None:
            return None
            
        # Check if it's already in the format we need
        if isinstance(result, tuple) and len(result) == 2:
            return result
            
        # If it's a dictionary, extract the components we need
        if isinstance(result, dict):
            if 'x' in result and 'edge_index' in result:
                return (result['x'], result['edge_index'])
            else:
                print(f"Unexpected dictionary format for glycan {glycan}: {list(result.keys())}")
                return None
                
        # If it's something else, print the type for debugging
        print(f"Unexpected result type for glycan {glycan}: {type(result)}")
        return None
        
    except Exception as e:
        #print(f"Error parsing glycan: {glycan}, error: {e}")
        return None

