def get_pred(prot, glycans, model_ft = model_ft, prot_dic = old_dic, batch_size = 128):
  try:
    repr = prot_dic[prot]
  except:
    print('new protein, no stored embedding')
  ggraph = []
  for glycan in glycans:
    if isinstance(glycan, str):
      ggraph.append(glycan_to_graph(glycan))
    elif isinstance(glycan, list):
      # If glycan is a list, convert it to a string or handle appropriately
      glycan_str = ''.join(glycan) if all(isinstance(x, str) for x in glycan) else str(glycan)
      ggraph.append(glycan_to_graph(glycan_str))
    else:
      raise TypeError(f"Unexpected glycan type: {type(glycan)}")
  graph_data = [Data(x = torch.tensor(ggraph[0], dtype = torch.long), y = torch.tensor(0.99, dtype = torch.float),
                    edge_index = torch.tensor([ggraph[1][0], ggraph[1][1]], dtype = torch.long))]*batch_size
  for k in range(len(graph_data)):
    graph_data[k].train_idx = torch.tensor(repr, dtype = torch.float)
  train_loader = DataLoader(graph_data, batch_size = batch_size, shuffle = False)
  model_ft = model_ft.eval()
  res = []
  for k in train_loader:
    x, y, edge_index, prot, batch = k.x, k.y, k.edge_index, k.train_idx, k.batch
    x = x.cuda()
    y = y.cuda()
    prot = prot.view(max(batch)+1, -1).cuda()
    edge_index = edge_index.cuda()
    batch = batch.cuda()
    pred = model_ft(prot, x, edge_index, batch)
    res.append(pred)
  res = [res[k].detach().cpu().numpy() for k in range(len(res))][0][0].tolist()[0]
  return res





def get_multi_pred(prot, glycans, model_ft=model_ft, prot_dic=old_dic, batch_size=128, background_correction=False, correction_df=df_corr):
  if prot not in prot_dic:
      print(f'Protein {prot} not found in protein dictionary')
      return [None] * len(glycans)

  repr = prot_dic[prot]

  valid_graphs = []
  valid_glycans = []

  for glycan in glycans:
      try:
          graph = safe_glycan_to_graph(glycan, lib)
          if graph is not None and isinstance(graph, tuple) and len(graph) == 2:
              node_features, edge_indices = graph
              if len(node_features) == 0 or len(edge_indices[0]) == 0:
                  continue  # Skip empty graphs
              valid_graphs.append((node_features, edge_indices))
              valid_glycans.append(glycan)
      except Exception as e:
          print(f"Error processing glycan {glycan}: {e}")
          continue

  if not valid_graphs:
      print("No valid glycan graphs generated")
      return [None] * len(glycans)

  graph_data = []
  for node_features, edge_indices in valid_graphs:
      data = Data(
          x=torch.tensor(node_features, dtype=torch.long),
          edge_index=torch.tensor(edge_indices, dtype=torch.long),
          y=torch.tensor(0.99, dtype=torch.float)
      )
      data.train_idx = torch.tensor(repr, dtype=torch.float)
      graph_data.append(data)

  loader = DataLoader(graph_data, batch_size=min(batch_size, len(graph_data)), shuffle=False)

  model_ft.eval()
  results = []

  with torch.no_grad():
      for batch in loader:
          x, edge_index, prot, batch_indices = batch.x, batch.edge_index, batch.train_idx, batch.batch
          device = next(model_ft.parameters()).device
          x = x.to(device)
          prot = prot.view(max(batch_indices)+1, -1).to(device)
          edge_index = edge_index.to(device)
          batch_indices = batch_indices.to(device)

          pred = model_ft(prot, x, edge_index, batch_indices)
          results.extend(pred.cpu().numpy().flatten().tolist())

  final_results = [None] * len(glycans)
  for glycan, pred in zip(valid_glycans, results):
      idx = glycans.index(glycan)
      final_results[idx] = pred

  if background_correction and correction_df is not None:
      correction_dict = pd.Series(correction_df.pred.values, index=correction_df.motif).to_dict()
      for i, glycan in enumerate(glycans):
          if final_results[i] is not None and glycan in correction_dict:
              final_results[i] -= correction_dict[glycan]

  return final_results





  

