def get_motif_predictions(protein, model=model_ft, more_motifs=False, prot_dic=old_dic,
                          trisaccharides=False, trisaccharide_list=trisaccharides, 
                          background_correction=False, correction_df=df_corr, 
                          batch_size=128, add_in_full=False, sorted=True):
    print(f'\n[get_motif_predictions]')
    
    # Debug protein input
    print(f'Input protein length: {len(protein)}')
    print(f'Protein in dictionary: {protein in prot_dic}')
    
    # Get glycans
    glycans = list(set([g for g in train2.glycan.values.tolist() + val2.glycan.values.tolist() 
                       if isinstance(g, str)]))
    print(f'Number of unique glycans: {len(glycans)}')
    
    # Get motifs from glycans
    try:
        glycan_motifs_df = annotate_dataset(glycans, feature_set=['exhaustive'], condense=True)
        glycan_motifs = glycan_motifs_df.columns.values.tolist()
        glycan_motifs = [k for k in glycan_motifs if isinstance(k, str) and '(' in k]
        print(f'Number of initial motifs: {len(glycan_motifs)}')
    except Exception as e:
        print(f"Error annotating dataset: {e}")
        glycan_motifs = []
        print("Using empty motif list")
    
    # Add more motifs if requested
    if more_motifs:
        print('Processing additional motifs...')
        additional_motifs = []
        forbidden_list = ['2(', '3(', '4(', '6(', ')(', 'b1-4GlcNAc']
        
        for k in glycans:
            try:
                ggraph = glycan_to_nxGraph(k, libr=lib)
                ggraph_nb = create_neighbors(ggraph, libr=lib)
                g_nb = []
                
                for j in ggraph_nb:
                    converted = try_string_conversion(j, libr=lib)
                    if converted is not None:
                        g_nb.append(converted)
                
                g_nb = [j if not j.startswith('[') else j.replace('[','',1).replace(']','',1) 
                       for j in g_nb]
                g_nb = [j for j in g_nb if not j.startswith('(')]
                g_nb = [j for j in g_nb if not any(m in j for m in forbidden_list)]
                
                additional_motifs.extend(g_nb)
            except Exception as e:
                continue
                
        glycan_motifs.extend(additional_motifs)
    
    # Add trisaccharides if requested
    if trisaccharides and trisaccharide_list:
        print('Adding trisaccharide motifs...')
        tri_motifs = [t for t in trisaccharide_list if isinstance(t, str)]
        glycan_motifs.extend(tri_motifs)
        print(f'Number of motifs after adding trisaccharides: {len(glycan_motifs)}')
    
    # Add full glycans if requested
    if add_in_full:
        print('Adding full glycans...')
        glycan_motifs.extend(glycans)
        print(f'Number of motifs after adding full glycans: {len(glycan_motifs)}')
    
    # Clean and check motifs
    glycan_motifs = [m for m in glycan_motifs if isinstance(m, str)]
    glycan_motifs = list(set(glycan_motifs))
    print(f'Final number of unique motifs: {len(glycan_motifs)}')
    
    # Get predictions with error handling
    try:
        print('Getting predictions...')
        preds = get_multi_pred(protein, glycan_motifs, model, prot_dic=prot_dic,
                           batch_size=batch_size, background_correction=background_correction)
        print(f'Predictions received: {preds is not None}')
        
        # Create DataFrame with valid predictions
        df_pred = pd.DataFrame({
            'motif': glycan_motifs,
            'pred': preds
        })
        
        # Filter out None values
        df_pred = df_pred[df_pred['pred'].notna()].reset_index(drop=True)
        print(f'Number of valid predictions: {len(df_pred)}')
        
        # Sort if requested
        if sorted and not df_pred.empty:
            df_pred = df_pred.sort_values('pred', ascending=False).reset_index(drop=True)
        
        return df_pred
        
    except Exception as e:
        print(f'Error during prediction: {str(e)}')
        return pd.DataFrame(columns=['motif', 'pred'])


