def predict_GBP_binding_affinity(protein_seq, glycans=None, model=None, 
                                 protein_embeddings_dict=None, lib_input=None,
                                 background_correction=True, top_n=20,
                                 batch_size=64, device=None):
    """
    Predict binding affinity of a glycan-binding protein against glycans.
    
    Parameters:
    -----------
    protein_seq : str
        Amino acid sequence of the protein
    glycans : list, optional
        List of glycan structures to test. If None, uses a predefined set of glycans and motifs
    model : torch.nn.Module, optional
        Trained LectinOracle model. If None, uses the global model_ft
    protein_embeddings_dict : dict, optional
        Dictionary of protein embeddings. If None, uses the global old_dic
    lib : list, optional
        Glycan library for graph conversion. If None, uses the global lib
    background_correction : bool, optional
        Whether to apply background correction to predictions
    top_n : int, optional
        Number of top predictions to return
    batch_size : int, optional
        Batch size for prediction
    device : torch.device, optional
        Device to run predictions on. If None, uses available device
        
    Returns:
    --------
    pd.DataFrame
        DataFrame with glycan motifs and their predicted binding affinities
    """
    import torch
    import pandas as pd
    from torch_geometric.data import Data, DataLoader
    import numpy as np
    
    # Use global variables if not provided
    if model is None:
        global model_ft
        model = model_ft
    
    if protein_embeddings_dict is None:
        global old_dic
        protein_embeddings_dict = old_dic
    
    if lib_input is None:
        global lib
        
    if device is None:
        device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
    
    # Ensure model is in evaluation mode
    model.eval()
    model = model.to(device)
    
    # Get protein embedding
    if protein_seq in protein_embeddings_dict:
        protein_embedding = protein_embeddings_dict[protein_seq]
        print(f"Using stored embedding for protein sequence")
    else:
        # For new proteins, we need to generate an embedding
        # Since we don't have access to the embedding model, we'll use a workaround
        # by finding the most similar protein in our dictionary
        print(f"Protein not in dictionary, using nearest neighbor approach")
        
        # Simple approach: use the first protein in the dictionary as a placeholder
        # In a real implementation, you would use a proper embedding model here
        protein_embedding = next(iter(protein_embeddings_dict.values()))
        
        # Alternatively, you could implement a more sophisticated approach:
        # 1. Calculate sequence similarity between input protein and all proteins in dictionary
        # 2. Use embedding from most similar protein
        
    # Get glycans to test if not provided
    if glycans is None:
        # Get a mix of common glycans and motifs
        global train2, val2
        try:
            glycans = list(set([g for g in train2.glycan.values.tolist() + val2.glycan.values.tolist() 
                           if isinstance(g, str)]))[:100]  # Limit to 100 for efficiency
            
            # Add some common motifs
            from glycowork.motif.annotate import annotate_dataset
            glycan_motifs_df = annotate_dataset(glycans, feature_set=['exhaustive'], condense=True)
            glycan_motifs = glycan_motifs_df.columns.values.tolist()
            glycan_motifs = [k for k in glycan_motifs if isinstance(k, str) and '(' in k]
            glycans.extend(glycan_motifs[:100])  # Add top 100 motifs
            
            # Deduplicate
            glycans = list(set(glycans))
            print(f"Using {len(glycans)} glycans and motifs for prediction")
        except Exception as e:
            print(f"Error getting glycans: {e}")
            # Fallback to some common glycans
            glycans = [
                "Man(a1-3)[Man(a1-6)]Man(b1-4)GlcNAc(b1-4)GlcNAc",
                "Gal(b1-4)GlcNAc",
                "Neu5Ac(a2-3)Gal(b1-4)GlcNAc",
                "Neu5Ac(a2-6)Gal(b1-4)GlcNAc",
                "Fuc(a1-2)Gal(b1-4)GlcNAc",
                "GalNAc(a1-3)[Fuc(a1-2)]Gal(b1-4)GlcNAc",
                "Gal(a1-3)[Fuc(a1-2)]Gal(b1-4)GlcNAc"
            ]
    
    # Process glycans and create graph data
    valid_graphs = []
    valid_glycans = []
    
    for glycan in glycans:
        try:
            # Convert glycan to graph
            from glycowork.motif.graph import glycan_to_graph
            graph = glycan_to_graph(glycan)
            if graph is not None and isinstance(graph, tuple) and len(graph) == 2:
                node_features, edge_indices = graph
                if len(node_features) > 0 and len(edge_indices) > 0 and len(edge_indices[0]) > 0:
                    valid_graphs.append((node_features, edge_indices))
                    valid_glycans.append(glycan)
        except Exception as e:
            print(f'Error: {e}')
            continue
    
    if not valid_graphs:
        print(f'No valid glycan graphs generated ({valid_graphs})')
        return pd.DataFrame(columns=['glycan', 'predicted_affinity'])
    
    # Create data objects for prediction
    graph_data = []
    for i, (node_features, edge_indices) in enumerate(valid_graphs):
        data = Data(
            x=torch.tensor(node_features, dtype=torch.long),
            edge_index=torch.tensor(edge_indices, dtype=torch.long),
            y=torch.tensor(0.0, dtype=torch.float)  # Dummy value
        )
        data.train_idx = torch.tensor(protein_embedding, dtype=torch.float)
        graph_data.append(data)
    
    # Create dataloader
    loader = DataLoader(graph_data, batch_size=min(batch_size, len(graph_data)), shuffle=False)
    
    # Make predictions
    predictions = []
    with torch.no_grad():
        for batch in loader:
            x, edge_index, batch_indices = batch.x, batch.edge_index, batch.batch
            prot = batch.train_idx.view(max(batch_indices)+1, -1)
            
            # Move to device
            x = x.to(device)
            prot = prot.to(device)
            edge_index = edge_index.to(device)
            batch_indices = batch_indices.to(device)
            
            # Get predictions
            pred = model(prot, x, edge_index, batch_indices)
            predictions.extend(pred.cpu().numpy().flatten().tolist())
    
    # Apply background correction if needed
    if background_correction:
        global df_corr
        try:
            correction_dict = pd.Series(df_corr.pred.values, index=df_corr.motif).to_dict()
            for i, glycan in enumerate(valid_glycans):
                if glycan in correction_dict:
                    predictions[i] -= correction_dict[glycan]
        except:
            print("Background correction failed, using raw predictions")
    
    # Create results dataframe
    results_df = pd.DataFrame({
        'glycan': valid_glycans,
        'predicted_affinity': predictions
    })
    
    # Sort by predicted affinity
    results_df = results_df.sort_values('predicted_affinity', ascending=False).reset_index(drop=True)
    
    # Return top N results
    return results_df.head(top_n)







