import torch



def convert_single_glycan_to_SweetNet_emb(single_glycan_in_IUPAC, model, cvt_to_list=True):
    """
    Function to convert glycan IUPAC representation to embedding.
    Note: 
    1. Nomenclature must be fully correct.
    2. "alphe" and "beta" needed to be replaced with "a" and "b".
    """
    # [1] Obtain the SweetNet embedding directly from the IUPAC-condensed glycan
    df_emb = glycans_to_emb([single_glycan_in_IUPAC], model=model)
    # [2] Convert the embedding to list.
    if cvt_to_list:
        emb_output = df_emb.values.flatten().tolist()
    # [3] Convert the embedding to tensor.
    else:
        emb_output = torch.tensor(df_emb.values) 
    
    return emb_output



def convert_multiple_glycans_to_SweetNet_embs(arr_glycan, model):
    """
    arr_glycan: 1D array of glycan_IUPAC.
    df_glycan_emb(): Glycan, Embedding
    
    """
    print(f'\n[convert_multiple_glycans_to_embeddings]')
    glycan_embeddings = []

    for i, i_glycan in enumerate(arr_glycan):
        try:
            # [1] Obtain the embedding for each glycan
            list_emb = convert_single_glycan_to_SweetNet_emb(i_glycan, model, cvt_to_list=True)
            glycan_embeddings.append((i_glycan, list_emb))
        except Exception as e:
            print(f"Error processing glycan '{i_glycan}': {e}")
            glycan_embeddings.append((i_glycan, None))  # Append None for failed embeddings
            
    # [2] Convert the results into a DataFrame
    df_glycan_emb = pd.DataFrame(glycan_embeddings, columns=['Glycan', 'Embedding'])

    return df_glycan_emb




def convert_single_protein_seq_to_ESM1b_emb(protein_seq, model, alphabet, cvt_to_list=True):
    #[1] Truncate if longer than 1022 residues (ESM1b limit)
    protein_seq = protein_seq[:1022]
    data = [('sequence', protein_seq)]

    #[2] Convert sequence to tokens
    batch_converter = alphabet.get_batch_converter()
    batch_labels, batch_strs, batch_tokens = batch_converter(data)

    #[3] Run model to get embeddings
    with torch.no_grad():
        results = model(batch_tokens, repr_layers=[33], return_contacts=False)
    token_representations = results["representations"][33]
    

    #[4] Extract average embedding (excluding [CLS] and [EOS])
    emb_output = token_representations[0, 1:len(protein_seq) + 1].mean(0)
    
    #[5] Convert to list or tensor
    if cvt_to_list:
        emb_output = emb_output.tolist()
    return emb_output


def convert_multiple_protein_seqes_to_ESM1b_embs(path_fasta, model_name='esm1b_t33_650M_UR50S'):
    """
    Convert a lectin protein FASTA sequence to an ESM-1b embedding.

    Parameters:
    - path_fasta (str): Path to the FASTA file.
    - model_name (str): ESM-1b model name.

    Returns:
    - embedding (torch.Tensor): Averaged token embedding (shape: [1280])
    """

    #[1] Load pretrained ESM-1b model


    batch_converter = alphabet.get_batch_converter()

    #[2] Load sequence from FASTA
    records = list(SeqIO.parse(path_fasta, "fasta"))
    data = [(record.id, str(record.seq)) for record in records]

    #[3] Truncate if longer than 1022 residues (ESM1b limit)
    data = [(name, seq[:1022]) for name, seq in data]

    #[4] Convert and embed
    batch_labels, batch_strs, batch_tokens = batch_converter(data)
    with torch.no_grad():
        results = model(batch_tokens, repr_layers=[33], return_contacts=False)
    token_representations = results["representations"][33]

    #[5] Extract per-sequence average embeddings (excluding [CLS] and [EOS])
    list_embs = []
    for i, (_, seq) in enumerate(data):
        emb = token_representations[i, 1:len(seq) + 1].mean(0)
        list_embs.append(emb)

    return list_embs if len(list_embs) > 1 else list_embs[0]
