def plot_2D_scatter_for_embedding_vis(emb_nby128d, path_save):
    print(f'\n[plot_2D_scatter_for_embedding_vis] \t Size of data: {emb_nby128d.shape}')
    #[1] Ensure input is a NumPy array
    if isinstance(emb_nby128d, list):
        emb_nby128d = np.array(emb_nby128d)
    elif not isinstance(emb_nby128d, np.ndarray):
        raise ValueError('Input data must be a NumPy array or a list.')
    elif not np.issubdtype(emb_nby128d.dtype, np.number):
        raise ValueError('Input array must contain numerical data.')

    # [1] Set plot
    fig, axes = plt.subplots(1, 3, figsize=(18, 6))
    fs_title, fs_subtitle, fs_axis, fs_tick = 24, 18, 16, 14
    fig.suptitle('Embedding Visualization', fontsize=fs_title) 

    # [4] PCA (with 3 components to use PC3 as color)
    pca = PCA(n_components=3)
    emb_3d_PCA = pca.fit_transform(emb_nby128d)
    print(f'\n[emb_3d_PCA.shape] \t{emb_3d_PCA.shape}')
    emb_2d_PCA = emb_3d_PCA[:, :2]
    color_PCA = emb_3d_PCA[:, 2]
    del pca, emb_3d_PCA

    # [5] KMeans clustering for categorical coloring
    cluster_labels = KMeans(n_clusters=5, random_state=42).fit_predict(emb_nby128d)

    # [6] t-SNE
    tsne = TSNE(n_components=2, perplexity=30, random_state=42)
    emb_2d_tSNE = tsne.fit_transform(emb_nby128d)

    # [7] UMAP
    reducer = UMAP(n_components=2, random_state=42)
    emb_2d_UMAP = reducer.fit_transform(emb_nby128d)

    # [8] Plot info
    plot_info = [
        (emb_2d_PCA, color_PCA, 'PC1', 'PC2', 'PCA (colored by PC3)'),
        (emb_2d_tSNE, cluster_labels, 't-SNE 1', 't-SNE 2', 't-SNE (colored by cluster)'),
        (emb_2d_UMAP, cluster_labels, 'UMAP 1', 'UMAP 2', 'UMAP (colored by cluster)')]

    # [9] Plotting loop
    for i, (plot_data, arr_color, xlabel, ylabel, title) in enumerate(plot_info):
        ax = axes[i]
        sc = ax.scatter(plot_data[:, 0], plot_data[:, 1], c=arr_color, cmap='viridis', s=10)
        ax.set_xlabel(xlabel, fontsize=fs_axis)
        ax.set_ylabel(ylabel, fontsize=fs_axis)
        ax.set_title(title, fontsize=fs_subtitle)
        ax.tick_params(axis='both', which='major', labelsize=fs_tick)
        #ax.set_aspect('equal', adjustable='datalim')
        #fig.colorbar(sc, ax=ax, shrink=0.7)

    # [10] Save or show plot
    plt.tight_layout(rect=[0.02, -0.02, 0.98, 1.02])     # left, bottom, right, top.
    if path_save is not None:
        plt.savefig(path_save)
        plt.close()
        print(f'Plot saved to {path_save}')
    else:
        plt.show()









