#!/usr/bin/env python


import os, sys
os.environ["OMP_NUM_THREADS"] = "8" # export OMP_NUM_THREADS=4
os.environ["OPENBLAS_NUM_THREADS"] = "8" # export OPENBLAS_NUM_THREADS=4
os.environ["MKL_NUM_THREADS"] = "8" # export MKL_NUM_THREADS=6
os.environ["VECLIB_MAXIMUM_THREADS"] = "8" # export VECLIB_MAXIMUM_THREADS=4
os.environ["NUMEXPR_NUM_THREADS"] = "8" # export NUMEXPR_NUM_THREADS=6

import copy

from typing import Union, Optional, List, Tuple, Dict, Any
from functools import reduce
from itertools import chain, accumulate

import numbers

from .ai_util import *

import networkx as nx
import numpy as np
import scipy

import torch
import torch.nn as nn
from torch_geometric.utils import softmax
from torch_scatter import scatter
torch.set_num_threads(8)
torch.autograd.set_detect_anomaly(True)

torch.set_printoptions(linewidth=1000, precision=4)
np.set_printoptions(linewidth=1000, precision=4)




ACT = {"relu": nn.ReLU, "tanh": nn.Tanh, "sigmoid": nn.Sigmoid, "": None, "none": None}
WBINS = [0, 0.01, 0.1, 0.25, 0.5, 0.75, 0.9, 0.99, 1, 10, 100, 1000, 1e4, 1e5]




class HYPERGRAPH(CACHE):
    PIN_VID = 1
    PIN_EID = 0
    def __init__(self, **kwargs):
        '''
        num_v: Optional[int],
        num_e: Optional[int],
        num_p: Optional[int],
        pins: Optional[torch.tensor],
        vpins: Optional[list[list[int]]] = None,
        epins: Optional[list[list[int]]] = None,
        vtx_feats: Optional[torch.tensor] = None,
        edg_feats: Optional[torch.tensor] = None,
        pin_feats: Optional[torch.tensor] = None,
        '''
        CACHE.__init__(self)
        self._init_empty()
        if len(kwargs)==0:
            return
        if 'num_vfeat' in kwargs:
            self.num_vfeat_ = kwargs.get('num_vfeat', 0)
            self.num_efeat_ = kwargs.get('num_efeat', 0)
            self.num_pfeat_ = kwargs.get('num_pfeat', 0)
            return
        if (sd:=kwargs.get('state_dict', None)) is not None:
            self.load_state_dict(sd)
            return
        self.build(num_v=kwargs.get('num_v', 0),
                   num_e=kwargs.get('num_e', 0),
                   num_p=kwargs.get('num_p', 0),
                   vpins=kwargs.get('vpins', None),
                   epins=kwargs.get('epins', None),
                   pins=kwargs.get('pins', None),
                   edg_feats=kwargs.get('edg_feats', None),
                   vtx_feats=kwargs.get('vtx_feats', None),
                   pin_feats=kwargs.get('pin_feats', None))
        self.device = torch.device('cpu')
    @property
    def num(self):
        return 1
    @property
    def vars_for_DL(self) -> List[str]:
        return [
                ]
    def to(self, device: torch.device):
        r"""Move the hypergraph to the specified device.

        Args:
            ``device`` (``torch.device``): The device to store the hypergraph.
        """
        self.device = device
        for v in self.vars_for_DL:
            if v in self.cache and self.cache[v] is not None:
                self.cache[v] = self.cache[v].to(device)
        # any variable needed in models
        self.pins_ = self.pins_.to(device)
        if self.vtx_feats_ is not None:
            self.vtx_feats_ = self.vtx_feats_.to(device)
        if self.edg_feats_ is not None:
            self.edg_feats_ = self.edg_feats_.to(device)
        if self.pin_feats_ is not None:
            self.pin_feats_ = self.pin_feats_.to(device)
    @property
    def empty(self):
        return self.pins_ is None
    def _init_empty(self):
        self.num_v_ = None
        self.num_e_ = None
        self.num_p_ = None
        self.pins_ = None
        self.vpins_ = None
        self.epins_ = None
        self.pin_feats_ = None
        self.edg_feats_ = None
        self.vtx_feats_ = None
        self.pin_wghts_ = None
        self.num_vfeat_ = None
        self.num_efeat_ = None
        self.num_pfeat_ = None
    def clone(self, hg):
        self.__init__()
        self.num_v_ = hg.num_v
        self.num_e_ = hg.num_e
        self.num_p_ = hg.num_p
        self.pins_ = hg.pins_.detach().clone()
        self.vpins_ = copy.deepcopy(hg.vpins_)
        self.epins_ = copy.deepcopy(hg.epins_)
        if hg.pin_feats_ is not None:
            self.pin_feats_ = hg.pin_feats_.detach().clone()
        if hg.vtx_feats_ is not None:
            self.vtx_feats_ = hg.vtx_feats_.detach().clone()
        if hg.edg_feats_ is not None:
            self.edg_feats_ = hg.edg_feats_.detach().clone()
        if hg.pin_wghts_ is not None:
            self.pin_wghts_ = hg.pin_wghts_.detach().clone()
            
            
    def build(
        self,
        num_v: Optional[int] = 0,
        num_e: Optional[int] = 0,
        num_p: Optional[int] = 0,
        vpins: Optional[list[list[int]]] = None,
        epins: Optional[list[list[int]]] = None,
        pins: Optional[torch.tensor] = None,
        edg_feats: Optional[torch.tensor] = None,
        vtx_feats: Optional[torch.tensor] = None,
        pin_feats: Optional[torch.tensor] = None,
    ):
        if pins is None:
            return
        pvem = pins.max(0).values
        vmax = pvem[HYPERGRAPH.PIN_VID]
        emax = pvem[HYPERGRAPH.PIN_EID]
        # num v
        if not num_v:
            if vpins is not None:
                num_v = len(vpins)
            else:
                num_v = vmax + 1
        assert num_v > vmax, 'vertex number is smaller than vertex id max: {}<{}.'.format(num_v, vmax)
        # num e
        if not num_e:
            if epins is not None:
                num_e = len(epins)
            else:
                num_e = emax + 1
        assert num_e > emax, 'edge number is smaller than max edge id: {} < {}.'.format(num_e, emax)
        # num p
        if not num_p:
            num_p = pins.size(0)
        assert num_p==pins.size(0), 'pin number mismatch: {} ~ {}.'.format(num_p, pins.size(0))
        # vepins
        #if vpins is None:
            #vpins = self._get_ilists_from_idxs(num_v, pins[:,HYPERGRAPH.PIN_VID])
        #if epins is None:
            #epins = self._get_ilists_from_idxs(num_e, pins[:,HYPERGRAPH.PIN_EID])
        # assign
        self.num_v_ = num_v
        self.num_e_ = num_e
        self.num_p_ = num_p
        self.pins_ = pins
        self.epins_ = epins
        self.vpins_ = vpins
        self.set_vtx_feats(vtx_feats)
        self.set_edg_feats(edg_feats)
        self.set_pin_feats(pin_feats)
        self.pin_wghts_ = None
    def state_dict(self):
        d = dict()
        d['num_v'] = self.num_v_
        d['num_e'] = self.num_e_
        d['num_p'] = self.num_p_
        d['pins'] = copy.deepcopy(self.pins_)
        #d['epins'] = copy.deepcopy(self.epins_)
        #d['vpins'] = copy.deepcopy(self.vpins_)
        d['vtx_feats'] = None if self.vtx_feats_ is None else copy.deepcopy(self.vtx_feats_.detach())
        d['edg_feats'] = None if self.edg_feats_ is None else copy.deepcopy(self.edg_feats_.detach())
        d['pin_feats'] = None if self.pin_feats_ is None else copy.deepcopy(self.pin_feats_.detach())
        d['num_vfeat'] = self.num_vfeat
        d['num_efeat'] = self.num_efeat
        d['num_pfeat'] = self.num_pfeat
        return d
    def load_state_dict(self, d):
        self.num_v_ = d['num_v']
        self.num_e_ = d['num_e']
        self.num_p_ = d['num_p']
        self.pins_ = d['pins']
        self.vtx_feats_ = d['vtx_feats']
        self.edg_feats_ = d['edg_feats']
        self.pin_feats_ = d['pin_feats']
        self.num_vfeat_ = d['num_vfeat']
        self.num_efeat_ = d['num_efeat']
        self.num_pfeat_ = d['num_pfeat']
    def set_vtx_feats(self, fs):
        if isinstance(fs, (int)):
            self.num_vfeat_ = fs
            if self.vtx_feats_ is not None and self.vtx_feats_.size(1)!=fs:
                self.vtx_feats_ = None
            return
        self.vtx_feats_ = fs
        if fs is not None:
            self.num_vfeat_ = fs.size(1)
            assert self.num_v is None or self.num_v == fs.size(0), 'unmatched vtx features {} ~ {}'.format(self.num_v, fs.size(0))
        else:
            self.num_vfeat_ = 0
    def set_edg_feats(self, fs):
        if isinstance(fs, (int)):
            self.num_efeat_ = fs
            if self.edg_feats_ is not None and self.edg_feats_.size(1)!=fs:
                self.edg_feats_ = None
            return
        self.edg_feats_ = fs
        if fs is not None:
            self.num_efeat_ = fs.size(1)
            assert self.num_e is None or self.num_e == fs.size(0), 'unmatched edg features {} ~ {}'.format(self.num_e, fs.size(0))
        else:
            self.num_efeat_ = 0
    def set_pin_feats(self, fs):
        if isinstance(fs, (int)):
            self.num_pfeat_ = fs
            if self.pin_feats_ is not None and self.pin_feats_.size(1)!=fs:
                self.pin_feats_ = None
            return
        self.pin_feats_ = fs
        if fs is not None:
            self.num_pfeat_ = fs.size(1)
            assert self.num_p is None or self.num_p == fs.size(0), 'unmatched pin features {} ~ {}'.format(self.num_p, fs.size(0))
        else:
            self.num_pfeat_ = 0
    def print_info(self):
        print("HYPERGRAPH:\n\t{} vtx, {} edg, {} pin".format(self.num_v_, self.num_e_, self.num_p_))
        print("pins:\n", self.pins_)
        print("vtx feats: {}\n{}".format(self.num_vfeat, self.vtx_feats_))
        print("edg feats: {}\n{}".format(self.num_efeat, self.edg_feats_))
        print("pin feats: {}\n{}".format(self.num_pfeat, self.pin_feats_))
        if self.empty:
            return
        vpins = self.vpins
        degs = [len(l) for l in vpins]
        print_array_hist('vtx degrees', np.asarray(degs), bins=[0, 1, 2, 5, 10, 20, 50, 100, 1000])
        epins = self.epins
        degs = [len(l) for l in epins]
        print_array_hist('edg degrees', np.asarray(degs), bins=[0, 1, 2, 5, 10, 20, 50, 100, 1000])
        print_array_hist('1v-edg degrees', np.asarray(degs)[self.e1v_idxs], bins=[0, 1, 2, 5, 10, 20, 50, 100, 1000])
    @staticmethod
    def _get_ilists_from_idxs(n, idxs):
        def _func(ps, p):
            ps[p[1].item()].append(p[0])
            return ps
        res = reduce(_func, enumerate(idxs), [[] for i in range(n)])
        return res
    def _fetch_H(self):
        w = self.pin_wghts_ if self.pin_wghts_ is not None else torch.ones(self.num_p_, device=self.device)
        pins = self.pins_[:, [HYPERGRAPH.PIN_VID, HYPERGRAPH.PIN_EID]]
        H = torch.sparse_coo_tensor(
                pins.transpose(0,1),
                w,
                (self.num_v_, self.num_e_),
                device=self.device)
        H = H.coalesce().to(self.device)
        return H
    @property
    def num_v(self):
        return self.num_v_
    @property
    def num_e(self):
        return self.num_e_
    @property
    def num_p(self):
        return self.num_p_
    @property
    def num_vfeat(self):
        if self.num_vfeat_ is not None:
            return self.num_vfeat_
        if self.vtx_feats_ is None:
            return 0
        return self.vtx_feats_.size(1)
    @property
    def num_efeat(self):
        if self.num_efeat_ is not None:
            return self.num_efeat_
        if self.edg_feats_ is None:
            return 0
        return self.edg_feats_.size(1)
    @property
    def num_pfeat(self):
        if self.num_pfeat_ is not None:
            return self.num_pfeat_
        if self.pin_feats_ is None:
            return 0
        return self.pin_feats_.size(1)
    def evs(self, i):
        r = [self.pinv(p) for p in self.epins[i]]
        return r
    def ves(self, i):
        r = [self.pine(p) for p in self.vpins[i]]
        return r
    @property
    def e1d_pins(self):
        # connected edge having degree 1
        if self.cache.get('E1DP') is None:
            r = [len(self.epins[self.pine(i)]) for i in range(self.num_p)]
            r = np.asarray(r)
            msk = r==1
            r = np.arange(self.num_p)[msk]
            self.cache['E1DP'] = r
        return self.cache['E1DP']
    def _is_e1v(self, i):
        l = self.evs(i)
        return all(x==l[0] for x in l)
    @property
    def e1v_idxs(self):
        if self.cache.get('E1VI') is None:
            r = [self._is_e1v(i) for i in range(self.num_e)]
            r = np.asarray(r)
            msk = r==1
            r = np.arange(self.num_e)[msk]
            self.cache['E1VI'] = r
        return self.cache['E1VI']
    @property
    def e1v_pins(self):
        # connected edge having degree 1
        if self.cache.get('E1VP') is None:
            r = [self._is_e1v(self.pine(i)) for i in range(self.num_p)]
            r = np.asarray(r)
            msk = r==1
            r = np.arange(self.num_p)[msk]
            self.cache['E1VP'] = r
        return self.cache['E1VP']
    def pinve(self, i):
        return self.pins_[i,HYPERGRAPH.PIN_VID].item(), self.pins_[i,HYPERGRAPH.PIN_EID].item()
    def pinv(self, i):
        return self.pins_[i, HYPERGRAPH.PIN_VID]
    def pine(self, i):
        return self.pins_[i, HYPERGRAPH.PIN_EID]
    def idxs(self): # v, e
        return self.pins_[:, [HYPERGRAPH.PIN_VID, HYPERGRAPH.PIN_EID]]
    @property
    def vpins(self):
        if self.vpins_ is None:
            if self.cache.get('VP') is None:
                vpins = self._get_ilists_from_idxs(self.num_v, self.pins_[:,HYPERGRAPH.PIN_VID])
                self.cache['VP'] = vpins
            return self.cache['VP']
        return self.vpins_
    @property
    def epins(self):
        if self.epins_ is None:
            if self.cache.get('EP') is None:
                epins = self._get_ilists_from_idxs(self.num_e, self.pins_[:,HYPERGRAPH.PIN_EID])
                self.cache['EP'] = epins
            return self.cache['EP']
        return self.epins_
    @property
    def pvtxs(self):
        return self.pins_[:,HYPERGRAPH.PIN_VID]
    @property
    def pedgs(self):
        return self.pins_[:,HYPERGRAPH.PIN_EID]
    def v2p(self, x):
        return x[self.pvtxs]
    def e2p(self, x):
        return x[self.pedgs]
    @property
    def H_v2e(self) -> torch.Tensor:
        if self.cache.get('H_v2e') is None:
            self.cache['H_v2e'] = self._fetch_H()
        return self.cache['H_v2e']
    @property
    def H(self) -> torch.Tensor:
        r"""Return the hypergraph incidence matrix :math:`\mathbf{H}` with ``torch.sparse_coo_tensor`` format.
        """
        if self.cache.get("H") is None:
            self.cache["H"] = self.H_v2e.to(self.device)
        return self.cache["H"]
    @property
    def H_T(self) -> torch.Tensor:
        r"""Return the transpose of the hypergraph incidence matrix :math:`\mathbf{H}^\top` with ``torch.sparse_coo_tensor`` format.
        """
        if self.cache.get("H_T") is None:
            self.cache["H_T"] = self.H.t().to(self.device)
        return self.cache["H_T"]
    @property
    def A(self) -> torch.Tensor:
        r"""Return the adjacency matrix :math:`\mathbf{A}^\top` with ``torch.sparse_coo_tensor`` format.
        """
        if self.cache.get("A") is None:
            self.cache["A"] = torch.mm(self.H, self.H_T)
        return self.cache["A"]
    @property
    def G(self) -> nx.Graph:
        if self.cache.get("G") is None:
            self.cache["G"] = self._gen_adjgraph_nx()
        return self.cache["G"]
    def xv(self, x=None):
        if self.vtx_feats_ is None:
            return x
        if x is None:
            x = self.vtx_feats_
        else:
            assert x.size(0)==self.num_v_, 'vertex num mismatch: {} ~ {}.'.format(x.size(), self.num_v_)
            x = torch.cat([self.vtx_feats_, x], dim=1)
        return x
    def xe(self, x=None):
        if self.edg_feats_ is None:
            return x
        if x is None:
            x = self.edg_feats_
        else:
            assert x.size(0)==self.num_e_, 'edge num mismatch: {} ~ {}.'.format(x.size(), self.num_e_)
            x = torch.cat([self.edg_feats_, x], dim=1)
        return x
    def xp(self, x=None):
        if self.pin_feats_ is None:
            return x
        if x is None:
            x = self.pin_feats_
        else:
            assert x.size(0)==self.num_p_, 'vertex pin mismatch: {} ~ {}.'.format(x.size(), self.num_p_)
            x = torch.cat([self.pin_feats_, x], dim=1)
        return x
    def len_xvp(self, nv=-1, np=-1):
        if nv==-1:
            nv = self.num_vfeat
        if np==-1:
            np = self.num_pfeat
        return nv + self.num_vfeat + np + self.num_pfeat
    def xvp(self,
            xv: torch.Tensor,
            xp: torch.Tensor,
        ):
        xv = self.xv(xv)
        xp = self.xp(xp)
        xv = self.v2p(xv)
        x = torch.cat([xv,xp], dim=1)
        return x
    def len_xep(self, ne=-1, np=-1):
        if ne==-1:
            ne = self.num_efeat
        if np==-1:
            np = self.num_pfeat
        return ne + self.num_efeat + np + self.num_pfeat
    def xep(self,
            xe: torch.Tensor,
            xp: torch.Tensor,
        ):
        xe = self.xe(xe)
        xp = self.xp(xp)
        xe = self.e2p(xe)
        x = torch.cat([xe,xp], dim=1)
        return x
    @staticmethod
    def _scatter(x, w, idxs, num, aggr):
        if w is not None:
            w = softmax(src=w, index=idxs, num_nodes=num)
            w = w.view(-1,1)
            x = torch.mul(x, w)
        #return scatter(src=x, index=idxs, reduce=aggr)
        if isinstance(aggr, str):
            return scatter(src=x, index=idxs, dim=0, out=None, dim_size=None, reduce=aggr)
        assert isinstance(aggr, list)
        rx = []
        for a in aggr:
            assert a in ['sum', 'mean', 'min', 'max']
            xx = scatter(src=x, index=idxs, dim=0, out=None, dim_size=None, reduce=a)
            rx.append(xx)
        x = torch.cat(rx, dim=1)
        return x
    def p2e(self,
            x: torch.Tensor,
            w: torch.Tensor=None,
            aggr: str='mean',
        ):
        assert x.size(0)==self.num_p_, 'x mismatch with pin num {} ~ {}'.format(x.size(), self.num_p_)
        assert w is None or w.size(0)==self.num_p_, 'w dimension wrong {} ~ {}'.format(w.size(), self.num_p_)
        res = self._scatter(x, w, self.pedgs, self.num_e_, aggr)
        if res.size(0) < self.num_e:
            n = self.num_e - res.size(0)
            res = nn.functional.pad(res, (0,0,0,n))
        return res
    def p2v(self,
            x: torch.Tensor,
            w: torch.Tensor=None,
            aggr: str='mean',
        ):
        assert x.size(0)==self.num_p_, 'x mismatch with pin num {} ~ {}'.format(x.size(), self.num_p_)
        assert w.size(0)==self.num_p_, 'w dimension wrong {} ~ {}'.format(w.size(), self.num_p_)
        res = self._scatter(x, w, self.pvtxs, self.num_v_, aggr)
        if res.size(0) < self.num_v:
            n = self.num_v - res.size(0)
            res = nn.functional.pad(res, (0,0,0,n))
        return res
    def set_pin_wghts(self, wghts):
        if isinstance(wghts, (np.ndarray, np.generic)):
            wghts = torch.from_numpy(wghts).to(self.device)
        self.pin_wghts_ = wghts.flatten()
        self._clear_cache()
    @property
    def pinwghts(self):
        return self.pin_wghts_
    def _gen_adjgraph_nx(self):
        m = self.A
        idxs = m.indices().numpy(force=True)
        vals = m.values().numpy(force=True)
        m2 = scipy.sparse.coo_array((vals, idxs), shape=(self.num_v, self.num_v))
        g = nx.from_scipy_sparse_array(m2)
        return g
    def clustering(self, pinwghts=None, rtype='sets'):
        if pinwghts is not None:
            self.set_pin_wghts(pinwghts)
        g = self.G
        cls = nx.algorithms.community.louvain_communities(g)
        if rtype=='sets':
            return cls
        assert rtype=='nparray', "wrong arg: rtype={}".format(rtype)
        r = np.ones(self.num_v)
        ncls = 0
        for c in cls:
            r[list(c)] = ncls
            ncls += 1
        return r
    def get_cut_eids(self, cls):
        evcids = [cls[self.pins_[pids,HYPERGRAPH.PIN_VID]] for pids in self.epins]
        msk = [False if isinstance(v, numbers.Number) or len(v)==1 else np.any(v!=v[0]) for v in evcids]
        return np.arange(self.num_e)[msk]
    def get_cut_degrees(self, cls):
        evcids = [cls[self.pins_[pids,HYPERGRAPH.PIN_VID]] for pids in self.epins]
        d = np.asarray([0 if isinstance(v, numbers.Number) else len(np.unique(v)) for v in evcids])
        return d[d>1]
    def gen_vtx_graph_mat(self, pinwghts=None):
        if pinwghts is not None:
            self.set_pin_wghts(pinwghts)
        return self.A
    def gen_vtx_graph(self, pinwghts=None):
        m = self.gen_vtx_graph_mat(pinwghts)
        idxs = m.indices().numpy(force=True).transpose()
        vals = m.values().numpy(force=True)
        return idxs, vals
    def print_mem_info(self):
        print("HYPERGRAPH: {} vtx, {} edg, {} pin.".format(self.num_v, self.num_e, self.num_p))
        print("\tvpins {} KB, vpins {} KB".format(sys.getsizeof(self.vpins_)/1024, sys.getsizeof(self.epins_)/1024))
        print('\tfeatures: {} KB vtx, {} KB edg, {} KB pin, {} KB pinwghts.'.format(0 if self.vtx_feats_ is None else self.vtx_feats_.nbytes/1024, 0 if self.edg_feats_ is None else self.edg_feats_.nbytes/1024, 0 if self.pin_feats_ is None else self.pin_feats_.nbytes/1024, 0 if self.pin_wghts_ is None else self.pin_wghts_.nbytes/1024))
        CACHE.print_mem_info(self)

class HYPERGRAPHS(HYPERGRAPH, CACHE):
    def __init__(self, **kwargs):
        HYPERGRAPH.__init__(self)
        CACHE.__init__(self)
        self.num_hg_ = 0
        self.nv_hgs_ = []
        self.ne_hgs_ = []
        self.np_hgs_ = []
        self.hgs = []
        if len(kwargs)==0:
            return
        if (hgs:=kwargs.get('hgs', None)) is not None:
            self.assemble(hgs)
    def add(self, hg):
        if self.num_hg_ == 0:
            self.clone(hg)
            self.hgs.append(hg)
            self.nv_hgs_.append(hg.num_v)
            self.ne_hgs_.append(hg.num_e)
            self.np_hgs_.append(hg.num_p)
            self.num_v_ += hg.num_v
            self.num_e_ += hg.num_e
            self.num_p_ += hg.num_p
            self.num_hg_ += 1
            return
        assert self.num_vfeat == hg.num_vfeat, 'num vfeat mismatch: {} ~ {}.'.format(self.num_vfeat, hg.num_vfeat)
        assert self.num_efeat == hg.num_efeat, 'num vfeat mismatch: {} ~ {}.'.format(self.num_efeat, hg.num_efeat)
        assert self.num_pfeat == hg.num_pfeat, 'num vfeat mismatch: {} ~ {}.'.format(self.num_pfeat, hg.num_pfeat)
        assert (self.pin_wghts_ is None and hg.pin_wghts_ is None) or (self.pin_wghts_ is not None and hg.pin_wghts_ is not None), 'pin wghts mismatch.'
        pins = hg.pins_.detach().clone()
        pins[:,HYPERGRAPH.PIN_VID] += self.num_v
        pins[:,HYPERGRAPH.PIN_EID] += self.num_e
        self.pins_ = torch.cat([self.pins_, pins], dim=0)
        if hg.vpins_ is not None:
            assert self.vpins_ is not None
            vpins = copy.deepcopy(hg.vpins_)
            vpins = [[x+self.num_p for x in xx] for xx in vpins]
            self.vpins_ += vpins
        if hg.epins_ is not None:
            assert self.epins_ is not None
            epins = copy.deepcopy(hg.epins_)
            epins = [[x+self.num_p for x in xx] for xx in epins]
            self.epins_ += epins
        if hg.pin_feats_ is not None:
            pin_feats = hg.pin_feats_.detach().clone()
        if hg.vtx_feats_ is not None:
            vtx_feats = hg.vtx_feats_.detach().clone()
        if hg.edg_feats_ is not None:
            edg_feats = hg.edg_feats_.detach().clone()
        if hg.pin_wghts_ is not None:
            pin_wghts = hg.pin_wghts_.detach().clone()
        self.num_v_ += hg.num_v
        self.num_e_ += hg.num_e
        self.num_p_ += hg.num_p
        self.num_hg_ += 1
        if hg.pin_feats_ is not None:
            self.pin_feats_ = torch.cat([self.pin_feats_, pin_feats], dim=0)
        if hg.vtx_feats_ is not None:
            self.set_vtx_feats(torch.cat([self.vtx_feats_, vtx_feats], dim=0))
        if hg.edg_feats_ is not None:
            self.set_edg_feats(torch.cat([self.edg_feats_, edg_feats], dim=0))
        if self.pin_wghts_ is not None:
            self.set_pin_feats(torch.cat([self.pin_wghts_, pin_wghts], dim=0))
        self.nv_hgs_.append(hg.num_v)
        self.ne_hgs_.append(hg.num_e)
        self.np_hgs_.append(hg.num_p)
        
        
        
        
        
    def assemble(self, hgs):
        assert self.num_hg_ == 0
        self.num_hg_ = nhg = len(hgs)
        self.hgs = hgs
        l_pins = []
        l_vpins = []
        l_epins = []
        l_pin_feats = []
        l_vtx_feats = []
        l_edg_feats = []
        l_pin_wghts = []
        numv = nume = nump = 0
        for i in range(nhg):
            hg = hgs[i]
            self.nv_hgs_.append(hg.num_v)
            self.ne_hgs_.append(hg.num_e)
            self.np_hgs_.append(hg.num_p)
            pins = hg.pins_.detach().clone()
            pins[:,HYPERGRAPH.PIN_VID] += numv
            pins[:,HYPERGRAPH.PIN_EID] += nume
            l_pins.append(pins)
            if hg.vpins_ is not None:
                vpins = copy.deepcopy(hg.vpins_)
                vpins = [[x+nump for x in xx] for xx in vpins]
                l_vpins.append(vpins)
            if hg.epins_ is not None:
                epins = copy.deepcopy(hg.epins_)
                epins = [[x+nump for x in xx] for xx in epins]
                l_epins.append(epins)
            if hg.pin_feats_ is not None:
                assert i==0 or l_pin_feats
                pin_feats = hg.pin_feats_.detach().clone()
                l_pin_feats.append(pin_feats)
            else:
                assert not l_pin_feats
            if hg.vtx_feats_ is not None:
                assert i==0 or l_vtx_feats
                vtx_feats = hg.vtx_feats_.detach().clone()
                l_vtx_feats.append(vtx_feats)
            else:
                assert not l_vtx_feats
            if hg.edg_feats_ is not None:
                assert i==0 or l_edg_feats
                edg_feats = hg.edg_feats_.detach().clone()
                l_edg_feats.append(edg_feats)
            else:
                assert not l_edg_feats
            if hg.pin_wghts_ is not None:
                assert i==0 or l_pin_wghts
                pin_wghts = hg.pin_wghts_.detach().clone()
                l_pin_wghts.append(pin_feats)
            else:
                assert not l_pin_wghts
            numv += hg.num_v
            nume += hg.num_e
            nump += hg.num_p
        self.pins_ = torch.cat(l_pins, dim=0)
        if l_vpins:
            assert len(l_vpins)==nhg
            self.vpins_ = list(chain.from_iterable(l_vpins))
        if l_epins:
            assert len(l_epins)==nhg
            self.epins_ = list(chain.from_iterable(l_epins))
        if l_pin_feats:
            self.set_pin_feats(torch.cat(l_pin_feats, dim=0))
        if l_vtx_feats:
            self.set_vtx_feats(torch.cat(l_vtx_feats, dim=0))
        if l_edg_feats:
            self.set_edg_feats(torch.cat(l_edg_feats, dim=0))
        if l_pin_wghts:
            self.pin_wghts_ = torch.cat(l_pin_wghts, dim=0)
        self.num_v_ = sum(self.nv_hgs_)
        self.num_e_ = sum(self.ne_hgs_)
        self.num_p_ = sum(self.np_hgs_)
        assert numv==self.num_v_ and nume==self.num_e_ and nump==self.num_p_
    @property
    def num(self):
        return self.num_hg_
    def numv(self, i=-1):
        if i<0:
            return self.num_v
        return self.nv_hgs_[i]
    def nume(self, i=-1):
        if i<0:
            return self.num_e
        return self.ne_hgs_[i]
    def nump(self, i=-1):
        if i<0:
            return self.num_p
        return self.np_hgs_[i]
    @property
    def iv_hgs(self):
        if self.cache.get('IV') is None:
            l = list(accumulate(self.nv_hgs_, initial=0))
            self.cache['IV'] = l
        return self.cache['IV']
    def ivbeg(self, i):
        return self.iv_hgs[i]
    def ivend(self, i):
        return self.iv_hgs[i+1]
    @property
    def ie_hgs(self):
        if self.cache.get('IE') is None:
            l = list(accumulate(self.ne_hgs_, initial=0))
            self.cache['IE'] = l
        return self.cache['IE']
    def iebeg(self, i):
        return self.ie_hgs[i]
    def ieend(self, i):
        return self.ie_hgs[i+1]
    @property
    def ip_hgs(self):
        if self.cache.get('IP') is None:
            l = list(accumulate(self.np_hgs_, initial=0))
            self.cache['IP'] = l
        return self.cache['IP']
    def ipbeg(self, i):
        return self.ip_hgs[i]
    def ipend(self, i):
        return self.ip_hgs[i+1]
    def pins(self, i=-1):
        if i<0:
            return self.pins_
        return self.pins_[self.ipbeg(i) : self.ipend(i)]
    #def vpins(self, i=-1):
        #if i<0:
            #return self.vpins_
        #return self.vpins_[self.ivbeg(i) : self.ivend(i)]
    #def epins(self, i=-1):
        #if i<0:
            #return self.epins_
        #return self.epins_[self.iebeg(i) : self.ieend(i)]
    def pin_feats(self, i=-1):
        if i<0:
            return self.pin_feats_
        return self.pin_feats_[self.ipbeg(i) : self.ipend(i)]
    def pin_wghts(self, i=-1):
        if i<0:
            return self.pin_wghts_
        return self.pin_wghts_[self.ipbeg(i) : self.ipend(i)]
    def vtx_feats(self, i=-1):
        if i<0:
            return self.vtx_feats_
        return self.vtx_feats_[self.ivbeg(i) : self.ivend(i)]
    def edg_feats(self, i=-1):
        if i<0:
            return self.edg_feats_
        return self.edg_feats_[self.iebeg(i) : self.ieend(i)]
    def vextract(self, x, i):
        if i<0:
            return x
        return x[self.ivbeg(i) : self.ivend(i)]
    def eextract(self, x, i):
        if i<0:
            return x
        return x[self.iebeg(i) : self.ieend(i)]
    def pextract(self, x, i):
        if i<0:
            return x
        return x[self.ipbeg(i) : self.ipend(i)]

class NN(nn.Module):
    def __init__(self,
            neuros: list[int],
            act: Union[str, list[str]] = 'sigmoid',
            dropout: Union[float, list[float]] = 0.0
        ):
        super().__init__()
        nlayer = len(neuros)
        if isinstance(act, str):
            act = [act] * (nlayer - 1)
        else:
            assert isinstance(act, list), 'wrong type for act: {}'.format(type(act))
            assert len(act)==nlayer-1, 'act num mismatch: {} ~ {}'.format(len(act), nlayer-1)
        if isinstance(dropout, float):
            dropout = [dropout] * (nlayer - 1)
        else:
            assert not isinstance(dropout, list), 'wrong type for dropout: {}'.format(type(dropout))
            assert len(dropout)==nlayer-1, 'dropout num mismatch: {} ~ {}'.format(len(dropout), nlayer-1)
        models = []
        for i in range(nlayer-1):
            if dropout[i]:
                models.append(nn.Dropout(p=dropout[i]))
            models.append(nn.Linear(neuros[i], neuros[i+1], bias=True))
            if act[i]:
                models.append(ACT[act[i]]())
        self.model = nn.Sequential(*models)
    def forward(self, x, debug=False):
        if debug:
            for m in self.model:
                x = m(x)
                print(m)
                print(x)
            return x
        x = self.model(x)
        return x

class HLSTM(nn.LSTM):
    def __init__(self, *args, **kwargs):
        proj_size = kwargs.get('proj_size', None)
        if proj_size is not None:
            kwargs['proj_size'] = 0
        super().__init__(*args, **kwargs)
        self.hx = None
        self.nnproj = None
        if proj_size is not None:
            hsize = kwargs['hidden_size']
            if proj_size != hsize:
                self.nnproj = NN([hsize, proj_size], dropout=0.)
    def forward(self, x):
        if x.dim() == 2:
            x = torch.unsqueeze(x, 0)
        output, hx = super().forward(x, self.hx)
        self.hx = hx
        output = output[-1]
        if self.nnproj is not None:
            output = self.nnproj(output)
        return output
    def clear(self):
        if self.hx is None:
            return
        if isinstance(self.hx, torch.Tensor):
            self.hx.detach()
        else:
            for h in self.hx:
                h.detach()
        self.hx = None

class HLSTM0(nn.Module): # use lstm as a member
    def __init__(self, *args, **kwargs):
        super().__init__()
        proj_size = kwargs.get('proj_size', None)
        if proj_size is not None:
            kwargs['proj_size'] = 0
        self.lstm_ = nn.LSTM(*args, **kwargs)
        self.hx = None
        self.nnproj = None
        if proj_size is not None:
            hsize = kwargs['hidden_size']
            if proj_size != hsize:
                self.nnproj = NN([hsize, proj_size], dropout=0.)
    def forward(self, x):
        if x.dim() == 2:
            x = torch.unsqueeze(x, 0)
        output, hx = self.lstm_(x, self.hx)
        self.hx = hx
        output = output[-1]
        if self.nnproj is not None:
            output = self.nnproj(output)
        return output
    def clear(self):
        if self.hx is None:
            return
        if isinstance(self.hx, torch.Tensor):
            self.hx.detach()
        else:
            for h in self.hx:
                h.detach()
        self.hx = None

class HGMP(nn.Module):
    def __init__(self,
            hg: HYPERGRAPH,
            nvf0: int = 0,
            nef0: int = 0,
            npf0: int = 0,
            nvf: int = -1,
            nef: int = -1,
            npf: int = -1,
            lstmlayer: int = 3,
            use_p_nn: bool = True,
            p2aggr: Union[str, list[str]] = ['sum','min','max'],
            nndropout: float = 0.0,
            rnndropout: float = 0.0
        ):
        super().__init__()
        if nvf < 0:
            nvf = hg.num_vfeat
        if nef < 0:
            nef = hg.num_efeat
        if npf < 0:
            npf = hg.num_pfeat
        self.nvf = nvf
        self.nef = nef
        self.npf = npf
        self.p2aggr = p2aggr
        np2aggr = 1 if isinstance(p2aggr, str) else len(p2aggr)
        self.model_v0 = None
        self.model_p0 = None
        if nvf0 and nvf0!=nvf:
            self.model_v0 = NN([nvf0, nvf])
        if npf0 and npf0!=npf:
            self.model_p0 = NN([npf0, npf])
        # v to p
        self.model_vp2p = HLSTM(input_size=hg.len_xvp(nvf,npf), hidden_size=npf*2, num_layers=lstmlayer, bias=True, batch_first=False, dropout=rnndropout, proj_size=(npf if use_p_nn else nef))
        # p to e weight
        neuros = [npf if use_p_nn else nef,1]
        self.model_wp2e = NN(neuros, act='relu', dropout=nndropout)
        # p to e transform
        if use_p_nn:
            self.model_tp2e = NN([npf, npf+nef, nef], act=['relu', 'sigmoid'], dropout=nndropout)
        else:
            self.model_tp2e = None
        # e update
        self.model_eupdate = HLSTM(input_size=nef*np2aggr+hg.num_efeat, hidden_size=nef*2, num_layers=lstmlayer, bias=True, batch_first=False, dropout=rnndropout, proj_size=nef)
        # e to p
        self.model_ep2p = HLSTM(input_size=hg.len_xep(nef,npf), hidden_size=npf*2, num_layers=lstmlayer, bias=True, batch_first=False, dropout=rnndropout, proj_size=(npf if use_p_nn else nvf))
        # p update
        self.model_pupdate = HLSTM(input_size=2*npf+hg.num_pfeat, hidden_size=npf*2, num_layers=lstmlayer, bias=True, batch_first=False, dropout=rnndropout, proj_size=npf)
        # p to v weight
        neuros = [npf if use_p_nn else nvf,1]
        self.model_wp2v = NN(neuros, act='relu', dropout=nndropout)
        # p to v transform
        if use_p_nn:
            self.model_tp2v = NN([npf, npf+nvf, nvf], act=['relu', 'sigmoid'], dropout=nndropout)
        else:
            self.model_tp2v = None
        # v update
        self.model_vupdate = HLSTM(input_size=nvf*np2aggr+hg.num_vfeat, hidden_size=nvf*2, num_layers=lstmlayer, bias=True, batch_first=False, dropout=0, proj_size=nvf)

    def _clear_hop_hist(self):
        self.model_vp2p.clear()
        self.model_eupdate.clear()
        self.model_ep2p.clear()
        self.model_pupdate.clear()
        self.model_vupdate.clear()
    def hop(self, hg, xv, xe, xp, verbose=False):
        # vertex to pin
        x = hg.xvp(xv, xp)
        x = self.model_vp2p(x)
        #print('vp2p: {}'.format(x.size()))
        xvpo = x
        # pin to edge
        w = self.model_wp2e(x).flatten()
        if self.model_tp2e is not None:
            x = self.model_tp2e(x)
        x = hg.p2e(x, w, self.p2aggr)
        # edge update
        if xe is not None:
            x = torch.cat([xe,x], dim=1)
        x = self.model_eupdate(x)
        #print('e update: {}'.format(x.size()))
        xeo = x
        # edge to pin
        x = hg.xep(x, xp)
        x = self.model_ep2p(x)
        #print('ep2p: {}'.format(x.size()))
        xepo = x
        # pin update
        x = torch.cat([xvpo, xepo], dim=1)
        x = hg.xp(x)
        x = self.model_pupdate(x)
        xpo = x
        # pin to vtx
        w = self.model_wp2v(x).flatten()
        if self.model_tp2v is not None:
            x = self.model_tp2v(x)
        x = hg.p2v(x, w, self.p2aggr)
        # vertex update
        x = hg.xv(x)
        x = self.model_vupdate(x)
        #print('v update: {}'.format(x.size()))
        xvo = x
        return xvo, xeo, xpo
    def forward(self, hg, xv, xe, xp, nhop=10, verbose=False):
        noxv = xv is None
        noxe = xe is None
        noxp = xp is None
        self._clear_hop_hist()
        if self.model_v0 is not None:
            xv = self.model_v0(xv)
        if self.model_p0 is not None:
            xp = self.model_p0(xp)
        for i in range(nhop):
            if verbose:
                print('hop {}:\nxv: {}\nxe: {}\nxp: {}'.format(i, xv, xe, xp))
            if noxv:
                xv = None
            if noxe:
                xe = None
            if noxp:
                xp = None
            xv, xe, xp = self.hop(hg, xv, xe, xp, verbose=verbose)
        return xv, xe, xp

class PINWGHT(nn.Module):
    def __init__(self,
            hg: HYPERGRAPH,
            ndf: int = -1,
            nnf: int = -1,
            npf: int = -1,
            nhop: int = 10,
            use_p_nn: bool = True,
            p2aggr: Union[str, list[str]] = ['sum','min','max']
        ):
        super().__init__()
        self.hgmodel = HGMP(hg, nvf0=hg.num_vfeat, nef0=hg.num_efeat, npf0=hg.num_pfeat, nvf=ndf, nef=nnf, npf=npf, use_p_nn=use_p_nn)
        self.pwmodel = NN([self.hgmodel.npf, self.hgmodel.npf*2, 1])
        self.nhop = nhop
    def forward(self, hg, verbose=False):
        xv, xe, xp = self.hgmodel(hg, hg.xv(), hg.xe(), hg.xp(), self.nhop, verbose=verbose)
        x = xp
        x = self.pwmodel(x)
        #x = nn.Sigmoid()(x)
        return x
    def loss_distr(self, x):
        d = x.max() - x.min()
        x = x - 0.5
        x = x.abs()
        s = x.std()
        return -(s+d)

# vertex/edge/graph model
class VEPGMODEL(nn.Module):
    def __init__(self,
            hg: Union[HYPERGRAPH, HYPERGRAPHS],
            nvcls: int,
            necls: int,
            npcls: int,
            ngcls: int,
            nvf: int = -1,
            nef: int = -1,
            npf: int = -1,
            ngf: int = 0,
            nhop: int = 10,
            lstmlayer: int = 3,
            nndropout: float = 0.0,
            rnndropout: float = 0.0,
            use_p_nn: bool = True,
            p2aggr: Union[str, list[str]] = ['sum','min','max'],
            v_use_g: bool = True,
            e_use_g: bool = True,
            p_use_g: bool = True,
            vepg_valid: str = 'vepg'
        ):
        super().__init__()
        self.vepg_valid_ = vepg_valid
        self.hgmodel = HGMP(hg, nvf0=hg.num_vfeat, nef0=hg.num_efeat, npf0=hg.num_pfeat, nvf=nvf, nef=nef, npf=npf, lstmlayer=lstmlayer,  use_p_nn=use_p_nn)
        self.nhop = nhop
        # graph level
        if ngf<0 and ngcls>0:
            ngf = hg.num_efeat
        self.ngf = ngf
        if ngf>0:
            self.hgtmodel = NN([self.len_xgr, ngf], dropout=nndropout)
            if ngcls:
                self.gmodel = NN([ngf, 10, ngcls], act=['relu','sigmoid'], dropout=nndropout)
            else:
                self.gmodel = None
        else:
            self.hgtmodel = None
            self.gmodel = None
        self.v_use_g = v_use_g
        self.e_use_g = e_use_g
        self.p_use_g = p_use_g
        # vtx
        if nvcls:
            nin = nvf + (ngf if v_use_g else 0)
            self.vtxmodel = NN([nin, 10, nvcls], act=['relu','sigmoid'], dropout=nndropout)
        else:
            self.vtxmodel = None
        # edge
        if necls:
            nin = nef + (ngf if e_use_g else 0)
            self.edgmodel = NN([nin, 10, necls], act=['relu','sigmoid'], dropout=nndropout)
        else:
            self.edgmodel = None
        # pin
        if npcls:
            nin = npf + (ngf if p_use_g else 0)
            self.pinmodel = NN([nin, 10, npcls], act=['relu','sigmoid'], dropout=nndropout)
        else:
            self.pinmodel = None
    @property
    def device(self):
        return next(self.parameters()).device
    def set_active(self, s):
        self.vepg_valid_ = s
    def check_active(self, s):
        if self.vepg_valid_ == s:
            return True
        return False
    @property
    def output(self):
        return self.vepg_valid_
    @property
    def nout(self):
        return len(self.vepg_valid_)
    @property
    def nvf(self):
        return self.hgmodel.nvf
    @property
    def nef(self):
        return self.hgmodel.nef
    @property
    def npf(self):
        return self.hgmodel.npf
    @property
    def len_xgr(self):
        return self.nvf*2 + self.nef*2
    def xgr_raw(self, xv, xe, hgs):
        def _getxh(xv, xe):
            xv_ave = xv.mean(dim=0)
            xv_std = xv.std(dim=0) if len(xv)>1 else torch.zeros(len(xv_ave), device=self.device)
            xe_ave = xe.mean(dim=0)
            xe_std = xe.std(dim=0) if len(xe)>1 else torch.zeros(len(xe_ave), device=self.device)
            x = torch.cat([xv_ave, xv_std, xe_ave, xe_std])
            return x
        if hgs is None or hgs.num==1:
            return _getxh(xv, xe).expand(1,-1)
        x = [_getxh(hgs.vextract(xv, i), hgs.eextract(xe, i)).reshape(1,-1) for i in range(hgs.num)]
        x = torch.cat(x, dim=0)
        return x
    def xgr(self, xv, xe, hgs, verbose=False):
        x = self.xgr_raw(xv, xe, hgs)
        x = self.hgtmodel(x)
        if (verbose):
            print('top graph:', x)
        return x
    def vexpand_xgr(self, x, hgs):
        if hgs.num==1:
            return x.expand(hgs.num_v, -1)
        xs = [x[i].expand(hgs.numv(i), -1) for i in range(hgs.num)]
        xs = torch.cat(xs, dim=0)
        return xs
    def eexpand_xgr(self, x, hgs):
        if hgs.num==1:
            return x.expand(hgs.num_e, -1)
        xs = [x[i].expand(hgs.nume(i), -1) for i in range(hgs.num)]
        xs = torch.cat(xs, dim=0)
        return xs
    def pexpand_xgr(self, x, hgs):
        if hgs.num==1:
            return x.expand(hgs.num_p, -1)
        xs = [x[i].expand(hgs.nump(i), -1) for i in range(hgs.num)]
        xs = torch.cat(xs, dim=0)
        return xs
    def forward_hg_only(self, hg, verbose=False):
        xv, xe, xp = self.hgmodel(hg, hg.xv(), hg.xe(), hg.xp(), self.nhop, verbose=verbose)
        if verbose:
            print('vertex:\n{}\nedges\n{}\npins\n{}'.format(xv,xe,xp))
        return xv, xe, xp
    def forward_mapping(self, hg, xv, xe, xp, verbose=False):
        xg = None
        if self.ngf>0:
            xgf = self.xgr(xv, xe, hg, verbose)
            if verbose:
                print('xgf:\n{}'.format(xgf))
            if self.gmodel is not None:
                xg = self.gmodel(xgf)
            else:
                xg = xgf
        if self.vtxmodel is not None:
            x = xv
            if self.v_use_g:
                xgfv = self.vexpand_xgr(xgf, hg)
                x = torch.cat([x, xgfv], dim=1)
            xv = self.vtxmodel(x)
        if self.edgmodel is not None:
            x = xe
            if self.e_use_g:
                xgfe = self.eexpand_xgr(xgf, hg)
                x = torch.cat([x, xgfe], dim=1)
            xe = self.edgmodel(x)
        if self.pinmodel is not None:
            x = xp
            if self.p_use_g:
                xgfp = self.pexpand_xgr(xgf, hg)
                x = torch.cat([x, xgfp], dim=1)
            xp = self.pinmodel(x)
        return xv, xe, xp, xg
    def forward(self, hg, verbose=False):
        xv, xe, xp = self.forward_hg_only(hg, verbose)
        xv, xe, xp, xg = self.forward_mapping(hg, xv, xe, xp, verbose)
        if verbose:
            print('cls pred:\n', xv.size(), xe.size(), xg.size(), xp.size())
            print('cls pred:\n', xv, xe, xg, xp)
        if self.vepg_valid_ == 'vepg':
            return xv, xe, xp, xg
        elif self.vepg_valid_ == 'veg':
            return xv, xe, xg
        elif self.vepg_valid_ == 've':
            return xv, xe
        elif self.vepg_valid_ == 'vep':
            return xv, xe, xp
        elif self.vepg_valid_ == 'eg':
            return xe, xg
        elif self.vepg_valid_ == 'v':
            return xv
        elif self.vepg_valid_ == 'e':
            return xe
        elif self.vepg_valid_ == 'p':
            return xp
        elif self.vepg_valid_ == 'g':
            return xg
        else:
            assert 0, 'vepg_valid = {}'.format(self.vepg_valid_)
    def get_x(self, c, xss):
        if not isinstance(xss, list):
            assert self.check_active(c), 'vepg mismatch: {} ~ {}'.format(c, self.vepg_valid_)
            return xss
        for i in range(self.nout):
            if self.vepg_valid_[i]==c:
                return xss[i]
        assert 0, '{} is not active: {}'.format(c, self.vepg_valid_)

def make_hg_from_array(pins, pfs, vfs, efs, nv, ne, local=True):
    assert pins.ndim==1 and pfs.ndim==1 and vfs.ndim==1 and efs.ndim==1
    if pfs.size == 0:
        pfs = None
    if vfs.size == 0:
        vfs = None
    if efs.size == 0:
        efs = None
    # pin reshaping
    pins = pins.reshape(-1, 2)
    npin = pins.shape[0]
    pfs = pfs.reshape(npin, -1) if pfs is not None else None
    # vtx reshaping
    vfs = vfs.reshape(nv, -1) if vfs is not None else None
    # edge reshaping
    efs = efs.reshape(ne, -1) if efs is not None else None
    # local memory
    if local:
        pins = copy.deepcopy(pins)
        if pfs is not None:
            pfs = copy.deepcopy(pfs)
        if vfs is not None:
            vfs = copy.deepcopy(vfs)
        if efs is not None:
            efs = copy.deepcopy(efs)
    # to torch
    pins = torch.from_numpy(pins)
    if pfs is not None:
        pfs = torch.from_numpy(pfs)
    if vfs is not None:
        vfs = torch.from_numpy(vfs)
    if efs is not None:
        efs = torch.from_numpy(efs)
    hg = HYPERGRAPH(num_v=nv,
                    num_e=ne,
                    num_p=npin,
                    pins=pins,
                    vtx_feats=vfs,
                    edg_feats=efs,
                    pin_feats=pfs)
    return hg

