class EMBEDDING(nn.Embedding):
    def __init__(self, seed, n, ndim):
        torch.manual_seed(seed)
        super().__init__(n, ndim, _freeze=True)
        # freeze is added due to:
        # RuntimeError: Trying to backward through the graph a second time (or directly access saved tensors after they have already been freed).
DevEmbedding = EMBEDDING(9, 60, 8)
NodeEmbedding = EMBEDDING(99, 10, 8)
PinEmbedding = EMBEDDING(999, 99, 8)

def make_devhg_from_array(pins, pfs, dfs, nfs, ndev, nnode, name='', node_names=None):
    assert pins.ndim==1 and pfs.ndim==1 and dfs.ndim==1 and nfs.ndim==1
    # pin reshaping
    pins = pins.reshape(-1, 2)
    npin = pins.shape[0]
    pfs = pfs.reshape(npin, -1)
    npf = pfs.shape[1]
    pf = np.hstack((pins, pfs))
    # dev reshaping
    dfs = dfs.reshape(ndev, -1)
    ndf = dfs.shape[1]
    df = np.hstack((np.arange(ndev).reshape(ndev,-1), dfs))
    # node reshaping
    nfs = nfs.reshape(nnode, -1)
    nnf = nfs.shape[1]
    nf = np.hstack((np.arange(nnode).reshape(nnode,-1), nfs))
    devhg = DEVHG(df=df, nf=nf, pf=pf, use_flags=True, name=name, node_names=node_names)
    return devhg
class DEVHG(CACHE):
    NODE_LABELS = {'def': 0, 'port': 1, 'in': 2, 'out': 3, 'pwr': 4, 'bias': 5, 'ebl': 6}
    PIN_TYPE_GATE = [8, 61, 75]
    PIN_SENSITIVE = [0, 1, 7, 9, 74, 76]
    @staticmethod
    def ptype_to_wght(t):
        if t in DEVHG.PIN_SENSITIVE:
            return 0.9
        return 0.1
    def __init__(self, **kwargs):
        CACHE.__init__(self)
        self.init_empty_()
        if len(kwargs)==0:
            return
        if (sd:=kwargs.get('state_dict', None)) is not None:
            self.load_state_dict(sd)
            return
        df = kwargs.get('df', None)
        nf = kwargs.get('nf', None)
        pf = kwargs.get('pf', None)
        name = kwargs.get('name', '')
        nclsf = kwargs.get('nclsf', None)
        self.use_flags_ = kwargs.get('use_flags', False)
        self.port2node = kwargs.get('port2node', False)
        if isinstance(df, str):
            assert nf is not None and pf is not None
            self.load(df, nf, pf, nclsf)
        elif isinstance(df, (np.ndarray,np.generic)):
            self.name = name
            self.build_from_array(df, nf, pf)
        self.node_names = copy.deepcopy(kwargs.get('node_names', None))
    def init_empty_(self):
        self.name = None
        self.devs = None
        self.nodes = None
        self.pins = None
        self.dev_ebds = None
        self.node_ebds = None
        self.pin_ebds = None
        self.hg = None
        self.port_label_counts_ = None
        self.flag = None
        self.use_flags_ = False
        self.port2node = False
        self.node_names = None
    def state_dict(self):
        d = dict()
        d['name'] = self.name
        d['devs'] = self.devs
        d['nodes'] = self.nodes
        d['pins'] = self.pins
        d['flag'] = self.flag
        d['use_flags'] = self.use_flags_
        d['hg'] = self.hg.state_dict() if self.hg is not None else None
        return d
    def load_state_dict(self, d):
        self.name = d['name']
        self.devs = d['devs']
        self.nodes = d['nodes']
        self.pins = d['pins']
        self.flag = d['flag']
        self.use_flags_ = d['use_flags']
        if (hg:=d.get('hg', None)) is not None:
            self.hg = HYPERGRAPH(state_dict=hg)
        else:
            self.build_from_array(self.devs, self.nodes, self.pins)
    def node_index(self, name):
        assert self.node_names is not None
        if self.cache.get('NIM') is None:
            self.cache['NIM'] = {v: i for i,v in enumerate(self.node_names)}
        return self.cache['NIM'][name]
    def node_name(self, i):
        assert self.node_names is not None
        return self.node_names[i]
    @staticmethod
    def num_node_label():
        return len(DEVHG.NODE_LABELS)
    @staticmethod
    def _get_ndlabel_key(l):
        ks = [k for k,v in DEVHG.NODE_LABELS.items() if v==l]
        assert len(ks)==1, 'multiple keys found for {}: {}'.format(l,ks)
        return ks[0]
    @staticmethod
    def num_port_label():
        return len(DEVHG.NODE_LABELS) - 1
    @staticmethod
    def _get_ptlabel_key(l):
        return DEVHG._get_ndlabel_key(l+1)
    @property
    def port_label_counts(self):
        if self.port_label_counts_:
            return self.port_label_counts_
        r = [0] * self.num_port_label()
        for i in self.port_labels_:
            r[i] += 1
        return r
    @property
    def port_label_weights(self):
        c = self.port_label_counts
        n = self.num_port
        r = [1 if i==0 else n/i for i in c]
        return r
    def _load_pins(self, pf: str):
        ps = np.loadtxt(pf, dtype=int, ndmin=2)
        ph = get_header(pf)
        #if ph[0]=='edge_index':
            #ps[:,[0,1]] = ps[:,[1,0]]
        for h in ph:
            if h[0]=='type:':
                self.flag = int(h[1])
        return ps
    @staticmethod
    def _load_dn(fn: str):
        v = np.loadtxt(fn, dtype=int, ndmin=2)
        if v.ndim==1:
            v = v.reshape(-1,1)
        return v
    def _load_node_cls(self, fn, num):
        # as comments in header
        ptcls = {}
        self.label = np.zeros(num)
        self.node_names = [''] * num
        with open(fn) as fp:
            for line in fp.readlines():
                line = line.lower()
                if line=='# id name':
                    continue
                elif line.startswith('#'):
                    if ':' not in line:
                        continue
                    l2 = line.split(':')
                    key = l2[0].split()[1]
                    if key not in DEVHG.NODE_LABELS.keys():
                        print('WARN: key {} from {} not found.'.format(key, fn))
                        continue
                    lb = DEVHG.NODE_LABELS[key]
                    nds = l2[1].split()
                    ptcls[key] = nds
                else:
                    l = line.split()
                    nid = int(l[0])
                    nm = l[1]
                    self.node_names[nid] = nm
                    if nm not in ptcls['port']:
                        continue
                    self.label[nid] = DEVHG.NODE_LABELS['port']
                    for k,v in ptcls.items():
                        if k=='port':
                            continue
                        if nm not in v:
                            continue
                        self.label[nid] = DEVHG.NODE_LABELS[k]
        self.port_mask = self.label > 0
        #self.port_labels = nn.functional.one_hot(torch.from_numpy(self.label[self.port_mask]).type(torch.int64)-1, num_classes=2)
        self.port_labels_ = torch.from_numpy(self.label[self.port_mask]).type(torch.int64)-1
        print('  {}: {} ports, {} nodes.'.format(fn, len(ptcls['port']), num))
    @property
    def num_pin(self):
        return self.hg.num_p
    @property
    def num_dev(self):
        return self.hg.num_v
    @property
    def num_node(self):
        return self.hg.num_e
    @property
    def num_port(self):
        return self.port_mask.sum()
    def load(self, df, nf, pf, nclsf=None):
        #if not (df or nf or pf):
            #self.init_empty_()
        self.name = nf
        v = self._load_dn(df)
        e = self._load_dn(nf)
        p = self._load_pins(pf)
        self.build_from_array(v, e, p)
        if nclsf is not None:
            self._load_node_cls(nclsf, self.hg.num_e)
    def build_from_array(self, v, e, p):
        self.devs = v
        self.nodes = e
        self.pins = p
        num_v = v.shape[0]
        num_e = e.shape[0]
        num_p = p.shape[0]
        if v.shape[1]>1:
            #assert v.shape[1]==2, 'only type is dealt with.'
            self.dev_ebds = DevEmbedding
        if not self.use_flags_ and e.shape[1]>1:
            #assert e.shape[1]==2, 'only type is dealt with.'
            self.node_ebds = NodeEmbedding
        if p.shape[1]>2:
            #assert p.shape[1]==3, 'only type is dealt with.'
            self.pin_ebds = PinEmbedding
        ps = torch.from_numpy(p[:,0:2])
        self.hg = HYPERGRAPH(num_v=num_v,
                             num_e=num_e,
                             num_p=num_p,
                             pins=ps,
                             vtx_feats=self.dev_feats,
                             edg_feats=self.node_feats,
                             pin_feats=self.pin_feats)
    @property
    def dev_feats(self):
        if self.dev_ebds is None:
            return None
        tps = torch.from_numpy(self.devs[:,1])
        return self.dev_ebds(tps)
    @property
    def node_feats(self):
        if self.node_ebds is None:
            return None
        tps = torch.from_numpy(self.nodes[:,1])
        nfs = self.node_ebds(tps)
        if self.port2node:
            nlbs = self.label != 0
            nfs = torch.cat([nfs, nlbs.type(float)],dim=1)
        return nfs
    @property
    def pin_feats(self):
        if self.pin_ebds is None:
            return None
        tps = torch.from_numpy(self.pins[:,2])
        return self.pin_ebds(tps)
    @property
    def gate_pins(self):
        if self.cache.get('PGT') is None:
            msk = [v in DEVHG.PIN_TYPE_GATE for v in self.pins[:,2]]
            msk = np.asarray(msk, dtype=bool)
            self.cache['PGT'] = np.arange(self.num_pin)[msk]
        return self.cache['PGT']
    @property
    def gate_nodes(self):
        if self.cache.get('NGT') is None:
            pids = self.gate_pins
            eids = self.hg.pine(pids).detach().cpu().numpy()
            eids = np.unique(eids)
            self.cache['NGT'] = eids
        return self.cache['NGT']
    @property
    def has_flag(self):
        return self.flag is not None
    @property
    def has_devflag(self):
        if not self.use_flags_:
            return False
        if self.devs.shape[1] < 3:
            return False
        return True
    @property
    def dev_flags(self):
        if not self.has_devflag:
            return None
        return self.devs[:,2]
    @property
    def has_nodeflag(self):
        if not self.use_flags_:
            return False
        if self.nodes.shape[1] < 2:
            return False
        return True
    @property
    def node_flags(self):
        if not self.has_nodeflag:
            return False
        return self.nodes[:,1]
    @property
    def pin_flags(self):
        assert self.pins.shape[1]>2
        return self.pins[:,2]
    def pin_efactor(self, idx=None):
        if self.cache.get('PEF') is None:
            f = np.zeros(self.num_pin)
            epins = self.hg.epins
            pf = self.pin_flags
            for eps in epins:
                pw = [self.ptype_to_wght(pf[i]) for i in eps]
                pw = normalize(pw)
                f[eps] = pw
            self.cache['PEF'] = f
        if idx is None:
            return self.cache['PEF']
        else:
            return self.cache['PEF'][idx]
    def loss(self, pred, l=''):
        p = pred[self.port_mask]
        if l=='ce' or (l=='' and p.ndim==2 and p.size(1)>1):
            #return nn.functional.cross_entropy(p, self.port_labels(), weight=torch.tensor([0.2,0.8]))
            return nn.functional.cross_entropy(p, self.port_labels())
        elif l=='bce':
            r = self.port_labels('multi')
            w = torch.tensor(self.port_label_weights)
            return nn.functional.binary_cross_entropy(p, r.type(torch.float), weight=w)
        elif l=='bce' or (l=='' and p.ndim==1 or p.size(1)==1):
            p = p.flatten()
            w = torch.zeros(p.size(), device=self.device)
            w[self.port_labels()==1] = 0.8
            w[self.port_labels()==0] = 0.2
            return nn.functional.binary_cross_entropy(p, self.port_labels().type(torch.float), weight=w)
        else:
            assert 0
    def port_labels(self, mode='single'):
        if mode=='single':
            return self.port_labels_
        else:
            return nn.functional.one_hot(self.port_labels_, num_classes=self.num_port_label())
    def port_label_names(self, p, mode='multi'):
        if mode=='multi':
            nms = list(DEVHG.NODE_LABELS.keys())
            return nms[1:]
        lbs = list(set(self.port_labels().tolist() + p.tolist()))
        lbs.sort()
        tnms = [DEVHG._get_ptlabel_key(l) for l in lbs]
        return tnms
    @staticmethod
    def _pred_to_label(p,mode='multi',c=0.5):
        if mode=='single':
            if p.ndim==1 or p.size(1)==1:
                return p.flatten() > c
            return p.argmax(dim=1)
        elif mode=='multi':
            p = p > c
            if p.ndim==1 or p.size(1)==1:
                p = nn.functional.one_hot(p.flatten(), num_classes=2)
            return p
        else:
            assert 0
    def accuracy(self, pred):
        p = pred[self.port_mask]
        p = self._pred_to_label(p)
        acc = (p==self.port_labels()).sum() / p.size(0)
        return acc.item()
    def f1(self, pred, mode='multi'):
        p = pred[self.port_mask]
        p = self._pred_to_label(p,mode)
        r = self.port_labels(mode)
        f = f1_score(r, p, average=None, zero_division=np.nan)
        c = self.port_label_counts
        for i in range(self.num_port_label()):
            if np.isnan(f[i]) and c[i]!=0:
                f[i] = 0
        return f
    def cls_report(self, pred, mode='multi'):
        p = pred[self.port_mask]
        p = self._pred_to_label(p, mode)
        tnms = self.port_label_names(p, mode)
        r = classification_report(self.port_labels(mode), p, target_names=tnms, zero_division=np.nan)
        return r
    def print_pred(self, pred, c=0.25, portonly=False):
        raw = c==0 or pred.ndim==1 or pred.size(1)==1
        for nm, p, lref in zip(self.node_names, pred, self.label):
            if portonly and lref==0:
                continue
            if raw:
                print('  {:<30s}, {}: {}'.format(nm, lref, p.data.numpy()))
            else:
                lbps = [(self._get_ptlabel_key(i), round(p[i].item(),2)) for i in range(p.size(0)) if p[i]>c]
                print('  {:<30s}, {}: {}'.format(nm, self._get_ndlabel_key(lref), lbps))

class DEVHGS(CACHE):
    # nodes, bool
    ND_FLG_PORT = 1
    ND_FLG_NOCUT = 2
    NODE_LBL_NMS = ['port', 'nocut']
    NODE_LBL_LIST = [ND_FLG_PORT, ND_FLG_NOCUT]
    # part int
    PART_FLG_ANALOG = 1
    PART_LBL_NMS = ['digital', 'analog']
    PART_LBL_LIST = [0, PART_FLG_ANALOG]
    # dev int
    DEV_FLG_DIFFAMP = 3
    DEV_LBL_NMS = ['default', 'diffamp']
    DEV_LBL_LIST = [0, DEV_FLG_DIFFAMP]
    def __init__(self, dhgs):
        CACHE.__init__(self)
        self.hgs = HYPERGRAPHS()
        self.dhgs = None
        self.devflgs = None
        self.nodeflgs = None
        self.pinflgs = None
        self.build(dhgs)
    def build(self, dhgs):
        self.dhgs = dhgs
        self.hgs.assemble([dhg.hg for dhg in dhgs])
        if self.has_devflag:
            dflgs = [dh.dev_flags for dh in dhgs]
            self.devflgs = np.hstack(dflgs)
        if self.has_nodeflag:
            nflgs = [dh.node_flags for dh in dhgs]
            self.nodeflgs = np.hstack(nflgs)
        pflgs = [dh.pin_flags for dh in dhgs]
        self.pinflgs = np.hstack(pflgs)
        if self.has_partflag:
            flgs = [dh.flag for dh in dhgs]
            self.partflgs = np.asarray(flgs)
    @property
    def hg(self):
        return self.hgs
    def num_part(self, f=-1):
        if f<0:
            return self.hgs.num
        if not self.has_partflag:
            return 0
        flg = self.PART_LBL_LIST[f]
        m = self.partflgs == flg
        return m.sum()
    def num_dev(self, f=-1):
        if f<0:
            return self.hgs.num_v
        if not self.has_devflag:
            return 0
        flg = self.DEV_LBL_LIST[f]
        m = self.devflgs == flg
        return m.sum()
    def num_node(self, f=-1):
        if f<0:
            return self.hgs.num_e
        if not self.has_nodeflag:
            return 0
        flg = self.NODE_LBL_LIST[f]
        m = self.nodeflgs & flg != 0
        return m.sum()
    @property
    def has_devflag(self):
        if self.devflgs is not None:
            return True
        if self.dhgs[0].has_devflag:
            return True
        return False
    @property
    def has_nodeflag(self):
        if self.nodeflgs is not None:
            return True
        if self.dhgs[0].has_nodeflag:
            return True
        return False
    def has_partflag(self):
        if self.partflgs is not None:
            return True
        return self.dhgs[0].has_flag
    @property
    def node_active_msk(self):
        if self.cache.get('NAM') is None:
            self.cache['NAM'] = self.nodeflgs&DEVHGS.ND_FLG_PORT != 0
        return self.cache['NAM']
    @property
    def node_active_flgs(self):
        if self.cache.get('NAF') is None:
            self.cache['NAF'] = self.nodeflgs[self.node_active_msk]
        return self.cache['NAF']
    @property
    def node_active_idxs(self):
        if self.cache.get('NAI') is None:
            idxs = np.arange(self.hgs.num_e)
            self.cache['NAI'] = idxs[self.node_active_msk]
        return self.cache['NAI']
    @property
    def node_active_num(self):
        if self.cache.get('NAN') is None:
            self.cache['NAN'] = sum(self.node_active_msk)
        return self.cache['NAN']
    @property
    def node_labels(self):
        if self.cache.get('NF') is None:
            flgs = self.nodeflgs[self.node_active_msk]&DEVHGS.ND_FLG_NOCUT != 0
            #flgs = np.functional.one_hot(flgs, num_classes=2)
            self.cache['NF'] = torch.as_tensor(flgs,dtype=torch.float)
        return self.cache['NF']
    @property
    def dev_labels(self):
        if self.cache.get('DF') is None:
            flgs = self.devflgs==DEVHGS.DEV_FLG_DIFFAMP
            #flgs = np.functional.one_hot(flgs, num_classes=2)
            self.cache['DF'] = torch.as_tensor(flgs,dtype=torch.float)
        return self.cache['DF']
    @property
    def part_labels(self):
        if self.cache.get('PF') is None:
            flgs = self.partflgs==DEVHGS.PART_FLG_ANALOG
            #flgs = np.functional.one_hot(flgs, num_classes=2)
            self.cache['PF'] = torch.as_tensor(flgs,dtype=torch.float)
        return self.cache['PF']
    @staticmethod
    def _cal_loss_wghts(f):
        f = f.flatten()
        n = f.nelement()
        npos = f.sum()
        nneg = n - npos
        w = torch.zeros(n)
        w[f] = n / npos
        w[~f] = n/nneg
        return w
    @staticmethod
    def _cal_loss_wghts_binary(f):
        n = f.nelement()
        npos = f.sum()
        nneg = n - npos
        w = torch.asarray([n/nneg, n/npos])
        return w
    @property
    def dev_loss_wghts(self):
        if self.cache.get('DLW') is None:
            f = self.dev_labels != 0
            w = self._cal_loss_wghts(f)
            self.cache['DLW'] = w
        return self.cache['DLW']
    @property
    def node_loss_wghts(self):
        if self.cache.get('NLW') is None:
            f = self.node_labels != 0
            w = self._cal_loss_wghts(f)
            self.cache['NLW'] = w
        return self.cache['NLW']
    @property
    def part_loss_wghts(self):
        if self.cache.get('PLW') is None:
            f = self.part_labels != 0
            w = self._cal_loss_wghts(f)
            self.cache['PLW'] = w
        return self.cache['PLW']
    def loss_dev(self, pred):
        if pred.ndim==2 and pred.shape[1]==1:
            pred = pred.flatten()
        return nn.functional.binary_cross_entropy(pred, self.dev_labels, self.dev_loss_wghts)
    def loss_node(self, pred):
        if pred.ndim==2 and pred.shape[1]==1:
            pred = pred.flatten()
        pred = pred[self.node_active_msk]
        return nn.functional.binary_cross_entropy(pred, self.node_labels, self.node_loss_wghts)
    def loss_part(self, pred):
        if pred.ndim==2 and pred.shape[1]==1:
            pred = pred.flatten()
        return nn.functional.binary_cross_entropy(pred, self.part_labels, self.part_loss_wghts)
    def _loss(self, dev=None, node=None, part=None):
        l = 0
        if dev is not None:
            l += self.loss_dev(dev)
        if node is not None:
            l += self.loss_node(node)
        if part is not None:
            l += self.loss_part(part)
        return l
    def loss(self, preds):
        assert len(preds)==3
        return self._loss(preds[0], preds[1], preds[2])
    def f1_dev(self, pred, c=0.5):
        if pred.ndim==2 and pred.shape[1]==1:
            pred = pred.flatten()
        pl = pred > c
        f = f1_score(self.dev_labels, pl, average='binary', zero_division=np.nan)
        return f
    def f1_node(self, pred, c=0.5):
        if pred.ndim==2 and pred.shape[1]==1:
            pred = pred.flatten()
        pred = pred[self.node_active_msk]
        pl = pred > c
        f = f1_score(self.node_labels, pl, average='binary', zero_division=np.nan)
        return f
    def f1_part(self, pred, c=0.5):
        if pred.ndim==2 and pred.shape[1]==1:
            pred = pred.flatten()
        pl = pred > c
        f = f1_score(self.part_labels, pl, average='binary', zero_division=np.nan)
        return f
    def _f1(self, dev, node, part, c=0.5):
        f1s = [None] * 3
        if dev is not None:
            f1s[0] = self.f1_dev(dev, c)
        if node is not None:
            f1s[1] = self.f1_node(node, c)
        if part is not None:
            f1s[2] = self.f1_part(part, c)
        return f1s
    def f1(self, preds, c=0.5):
        assert len(preds)==3
        return self._f1(preds[0], preds[1], preds[2], c)
    def cls_report_dev(self, pred, c=0.5):
        if pred.ndim==2 and pred.shape[1]==1:
            pred = pred.flatten()
        pl = pred > c
        pl[0] = 1
        r = classification_report(self.dev_labels, pl, labels=np.arange(len(DEVHGS.DEV_LBL_NMS)), target_names=DEVHGS.DEV_LBL_NMS, zero_division=np.nan)
        return r
    def cls_report_node(self, pred, c=0.5):
        if pred.ndim==2 and pred.shape[1]==1:
            pred = pred.flatten()
        pred = pred[self.node_active_msk]
        pl = pred > c
        r = classification_report(self.node_labels, pl, labels=np.arange(len(DEVHGS.NODE_LBL_NMS)), target_names=DEVHGS.NODE_LBL_NMS, zero_division=np.nan)
        return r
    def cls_report_part(self, pred, c=0.5):
        if pred.ndim==2 and pred.shape[1]==1:
            pred = pred.flatten()
        pl = pred > c
        r = classification_report(self.part_labels, pl, labels=np.arange(len(DEVHGS.PART_LBL_NMS)), target_names=DEVHGS.PART_LBL_NMS, zero_division=np.nan)
        return r
    def _cls_report(self, dev, node, part, c=0.5):
        r = []
        if dev is not None:
            r.append(self.cls_report_dev(dev, c))
        if node is not None:
            r.append(self.cls_report_node(node, c))
        if part is not None:
            r.append(self.cls_report_part(part, c))
        return r
    def cls_report(self, preds, c=0.5):
        assert len(preds)==3
        return self._cls_report(preds[0], preds[1], preds[2], c)
    def print_info(self):
        print('\t{} part ({},{}), {} dev ({},{}), {} node ({},{}), {} pin.'.format(self.num_part(), self.num_part(0), self.num_part(1), self.num_dev(), self.num_dev(0), self.num_dev(1), self.num_node(), self.num_node(0), self.num_node(1), self.hgs.num_p))
        print('\t  nvf={}, nef={}, npf={}'.format(self.hg.num_vfeat, self.hg.num_efeat, self.hg.num_pfeat))

class SAMPLER:
    def __init__(self, dhgs):
        self.dhgs_ = dhgs
        self._ana_prob()
    def dhgs(self):
        return self.dhgs_
    def dhg(self, i):
        return self.dhgs_[i]
    def _ana_prob(self):
        def _ana_func(flags, tflg):
            flags = np.asarray(flags)
            msk = flags == tflg
            v, c = np.unique(msk, return_counts=True)
            assert len(v)==2 and v[0]==0 and v[1]==1
            vcs = ', '.join(['{}:{}'.format(vv,cc) for vv, cc in zip(v,c)])
            ppos = 0.5/c[1]
            pneg = 0.5/c[0]
            self.prob_[msk] += ppos
            self.prob_[~msk] += pneg
            return vcs
        dhgs = self.dhgs()
        self.prob_ = np.zeros(len(dhgs), dtype=float)
        # part flag
        assert dhgs[0].has_flag
        flags = [dhg.flag for dhg in dhgs]
        vcs = _ana_func(flags, DEVHGS.PART_FLG_ANALOG)
        print('\tpart flag:cnts: {}'.format(vcs))
        renormalize = False
        # dev flag
        if dhgs[0].has_devflag:
            flags = [np.any(dhg.dev_flags==DEVHGS.DEV_FLG_DIFFAMP) for dhg in dhgs]
            vcs = _ana_func(flags, 1)
            print('\tdev flag:cnts: {}'.format(vcs))
            renormalize = True
        # node flag
        if dhgs[0].has_nodeflag:
            flags = [np.any(dhg.node_flags&DEVHGS.ND_FLG_NOCUT != 0) for dhg in dhgs]
            vcs = _ana_func(flags, 1)
            print('\tnode flag:cnts: {}'.format(vcs))
            renormalize = True
        # normalize
        if renormalize:
            self.prob_ /= self.prob_.sum()
    def gen_sample(self, size):
        sidxs = np.random.choice(len(self.dhgs()), size, True, self.prob_)
        dhgs = [self.dhg(i) for i in sidxs]
        dhgsample = DEVHGS(dhgs)
        return dhgsample

class CKTHG_UTIL:
    def __init__(self, hg):
        #self.cut_eids_ = None
        #self.cut_pids_ = None
        #self.cls_cache_ = None
        # fake clusters for consistency, mainly due to single-v edge
        ncls = hg.num_v
        cls = np.arange(hg.num_v)
        self.cache_cls(ncls, cls)
    @property
    def cls_cache(self):
        return self.cls_cache_
    def ptcid(self, i):
        if self.cls_cache is None:
            return -1
        return self.cls_cache[i]
    def grad_x(self, x, config):
        grad = np.empty_like(x)
        msk = x != 0
        if not np.any(msk):
            grad.fill(1e3)
            print('grad: No event. All grad assigned with 1e3.')
            return torch.from_numpy(grad).to(self.device)
        nnz = msk.sum()
        nz = msk.size - nnz
        if (rnzb:=config.get('grad_nzblnc',0)) and nz < nnz * rnzb:
            xave = x.mean()
            msk = x >= xave
            nnz = msk.sum()
            nz = msk.size - nnz
        if config.get('grad_sq', 0):
            x = np.square(x[msk])
        x = x[msk]
        if (m:=config.get('grad_max', 0)):
            if (xm:=x.max()) > m:
                x *= m/xm
        grad[msk] = -x
        if nz>0:
            tgave = x.sum() / nz
            grad[~msk] = tgave
        print_array_hist('grad', grad, bins=[-1e6, -1000, -100, -10, -1, 0, 1, 10, 100, 1000, 1e6])
        return torch.from_numpy(grad).to(self.device)
    def num_cut(self):
        return len(self.cut_eids_)
    def cut_eid(self, i):
        if self.cut_eids_ is None or self.no_cut():
            return i
        return self.cut_eids_[i]
    def cut_pid(self, i):
        if self.cut_pids_ is None or self.no_cut():
            return i
        return self.cut_pids_[i]
    def active_pid(self, i):
        return self.active_pids_[i]
    def cut_degree(self, lid):
        return self.cut_degrees_[lid]
    def _cut_epins(self):
        pins = [self.hg.epins[i] for i in self.cut_eids_]
        return pins
    def _cut_pins(self):
        cpins = self._cut_epins()
        pidx = [p for pp in cpins for p in pp]
        return pidx
    def _cut_edge_msk(self):
        res = np.zeros(self.hg.num_e, dtype=bool)
        res[self.cut_eids_] = 1
        return res
    def _cut_pin_msk(self):
        res = np.zeros(self.hg.num_p, dtype=bool)
        res[self._cut_pins()] = 1
        return res
    def no_cut(self):
        if self.cut_eids_ is None:
            return 0
        return len(self.cut_eids_)==0
    def select_by_cut_pins(self, x):
        if self.cls_cache is None or self.no_cut():
            return x
        return x[self.cut_pin_msk_]
    def select_by_cut_edgs(self, x):
        if self.cls_cache is None or self.no_cut():
            return x
        return x[self.cut_eids_]
    def select_by_active_pins(self, x):
        return x[self.active_pin_msk_]
    def select_by_active_edgs(self, x):
        return x[self.active_edg_msk_]
    def assemble_p2ce(self, pval, aggr='max'):
        r = self.hg.p2e(pval, aggr=aggr)
        if self.cls_cache is None or self.no_cut():
            return r
        return r[self.cut_eids_]
    def cache_cls(self, ncls, cls, pwghts=None):
        self.num_cls = ncls
        self.cls_cache_ = cls
        self.cut_eids_ = self.hg.get_cut_eids(cls)
        self.cut_edg_msk_ = cmsk = self._cut_edge_msk()
        self.cut_degrees_ = self.hg.get_cut_degrees(cls)
        self.cut_pin_msk_ = cmsk = self._cut_pin_msk()
        self.cut_pids_ = np.arange(self.hg.num_p)[self.cut_pin_msk_]
        print_array_hist('  cut degrees', self.cut_degrees_, bins=[1, 2, 5, 10, 20, 50, 100, 200, 500, 1000, 1e6])
        if np.all(cmsk):
            print('!! all nodes cut.')
        elif not np.any(cmsk):
            cvals, cnts = np.unique(cls, return_counts=True)
            print('!! No edge cut... Independently {} clusters.'.format(len(cnts)))
            print_array_hist('  #vtxs', cnts, bins=[1,2,5,10,50,100,1000,10000,100000])
        else:
            cmsk1 = cmsk.copy()
            if pwghts is None:
                return
            print_array_hist('  cut pin wghts', pwghts[cmsk1], bins=WBINS)
            cmsk1[self.hg.e1v_pins] = 1
            print_array_hist('  noncutp wghts', pwghts[~cmsk1], bins=WBINS)
            print_array_hist('  e1v pin wghts', pwghts[self.hg.e1v_pins], bins=WBINS)
            print_array_hist('  e1d pin wghts', pwghts[self.hg.e1d_pins], bins=WBINS)
    def update_active_msk(self, lstats, pstats):
        eids = np.arange(self.hg.num_e)[lstats != 0]
        pids = [self.hg.epins[i] for i in eids]
        pids = list(chain.from_iterable(pids))
        pmsk_nz_l = np.zeros(self.hg.num_p, dtype=bool)
        pmsk_nz_l[pids] = 1
        pmsk_z_p = pstats==0
        pskip = np.logical_and(pmsk_nz_l, pmsk_z_p)
        pmsk = copy.deepcopy(self.cut_pin_msk_)
        pmsk[pskip] = 0
        self.active_edg_msk_ = self.cut_edg_msk_
        self.active_pin_msk_ = pmsk
        self.active_pids_ = np.arange(self.hg.num_p)[pmsk]
    def update_active_msk_refvals(self, lstats, pstats, x, refmin=0.5, refmax=0.5, mesg=''):
        if isinstance(x, torch.Tensor):
            x = x.detach().cpu().numpy().flatten()
        self.update_active_msk(lstats, pstats)
        viomin = np.all([pstats==0, x>refmin, self.active_pin_msk_], axis=0)
        viomax = np.all([pstats>0, x<refmax, self.active_pin_msk_], axis=0)
        vio = np.logical_or(viomin, viomax)
        self.active_pin_msk_ = vio
        self.active_pids_ = np.arange(self.hg.num_p)[vio]
        if mesg:
            print(' {} Updated active: {} min violation, {} max violation.'.format(mesg, np.sum(viomin), np.sum(viomax)))

class SUBCKT_HGRAPH(CACHE, CKTHG_UTIL):
    MAP_PT = 0
    MAP_TOP = 1
    def __init__(self, **kwargs):
        CACHE.__init__(self)
        self._init_empty()
        if (sd:=kwargs.get('state_dict', None)) is not None:
            self.load_state_dict(sd)
            self.print_info()
            return
        hg = kwargs.get('tophg', None)
        hgs = kwargs.get('pthgs', None)
        idxmaps = kwargs.get('idxmaps', None)
        assert hg is not None and hgs is not None, 'tophg and pthgs must be provided'
        self.top_hg_ = hg
        CKTHG_UTIL.__init__(self, hg)
        self.batch_size_ = kwargs.get('batch_size', 100000)
        assert len(hgs)==len(idxmaps)
        self.pthgs_ = hgs
        self.idxmaps_ = copy.deepcopy(idxmaps)
        self.id_ = kwargs.get('sid', 0)
        self._set_names(kwargs.get('name', ''))
        assert len(self.idxmaps_)==len(self.pthgs_) and len(self.pthgs_)==self.top_hg_.num_v
        self.print_info()
    def _init_empty(self):
        #self.training_ = True
        self.idxmaps_ = None
        self.id_ = 0
        self.name_ = ''
        self.lnames_ = None
        self.top_hg_ = None
        self.pthgs_ = None
        self.x_cache = None
        self.batch_size_ = 100000
        self.device = torch.device('cpu')
    def to(self, device: torch.device):
        self.device = device
        self.hg.to(device)
        for ptdhg in self.pthgs_:
            ptdhg.hg.to(device)
    def _set_names(self, names):
        if isinstance(names, str):
            self.name_ = names
            self.lnames_ = None
        else:
            assert isinstance(names, (list,tuple)), '{}'.format(names)
            self.name_ = names[0]
            self.lnames_ = names[1]
            assert len(self.lnames_)==self.num_link, '{} != {}, {}'.format(len(self.lnames_), self.num_link, self.lnames_)
    def state_dict(self):
        d = dict()
        d['idxmaps'] = self.idxmaps_
        d['id'] = self.id_
        d['name'] = self.name_
        d['lnames'] = self.lnames_
        d['tophg'] = self.top_hg_.state_dict()
        d['pthgs'] = [dhg.state_dict() for dhg in self.pthgs_]
        d['num_cls'] = self.num_cls
        d['cids'] = self.cls_cache
        return d
    def load_state_dict(self, d):
        self.idxmaps_ = d['idxmaps']
        self.id_ = d['id']
        self.name_ = d['name']
        self.lnames_ = d['lnames']
        self.top_hg_ = HYPERGRAPH(state_dict=d['tophg'])
        self.pthgs_ = [DEVHG(state_dict=sd) for sd in d['pthgs']]
        if (ncls:=d['num_cls'])>0:
            self.cache_cls(ncls, d['cids'], None)
    @property
    def hg(self):
        return self.top_hg_
    @property
    def hg0(self):
        return self.pthgs_[0].hg
    @property
    def name(self):
        return self.name_
    def lname(self, i):
        if self.lnames_ is None:
            return ''
        return self.lnames_[i]
    @property
    def id(self):
        return self.id_
    def print_info(self):
        print("Sckt {}: {} parts, {} links, {} ports, {} ptdevs, {} ptnodes, {} ptpins.".format(self.name, self.num_part, self.num_link, self.num_port, self.num_dev, self.num_node, self.num_pin))
        self.top_hg_.print_info()
    #def train(self):
        #self.training_ = True
    #def eval(self):
        #self.training_ = False
    @property
    def num_part(self):
        return len(self.pthgs_) # ==self.top_hg_.num_v
    @property
    def num_link(self):
        return self.top_hg_.num_e
    @property
    def num_port(self):
        return self.top_hg_.num_p
    @property
    def num_dev(self):
        if self.cache.get('ND') is None:
            ndev = 0
            for hg in self.pthgs_:
                ndev += hg.num_dev
            self.cache['ND'] = ndev
        return self.cache['ND']
    @property
    def num_node(self):
        if self.cache.get('NN') is None:
            n = 0
            for hg in self.pthgs_:
                n += hg.num_node
            self.cache['NN'] = n
        return self.cache['NN']
    @property
    def num_pin(self):
        if self.cache.get('NP') is None:
            n = 0
            for hg in self.pthgs_:
                n += hg.num_pin
            self.cache['NP'] = n
        return self.cache['NP']
    @property
    def pt_ndevs(self):
        if self.cache.get('PTND') is None:
            r = [pt.num_dev for pt in self.pthgs_]
            r = np.asarray(r)
            self.cache['PTND'] = r
        return self.cache['PTND']
    def num_ptdev(self, i):
        return self.pthgs_[i].num_dev
    def num_ptnode(self, i):
        return self.pthgs_[i].num_node
    def num_ptpin(self, i):
        return self.pthgs_[i].num_pin
    def node_sid(self, ipt):
        sids = self.cache.get('SIDN')
        if sids is None:
            cnt = 0
            sids = [0]*self.num_part
            for i in range(self.num_part):
                sids[i] = cnt
                cnt += self.num_ptnode(i)
            self.cache['SIDN'] = sids
        return sids[ipt]
    @staticmethod
    def _call_dngflag_model(model, hgs):
        hgs = HYPERGRAPHS(hgs=hgs)
        xv, xe, xg = model(hgs.hgs, verbose=False)
        xv = xv.detach().cpu().numpy()
        xe = xe.detach().cpu().numpy()
        xg = xg.detach().cpu().numpy()
        xv = xv.squeeze(axis=1).astype(int)
        xe = xe.squeeze(axis=1).astype(int)
        xg = xg.squeeze().astype(int)
        return xv, xe, xg
    def run_dngflag_model(self, model):
        if self.num_dev < self.batch_size_:
            xv, xe, xg = self._call_dngflag_model(model, [dhg.hg for dhg in self.pthgs_])
        else:
            cnt = 0
            xvs = []
            xes = []
            xgs = []
            while cnt < len(self.pthgs_):
                size = 0
                hgs = []
                while size < self.batch_size_ and cnt < len(self.pthgs_):
                    hgs.append(self.pthgs_[cnt].hg)
                    size += self.pthgs_[cnt].num_dev
                    cnt += 1
                xv, xe, xg = self._call_dngflag_model(model, hgs)
                xvs.append(xv)
                xes.append(xe)
                xgs.append(xg)
            xv = np.hstack(xvs)
            xe = np.hstack(xes)
            xg = np.hstack(xgs)
        return xv, xe, xg
    @staticmethod
    def _call_model(model, hgs):
        hgs = HYPERGRAPHS(hgs=hgs)
        xs = model(hgs, verbose=False)
        assert isinstance(xs, torch.Tensor) or len(xs)==model.nout
        if model.nout==1:
            if xs.ndim > 1 and xs.size(1)==1:
                assert xs.ndim==2
                xs = xs.squeeze(1)
            return [xs]
        res = []
        for x in xs:
            assert x.ndim <= 2
            if x.ndim==2 and x.size(1)==1:
                x = x.squeeze(1)
            res.append(x)
        return res
    def _run_model_pt(self, model):
        #if self.training_:
            #model.train()
        #else:
            #model.eval()
        if self.num_dev < self.batch_size_:
            xss = self._call_model(model, [dhg.hg for dhg in self.pthgs_])
        else:
            cnt = 0
            xss = [[] for i in range(model.nout)]
            while cnt < len(self.pthgs_):
                size = 0
                hgs = []
                while size<self.batch_size_ and cnt < len(self.pthgs_):
                    hgs.append(self.pthgs_[cnt].hg)
                    size += self.pthgs_[cnt].num_dev
                    cnt += 1
                xs = self._call_model(model, hgs)
                for i in range(model.nout):
                    xss[i].append(xs[i])
            for i in range(model.nout):
                xss[i] = torch.cat(xss[i])
        if model.nout==1:
            return xss[0]
        else:
            return xss
    def run_models(self, topmodel, model, mode='l'):
        self.x_cache = None
        xss = self._run_model_pt(model)
        if topmodel is None:
            if mode=='l':
                assert model.check_active('e')
                xss = self._assemble_pin_from_ptxes(xss)
            return xss
        xe = model.get_x('e', xss)
        xg = model.get_x('g', xss)
        self.top_hg_.set_vtx_feats(xg)
        xl = self._assemble_pin_from_ptxes(xe)
        self.top_hg_.set_pin_feats(xl)
        xs = topmodel(self.top_hg_)
        self.x_cache = xs
        #print('run_models: {}\n{}'.format(xs.size(), xs), flush=1)
        return xs
    def inspect_models(self, topmodel, model, mode='l'):
        xss = self._run_model_pt(model)
        if topmodel is None:
            if mode=='l':
                assert model.check_active('e')
                xss = self._assemble_pin_from_ptxes(xss)
            return xss
        xe = model.get_x('e', xss)
        xg = model.get_x('g', xss)
        self.top_hg_.set_vtx_feats(xg)
        xl = self._assemble_pin_from_ptxes(xe)
        self.top_hg_.set_pin_feats(xl)
        xv1, xe1, xp1 = topmodel.forward_hg_only(self.top_hg_)
        xv2, xe2, xp2, _ = topmodel.forward_mapping(self.top_hg_, xv1, xe1, xp1)
        ptxe = []
        ptxg = []
        ecnt = 0
        for i in range(self.num_part):
            ptxe.append(xe[ecnt:ecnt+self.num_ptnode(i)])
            ptxg.append(xg[i])
            ecnt += self.num_ptnode(i)
        ptx = {'e':ptxe, 'g':ptxg}
        hgx = {'v':xv1, 'e':xe1, 'p':xp1}
        x = {'v':xv2, 'e':xe2, 'p':xp2}
        return ptx, hgx, x
    def _get_ptie(self, ipt, ie):
        imap = self.idxmaps_[ipt]
        ptie = imap[SUBCKT_HGRAPH.MAP_PT][np.argwhere(imap[SUBCKT_HGRAPH.MAP_TOP]==ie)[0]]
        return ptie
    def _assemble_pin_from_ptxes(self, xin):
        iout = np.empty(self.num_port, dtype=int)
        for i in range(self.num_port):
            iv, ie = self.top_hg_.pinve(i)
            ptie = self._get_ptie(iv, ie)
            sid = self.node_sid(iv)
            xid = sid + ptie
            iout[i] = xid
        return xin[iout]
    def _assemble_ptxes_from_pin(self, xin):
        iout = np.empty(self.num_node, dtype=int)
        if xin is None:
            return torch.zeros(self.num_node, device=self.device)
        for i in range(self.num_port):
            iv, ie = self.top_hg_.pinve(i)
            ptie = self._get_ptie(iv, ie)
            sid = self.node_sid(iv)
            xid = sid + ptie
            iout[xid] = i
        return xin[iout]
    #def _prepare_models(self, topmodel, model):
        #if topmodel is None:
            #model.set_active('e')
        #else:
            #model.set_active('eg')
            #topmodel.set_active('p')
    def cls_cache_str(self):
        if self.cls_cache is None or self.num_cls == self.num_part:
            return b"original"
        return self.cls_cache.tobytes()
    def run_clustering(self, topmodel, model, sim=None, config=None, use_cls_cache=True):
        timer = TIMER()
        timer.start()
        if use_cls_cache and self.cls_cache is not None:
            print('... using cached clusters')
            return self.cls_cache, None
        #self._prepare_models(topmodel, model)
        x = self.run_models(topmodel, model)
        pwghts = x.detach().cpu().numpy().flatten()
        if np.all(pwghts==0):
            print('!!! all wghts being zero, cannot continue...')
            sys.exit(0)
        print_array_hist('  clustering wghts', pwghts, bins=WBINS)
        if sim is None:
            rc = 0
            cls = self.top_hg_.clustering(pwghts)
        else:
            hg = self.top_hg_
            if config.get('cls_use_hg',False):
                hg.set_pin_wghts(pwghts)
                mode = 1 \
                        + (2 if config.get('cls_use_louvain', True) else 0) \
                        + (4 if config.get('cls_spmm', 'sum')=='max' else 0) \
                        + (8 if config.get('cls_hg_1all', 0) else 0)
                m = hg.num_v
                n = hg.num_e
                idxs = hg.idxs().detach().cpu().numpy()
                if (w:=config.get('min_conn'))>0:
                    pwghts[pwghts<w] = 0
                wghts = pwghts
            else: # old way
                mode = 2
                m = n = hg.num_v
                if (w:=config.get('min_conn'))>0:
                    pwghts[pwghts<w] = 0
                idxs, wghts = hg.gen_vtx_graph(pwghts)
                print_array_hist('  G conn vals', wghts, bins=WBINS)
            if config.get('max_dev')>0:
                ndevs = np.asarray(self.pt_ndevs, dtype='float64')
            else:
                ndevs = None
