    for i in N:
        fnn = fn + '.' + str(i) + '.devhg'
        if i%1000 == 0:
            print('+++ {}'.format(fnn))
        dhg = DEVHG(df=fnn+'.vtx', nf=fnn+'.edg', pf=fnn+'.pin', use_flags=True)
        dhgl.append(dhg)
    return dhgl
