def plot_glyph_with_curves(char, font_path, font_size=48):
    face = freetype.Face(font_path)
    face.set_char_size(font_size * 64)
    face.load_char(char)
    
    slot = face.glyph
    outline = slot.outline
    plt.figure(figsize=(10, 10))

    start, end = 0, 0
    points = []
    tags = []
    for i in range(len(outline.contours)):
        end = outline.contours[i]
        points.append(outline.points[start:end + 1])
        tags.append(outline.tags[start:end + 1])
        start = end + 1

    for contour, contour_tags in zip(points, tags):
        vertices = []
        codes = []
        prev_point = contour[0]
        for point, tag in zip(contour[1:], contour_tags[1:]):
            if tag & 1:  # On-curve point
                vertices.append(prev_point)
                codes.append(Path.LINETO)
                prev_point = point
            else:  # Off-curve point, quadratic Bezier curve's control point
                vertices.append(prev_point)
                codes.append(Path.CURVE3)
                vertices.append(point)
                codes.append(Path.CURVE3)
                prev_point = point

        vertices.append(prev_point)
        codes.append(Path.LINETO)
        vertices.append(contour[0])
        codes.append(Path.CLOSEPOLY)

        # Remove the first LINETO code and replace it with a MOVETO code
        codes[0] = Path.MOVETO

        # Scale the vertices
        units_per_pixel  = 1
        vertices = [(x / units_per_pixel , y / units_per_pixel ) for x, y in vertices]

        path = Path(vertices, codes)
        patch = patches.PathPatch(path, facecolor='none', lw=2)
        plt.gca().add_patch(patch)

        # Plot dots at vertices
        for vertex in vertices:
            plt.plot(vertex[0], vertex[1], 'ro', markersize=1)

    # Set plot limits
    plt.xlim(0, 4000 / units_per_pixel)
    plt.ylim(-1000 / units_per_pixel, 3000 / units_per_pixel)

    plt.gca().set_aspect('equal', adjustable='box')
    plt.show()




