import netifaces
import socket

def find_device_ip(device_port=80):
    """Scan the local network through physical Ethernet cable for a device on a given port"""
    interfaces = netifaces.interfaces()
    ethernet_interfaces = []

    # Filter only the interfaces that are connected via Ethernet
    for interface in interfaces:
        addrs = netifaces.ifaddresses(interface)
        if netifaces.AF_LINK in addrs:
            ethernet_interfaces.append(interface)

    # Scan the IP addresses of the Ethernet interfaces
    for interface in ethernet_interfaces:
        addresses = netifaces.ifaddresses(interface)
        if netifaces.AF_INET in addresses:
            ip_info = addresses[netifaces.AF_INET]
            for ip in ip_info:
                ip_address = ip['addr']
                print(f"Scanning {ip_address}", end="\r", flush=True)

                try:
                    # Try to open a socket to the IP address
                    sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                    sock.settimeout(0.05)  # Don't wait too long, we have many IPs to scan
                    result = sock.connect_ex((ip_address, device_port))

                    if result == 0:  # Success, something is open on the port
                        print(f"\nFound potential device at {ip_address}")
                        sock.close()

                except socket.error as ex:
                    pass  # We can't connect, likely nothing there
    print("\nScan completed.")

find_device_ip()
# End of [WEC-01_(IP scanner cGPT3-1).py]




