import numpy as np
import matplotlib.pyplot as plt
import pandas as pd
import pandoc
import plotly.express as px



def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n-1)

def lower_bound_stirling(n):
    """Return the lower bound of Stirling's approximation."""
    return round(np.sqrt(2 * np.pi * n) * (n / np.e) ** n, 2)

def upper_bound_stirling(n):
    """Return the upper bound of Stirling's approximation."""
    return round(np.sqrt(np.e ** 2 * n) * (n / np.e) ** n, 2)

print('4!=', factorial(4))
print('0!=', factorial(0))
print('8!=', factorial(8))

print('lower_bound_stirling(8)=', lower_bound_stirling(8))
print('upper_bound_stirling(8)=', upper_bound_stirling(8))



#[] Setting the values of n
max_n = 10
n_values = np.arange(1, max_n)

#[] Calculate factorial, lower and upper bounds for each n
factorial_values = [factorial(n) for n in n_values]
lower_bound_values = [lower_bound_stirling(n) for n in n_values]
upper_bound_values = [upper_bound_stirling(n) for n in n_values]
measure_M = [round((upper_bound_stirling(n)-lower_bound_stirling(n))/lower_bound_stirling(n), 4) for n in n_values]

#[] Organizing into dataframe
df = pd.DataFrame({
    'n': n_values,
    'n!': factorial_values,
    'Lower Bound': lower_bound_values,
    'Upper Bound': upper_bound_values,
    'measure_M': measure_M,
})

#[] Show dataframe
print(df.to_string(index=False))



#[] Plotting
plt.figure(figsize=(10, 6))
plt.plot(n_values, factorial_values, label='n!', marker='o')
plt.plot(n_values, lower_bound_values, label='Lower Bound', linestyle='--', marker='x')
plt.plot(n_values, upper_bound_values, label='Upper Bound', linestyle='--', marker='x')

#[] Setting logarithmic axes
plt.yscale('log')
plt.xscale('log')

#[] Labelling the graph
plt.title("Stirling's Approximation and Boundries for n!")
plt.xlabel('n')
plt.ylabel('Value')
plt.legend()

plt.grid(True, which="both", ls="--", c='0.7')
plt.tight_layout()
plt.show()
import numpy as np
import matplotlib.pyplot as plt

def binomial_coefficient(upper, lower):
    """Return the binomial coefficient."""
    return factorial(upper) / (factorial(lower) * factorial(upper - lower))
    #If we use the above approach, it will overflow at n = 7.

def approximate_binomial_coefficient_upper(n):
    """Return the approximate binomial coefficient using Stirling's approximation."""
    numerator = upper_bound_stirling(2*n)
    denominator = lower_bound_stirling(n) * lower_bound_stirling(n)
    return numerator / denominator

def approximate_binomial_coefficient_lower(n):
    """Return the approximate binomial coefficient using Stirling's approximation."""
    numerator = lower_bound_stirling(2*n)
    denominator = upper_bound_stirling(n) * upper_bound_stirling(n)
    return numerator / denominator



max_n = 10

# Values of n
n_values = np.arange(1, max_n)  # Sample values up to 20 for a clearer plot

# Exact ratio values
ratios_upper = [approximate_binomial_coefficient_upper(n) / 2**(2*n) for n in n_values]
ratios_lower = [approximate_binomial_coefficient_lower(n) / 2**(2*n) for n in n_values]


#[] Approches that overflows
overflow_approach = [binomial_coefficient(2*n, n) / 2**(2*n) for n in n_values]


# Plotting
plt.figure(figsize=(10, 6))
plt.plot(n_values, ratios_upper, label='ratios_upper', linestyle='-', marker='o')
plt.plot(n_values, ratios_lower, label='ratios_lower', linestyle='-', marker='o')
plt.plot(n_values, overflow_approach, label='overflow_approach', linestyle='--', marker='x')


# Labelling the graph
plt.title("Exact and Approximated Ratio for Binomial Coefficient and Random Walk")
plt.xlabel('n')
plt.ylabel('Value')
plt.legend()

plt.grid(True)
plt.tight_layout()
plt.show()

