from transformers import GPT2LMHeadModel, GPT2Tokenizer

model_name = "gpt2-large"  # You can choose a different size like "gpt2-medium", "gpt2-large", "gpt2-xl"
tokenizer = GPT2Tokenizer.from_pretrained(model_name)
model = GPT2LMHeadModel.from_pretrained(model_name)


def generate_response(input_text):
    print('--[Start thinking]')
    # Encode the input text
    input_ids = tokenizer.encode(input_text, return_tensors='pt')

    # Generate a response
    output = model.generate(
        input_ids,
        max_length=50, 
        num_return_sequences=1, 
        no_repeat_ngram_size=2,
        pad_token_id=tokenizer.eos_token_id
    )

    # Decode the response
    response = tokenizer.decode(output[0], skip_special_tokens=True)
    print('--[Finish thinking]')
    return response

# Step 3: Chat loop
print("\n\nYou can start chatting with GPT-2. Type 'quit' to exit.")
while True:
    user_input = input("\n[You  ]: ")
    if user_input.lower() == 'quit':
        break
    response = generate_response(user_input)
    print("\n[GPT-2]: " + response)
# End of [GPT2-1_connect with GPT2.py]




